window.BASAIR_QUESTIONS=(window.BASAIR_QUESTIONS||[]).concat([{"id":"s1-1","number":1,"surah":1,"verses":[1],"references":[{"surah":1,"verses":[1]}],"verseLabel":"1","question":"ما سرّ التعبير بقوله تعالى: ﴿بِسْمِ اللَّهِ﴾ من غير أن يُذكر الفعل: «أبدأ» أو «أقرأ»؟","answer":"البسملة شبه جملة متعلقة بمحذوف يقدّر بحسب المقام؛ ففي مقام القراءة يقدّر فعل القراءة، وفي غيره ما يناسب العمل. وفي حذف ما يدل عليه السياق إيجاز.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص48، تحت عنوان «إيجاز الحذف في البسملة»","url":""}]},{"id":"s1-35","number":35,"surah":1,"verses":[1],"references":[{"surah":1,"verses":[1]}],"verseLabel":"1","question":"لماذا يقدّر الفعل المحذوف في البسملة متأخرًا: «باسم الله أقرأ»؟","answer":"تأخير الفعل المقدّر يبرز الاهتمام باسم الله، لئلا يتقدم عليه شيء، ويفيد اختصاص الاستعانة به؛ فتقدير «باسم الله أقرأ» أنسب بهذا المقام.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص48، تحت عنوان «دلالة المتعلق المحذوف على القصر والتجدد الاستمراري»","url":""}]},{"id":"s1-2","number":2,"surah":1,"verses":[1],"references":[{"surah":1,"verses":[1]}],"verseLabel":"1","question":"لماذا اجتمع الاسمان ﴿الرَّحْمَنِ الرَّحِيمِ﴾، ولم يُكتفَ بأحدهما؟","answer":"«الرحمن» أبلغ في الاتصاف بالرحمة، و«الرحيم» يدل على ثبوتها وتعلّقها بالمرحوم؛ فجمع الاسمان بين كمال صفة الرحمة وظهور أثرها في الخلق.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص50–51، تحت «الفروق المعجمية: الرحمن والرحيم»","url":""}]},{"id":"s1-3","number":3,"surah":1,"verses":[1],"references":[{"surah":1,"verses":[1]}],"verseLabel":"1","question":"ما سرّ تقديم ﴿الرَّحْمَنِ﴾ على ﴿الرَّحِيمِ﴾؟","answer":"قُدِّم «الرحمن» لأنه أبلغ، ويتناول عظائم النعم وأصولها، ثم أُتبع بـ«الرحيم» ليتناول ما دقّ منها ولطف؛ فكان الانتقال من الأعم والأعلى إلى ما يتممه ويفصله.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص49–50، تحت «أبلغية ﴿الرحمن﴾ على ﴿الرحيم﴾، وجمعهما للتوكيد»","url":""}]},{"id":"s1-4","number":4,"surah":1,"verses":[2],"references":[{"surah":1,"verses":[2]}],"verseLabel":"2","question":"لماذا اختير ﴿الْحَمْدُ﴾ بدل «الشكر»؟","answer":"اختير ﴿الْحَمْدُ﴾ دون الشكر؛ لأن الحمد يعمّ الفضائل والفواضل، بخلاف الشكر فإنه خاص بالفواضل؛ أي إن الحمد يكون على صفات الكمال وعلى النِّعم، أما الشكر فيكون على النِّعم.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص55–56، تحت «مذاهب العلماء في معاني (أل)»؛ الفقرة التي تبدأ: واختير الحمد دون الشكر","url":""}]},{"id":"s1-5","number":5,"surah":1,"verses":[2],"references":[{"surah":1,"verses":[2]}],"verseLabel":"2","question":"لماذا اختير ﴿الْحَمْدُ﴾ بدل «المدح»؟","answer":"اختير الحمد لأن فيه إخبارًا بمحاسن المحمود مع محبته وإجلاله وتعظيمه؛ أما المدح فهو أعم، وقد يكون عاريًا عن المحبة والتعظيم، فكان الحمد أدخل في الثناء على الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص55–56، تحت «مذاهب العلماء في معاني (أل)»؛ الفقرة التي تبدأ: وعبر بالحمد دون المدح","url":""}]},{"id":"s1-6","number":6,"surah":1,"verses":[2],"references":[{"surah":1,"verses":[2]}],"verseLabel":"2","question":"ما سرّ التعبير بقوله تعالى: ﴿الْحَمْدُ لِلَّهِ﴾ جملةً اسمية، ولم يقل: «أحمد الله» أو «نحمد الله»؟","answer":"الجملة الاسمية تثبت استحقاق الحمد وتطلقه من فاعل وزمن محددين؛ فالله محمود قبل حمد الحامدين وبعده، أما الفعل فيقيد الحمد بفاعل وزمن وقدر محدود.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص57، تحت «إيثار التعبير بجملة الحمد الاسمية دون الفعلية»","url":""}]},{"id":"s1-7","number":7,"surah":1,"verses":[2],"references":[{"surah":1,"verses":[2]}],"verseLabel":"2","question":"لماذا عُرّف ﴿الْحَمْدُ﴾ في مطلع الفاتحة، ولم يقل: «حمدٌ لله»؟","answer":"تفيد «أل» استغراق المحامد، على الوجه الذي يرجحه المصدر؛ فالحمد كله مستحق لله، إذ ما من خير إلا وهو موليه، بواسطة أو بغير واسطة.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص55–56، تحت «مذاهب العلماء في معاني (أل)»","url":""}]},{"id":"s1-8","number":8,"surah":1,"verses":[2],"references":[{"surah":1,"verses":[2]}],"verseLabel":"2","question":"ما سرّ التعبير بقوله تعالى: ﴿الْحَمْدُ لِلَّهِ﴾ لا «لله الحمد»؟","answer":"الفاتحة في مقام تعليم العباد الحمد، أما آية الجاثية فجاءت بعد إرغام المكذب وظهور صدق ما أخبرت به الرسل؛ فكأن السؤال: لمن الحمد؟ فجاء الجواب: ﴿فَلِلَّهِ الْحَمْدُ﴾، مقدمًا ما يدل على اختصاصه به.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص59–60، تحت «الفرق بين ﴿الحمد لله﴾ و﴿فلله الحمد﴾»","url":""}]},{"id":"s1-9","number":9,"surah":1,"verses":[2],"references":[{"surah":1,"verses":[2]}],"verseLabel":"2","question":"لماذا أُظهر اسم الجلالة في ﴿الْحَمْدُ لِلَّهِ﴾ ولم يقل: «الحمد له»؟","answer":"أُظهر اسم الجلالة مع سبق ذكره في البسملة، فعدل عن الضمير للتلذذ والتبرك بذكر اسم الله الصريح وتعظيمه.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص59، تحت «من بلاغة إظهار لفظ الجلالة دون إضماره»","url":""}]},{"id":"s1-10","number":10,"surah":1,"verses":[2],"references":[{"surah":1,"verses":[2]}],"verseLabel":"2","question":"لماذا اختير اسم ﴿اللَّهِ﴾ لا اسم آخر من أسمائه؟","answer":"اختير اسم ﴿اللَّهِ﴾ لأنه يدل بمفرده على صفات الجلال والجمال والكمال، وعلى استحقاق الحمد لذاته؛ ولو عُلّق الحمد باسم آخر فقد يُتوهم اختصاصه بالصفة التي يدل عليها ذلك الاسم.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص60، تحت «سر تعليق الحمد بلفظ الجلالة»","url":""}]},{"id":"s1-11","number":11,"surah":1,"verses":[2],"references":[{"surah":1,"verses":[2]}],"verseLabel":"2","question":"لماذا أتبع اسم الله بوصف ﴿رَبِّ الْعَالَمِينَ﴾؟","answer":"لأن من انفرد بملك الخلق وتدبير شؤونهم وتربيتهم بالنعم استحق جميع المحامد؛ فجاء وصف ربوبية العالمين مبينًا استحقاق الله وحده للحمد.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص55، تحت عنوان «المعنى الإجمالي» لآية ﴿الحمد لله رب العالمين﴾","url":""}]},{"id":"s1-36","number":36,"surah":1,"verses":[2],"references":[{"surah":1,"verses":[2]}],"verseLabel":"2","question":"ما المعاني التي يجمعها لفظ ﴿رَبِّ﴾ في ﴿رَبِّ الْعَالَمِينَ﴾؟","answer":"يجمع معاني المالك والسيد المطاع والمصلح والمدبر والمنعم والمربي؛ فتتضافر هذه المعاني في بيان عناية الله بخلقه وقيامه على شؤونهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص53–54، تحت عنوان «شرح المفردات»، مدخل ﴿رب﴾","url":""}]},{"id":"s1-12","number":12,"surah":1,"verses":[2],"references":[{"surah":1,"verses":[2]}],"verseLabel":"2","question":"ما سرّ التعبير بقوله تعالى: ﴿الْعَالَمِينَ﴾ لا «العوالم»؟","answer":"جُمع اللفظ ليشمل الأجناس المختلفة، وغُلّب العقلاء على غيرهم فجاء بالياء والنون؛ فتدخل أصناف الخلق في عموم ربوبية الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص60–61، تحت «سر العدول عن (العوالم) إلى ﴿العالمين﴾»","url":""}]},{"id":"s1-13","number":13,"surah":1,"verses":[3],"references":[{"surah":1,"verses":[3]}],"verseLabel":"3","question":"لماذا تكرر ﴿الرَّحْمَنِ الرَّحِيمِ﴾ بعد ورودهما في البسملة؟","answer":"تكرر الاسمان في البسملة وهذا الموضع للتوكيد، والتنبيه على عظم قدرهما وتأكد أمرهما، والإشارة إلى أن العناية بالرحمة أكثر من غيرها.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص65، تحت «عظم قدر اسمي الله الرحمن والرحيم»","url":""}]},{"id":"s1-14","number":14,"surah":1,"verses":[3,4],"references":[{"surah":1,"verses":[3,4]}],"verseLabel":"3–4","question":"لماذا تقدمت الرحمة في ﴿الرَّحْمَنِ الرَّحِيمِ﴾ على الملك والجزاء في ﴿مَالِكِ يَوْمِ الدِّينِ﴾؟","answer":"تقدمت الرحمة لتبعث على الرجاء، ثم ذُكر ملك يوم الدين ليبعث على الخوف والاستعداد للجزاء؛ فجمع السياق للعبد بين الرجاء والخوف.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص73، تحت «مناسبة الآية لما قبلها»؛ تمهيد آية ﴿إياك نعبد وإياك نستعين﴾: الرحمة باعثة على الرجاء وملك يوم الدين باعث على الخوف","url":""}]},{"id":"s1-15","number":15,"surah":1,"verses":[4],"references":[{"surah":1,"verses":[4]}],"verseLabel":"4","question":"ماذا يضيف اجتماع القراءتين المتواترتين: ﴿مَالِكِ﴾ و﴿مَلِكِ يَوْمِ الدِّينِ﴾؟","answer":"تتكامل بهما الدلالة؛ إذ تذكر الموسوعة أن بين المالك والملك عمومًا وخصوصًا من وجه، فلكل منهما جهة عموم لا تستوعبها الأخرى وحدها. وبضم القراءتين يجتمع المعنيان.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص72، تحت عنوان «بين ﴿مالك﴾ و﴿ملك﴾ عموم وخصوص وجهي»","url":""}]},{"id":"s1-37","number":37,"surah":1,"verses":[4],"references":[{"surah":1,"verses":[4]}],"verseLabel":"4","question":"ما الفرق بين «المالك» و«الملك» في الاستعمال؟","answer":"المالك يتملك الشيء، ويستعمل في الناس وغيرهم، فيقال: مالك الناس ومالك الأشياء. أما الملك فيبرز معنى السلطان والحكم في الناس، وقد ينفذ أمره في مال لا يملكه بنفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص71–72، تحت عنوان «ملك، ومالك»","url":""}]},{"id":"s1-16","number":16,"surah":1,"verses":[4],"references":[{"surah":1,"verses":[4]}],"verseLabel":"4","question":"لماذا اختير ﴿مَالِكِ﴾ هنا لا «رب يوم الدين»؟","answer":"لأن وصف المالك أشعر بإقامة الجزاء على وفق أعمال العباد، أما وصف الرب ففيه معنى التربية والرحمة، وقد يطمع المفسد في العفو؛ فناسب مقام الجزاء وصف ﴿مَالِكِ﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص68–69، تحت «سر اختيار لفظ ﴿مالك﴾ دون وصف (رب)»","url":""}]},{"id":"s1-17","number":17,"surah":1,"verses":[4],"references":[{"surah":1,"verses":[4]}],"verseLabel":"4","question":"لماذا أضيف الملك إلى اليوم نفسه: ﴿مَالِكِ يَوْمِ الدِّينِ﴾، مع أن اليوم زمن؟","answer":"لأن ملك الظرف يستلزم ملك جميع ما يقع فيه؛ فملكية يوم الدين كناية عن ملك كل ما يشتمل عليه ذلك اليوم، وهي أبلغ من ذكر بعض ما فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص69، تحت «سر إضافة لفظ ﴿مالك﴾ إلى ظرف الزمان ﴿يوم﴾»","url":""}]},{"id":"s1-18","number":18,"surah":1,"verses":[4],"references":[{"surah":1,"verses":[4]}],"verseLabel":"4","question":"ما سرّ التعبير بقوله تعالى: ﴿يَوْمِ الدِّينِ﴾ لا «يوم القيامة»؟","answer":"لأن ﴿يوم الدين﴾ أعم من «يوم القيامة»؛ فالدين بمعنى الجزاء والحساب يشمل جميع أحوال القيامة من ابتداء النشور إلى السرمد الدائم.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص71، تحت «عبارة ﴿يوم الدين﴾ أشمل من (يوم القيامة)»","url":""}]},{"id":"s1-19","number":19,"surah":1,"verses":[4],"references":[{"surah":1,"verses":[4]}],"verseLabel":"4","question":"لماذا خُص يوم الدين بالملك، ولم تُذكر الدنيا معه؟","answer":"سبق وصف الله بأنه ﴿رَبِّ الْعَالَمِينَ﴾، فشمل ملكه وتصرفه في الدنيا والآخرة. ثم خُص يوم الدين بالذكر عنايةً به وتنبيهًا إلى الاستعداد له؛ وذكره لا ينفي ملك الله لما عداه.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص69–70، تحت «ذكر ﴿مالك يوم الدين﴾ من الإطناب بذكر الخاص بعد العام»","url":""}]},{"id":"s1-20","number":20,"surah":1,"verses":[5,6],"references":[{"surah":1,"verses":[5,6]}],"verseLabel":"5–6","question":"لماذا قُدّم المفعول في ﴿إِيَّاكَ نَعْبُدُ﴾، ولم يُقدّم في طلب الهداية فيقال: «إيانا اهدِ»؟","answer":"تقديم المفعول في العبادة يفيد اختصاص الله بها، أما تقديمه في طلب الهداية فقد يوهم قصرها علينا دون غيرنا؛ والمطلوب أن نسأل الهداية دون منعها عن الآخرين.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص87، تحت «دفع توهم القصر بالتقديم»","url":""}]},{"id":"s1-21","number":21,"surah":1,"verses":[5],"references":[{"surah":1,"verses":[5]}],"verseLabel":"5","question":"ما سرّ الانتقال من الغيبة في ﴿الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ﴾ إلى الخطاب في ﴿إِيَّاكَ نَعْبُدُ﴾؟","answer":"لما أثنى العبد على الله بأسمائه وصفاته ارتقى من الحديث عنه إلى مناجاته ومواجهته بالعبادة والاستعانة؛ فالالتفات يصور قرب العبد وحضوره بين يدي ربه بعد الثناء.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص74–75، تحت «نكت العدول عن الغيبة إلى الخطاب»","url":""}]},{"id":"s1-22","number":22,"surah":1,"verses":[5],"references":[{"surah":1,"verses":[5]}],"verseLabel":"5","question":"ما سرّ تقديم ﴿إِيَّاكَ﴾ في ﴿إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ﴾؟","answer":"تقديم المفعول يفيد الاختصاص والقصر؛ أي نخصك وحدك بالعبادة والاستعانة، بخلاف «نعبدك» التي تثبت العبادة له من غير أن تنفيها عمن سواه.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص77–78، تحت «تقديم المعمول يفيد القصر عند أغلب أهل البيان»","url":""}]},{"id":"s1-23","number":23,"surah":1,"verses":[5],"references":[{"surah":1,"verses":[5]}],"verseLabel":"5","question":"ما سرّ تكرار ﴿إِيَّاكَ﴾ في ﴿إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ﴾؟","answer":"أعيد الضمير لينص على أن المستعان به هو الله كما أن المعبود هو الله، وليجعل العبادة والاستعانة جملتين مستقلتين يمكن أن يقع كل منهما منفردًا، مع تقوية معنى الحصر بالتكرار.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص80، تحت «فائدة تكرار الضمير ﴿إياك﴾»","url":""}]},{"id":"s1-24","number":24,"surah":1,"verses":[5],"references":[{"surah":1,"verses":[5]}],"verseLabel":"5","question":"ما دلالة التعبير بنون الجماعة في ﴿نَعْبُدُ﴾ و﴿نَسْتَعِينُ﴾؟","answer":"صيغة الجمع تدخل القارئ في جماعة المؤمنين، وتبرز مكانة الجماعة في العبادة والاستعانة، فلا يقف العبد في الدعاء منعزلًا عن إخوانه.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص76–77، تحت «نكات التعبير بالنون في ﴿نعبد﴾»","url":""}]},{"id":"s1-25","number":25,"surah":1,"verses":[5],"references":[{"surah":1,"verses":[5]}],"verseLabel":"5","question":"ما سرّ تقديم العبادة على الاستعانة؟","answer":"العبادة غاية والاستعانة وسيلة إليها، فقدمت الغاية. والعبادة طلب لله، والاستعانة طلب منه؛ فقدم ما كان لله على ما كان منه.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص78–79، تحت «نكت تقديم العبادة على الاستعانة»","url":""}]},{"id":"s1-26","number":26,"surah":1,"verses":[5],"references":[{"surah":1,"verses":[5]}],"verseLabel":"5","question":"ما دلالة إطلاق فعل ﴿نَسْتَعِينُ﴾ من غير تقييده بالعبادة أو الطاعة؟","answer":"حذف المتعلَّق يعمّم الاستعانة في كل ما يحتاجه العبد من أمر الدين والدنيا؛ ولو قُيدت بشيء لبقي حكم ما عداه خارج العبارة.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص81، تحت «دلالة حذف المفعول على العموم»","url":""}]},{"id":"s1-27","number":27,"surah":1,"verses":[6],"references":[{"surah":1,"verses":[6]}],"verseLabel":"6","question":"لماذا قيل في الفاتحة: ﴿اهْدِنَا الصِّرَاطَ الْمُسْتَقِيمَ﴾ دون حرف جر قبل «الصراط»؟","answer":"يوجه المصدر تعدية الفعل بنفسه بأنها تجمع معنى الدلالة والإرشاد ومعنى التوفيق والإلهام؛ فالطلب يشمل معرفة الطريق والإعانة على سلوكه.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص85–86، تحت «طرق تعدية فعل الهداية»","url":""}]},{"id":"s1-28","number":28,"surah":1,"verses":[6],"references":[{"surah":1,"verses":[6]}],"verseLabel":"6","question":"ما سرّ طلب المؤمن الهداية في كل صلاة مع أنه مهتدٍ؟","answer":"لأنه يحتاج إلى هداية فيما يجهله، وإلى العمل بما يعلمه، وإلى معرفة تفاصيل ما عرفه إجمالًا؛ فلا يقتصر الطلب على بقاء الإيمان، بل يشمل تحصيل الهداية التامة والثبات عليها.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص86–87، تحت «وجه التعبير بنون الجمع في ﴿اهدنا﴾»؛ الفقرة الختامية التي تبدأ: وحقيقة الأمر في قوله تعالى ﴿اهدنا الصراط المستقيم﴾","url":""}]},{"id":"s1-29","number":29,"surah":1,"verses":[6],"references":[{"surah":1,"verses":[6]}],"verseLabel":"6","question":"لماذا اختير ﴿الصِّرَاطَ﴾ في دعاء الهداية، دون «الطريق» أو «السبيل»؟","answer":"لأن لفظ الصراط يشعر بطريق واسع يشتمل على سالكيه ولا يضيق بهم، أما الطريق والسبيل فلا يلزم من لفظهما هذا الاتساع.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص87، تحت «من أسرار استعمال ﴿الصراط﴾ دون (سبيل) أو (طريق)»","url":""}]},{"id":"s1-30","number":30,"surah":1,"verses":[6],"references":[{"surah":1,"verses":[6]}],"verseLabel":"6","question":"ما دلالة وصف الصراط بأنه ﴿الْمُسْتَقِيمَ﴾؟","answer":"الطريق المستقيم أقصر من المعوج، وأبعد عن المخاوف والآفات، وأقرب إلى الأمان والوصول إلى المقصود؛ فيناسب طلب العبد الضعيف هداية ربه.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص88–89، تحت «فائدة وصف الصراط بالمستقيم»","url":""}]},{"id":"s1-31","number":31,"surah":1,"verses":[6,7],"references":[{"surah":1,"verses":[6,7]}],"verseLabel":"6–7","question":"ما سرّ إعادة لفظ ﴿صِرَاطَ﴾ في ﴿صِرَاطَ الَّذِينَ أَنْعَمْتَ عَلَيْهِمْ﴾؟","answer":"أعيد اللفظ لبيان الصراط المطلوب وتفسيره بطريق أهل النعمة؛ فالثاني بدل يوضح الأول ويعيّن نموذجه العملي.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص93، تحت «فائدة البدل في ﴿صراط﴾ الثانية»","url":""}]},{"id":"s1-32","number":32,"surah":1,"verses":[7],"references":[{"surah":1,"verses":[7]}],"verseLabel":"7","question":"لماذا قيل: ﴿صِرَاطَ الَّذِينَ أَنْعَمْتَ عَلَيْهِمْ﴾ دون تسمية أشخاص معينين؟","answer":"للدلالة على أن اتباعهم إنما هو لما أنعم الله به عليهم من الهداية، لا لذواتهم؛ وفيه إشعار بأن كل من هدي إلى الصراط المستقيم داخل في المنعم عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص93–94، تحت «فائدة إضافة ﴿الصراط﴾ إلى المنعم عليهم دون تعيينهم»","url":""}]},{"id":"s1-33","number":33,"surah":1,"verses":[7],"references":[{"surah":1,"verses":[7]}],"verseLabel":"7","question":"لماذا أُسند الإنعام إلى الله في ﴿أَنْعَمْتَ عَلَيْهِمْ﴾، ولم يقل في مقابله: «الذين غضبت عليهم»؟","answer":"فيه أدب في خطاب الله؛ إذ صُرّح بإسناد النعمة إليه تعظيمًا له، وطُوي التصريح بفاعل الغضب في هذا المقام، فجاء ﴿الْمَغْضُوبِ عَلَيْهِمْ﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص94، تحت «إسناد ﴿أنعمت﴾ إلى الفاعل، وعدم الإسناد في ﴿المغضوب عليهم﴾»","url":""}]},{"id":"s1-34","number":34,"surah":1,"verses":[7],"references":[{"surah":1,"verses":[7]}],"verseLabel":"7","question":"لماذا قُدّم ﴿الْمَغْضُوبِ عَلَيْهِمْ﴾ على ﴿الضَّالِّينَ﴾ في ختام الفاتحة؟","answer":"لأن الغضب أظهر في مقابلة الإنعام، فناسب أن يلي ذكر المنعم عليهم. ولأن مخالفة الحق عن عمد أشد من مخالفته عن جهل، فقدم الأشد في مقام الدعاء باجتنابه.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص95، تحت «نكات تقديم ﴿المغضوب عليهم﴾ على ﴿الضالين﴾»","url":""}]},{"id":"s2-1","number":1,"surah":2,"verses":[1],"references":[{"surah":2,"verses":[1]}],"verseLabel":"البقرة: 1","question":"لماذا افتُتحت سورة البقرة بـ﴿الم﴾؟ وما أثر هذا المطلع في السامع؟","answer":"في افتتاح السورة بالحروف المقطعة غرابة تستدعي التفات السامع وتشرفه لمعرفة ما بعدها، فيقع الكلام الآتي في قلبٍ مستعد للإصغاء. وهي كذلك تلوّح بتحدي العرب وإعجاز القرآن؛ فالقرآن مؤلف من جنس الحروف التي يستعملونها في كلامهم، ومع ذلك عجزوا عن معارضته.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص107، تحت «حسن الافتتاح وبراعته بالبداءة بالأحرف المقطعة»","url":""}]},{"id":"s2-2","number":2,"surah":2,"verses":[2],"references":[{"surah":2,"verses":[2]}],"verseLabel":"البقرة: 2","question":"ما سرّ الإشارة إلى القرآن باسم البعيد في قوله تعالى: ﴿ذلك الكتاب﴾، مع أنه حاضر؟","answer":"أشير إليه باسم البعيد للإيماء إلى علو مكانه وسمو منزلته عن أن يشابه كلام البشر، فهو بُعد منزلة لا بُعد مكان.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص107، تحت «سر الإشارة إلى الكتاب باسم الإشارة الخاص بالبعد»","url":""}]},{"id":"s2-3","number":3,"surah":2,"verses":[2],"references":[{"surah":2,"verses":[2]}],"verseLabel":"البقرة: 2","question":"ما الفرق بين الريب والشك في قوله تعالى: ﴿لا ريب فيه﴾؟","answer":"الريب أخص من الشك؛ فهو شك معه تهمة، أو شك تزيد عليه إساءة الظن، وحقيقته قلق النفس واضطرابها. فنفي الريب عن القرآن ينفي عنه الشك المصحوب بالتهمة والقلق.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص113–114، تحت «الريب والشك»","url":""}]},{"id":"s2-4","number":4,"surah":2,"verses":[2],"references":[{"surah":2,"verses":[2]}],"verseLabel":"البقرة: 2","question":"ما أثر توالي أوصاف القرآن في قوله تعالى: ﴿ذلك الكتاب لا ريب فيه هدى للمتقين﴾؟","answer":"يقوي بعض هذه الأوصاف بعضًا في الدلالة على كمال القرآن: فقوله ﴿ذلك الكتاب﴾ يدل على كماله، ويعزز ذلك نفي الريب عنه، ثم يأتي ﴿هدى﴾ منكّرًا للدلالة على عظيم هدايته. وجاءت الجمل مفصولًا بعضها عن بعض للإيماء إلى كمال الاتصال بينها.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص111، تحت «بلاغة الأوصاف المتوالية»","url":""}]},{"id":"s2-5","number":5,"surah":2,"verses":[2],"references":[{"surah":2,"verses":[2]}],"verseLabel":"البقرة: 2","question":"ما دلالة تنكير ﴿هدى﴾ في قوله تعالى: ﴿هدى للمتقين﴾؟","answer":"نُكّر الهدى لتعظيمه وتفخيمه؛ فهو هدى عظيم لا يُسبر غوره ولا يُدرك منتهاه، وهو فخم لا يليق إلا بالمتقين.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص111، تحت «فائدة تنكير لفظ هدى لتعظيم القرآن»","url":""}]},{"id":"s2-6","number":6,"surah":2,"verses":[2],"references":[{"surah":2,"verses":[2]}],"verseLabel":"البقرة: 2","question":"لماذا خُصّ المتقون بالذكر في قوله تعالى: ﴿هدى للمتقين﴾، مع أن القرآن هدى للناس؟","answer":"خُصّ المتقون بالذكر لكونهم المنتفعين به، وإلا فالقرآن في نفسه هادٍ للناس وبيان لهم جميعًا، كما قال تعالى: ﴿هدى للناس﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص112، تحت «توجيه المخصوص بالذكر»","url":""}]},{"id":"s2-7","number":7,"surah":2,"verses":[2],"references":[{"surah":2,"verses":[2]},{"surah":31,"verses":[2]}],"verseLabel":"البقرة: 2، ولقمان: 2","question":"لماذا بدأ في البقرة بقوله: ﴿ذلك الكتاب﴾، وفي لقمان بقوله: ﴿تلك آيات الكتاب الحكيم﴾؟","answer":"في البقرة لم تكن الآيات قد ذُكرت قبل، فمدح الكتاب برمته بقوله: ﴿ذلك الكتاب﴾. أما في لقمان فلما سبقت في الخطاب آيات كثيرة أشار إلى عظمة تلك الآيات؛ ليبين كمال الكتاب في كل جزء من أجزائه، لا في مجموعه وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص620، تحت «غرض إضافة الآيات إلى الكتاب وجمعها»","url":""}]},{"id":"s2-8","number":8,"surah":2,"verses":[2,3,4,5],"references":[{"surah":2,"verses":[2,3,4,5]},{"surah":31,"verses":[3,4,5]}],"verseLabel":"البقرة: 2–5، ولقمان: 3–5","question":"ما سرّ اختلاف التعبير بين قوله تعالى في البقرة: ﴿هدى للمتقين﴾، وقوله في لقمان: ﴿هدى ورحمة للمحسنين﴾؟","answer":"تقدّم آية البقرة دعاء الفاتحة: ﴿اهدنا الصراط المستقيم﴾، فكان السياق متعلقًا بالهداية، فناسب قوله: ﴿هدى للمتقين﴾. أما سورة لقمان فتقدمها في ختام الروم ذكر الذين لا يعلمون ولا يوقنون وتهديدهم بوعد الله؛ فناسب أن تُخص هداية الله ورحمته بمن علموا وعده وآمنوا به وأيقنوا، فوصلوا إلى درجة الإحسان، فقيل: ﴿هدى ورحمة للمحسنين﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص639–640، تحت «توجيه المتشابه اللفظي في الآية»","url":""}]},{"id":"s2-9","number":9,"surah":2,"verses":[3],"references":[{"surah":2,"verses":[3]}],"verseLabel":"البقرة: 3","question":"لماذا بدأ صفات المتقين بالإيمان بالغيب قبل الصلاة والإنفاق؟","answer":"لأن الإيمان بالغيب أُسّ متين وركن من مقومات الاعتقاد الإسلامي؛ فبدأ بالأصل الذي تقوم عليه سائر الخصال العملية، ثم ذكر إقامة الصلاة والإنفاق.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص119، تحت «فائدة الوصف بالاسم الموصول»","url":""}]},{"id":"s2-10","number":10,"surah":2,"verses":[3],"references":[{"surah":2,"verses":[3]}],"verseLabel":"البقرة: 3","question":"ما الذي يفيده قوله تعالى: ﴿يقيمون الصلاة﴾ فوق مجرد فعل الصلاة؟","answer":"إقامة الصلاة هي المداومة عليها، وإظهارها، والإتيان بها مع المحافظة على أركانها وشروطها ومكملاتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص120–121، تحت «بلاغة الاستعارة في فعل: ﴿ويقيمون﴾»","url":""}]},{"id":"s2-11","number":11,"surah":2,"verses":[3],"references":[{"surah":2,"verses":[3]}],"verseLabel":"البقرة: 3","question":"لماذا عبّر بقوله ﴿وَمِمَّا رَزَقْنَاهُمْ يُنْفِقُونَ﴾ ولم يقل: «ومن أموالهم»؟","answer":"لأن الرزق أعم من المال؛ فحمله على العموم يشمل القوة والجاه والعلم وسائر ما أعطاهم الله، وهذا أنسب بوفرة معاني القرآن.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص117–118، تحت عنوان «شرح المفردات»، مدخل ﴿رزقناهم﴾","url":""}]},{"id":"s2-1461","number":1461,"surah":2,"verses":[3],"references":[{"surah":2,"verses":[3]}],"verseLabel":"البقرة: 3","question":"هل يقتصر الإنفاق في ﴿وَمِمَّا رَزَقْنَاهُمْ يُنْفِقُونَ﴾ على بذل المال؟","answer":"تذكر الموسوعة أن الإنفاق قد يكون بالمال وقد يكون بغيره، وأنه يشمل الواجب والمستحب؛ فلا ينحصر معنى اللفظ في صورة واحدة من البذل.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص118، تحت عنوان «شرح المفردات»، مدخل ﴿ينفقون﴾","url":""}]},{"id":"s2-12","number":12,"surah":2,"verses":[3],"references":[{"surah":2,"verses":[3]}],"verseLabel":"البقرة: 3","question":"ما دلالة ﴿من﴾ في قوله تعالى: ﴿ومما رزقناهم ينفقون﴾؟","answer":"﴿من﴾ للتبعيض؛ فهي تدل على أن المطلوب إنفاق بعض ما أُعطوا لا كله، حذرًا من الإسراف وتضييع من يعولون.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص122–123، تحت «فائدة تقديم الجار والمجرور»","url":""}]},{"id":"s2-13","number":13,"surah":2,"verses":[3],"references":[{"surah":2,"verses":[3]}],"verseLabel":"البقرة: 3","question":"ما سرّ تقديم قوله تعالى: ﴿ومما رزقناهم﴾ على فعل الإنفاق؟","answer":"قُدّم المنفَق منه للاهتمام بما أعطاهم الله، وتوجيه نظر المؤمن إلى نعمة الله عليه، بما يدعوه إلى تقييدها بالشكر إنفاقًا، وفيه إشارة إلى أنهم ينفقون مع ما للرزق من معزة على النفس.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص122، تحت «فائدة تقديم الجار والمجرور»","url":""}]},{"id":"s2-14","number":14,"surah":2,"verses":[3],"references":[{"surah":2,"verses":[3]}],"verseLabel":"البقرة: 3","question":"لماذا لم يبيّن قوله تعالى: ﴿ينفقون﴾ مَن ينفقون عليهم؟","answer":"للدلالة على تنوع المستحقين للنفقة، فيدخل في ذلك كل من يصلح أن يُنفق عليه، كمصارف الزكاة، والأهل والأولاد والوالدين والضيف والجار وغيرهم. وفي الحذف أيضًا إشارة إلى أن النفقة مقصودة من حيث هي قربة إلى الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص123، تحت «براعة حذف المتعلق في الإشارة إلى المقاصد»","url":""}]},{"id":"s2-15","number":15,"surah":2,"verses":[4],"references":[{"surah":2,"verses":[4]}],"verseLabel":"البقرة: 4","question":"لماذا كرر الاسم الموصول في ﴿وَالَّذِينَ يُؤْمِنُونَ بِمَا أُنْزِلَ إِلَيْكَ﴾ بعد ذكر المؤمنين بالغيب؟","answer":"على الوجه الأرجح، جُعل اختلاف الصفات بمنزلة اختلاف الذوات مع أن الموصوفين جماعة واحدة؛ وذلك أمدح لهم وأرجى لهم، بإبراز كل صفة من صفاتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص126، تحت عنوان «تكرار الاسم الموصول للدلالة على تغاير الصفات أم تغاير الموصوفين»","url":""}]},{"id":"s2-1462","number":1462,"surah":2,"verses":[4],"references":[{"surah":2,"verses":[4]}],"verseLabel":"البقرة: 4","question":"ما فائدة تكرار ﴿يُؤْمِنُونَ﴾ مع الغيب ثم مع ما أُنزل إلى الرسول؟","answer":"يرسّخ التكرار المعنى في الذهن، ويبرز أن الإيمان بالغيب والإيمان بالكتب المنزلة وصفان جليلان، لكل منهما شأنه؛ فلا يجعل أحدهما مجرد تتمة للآخر.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص127، تحت عنوان «فائدة تكرار فعل: ﴿يؤمنون﴾»","url":""}]},{"id":"s2-16","number":16,"surah":2,"verses":[4],"references":[{"surah":2,"verses":[4]}],"verseLabel":"البقرة: 4","question":"كيف يقوّي ذكر ﴿هُمْ﴾ الخبر في ﴿وَبِالْآخِرَةِ هُمْ يُوقِنُونَ﴾؟","answer":"أُسند الإيقان إليهم مرتين: بضمير ﴿هم﴾ وبواو الجماعة في ﴿يوقنون﴾؛ فتقوّى الخبر وظهر الاهتمام بإيمانهم بالآخرة وعظيم شأنها.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص130، تحت عنوان «نكتة إسناد فعل الإيقان إلى فاعله مرتين»","url":""}]},{"id":"s2-1463","number":1463,"surah":2,"verses":[4],"references":[{"surah":2,"verses":[4]}],"verseLabel":"البقرة: 4","question":"لماذا ذُكر ﴿هُمْ﴾ مع ﴿يُوقِنُونَ﴾ ولم يُذكر مع ﴿يُنْفِقُونَ﴾؟","answer":"لأن وصفهم بالإيمان بالآخرة أعلى من وصفهم بالإنفاق، فناسبه مزيد التوكيد. أما ذكر الضمير مع الإنفاق فكان يثقل اللفظ، نحو: «ومما رزقناهم هم ينفقون».","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص131، تحت عنوان «بلاغة ذكر الضمير في قوله: ﴿هم يوقنون﴾»","url":""}]},{"id":"s2-1464","number":1464,"surah":2,"verses":[4],"references":[{"surah":2,"verses":[4]}],"verseLabel":"البقرة: 4","question":"ما أثر تقديم ﴿وَبِالْآخِرَةِ﴾ على فعل الإيقان؟","answer":"يبرز الاهتمام بشأن الآخرة والمبالغة في الثناء على المؤمنين؛ فهم يوقنون بها، بخلاف من اضطربت معتقداتهم فيها ولم تبلغ رتبة اليقين.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص129–130، تحت عنوان «سر تقديم الجار والمجرور على الفعل»","url":""}]},{"id":"s2-17","number":17,"surah":2,"verses":[4],"references":[{"surah":2,"verses":[4]}],"verseLabel":"البقرة: 4","question":"لماذا عبّر عن الآخرة باليقين، مع أنه عبّر عن الغيب والوحي بالإيمان؟","answer":"لأن الآخرة حياة غائبة عن المشاهدة، غريبة بحسب المتعارف، وقد كثرت الشبه التي جرّت المشركين والدهريين إلى نفيها؛ فكان الإيمان بها جديرًا بمادة الإيقان، وهي أخص من مطلق الإيمان وأدل على العلم الذي لا يتطرق إليه الشك.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص130–131، تحت عنوان «نكتة إسناد فعل الإيقان إلى فاعله مرتين»، الفقرة التي تشرح اختيار مادة الإيقان","url":""}]},{"id":"s2-18","number":18,"surah":2,"verses":[5],"references":[{"surah":2,"verses":[5]}],"verseLabel":"البقرة: 5","question":"لماذا كرر اسم الإشارة في قوله تعالى: ﴿أولئك على هدى من ربهم وأولئك هم المفلحون﴾؟","answer":"للتنبيه على أن كل حكم مستقل عن الآخر؛ تكثيرًا لفضل الله الذي حصّلوه، وزيادة في الثناء عليهم وتكريمهم. فجُعل ثبوت الهدى لهم منزلة مستقلة، وثبوت الفلاح منزلة أخرى مستقلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص136، تحت «دلالة تكرير اسم الإشارة»","url":""}]},{"id":"s2-19","number":19,"surah":2,"verses":[5],"references":[{"surah":2,"verses":[5]}],"verseLabel":"البقرة: 5","question":"ما دلالة حرف الاستعلاء في قوله تعالى: ﴿على هدى﴾؟","answer":"شُبّه حال المتقين في تمسكهم بالهدى واستقرارهم عليه بحال من اعتلى شيئًا وتمكن منه؛ لأن أفعالهم كانت على مقتضى الهدى، فكان تصرفهم به كتصرف الراكب فيما يركب.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص134–135، تحت «دلالة الاستعلاء في قوله: على هدى»","url":""}]},{"id":"s2-20","number":20,"surah":2,"verses":[5],"references":[{"surah":2,"verses":[5]}],"verseLabel":"البقرة: 5","question":"ماذا أفاد قوله تعالى: ﴿من ربهم﴾ بعد وصف المتقين بأنهم ﴿على هدى﴾؟","answer":"أفاد أن هذا الهدى صادر من الله سبحانه وبتوفيقه، وفي إضافة الرب إليهم تعظيم لشأن المتقين وتشريف لهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص135، تحت عنوان «دلالة التنكير في لفظ ﴿هدى﴾»، فقرة ﴿من ربهم﴾","url":""}]},{"id":"s2-21","number":21,"surah":2,"verses":[5],"references":[{"surah":2,"verses":[5]}],"verseLabel":"البقرة: 5","question":"ما الذي يفيده تعريف طرفي ﴿أُولَئِكَ هُمُ الْمُفْلِحُونَ﴾؟","answer":"يفيد القصر؛ فتعريف ﴿أولئك﴾ و﴿المفلحون﴾ يقرر أن المتقين منفردون بالفلاح الحقيقي الذي لا يشاركهم فيه غيرهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص136، تحت عنوان «القصر بتعريف طرفي الجملة»","url":""}]},{"id":"s2-1465","number":1465,"surah":2,"verses":[5],"references":[{"surah":2,"verses":[5]}],"verseLabel":"البقرة: 5","question":"ماذا يزيد ضمير ﴿هُمْ﴾ في ﴿أُولَئِكَ هُمُ الْمُفْلِحُونَ﴾ بعد إفادة القصر بتعريف الطرفين؟","answer":"يقوّي القصر ويؤكده؛ فالحصر ثابت من تعريف طرفي الجملة، وجاء ضمير الفصل ﴿هم﴾ لتوكيد هذه الدلالة.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص136، تحت عنوان «دور الضمير ﴿هم﴾ في تقوية القصر وتوكيده»","url":""}]},{"id":"s2-22","number":22,"surah":2,"verses":[6],"references":[{"surah":2,"verses":[6]}],"verseLabel":"البقرة: 6","question":"كيف يستوي الإنذار وعدمه للكافرين الموصوفين في مطلع البقرة؟","answer":"المراد من جحد ما أُنزل إلى الرسول استكبارًا وإعراضًا وعنادًا؛ فلا يثمر تخويفه من عذاب الله إيمانًا، ولذلك يستوي عنده الإنذار وعدمه.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص141، تحت عنوان «المعنى الإجمالي» لآية ﴿إن الذين كفروا سواء عليهم﴾","url":""}]},{"id":"s2-1466","number":1466,"surah":2,"verses":[6],"references":[{"surah":2,"verses":[6]}],"verseLabel":"البقرة: 6","question":"لماذا جاءت ﴿لَا يُؤْمِنُونَ﴾ دون عاطف بعد ﴿سَوَاءٌ عَلَيْهِمْ أَأَنْذَرْتَهُمْ أَمْ لَمْ تُنْذِرْهُمْ﴾؟","answer":"لأنها تفسّر الاستواء المجمل قبلها، أو تجيب عن سؤال يثيره: أهو استواء في الإيمان أم في الكفر؟ فجاءت لتقطع بأن المراد عدم إيمانهم، وتدفع توهم خلافه.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص145–146، تحت عنوان «توجيه فصل جملة ﴿لا يؤمنون﴾ عما قبلها»","url":""}]},{"id":"s2-23","number":23,"surah":2,"verses":[6],"references":[{"surah":2,"verses":[6]}],"verseLabel":"البقرة: 6","question":"لماذا ذُكر الإنذار دون البشارة في شأن هؤلاء الكافرين؟","answer":"لأن المتحدث عنهم ليسوا أهلًا للبشارة، ولأن الإنذار أشد وقعًا وتأثيرًا في القلب؛ فإذا لم ينتفعوا بالإنذار كان عدم انتفاعهم بالبشارة من باب أولى.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص145، تحت «نكتة الاكتفاء بالنذارة عن البشارة»","url":""}]},{"id":"s2-24","number":24,"surah":2,"verses":[7],"references":[{"surah":2,"verses":[7]}],"verseLabel":"البقرة: 7","question":"ما الفرق بين الختم والطبع في الاستعمال القرآني؟","answer":"للعلماء قولان مشهوران: أحدهما أن الختم والطبع بمعنى واحد، والآخر أن الطبع أقوى؛ لأن فيه معنى الثبات، فهو أثر يثبت في المطبوع ولا يزول. ويؤيد القول الثاني أن مشتقات الختم وردت في القرآن في الخير والشر، أما الطبع فلم يرد إلا في الشر والذم. ومع ذلك، إذا جاء الختم والطبع فعلين فإن دلالتهما تكاد تكون متقاربة.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص156–157، تحت «ختم وطبع»","url":""}]},{"id":"s2-25","number":25,"surah":2,"verses":[7],"references":[{"surah":2,"verses":[7]}],"verseLabel":"البقرة: 7","question":"لماذا أُفرد السمع وجُمعت القلوب والأبصار في قوله تعالى: ﴿على قلوبهم وعلى سمعهم وعلى أبصارهم﴾؟","answer":"لأن السمع مصدر، والمصدر يقع على القليل والكثير من جنسه، فلا يُجمع في الأصل. أما القلب والبصر فاسمان للجارحتين، فصح جمعهما، وجاء الجمع مناسبًا لأن الحديث عن جماعة من الكافرين، فيُرد كل قلب وبصر إلى صاحبه.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص153–154، تحت «نكتة إفراد السمع وجمع القلوب والأبصار»","url":""}]},{"id":"s2-26","number":26,"surah":2,"verses":[7],"references":[{"surah":2,"verses":[7]}],"verseLabel":"البقرة: 7","question":"لماذا جُعل الختم على القلوب والأسماع، وجُعلت الغشاوة على الأبصار؟","answer":"لأن القلوب والأسماع تشبه الأوعية، فيتصور فيها معنى السد والختم، أما الأبصار فاختصت بالغشاوة لأنها تمنع أصل الرؤية. والمقصود حجب رؤية الاعتبار المؤدية إلى الإيمان، لا منع الرؤية الحسية مطلقًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص154–155، تحت «انتقاء الألفاظ تابع لدقة المعنى»","url":""}]},{"id":"s2-27","number":27,"surah":2,"verses":[7],"references":[{"surah":2,"verses":[7]}],"verseLabel":"البقرة: 7","question":"ما سرّ التعبير في قوله تعالى: ﴿ولهم عذاب عظيم﴾، فقُدّم ﴿لهم﴾ ووُصف العذاب بالعِظم؟","answer":"قُدّم ﴿لهم﴾ على ﴿عذاب﴾ لإفادة اختصاصهم بهذا العذاب، ووُصف بأنه ﴿عظيم﴾ لعِظم جرمهم، وهو الكفر بآيات الله ورسوله.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص156، تحت «تأخير المبتدأ لإفادة القصر»","url":""}]},{"id":"s2-28","number":28,"surah":2,"verses":[7],"references":[{"surah":2,"verses":[7]},{"surah":32,"verses":[9]}],"verseLabel":"البقرة: 7، والسجدة: 9","question":"ما سرّ البدء في البقرة بالقلوب: ﴿ختم الله على قلوبهم وعلى سمعهم﴾، وبدأ في السجدة بالسمع ثم الأبصار ثم الأفئدة؟","answer":"روعي في آية السجدة ترتيب حصول وسائل الإدراك في الوجود؛ فالمسموعات والمبصرات تُكتسب قبل اكتمال التعقل. أما في البقرة فبدأ بالقلوب؛ لأنها الأنسب بسياق مرض القلوب، كما قال بعد ذلك: ﴿في قلوبهم مرض﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص254–255، تحت «توجيه المتشابه اللفظي»","url":""}]},{"id":"s2-29","number":29,"surah":2,"verses":[7],"references":[{"surah":2,"verses":[7]},{"surah":45,"verses":[23]}],"verseLabel":"البقرة: 7، والجاثية: 23","question":"ما سر اختلاف ترتيب القلب والسمع بين قوله في البقرة: ﴿ختم الله على قلوبهم وعلى سمعهم﴾، وقوله في الجاثية: ﴿وختم على سمعه وقلبه﴾؟","answer":"قُدّم السمع في الجاثية لأن السياق سبق بالحديث عن القرآن بوصفه بصائر وهدى، وبالحث على الاتعاظ به؛ فناسب تقديم السمع لبيان عدم قبول النصح والمواعظ الواصلة إليهم. أما البقرة فسياقها الإيمان والكفر، وموضعهما القلب، فقدم القلب.","sources":[{"label":"موسوعة التفسير البلاغي، ج55، ص108، تحت «توجيه المتشابه اللفظي مع آية البقرة»","url":""}]},{"id":"s2-30","number":30,"surah":2,"verses":[7],"references":[{"surah":2,"verses":[7]},{"surah":6,"verses":[46]}],"verseLabel":"البقرة: 7، والأنعام: 46","question":"ما سرّ تقديم البقرة الختم على القلوب، بينما أخرت الأنعام القلوب في قوله: ﴿أخذ الله سمعكم وأبصاركم وختم على قلوبكم﴾؟","answer":"في البقرة الحديث عن كافرين لا يؤمنون مع الإنذار، والقلب محل الإيمان ووسيلة الإدراك؛ فناسب تقديم الختم عليه. وفي الأنعام المقام مقام تهديد وتخويف، والسمع والبصر آلتا توصيل الأدلة إلى الإيمان؛ فبدأ بأخذهما، وإذا سُلبت الآلة تعطّل عمل القلب.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص700، تحت «بيان المتشابه في تقديم الختم في سورتي البقرة والأنعام»","url":""}]},{"id":"s2-31","number":31,"surah":2,"verses":[8],"references":[{"surah":2,"verses":[8]}],"verseLabel":"البقرة: 8","question":"لماذا حكى قول المنافقين: ﴿آمنا بالله وباليوم الآخر﴾، ثم قال: ﴿وما هم بمؤمنين﴾؟","answer":"لأنهم قالوا بألسنتهم ما ليس في قلوبهم؛ فحكى دعواهم أولًا، ثم نفى عنهم حقيقة الإيمان. وجاء النفي بالجملة الاسمية ليدل على دوام انتفاء الإيمان عنهم، ماضيًا وحالًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص163–164، تحت «تغاير الصيغة وأثره في المقابلة»","url":""}]},{"id":"s2-32","number":32,"surah":2,"verses":[8],"references":[{"surah":2,"verses":[8]}],"verseLabel":"البقرة: 8","question":"ما فائدة الباء في قوله ﴿وَمَا هُمْ بِمُؤْمِنِينَ﴾؟","answer":"دخول الباء على خبر ﴿ما﴾ يؤكد نفي الإيمان عنهم، ويقوّي الرد على دعواهم أنهم آمنوا.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص163–164، تحت عنوان «تغاير الصيغة وأثره في المقابلة»","url":""}]},{"id":"s2-1467","number":1467,"surah":2,"verses":[8],"references":[{"surah":2,"verses":[8]}],"verseLabel":"البقرة: 8","question":"ما دلالة عدم تقييد الإيمان بشيء معيّن في ﴿وَمَا هُمْ بِمُؤْمِنِينَ﴾؟","answer":"من توجيهاته أن حذف متعلق الإيمان يفيد العموم؛ فهم ليسوا بمؤمنين بشيء مما من شأنه الإيمان به. وفي ذلك بيان شدة كفرهم وبالغ نفاقهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص164، تحت عنوان «نكتة حذف المفعول وأثرها في توسيع المعنى»","url":""}]},{"id":"s2-33","number":33,"surah":2,"verses":[9],"references":[{"surah":2,"verses":[9]}],"verseLabel":"البقرة: 9","question":"كيف يصوّر ﴿يُخَادِعُونَ اللَّهَ﴾ حال المنافقين مع أن الله لا يُخدع؟","answer":"من توجيهاته الاستعارة التمثيلية: شُبّه إظهارهم الإيمان وإبطانهم الكفر بحال رعية تخادع سلطانها. فيبيّن التعبير شناعة معاملتهم، ولا يعني أن شيئًا يخفى على الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص167، تحت عنوان «بلاغة الاستعارة التمثيلية في بيان شناعة جرم المنافقين»","url":""}]},{"id":"s2-1468","number":1468,"surah":2,"verses":[9],"references":[{"surah":2,"verses":[9]}],"verseLabel":"البقرة: 9","question":"ما الفائدة من تقدير «رسول الله» في أحد توجيهات ﴿يُخَادِعُونَ اللَّهَ﴾؟","answer":"على هذا الوجه حُذف المضاف، فجُعل خداع الرسول بمنزلة خداع مرسله؛ تعظيمًا لشأن الرسول وتقبيحًا لفعل المنافقين. وقرينة الحذف استحالة إخفاء شيء عن الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص167، تحت عنوان «فائدة الإيجاز بحذف المضاف»","url":""}]},{"id":"s2-34","number":34,"surah":2,"verses":[9],"references":[{"surah":2,"verses":[9]}],"verseLabel":"البقرة: 9","question":"لماذا عُطف المؤمنون على اسم الله في قوله: ﴿يخادعون الله والذين آمنوا﴾؟","answer":"لأن قول المنافقين قبلها ﴿آمنا بالله وباليوم الآخر﴾ كان خداعًا للذين آمنوا، فناسب أن يُذكر المؤمنون الذين توجه إليهم ذلك الخداع.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص259–260، تحت عنوان «دلالة اختلاف التعبير بين موضع سورة البقرة وموضع سورة النساء»","url":""}]},{"id":"s2-35","number":35,"surah":2,"verses":[9],"references":[{"surah":2,"verses":[9]}],"verseLabel":"البقرة: 9","question":"ما سرّ التعبير في قوله تعالى: ﴿وما يخدعون إلا أنفسهم﴾ مع أنهم يقصدون خداع غيرهم؟","answer":"لأن دائرة الخداع رجعت عليهم؛ فخداعهم أوقعهم في ضرر الدنيا وعذاب الآخرة، ولم يضروا الله ولا المؤمنين. وعلى قراءة ﴿وما يخادعون﴾ يكون الخداع واقعًا منهم وإليهم، فكأن أنفسهم خدعتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص168–169، تحت «توجيه القراءات القرآنية في الفعل ﴿يخدعون﴾»","url":""}]},{"id":"s2-36","number":36,"surah":2,"verses":[9],"references":[{"surah":2,"verses":[9]}],"verseLabel":"البقرة: 9","question":"ما سرّ ختم بقوله: ﴿وما يشعرون﴾؟","answer":"الشعور هو العلم الدقيق أو مبادئ الإدراك؛ فنفى عنهم الشعور لأن خداعهم لأنفسهم أمر خفي لا يتفطنون له.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص169، تحت «نكتة حذف متعلق الفعل»","url":""}]},{"id":"s2-37","number":37,"surah":2,"verses":[9],"references":[{"surah":2,"verses":[9]},{"surah":4,"verses":[142]}],"verseLabel":"البقرة: 9، والنساء: 142","question":"ما سرّ ذكر المؤمنون في قوله بالبقرة: ﴿يخادعون الله والذين آمنوا﴾، ولم يُذكروا في قوله بالنساء: ﴿إن المنافقين يخادعون الله وهو خادعهم﴾؟","answer":"ذُكر المؤمنون في البقرة لأن قول المنافقين قبلها: ﴿آمنا بالله وباليوم الآخر﴾ كان صادرًا منهم خداعًا للذين آمنوا. أما موضع النساء فسبقه وعيد المنافقين والكافرين باجتماعهم في جهنم، ولم يسبق فيه ذكر خداعهم للمؤمنين صراحة؛ لذلك لم يُذكروا.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص259–260، تحت «دلالة اختلاف التعبير بين موضع سورة البقرة وموضع سورة النساء»","url":""}]},{"id":"s2-38","number":38,"surah":2,"verses":[9],"references":[{"surah":2,"verses":[9]},{"surah":4,"verses":[142]}],"verseLabel":"البقرة: 9، والنساء: 142","question":"ما المراد بقوله في شأن المنافقين ﴿وَهُوَ خَادِعُهُمْ﴾؟","answer":"المراد مجازاتهم على خداعهم؛ أُطلق اسم الخداع على الجزاء المقابل له. فقد يعاملون في الدنيا بظاهر الإسلام مع ما أُعد لهم من العقوبة، فلا يكون ما أُمهلوا فيه دليل كرامة لهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص251، تحت عنوان «المجاز بإسناد الخداع لله تعالى»","url":""}]},{"id":"s2-39","number":39,"surah":2,"verses":[10],"references":[{"surah":2,"verses":[10]}],"verseLabel":"البقرة: 10","question":"ما سرّ التعبير عن النفاق بالمرض في قوله: ﴿في قلوبهم مرض﴾؟","answer":"المرض هنا مرض النفاق والشك، وأصله نقص القوة؛ فحال قلوبهم كحال البدن المريض: ناقصة القوة، مضطربة بين التصديق والإنكار.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص174، تحت «بيان الاستعارة في لفظ ﴿مرض﴾»","url":""}]},{"id":"s2-40","number":40,"surah":2,"verses":[10],"references":[{"surah":2,"verses":[10]}],"verseLabel":"البقرة: 10","question":"هل ﴿فَزَادَهُمُ اللَّهُ مَرَضًا﴾ إخبار عن حال المنافقين أم دعاء عليهم؟","answer":"الأصل الذي يذكره المبحث أنها خبر عن ازدياد مرضهم مع عنادهم. وذكر احتمال الدعاء عليهم بزيادة الشك والنفاق، ثم عرض الاعتراض عليه؛ فلا يُجعل هذا الاحتمال هو التفسير المتعين.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص174–175، تحت عنوان «احتمال الجملة الخبرية والإنشائية للآية»","url":""}]},{"id":"s2-1470","number":1470,"surah":2,"verses":[10],"references":[{"surah":2,"verses":[10]}],"verseLabel":"البقرة: 10","question":"ما دلالة إسناد زيادة المرض إلى الله في ﴿فَزَادَهُمُ اللَّهُ مَرَضًا﴾؟","answer":"تقرر الموسوعة أنه إسناد حقيقي يبيّن تمام قدرة الله على ظاهر العباد وباطنهم؛ وكانت الزيادة جزاءً على إعراض المنافقين عن الوحي المنزل وإصرارهم على الكفر.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص175، تحت عنوان «إسناد فعل الزيادة إلى الله تعالى حقيقي لا مجازي»","url":""}]},{"id":"s2-41","number":41,"surah":2,"verses":[10],"references":[{"surah":2,"verses":[10]}],"verseLabel":"البقرة: 10","question":"ما سرّ وصف عذاب المنافقين هنا بأنه ﴿أليم﴾، ووصف عذاب الكافرين قبلها بأنه ﴿عظيم﴾؟","answer":"﴿العظيم﴾ ظاهر العِظم، فناسب مقام الكافرين الظاهرين. أما ﴿الأليم﴾ فهو وجع غير ظاهر، فناسب المنافقين الذين يُبطنون الكفر، كما أن أخلاقهم المنحرفة مؤلمة للمجتمع المسلم؛ فناسب كل لفظ مقامه ومعناه.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص177، تحت «توجيه المتشابه اللفظي»","url":""}]},{"id":"s2-42","number":42,"surah":2,"verses":[10],"references":[{"surah":2,"verses":[10]}],"verseLabel":"البقرة: 10","question":"ما صلة الباء في ﴿بِمَا كَانُوا يَكْذِبُونَ﴾ بالعذاب المذكور قبلها؟","answer":"من معانيها السببية: لهم عذاب أليم بسبب كذبهم. ويحتمل المبحث المقابلة، فيصوّر العذاب جزاءً يقابل ما قدموه من كذب.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص177–178، تحت عنوان «بلاغة الباء في جمعها بين معنى السببية والتهكم والمقابلة»","url":""}]},{"id":"s2-1471","number":1471,"surah":2,"verses":[10],"references":[{"surah":2,"verses":[10]}],"verseLabel":"البقرة: 10","question":"ما فائدة ﴿كَانُوا﴾ في وصف كذب المنافقين؟","answer":"تدل على دوام كذبهم واستمرارهم فيه؛ فليس المذكور كذبة عارضة انفصلت عن حالهم، بل سلوك استمروا عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص178، تحت عنوان «فائدة ذكر ﴿كانوا﴾ في بيان استمرار المنافقين على الكذب»","url":""}]},{"id":"s2-1472","number":1472,"surah":2,"verses":[10],"references":[{"surah":2,"verses":[10]}],"verseLabel":"البقرة: 10","question":"كيف يصوّر المضارع ﴿يَكْذِبُونَ﴾ تكرر فعل المنافقين؟","answer":"يضفي المضارع معنى التجدد والاستمرار؛ فهم يزاولون الكذب مرة بعد مرة حتى صار طبعًا لهم، واجتمع ذلك مع دلالة ﴿كانوا﴾ على الدوام.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص178، تحت عنوان «دلالة الفعل المضارع على التجدد والاستمرار»","url":""}]},{"id":"s2-1473","number":1473,"surah":2,"verses":[10],"references":[{"surah":2,"verses":[10]}],"verseLabel":"البقرة: 10","question":"ما المعنيان اللذان تجمعهما قراءتا ﴿يَكْذِبُونَ﴾ و﴿يُكَذِّبُونَ﴾؟","answer":"قراءة التخفيف تصف كذبهم، وقراءة التشديد تصف تكذيبهم؛ فتجمع القراءتان ذم كذبهم على الله والرسل وذم تكذيبهم بآيات الله ورسله وكتبه.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص178، تحت عنوان «سر حذف المفعول في القراءتين»","url":""}]},{"id":"s2-43","number":43,"surah":2,"verses":[11],"references":[{"surah":2,"verses":[11]}],"verseLabel":"البقرة: 11","question":"لماذا نُص على الأرض في قوله: ﴿لا تفسدوا في الأرض﴾؟","answer":"ذُكرت الأرض لأنها محل نشأة الناس وتصرفهم، ومنها مادة حياتهم، وهي جديرة بأن تكون محل إصلاح لا محل إفساد. ويحتمل أن يراد بها المدينة أولًا، أو جنس الأرض؛ تنبيهًا إلى أن طمع المفسدين لا يقف عند موضع واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص182، تحت «سر التنصيص على لفظ ﴿الأرض﴾»","url":""}]},{"id":"s2-44","number":44,"surah":2,"verses":[11],"references":[{"surah":2,"verses":[11]}],"verseLabel":"البقرة: 11","question":"ما الذي يدّعيه المنافقون بالقصر في ﴿إِنَّمَا نَحْنُ مُصْلِحُونَ﴾؟","answer":"يدّعون أنه لا صفة لهم إلا الإصلاح، وهو قصر ادعائي يقلب حكم الناصح عليهم بالفساد. فلم يكتفوا بنفي الإفساد، بل أثبتوا لأنفسهم خلافه.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص183، تحت عنوان «سر التعبير بأسلوب القصر»","url":""}]},{"id":"s2-1474","number":1474,"surah":2,"verses":[11],"references":[{"surah":2,"verses":[11]}],"verseLabel":"البقرة: 11","question":"لماذا اختار المنافقون ﴿إِنَّمَا﴾ في ادعاء الإصلاح؟","answer":"لأنها تناسب قصر القلب، ولأنها تستعمل في خطاب من يُعامل كالعالم بالأمر؛ فكأن صلاح حالهم واضح لا ينبغي أن يخفى على ناصحيهم، وفي ذلك مبالغة في تمويههم.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص183، تحت عنوان «علة اختيار أداة القصر ﴿إنما﴾»","url":""}]},{"id":"s2-45","number":45,"surah":2,"verses":[12],"references":[{"surah":2,"verses":[12]}],"verseLabel":"البقرة: 12","question":"لماذا كثرت المؤكدات في ﴿أَلَا إِنَّهُمْ هُمُ الْمُفْسِدُونَ﴾؟","answer":"لتبطل دعوى المنافقين الإصلاح إبطالًا قويًا؛ فاجتمعت ﴿ألا﴾ للتنبيه، و﴿إن﴾، وضمير الفصل، واسمية الجملة، بما يناسب تمويههم ومخالفة دعواهم للواقع.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص185–186، تحت عنوان «نكتة تأكيد الجملة»","url":""}]},{"id":"s2-1475","number":1475,"surah":2,"verses":[12],"references":[{"surah":2,"verses":[12]}],"verseLabel":"البقرة: 12","question":"كيف يقابل القصر في ﴿هُمُ الْمُفْسِدُونَ﴾ ادعاءهم ﴿إِنَّمَا نَحْنُ مُصْلِحُونَ﴾؟","answer":"جاء الرد على أسلوب دعواهم نفسه، فأثبت لهم الإفساد الذي حاولوا نفيه والتعريض به بغيرهم. وأفاد تعريف طرفي الجملة القصر، وأكده ضمير الفصل؛ فهو قصر قلب يرد التهمة عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص186، تحت عنوان «بلاغة أسلوب القصر»","url":""}]},{"id":"s2-46","number":46,"surah":2,"verses":[12],"references":[{"surah":2,"verses":[12]}],"verseLabel":"البقرة: 12","question":"ما سرّ ختم آية الإفساد بقوله: ﴿ولكن لا يشعرون﴾؟","answer":"لأنهم لا يدركون أن ما يفعلونه هو الإفساد بعينه؛ فنُفي عنهم الشعور، وهو إدراك الأمر الدقيق، لتصوير خفاء حقيقة فسادهم عنهم مع وضوحه في نفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص187، تحت «حذف المعمول لدلالة القرينة عليه أو لإفادة العموم»","url":""}]},{"id":"s2-47","number":47,"surah":2,"verses":[13],"references":[{"surah":2,"verses":[13]}],"verseLabel":"البقرة: 13","question":"من المراد بالناس في قوله: ﴿آمنوا كما آمن الناس﴾؟ وما سرّ التعبير عنهم بهذا اللفظ؟","answer":"المراد بالناس المؤمنون، ولا سيما أصحاب النبي ﷺ. وعُبّر عنهم باسم الناس تعظيمًا لإيمانهم؛ فكأن من عداهم ليسوا من الناس الكاملين، أو لأنهم الناس المعهودون في الخطاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص190، تحت «سر تعريف ﴿الناس﴾ باللام»","url":""}]},{"id":"s2-48","number":48,"surah":2,"verses":[13],"references":[{"surah":2,"verses":[13]}],"verseLabel":"البقرة: 13","question":"ماذا يقصد المنافقون باستفهامهم ﴿أَنُؤْمِنُ كَمَا آمَنَ السُّفَهَاءُ﴾؟","answer":"هو استفهام إنكاري بمعنى النفي؛ أي لا نؤمن كما آمنوا. وعدلوا إليه من الخبر للمبالغة في إظهار رفضهم الإيمان والتبرؤ منه.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص191، تحت عنوان «دلالة الاستفهام على الإنكار»","url":""}]},{"id":"s2-1476","number":1476,"surah":2,"verses":[13],"references":[{"surah":2,"verses":[13]}],"verseLabel":"البقرة: 13","question":"لماذا جاء الرد ﴿أَلَا إِنَّهُمْ هُمُ السُّفَهَاءُ﴾ مؤكدًا بأكثر من مؤكد؟","answer":"لإبطال تعريضهم بالمؤمنين أبلغ إبطال، وإثبات أن السفه فيهم هم؛ فاجتمع التنبيه بـ﴿ألا﴾ و﴿إن﴾ وضمير الفصل واسمية الجملة.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص192، تحت عنوان «سر التأكيد بأكثر من مؤكد»","url":""}]},{"id":"s2-49","number":49,"surah":2,"verses":[12,13],"references":[{"surah":2,"verses":[12,13]}],"verseLabel":"البقرة: 12–13","question":"ما سرّ اختلاف التعبير بين قوله تعالى في الإفساد: ﴿لا يشعرون﴾، وقوله تعالى في السفه: ﴿لا يعلمون﴾؟","answer":"لأن الإفساد من الأمور المحسوسة التي تدرك آثارها بالشعور، فنفى عنهم الشعور. أما السفه فصفة معنوية لا تُعرف إلا بالنظر والعلم، فناسبها نفي العلم.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص192–193، تحت «مناسبة ختم هذه الآية بنفي العلم وختم الآية التي قبلها بنفي الشعور»","url":""}]},{"id":"s2-50","number":50,"surah":2,"verses":[14],"references":[{"surah":2,"verses":[14]}],"verseLabel":"البقرة: 14","question":"ما سر المغايرة بين ﴿لقوا الذين آمنوا﴾ و﴿خلوا إلى شياطينهم﴾؟","answer":"اللقاء بالمؤمنين لا يقتضي موافقتهم، أما الخلوة بشياطينهم فتمكنهم من التصريح بما في نفوسهم من اعتقادات خبيثة؛ فتكشف المغايرة اختلاف ظاهرهم عن باطنهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص196، تحت عنوان «المغايرة بين اللقاء والخلو»","url":""}]},{"id":"s2-1477","number":1477,"surah":2,"verses":[14],"references":[{"surah":2,"verses":[14]}],"verseLabel":"البقرة: 14","question":"لماذا عُدّي الفعل ﴿خلوا﴾ بـ﴿إلى﴾ في ﴿وإذا خلوا إلى شياطينهم﴾؟","answer":"ضُمّن معاني الانصراف والإيواء والانتهاء؛ أي انصرفوا إلى شياطينهم وآووا إليهم وانتهوا إليهم. وفي ذلك إشعار برغبتهم عن المؤمنين ومشاكلتهم لشياطينهم، ويصح أن يجمع التضمين هذه المعاني.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص197، تحت عنوان «تضمين الفعل ﴿خلوا﴾ معاني عدة أفعال»","url":""}]},{"id":"s2-51","number":51,"surah":2,"verses":[14],"references":[{"surah":2,"verses":[14]}],"verseLabel":"البقرة: 14","question":"ما دلالة اختلاف تعبير المنافقين، إذ قالوا للمؤمنين: ﴿آمنا﴾، وقالوا لشياطينهم: ﴿إنا معكم﴾؟","answer":"قصدهم مع المؤمنين الإخبار بتحصيل مطلق الإيمان، فجاءت جملة فعلية. أما مع شياطينهم فأخبروا بحقيقة أمرهم على جهة الثبوت واللزوم، فجاءت الجملة الاسمية المؤكدة: ﴿إنا معكم﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص198، تحت «نكتة مقابلة الجملة الاسمية للفعلية في الجوابين»","url":""}]},{"id":"s2-52","number":52,"surah":2,"verses":[14],"references":[{"surah":2,"verses":[14]}],"verseLabel":"البقرة: 14","question":"لماذا أكد المنافقون لشياطينهم قولهم ﴿إنا معكم﴾ بـ﴿إن﴾؟","answer":"بالغوا في إثبات ما يحبونه من الكفر، ودفعوا أن يتهمهم رؤساؤهم بالإسلام حقيقةً بسبب إظهاره أمام المؤمنين؛ فكان التوكيد تمهيدًا لبيان ما أضمروه بقولهم ﴿إنما نحن مستهزئون﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص198، تحت عنوان «تأكيد الجملة بـ(إن) لبيان مبالغة المنافقين في حب الكافرين»","url":""}]},{"id":"s2-1478","number":1478,"surah":2,"verses":[14],"references":[{"surah":2,"verses":[14]}],"verseLabel":"البقرة: 14","question":"ما دلالة القصر بـ﴿إنما﴾ في قول المنافقين ﴿إنما نحن مستهزئون﴾؟","answer":"هو قصر ادعائي للموصوف على الصفة؛ يدعون أنه لا صفة لهم في معاملتهم المؤمنين إلا الاستهزاء. واختاروا ﴿إنما﴾ لإظهار ذلك كأنه أمر واضح لا ينبغي أن يخفى على شياطينهم أو يحتاج إلى سؤال.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص199، تحت عنوان «القصر بـ﴿إنما﴾ لبيان أن استهزاءهم لا ينبغي خفاؤه على الشياطين»","url":""}]},{"id":"s2-53","number":53,"surah":2,"verses":[15],"references":[{"surah":2,"verses":[15]}],"verseLabel":"البقرة: 15","question":"كيف يُفهم قوله: ﴿الله يستهزئ بهم﴾؟","answer":"جاء قوله: ﴿الله يستهزئ بهم﴾ استئنافًا بيانيًا جوابًا عما يثيره استهزاؤهم بالمؤمنين؛ ومعناه أن الله ينتقم منهم ويجازيهم في مقابل استهزائهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص203، تحت عنوان «الاستئناف البياني لبيان انتقام الله تعالى من المنافقين»","url":""}]},{"id":"s2-54","number":54,"surah":2,"verses":[15],"references":[{"surah":2,"verses":[15]}],"verseLabel":"البقرة: 15","question":"ما وجه زيادة المنافقين في الطغيان في قوله ﴿ويمدهم في طغيانهم﴾؟","answer":"من معاني المد الزيادة؛ فناسب ذكره شدة إعراض المنافقين عن الإيمان، إذ من أعرض عنه بعد علمه بحقيقته زاده الله ضلالًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص205، تحت عنوان «توجيه المتشابه اللفظي بين ﴿يمدهم﴾ و﴿ويذرهم﴾»","url":""}]},{"id":"s2-1479","number":1479,"surah":2,"verses":[15],"references":[{"surah":2,"verses":[15]}],"verseLabel":"البقرة: 15","question":"كيف يُحمل ﴿ويمدهم في طغيانهم﴾ على زيادة مدة حياة المنافقين؟","answer":"يحتمل أن يكون المراد زيادة مدة حياتهم، وهي سبب لازديادهم في الطغيان؛ فعبّر بالمسبَّب عن السبب على سبيل المجاز المرسل. وفيه مبالغة في وصف طغيانهم، حتى كأنه لا عمل لهم في الحياة إلا الطغيان.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص204–205، تحت عنوان «سر التعبير بالمسبب عن السبب»","url":""}]},{"id":"s2-55","number":55,"surah":2,"verses":[15],"references":[{"surah":2,"verses":[15]}],"verseLabel":"البقرة: 15","question":"ما الفرق بين العمه والعمى في قوله: ﴿يعمهون﴾؟","answer":"العمه خاص بالرأي، ومعناه التحير والتردد، فهو أخص من العمى؛ أما العمى فيكون في البصر ويكون في الرأي. فاختير ﴿يعمهون﴾ لوصف حيرتهم في طغيانهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص205–206، تحت «العمه والعمى»","url":""}]},{"id":"s2-56","number":56,"surah":2,"verses":[16],"references":[{"surah":2,"verses":[16]}],"verseLabel":"البقرة: 16","question":"لماذا صُوّر أخذ المنافقين الضلالة وتركهم الهدى بالشراء؟","answer":"شُبّه استبدالهم الضلالة بالهدى بالشراء؛ لأنهم رغبوا في الضلالة رغبة المشتري في السلعة، حتى بذلوا الهدى ثمنًا لها، فكانت تجارتهم أعظم الخسارة.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص209–210، تحت «التعبير بالاشتراء؛ لبيان حرص المنافقين على الضلال وزهدهم في الهدى»","url":""}]},{"id":"s2-57","number":57,"surah":2,"verses":[16],"references":[{"surah":2,"verses":[16]}],"verseLabel":"البقرة: 16","question":"لماذا جُعلت الضلالة مُشترًى وجُعل الهدى ثمنًا في قوله: ﴿اشتروا الضلالة بالهدى﴾؟","answer":"لأن رغبتهم اتجهت إلى الضلالة، فهي السلعة التي طلبوها، وبذلوا في سبيل تحصيلها الهدى رغبةً عنه؛ فصُوّر الهدى ثمنًا والضلالة مشترًى.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص209–210، تحت «التعبير بالاشتراء؛ لبيان حرص المنافقين على الضلال وزهدهم في الهدى»","url":""}]},{"id":"s2-58","number":58,"surah":2,"verses":[16],"references":[{"surah":2,"verses":[16]}],"verseLabel":"البقرة: 16","question":"لماذا أُسند الربح إلى التجارة في قوله: ﴿فما ربحت تجارتهم﴾؟","answer":"هذا إسناد مجازي؛ لأن الذي يربح حقيقة هو التاجر، وإنما أُسند الربح إلى التجارة لتلبسها بالفاعل، أو لأنها سبب الربح والخسارة. وفيه إشارة إلى ترك هذه البيعة؛ فإذا كانت لا تربح، فكيف يُقدم عليها؟","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص211، تحت «نكتة إسناد الربح إلى التجارة مجازًا»","url":""}]},{"id":"s2-59","number":59,"surah":2,"verses":[16],"references":[{"surah":2,"verses":[16]}],"verseLabel":"البقرة: 16","question":"ماذا أضاف قوله: ﴿وما كانوا مهتدين﴾ بعد قوله: ﴿فما ربحت تجارتهم﴾؟","answer":"نفى عنهم الربح أولًا، ثم نفى عنهم الهداية نفيًا مؤكدًا بالجملة الاسمية و﴿كانوا﴾ الدالة على الدوام والاستمرار؛ فليس من شأن من هذه حاله أن يُتصور منه الاهتداء.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص212، تحت «نفي الهداية عن المنافقين لأنها ليست من شأنهم»","url":""}]},{"id":"s2-60","number":60,"surah":2,"verses":[17],"references":[{"surah":2,"verses":[17]}],"verseLabel":"البقرة: 17","question":"ما سرّ مجيء الموصول مفردًا في قوله: ﴿مثلهم كمثل الذي استوقد نارًا﴾ مع أن الحديث عن جماعة؟","answer":"لأن ﴿الذي﴾ وإن كان مفردًا في اللفظ فهو يعم أفراده، فهو في المعنى جمع. ويحتمل أن يكون التقدير: كمثل الفريق الذي استوقد، ثم روعي لفظ الموصول فأُفرد الضمير، وروعي معناه فجمع بعد ذلك في ﴿بنورهم﴾ و﴿تركهم﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص218، تحت «دلالة الاسم الموصول»","url":""}]},{"id":"s2-61","number":61,"surah":2,"verses":[17],"references":[{"surah":2,"verses":[17]}],"verseLabel":"البقرة: 17","question":"ما الذي يفيده لفظ ﴿استوقد﴾ في مشهد المثل؟","answer":"يفيد طلب وقود النار، ويعزز معنى علو النار وارتفاع لهبها وشدة إضاءتها؛ فقد طلب صاحب المثل إيقاد نار عظيمة، ثم ذهبت منفعتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص219، تحت عنوان «دلالة تنكير ﴿نارًا﴾ على التعظيم»","url":""}]},{"id":"s2-62","number":62,"surah":2,"verses":[17],"references":[{"surah":2,"verses":[17]}],"verseLabel":"البقرة: 17","question":"ما دلالة قوله: ﴿أضاءت ما حوله﴾ في المثل؟","answer":"يحتمل أن تكون ﴿ما﴾ مفعولًا به؛ أي أضاءت النار الأماكن والأشياء المحيطة به. ويحتمل أن تكون فاعلًا؛ أي أضاء ما حوله، وفي هذا مبالغة في شدة الإضاءة حتى كأن ما حوله هو الذي أضاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص219، تحت «دلالة (ما) في ﴿ما حوله﴾»","url":""}]},{"id":"s2-63","number":63,"surah":2,"verses":[17],"references":[{"surah":2,"verses":[17]}],"verseLabel":"البقرة: 17","question":"ما سر قوله: ﴿ذهب الله بنورهم﴾ دون: أذهب الله نورهم؟","answer":"التعدية بالباء دون الهمزة تشعر بدوام ذهاب النور وملازمته؛ لما في الباء من معنى الإمساك، كأنه أُخذ فأُمسك ولم يُرسل بعده، فلا يُتصور رجوعه إليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص219–220، تحت «دلالة حرف الباء»","url":""}]},{"id":"s2-64","number":64,"surah":2,"verses":[17],"references":[{"surah":2,"verses":[17]}],"verseLabel":"البقرة: 17","question":"ما سرّ التعبير في قوله تعالى: ﴿بنورهم﴾ ولم يقل: بنارهم، مع أن المثل بدأ بالنار؟","answer":"لأن المقصود من إيقاد النار حصول النور، فأذهب الله مقصودهم منها. ولأن النار فيها إشراق وإحراق، فأذهب ما فيها من الإشراق وهو النور، وأبقى ما فيها من الإحراق وهو النار.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص220، تحت «نكتة التعبير بـ﴿نورهم﴾ دون (نارهم) أو (ضوئهم)»","url":""}]},{"id":"s2-65","number":65,"surah":2,"verses":[17],"references":[{"surah":2,"verses":[17]}],"verseLabel":"البقرة: 17","question":"ما دلالة تنكير الظلمات وجمعها في قوله: ﴿وتركهم في ظلمات﴾؟","answer":"نُكرت الظلمات وجُمعت للتهويل؛ أي تُركوا في ظلمات هائلة اختلت معها حواسهم وانتقصت قواهم، وليست ظلمة واحدة، بل ظلمات يعجز الواصف عن تصوير مبلغها.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص220–221، تحت «تنكير ﴿ظلمات﴾ للتهويل»","url":""}]},{"id":"s2-66","number":66,"surah":2,"verses":[17],"references":[{"surah":2,"verses":[17]}],"verseLabel":"البقرة: 17","question":"ما فائدة قوله: ﴿وتركهم في ظلمات لا يبصرون﴾ بعد قوله: ﴿ذهب الله بنورهم﴾؟","answer":"الجملة الثانية تقرير لمضمون الأولى وزيادة في كشف الحال التي صاروا إليها؛ فذهاب النور يدل على انعدام الفائدة، ثم جاء وصف تركهم في الظلمات لا يبصرون تذكيرًا بما آلوا إليه وتنبيهًا عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص221، تحت «الإطناب لزيادة كشف الحال التي آل إليها المنافقون»","url":""}]},{"id":"s2-67","number":67,"surah":2,"verses":[18],"references":[{"surah":2,"verses":[18]}],"verseLabel":"البقرة: 18","question":"لماذا رتبت أوصاف المنافقين: ﴿صم بكم عمي﴾ بهذا الترتيب؟","answer":"روعي ترتيب ما يقع عند تلقي الوحي: يسمع الإنسان قول الرسول، ثم ينطق ويسأل عن دليل صدقه، ثم يرى الآية؛ فنُفي عن المنافقين الانتفاع بالسمع، ثم بالنطق، ثم بالبصر، وأثبتت لهم أضداد هذه الحواس.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص226، تحت «سر ترتيب الأوصاف في سياق الآية»","url":""}]},{"id":"s2-68","number":68,"surah":2,"verses":[18],"references":[{"surah":2,"verses":[18]}],"verseLabel":"البقرة: 18","question":"ما معنى قوله: ﴿فهم لا يرجعون﴾ في ختام مثل النار؟","answer":"لا يرجعون إلى ضياء يدفع حيرتهم، ولا يرجعون إلى الإيمان بعد أن آمنوا ظاهرًا ثم كفروا. وجاءت الجملة اسمية لتفيد استمرارهم في باطلهم وإصرارهم على غيهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص227، تحت «نكتة التعبير بالجملة الاسمية»","url":""}]},{"id":"s2-69","number":69,"surah":2,"verses":[18],"references":[{"surah":2,"verses":[18]},{"surah":6,"verses":[39]}],"verseLabel":"البقرة: 18، والأنعام: 39","question":"لماذا جاءت صفات البقرة بلا عطف: ﴿صم بكم عمي﴾، وجاءت في الأنعام بالعطف: ﴿صم وبكم في الظلمات﴾؟","answer":"سيقت صفات البقرة بلا عطف لقصد اجتماعها في كل واحد من المنافقين، لا توزيعها بينهم. أما العطف في الأنعام فيحتمل معه التوزيع؛ فيكون بعض المكذبين كالصم وبعضهم كالبكم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص624، تحت «توجيه المتشابه اللفظي، بين قوله تعالى: ﴿صم وبكم﴾ وقوله: ﴿صم بكم﴾»","url":""}]},{"id":"s2-70","number":70,"surah":2,"verses":[18],"references":[{"surah":2,"verses":[18]},{"surah":25,"verses":[73]}],"verseLabel":"البقرة: 18، والفرقان: 73","question":"ما سرّ التعبير بقوله تعالى: في البقرة: ﴿عمي﴾، وقيل في الفرقان: ﴿عميانًا﴾؟","answer":"جاءت صيغة ﴿عميانًا﴾ للمبالغة في تصوير عمى المشركين عن الانتفاع بآيات الذكر الحكيم، ودل على المبالغة زيادة النون في الجمع. وناسب ذلك سياق وصف عباد الرحمن بفعل مضاد لفعل المشركين المعرضين.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص268، تحت «إيثار الجمع «عميانا» دون (عميا)»","url":""}]},{"id":"s2-71","number":71,"surah":2,"verses":[19],"references":[{"surah":2,"verses":[19]}],"verseLabel":"البقرة: 19","question":"ماذا يضيف مثل الصيب إلى مثل النار في تصوير حال المنافقين؟","answer":"المثل الناري يبين ضياع أعمال المنافقين وجهودهم، أما المثل المائي فيبين أثر القرآن في فضحهم وكشف حقيقتهم؛ فالمثلان متكاملان، ولكل منهما وجه تشبيه مستقل.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص230–231، تحت «استعمال ﴿أو﴾ لمطلق التساوي على طريقة المجاز المرسل»","url":""}]},{"id":"s2-72","number":72,"surah":2,"verses":[19],"references":[{"surah":2,"verses":[19]}],"verseLabel":"البقرة: 19","question":"ما معنى ﴿صيّب﴾ في قوله: ﴿أو كصيّب من السماء﴾، وما دلالة تنكيره؟","answer":"الصيّب هو المطر، وأصل مادته يدل على نزول شيء واستقراره. ونُكّر للتعظيم وبيان النوع؛ أي مطر من نوع هائل كأنه جنس مستقل عن المعهود.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص231، تحت «سر تنكير (صيب)»","url":""}]},{"id":"s2-73","number":73,"surah":2,"verses":[19],"references":[{"surah":2,"verses":[19]}],"verseLabel":"البقرة: 19","question":"لماذا رتبت عناصر المثل: ﴿ظلمات ورعد وبرق﴾ بهذا الترتيب؟","answer":"روعي في ترتيبها كثرة وجودها: فالظلام يوجد في الليل مع كل يوم، والرعد أكثر وجودًا من البرق؛ لأن البرق لا يكون إلا مع رعد، وقد يكون الرعد ولا برق معه.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص233، تحت «نكتة ترتيب الظلمات والرعد والبرق»","url":""}]},{"id":"s2-74","number":74,"surah":2,"verses":[19],"references":[{"surah":2,"verses":[19]}],"verseLabel":"البقرة: 19","question":"ما سرّ التعبير في قوله تعالى: ﴿يجعلون أصابعهم في آذانهم﴾ مع أن الذي يدخل هو الأنامل؟","answer":"أطلق الأصابع وأريدت الأنامل، وهو مجاز مرسل علاقته الكلية؛ للمبالغة في شدة سد المسامع، فكأنهم لو استطاعوا إدخال الإصبع كلها لفعلوا.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص233–234، تحت «نكتة التعبير بالأصابع دون الأنامل»","url":""}]},{"id":"s2-75","number":75,"surah":2,"verses":[19],"references":[{"surah":2,"verses":[19]}],"verseLabel":"البقرة: 19","question":"ما الذي يصوره قوله: ﴿حذر الموت﴾ بعد جعل الأصابع في الآذان؟","answer":"يبين أن شدة حيرتهم وخوفهم أوهمتهم أن وضع الأصابع في الآذان قد يدفع عنهم الموت؛ فبلغ بهم الهلع أن بالغوا في سد المسامع فرارًا من الصواعق.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص234، تحت «سر جمع (الأصابع)»","url":""}]},{"id":"s2-76","number":76,"surah":2,"verses":[19],"references":[{"surah":2,"verses":[19]}],"verseLabel":"البقرة: 19","question":"كيف تُفهم إحاطة الله بالكافرين في قوله ﴿والله محيط بالكافرين﴾؟","answer":"الله محيط بهم قدرةً وعلمًا؛ فلا يفوتونه ولا يعجزونه، ولا ينجيهم من إحاطته ما يتخذونه من وسائل الفرار من الهلاك.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص230، تحت عنوان «المعنى الإجمالي»","url":""}]},{"id":"s2-1480","number":1480,"surah":2,"verses":[19],"references":[{"surah":2,"verses":[19]}],"verseLabel":"البقرة: 19","question":"لماذا قيل ﴿والله محيط بالكافرين﴾ ولم يقل: «محيط بهم»؟","answer":"إظهار وصف الكفر بدل الضمير يزيد الترهيب، ويبيّن سبب استحقاقهم العذاب، وهو كفرهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص234، تحت عنوان «نكتة وضع المظهر موقع المضمر»","url":""}]},{"id":"s2-77","number":77,"surah":2,"verses":[20],"references":[{"surah":2,"verses":[20]}],"verseLabel":"البقرة: 20","question":"ما أثر التعبير بالمضارع في قوله: ﴿يكاد البرق يخطف أبصارهم﴾؟","answer":"جاء ﴿يكاد﴾ مضارعًا لاستحضار قوة البرق وأثره في سلب الأبصار، وجاء ﴿يخطف﴾ مضارعًا لأنه خبر فعل المقاربة والمقصود بيان قرب وقوع الخطف.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص235–236، تحت «إيثار استعمال صيغة الفعل المضارع»","url":""}]},{"id":"s2-78","number":78,"surah":2,"verses":[20],"references":[{"surah":2,"verses":[20]}],"verseLabel":"البقرة: 20","question":"ما سرّ التعبير في قوله تعالى: ﴿كلما أضاء لهم مشوا فيه وإذا أظلم عليهم قاموا﴾، فاستعملت ﴿كلما﴾ مع الضوء و﴿إذا﴾ مع الظلمة؟","answer":"تدل ﴿كلما﴾ على حرصهم على انتهاز كل فرصة للمشي والمضي؛ فهم يترقبون أدنى فرصة للهرب. أما ﴿إذا﴾ فتفيد تحقق توقفهم عن المشي عند الإظلام.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص236، تحت «اختيار الأدوات النحوية في البلاغة القرآنية»","url":""}]},{"id":"s2-79","number":79,"surah":2,"verses":[20],"references":[{"surah":2,"verses":[20]}],"verseLabel":"البقرة: 20","question":"ما سرّ التعبير بقوله تعالى: في الضوء: ﴿أضاء لهم﴾، وفي الظلمة: ﴿أظلم عليهم﴾؟","answer":"جاءت المقابلة بين ﴿لهم﴾ و﴿عليهم﴾؛ فالضوء منفعة لهم، والإظلام عقوبة واقعة عليهم. وتتكامل معها المقابلة بين ﴿أضاء﴾ و﴿أظلم﴾، وبين ﴿مشوا﴾ و﴿قاموا﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص237، تحت «سر التعبير بفعل ﴿أضاء﴾ دون مرادفاته»","url":""}]},{"id":"s2-80","number":80,"surah":2,"verses":[20],"references":[{"surah":2,"verses":[20]}],"verseLabel":"البقرة: 20","question":"كيف قوّت المقابلات صورة المنافقين في قوله: ﴿كلما أضاء لهم مشوا فيه وإذا أظلم عليهم قاموا﴾؟","answer":"قابل التعبير بين ثلاثة أزواج: ﴿أضاء﴾ و﴿أظلم﴾، و﴿لهم﴾ و﴿عليهم﴾، و﴿مشوا﴾ و﴿قاموا﴾؛ فاجتماع هذه المقابلات يدل على شدة ما هم فيه من الظلمة والمخاوف.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص237، تحت «سر التعبير بفعل ﴿أضاء﴾ دون مرادفاته»","url":""}]},{"id":"s2-81","number":81,"surah":2,"verses":[20],"references":[{"surah":2,"verses":[20]}],"verseLabel":"البقرة: 20","question":"لماذا حُذف مفعول المشيئة في قوله: ﴿ولو شاء الله لذهب بسمعهم وأبصارهم﴾؟","answer":"حذف مفعول المشيئة بعد الشرط شائع لدلالة الجزاء عليه؛ أي: لو شاء الله إذهاب سمعهم لذهب به. والحذف يشوق المتلقي إلى معرفة الجواب، فإذا جاء وقع على نفس مستشرفة فتمكن منها.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص238، تحت «بلاغة حذف مفعول المشيئة»","url":""}]},{"id":"s2-82","number":82,"surah":2,"verses":[20],"references":[{"surah":2,"verses":[20]}],"verseLabel":"البقرة: 20","question":"ما سرّ إفراد السمع وجُمعت الأبصار في ختام المثل؟","answer":"لأن السمع مصدر، والمصادر لا يحسن جمعها، والأبصار يراد بها الأعين الباصرة. ويلائم الجمع سياق المثل؛ فالإضاءة والإظلام والمشي والقيام من توابع البصر المتكررة المتفاوتة، فتعددت متعلقاته، بخلاف السمع فهو واحد باعتبار المسموع والسامع.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص238، تحت «بلاغة الجمع والإفراد في المثل القرآني»","url":""}]},{"id":"s2-83","number":83,"surah":2,"verses":[20],"references":[{"surah":2,"verses":[20]}],"verseLabel":"البقرة: 20","question":"ما سرّ ختم المثل بقوله: ﴿إن الله على كل شيء قدير﴾؟","answer":"جاءت الفاصلة مؤكدة لمضمون المثل ومبرزة قدرة الله على كل شيء؛ فتؤكد قدرته على إذهاب السمع والأبصار، وتتضمن التهديد والوعيد لمن يصر على باطله ونفاقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص239، تحت «بلاغة الفصل بالفاصلة»","url":""}]},{"id":"s2-84","number":84,"surah":2,"verses":[21],"references":[{"surah":2,"verses":[21]}],"verseLabel":"البقرة: 21","question":"ما مناسبة الانتقال من وصف المؤمنين والكافرين والمنافقين إلى قوله: ﴿يا أيها الناس اعبدوا ربكم﴾؟","answer":"بعد أن ذكر أحوال الأصناف الثلاثة وضرب الأمثال، صلح المقام لخطابهم جميعًا بما ينفعهم إرشادًا ورحمة. ولم يمنع سوء صنيع الكافرين والمنافقين من إعادة إرشادهم ووعظهم؛ ليعلموا أن الإغلاظ عليهم كان حرصًا على صلاحهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص241، تحت «مناسبة الآيتين لما قبلهما»","url":""}]},{"id":"s2-85","number":85,"surah":2,"verses":[21],"references":[{"surah":2,"verses":[21]}],"verseLabel":"البقرة: 21","question":"ما سرّ مجيء النداء عامًا بلفظ ﴿الناس﴾؟","answer":"لأن الخطاب لجميع الناس: مؤمنهم وكافرهم، وقد أُمروا جميعًا بعبادة الله ونُهوا عن الإشراك به. وهو أول نداء في القرآن، يشمل الإنس والجن على القول بعموم لفظ الناس.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص244، تحت «معنى اللام في ﴿الناس﴾»","url":""}]},{"id":"s2-86","number":86,"surah":2,"verses":[21],"references":[{"surah":2,"verses":[21]}],"verseLabel":"البقرة: 21","question":"ما سرّ التعبير في قوله تعالى: ﴿اعبدوا ربكم﴾ باسم الربوبية؟","answer":"لأن اسم الرب يشعر بالتربية بالإحسان والإنعام، وفي ذلك تهييج للمخاطبين على امتثال الأمر. وفيه أيضًا استدلال بربوبيته على استحقاقه العبادة وألوهيته.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص245، تحت «إيثار عنوان الربوبية على الألوهية»","url":""}]},{"id":"s2-87","number":87,"surah":2,"verses":[21],"references":[{"surah":2,"verses":[21]}],"verseLabel":"البقرة: 21","question":"ما فائدة وصف الرب بقوله: ﴿الذي خلقكم والذين من قبلكم﴾؟","answer":"أفاد الوصف وصلته زيادة بيان موجب العبادة، وهو خلق المخاطبين ومن قبلهم، وزاد بيان ما أفادته إضافة ﴿ربكم﴾ من اختصاص الله باستحقاق العبادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص246، تحت «نكتة الوصف: زيادة البيان»","url":""}]},{"id":"s2-88","number":88,"surah":2,"verses":[21],"references":[{"surah":2,"verses":[21]}],"verseLabel":"البقرة: 21","question":"ما فائدة ﴿من﴾ في قوله: ﴿والذين من قبلكم﴾؟","answer":"أفادت توكيد معنى القبلية وتقويته، وأشارت إلى أول الموصوفين بها لأن من معانيها الابتداء. فذِكر الحاضرين وأول المخلوقين يستحضر ما بينهما، فيجمع الخطاب البشرية من مبدئها إلى منتهاها.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص246، تحت «فائدة دخول حرف الابتداء في صلة الموصول»","url":""}]},{"id":"s2-89","number":89,"surah":2,"verses":[21],"references":[{"surah":2,"verses":[21]}],"verseLabel":"البقرة: 21","question":"ما صلة ﴿لعلكم تتقون﴾ بالأمر ﴿اعبدوا ربكم﴾؟","answer":"من توجيهها أنها تعليل للأمر بالعبادة؛ أي اعبدوا الله لتحترزوا عن عقابه. فالعبادة امتثال لأمره واجتناب لنهيه، وهي طريق الوقاية من العقاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص246–247، تحت عنوان «بلاغة التصدير»","url":""}]},{"id":"s2-1481","number":1481,"surah":2,"verses":[21],"references":[{"surah":2,"verses":[21]}],"verseLabel":"البقرة: 21","question":"لماذا لم يُذكر ما يتقونه في قوله ﴿لعلكم تتقون﴾؟","answer":"حذف المفعول يوسّع المعنى: فيصح تقدير عقابه، ويصح إرادة جميع ما أُمر العبد باتقائه. ويحتمل أن يُنظر إلى حصول التقوى نفسها دون تقدير مفعول؛ وهذه الأوجه متوافقة في المحصلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص247، تحت عنوان «فائدة حذف المفعول»","url":""}]},{"id":"s2-90","number":90,"surah":2,"verses":[22],"references":[{"surah":2,"verses":[22]}],"verseLabel":"البقرة: 22","question":"ما وجه تشبيه الأرض بالفراش والسماء بالبناء؟","answer":"شُبهت الأرض بالفراش للتمكن من الاستقرار عليها والانتفاع والراحة والسهولة، وشُبهت السماء بالبناء للوقاية من الأضرار النازلة؛ فكما يقي البناء مما يأتي من فوق تقي السماء أضرارًا نازلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص249، تحت «براعة التشبيه البليغ»","url":""}]},{"id":"s2-91","number":91,"surah":2,"verses":[22],"references":[{"surah":2,"verses":[22]}],"verseLabel":"البقرة: 22","question":"لماذا أُظهر لفظ السماء في قوله: ﴿وأنزل من السماء ماء﴾ بعد ذكرها، ولم يقل: وأنزل منها؟","answer":"أُظهر لفظ السماء لاختلاف المراد بالسماءين: فالأولى هي البناء الذي يظهر للناظر أزرق نهارًا، والثانية يراد بها السحاب الذي ينزل منه الماء.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص249، تحت «نكتة وضع المظهر موقع المضمر»","url":""}]},{"id":"s2-92","number":92,"surah":2,"verses":[22],"references":[{"surah":2,"verses":[22]}],"verseLabel":"البقرة: 22","question":"ما سرّ التعبير في قوله تعالى: ﴿الثمرات﴾ ولم يقل: الثمار أو الثمر؟","answer":"لأن المقصود بالثمرة جماعة الثمر؛ فـ﴿الثمرات﴾ أفراد، وكل فرد منها يشتمل على ثمار، ولذلك تفيد من الكثرة ما لا تفيده ﴿الثمار﴾ أو ﴿الثمر﴾. ثم إن الجمع المحلى باللام يخرج عن حد القلة، فلا يلزم أن يراد به عدد قليل.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص250، تحت «التعبير بالثمرات دون الثمار أو الثمر»","url":""}]},{"id":"s2-93","number":93,"surah":2,"verses":[22],"references":[{"surah":2,"verses":[22]}],"verseLabel":"البقرة: 22","question":"لماذا أُظهر اسم الله في قوله: ﴿فلا تجعلوا لله أندادًا﴾، ولم يقل: فلا تجعلوا له أندادًا؟","answer":"أُظهر اسم الله زيادةً في التقرير، ولتعيين المعبود بالذات بعد أن عُيّن بالصفات السابقة من الخلق والإنعام. وفي ذكر اسم الألوهية تعليل للنهي عن الشرك وبيان استحالة الشركة معه.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص250–251، تحت «إظهار الاسم الأحسن ﴿الله﴾ زيادة في التقرير وتعليل للحكم بوصف الألوهية»","url":""}]},{"id":"s2-94","number":94,"surah":2,"verses":[23],"references":[{"surah":2,"verses":[23]}],"verseLabel":"البقرة: 23","question":"لماذا عُبر بالريب دون الشك في قوله: ﴿وإن كنتم في ريب﴾؟","answer":"للتنبيه على أن جزمهم بمنزلة الريب المستضعف؛ لكمال وضوح أدلة الإعجاز وقوتها، أو للإشارة إلى أن أقصى ما يمكن أن يصدر منهم هو الريب وإن بلغوا غاية المكابرة والمعاندة.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص255، تحت «اختيار المفردة وأثره في بيان دقائق النظم»","url":""}]},{"id":"s2-95","number":95,"surah":2,"verses":[23],"references":[{"surah":2,"verses":[23]}],"verseLabel":"البقرة: 23","question":"ما دلالة قوله: ﴿إن كنتم في ريب﴾، فجعلهم كأنهم داخل الريب؟","answer":"يومئ حرف الجر ﴿في﴾ إلى انغماسهم في الريب وإحاطته بهم إحاطة الظرف بالمظروف. ومع ذلك فالريب واقع في عقولهم الفاسدة، لا في ذات القرآن الكريم، وفي التعبير مبالغة في تنزيه القرآن عن شائبة الريب.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص255، تحت «التعبير بـ﴿وإن كنتم في ريب﴾ دون (وإن ارتبتم)»","url":""}]},{"id":"s2-96","number":96,"surah":2,"verses":[23],"references":[{"surah":2,"verses":[23]}],"verseLabel":"البقرة: 23","question":"ما الفرق بين التعبير بـ﴿نزّلنا﴾ والتعبير بـ«أنزلنا»؟","answer":"التنزيل يكون لما ينزل مفرّقًا أو تدريجيًا، أما الإنزال فلما يكون دفعة واحدة؛ وقد نزل القرآن تدريجيًا بحسب الوقائع والأحداث.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص265، تحت «نزّل وأنزل»","url":""}]},{"id":"s2-97","number":97,"surah":2,"verses":[23],"references":[{"surah":2,"verses":[23]}],"verseLabel":"البقرة: 23","question":"ما دلالة تنكير ﴿سورة﴾ في قوله: ﴿فأتوا بسورة من مثله﴾؟","answer":"نُكرت ﴿سورة﴾ لبيان النوع، والإيماء إلى اتساع مجال التحدي؛ فالمطلوب الإتيان بمثل أي سورة من سور القرآن، وفي عجزهم عن ذلك غاية التبكيت والتخجيل.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص257، تحت «تنكير (سورة) لبيان النوع»","url":""}]},{"id":"s2-98","number":98,"surah":2,"verses":[23],"references":[{"surah":2,"verses":[23]}],"verseLabel":"البقرة: 23","question":"ما الغرض من الأمر ﴿وادعوا شهداءكم﴾ في تحدي المعاندين؟","answer":"هو للتعجيز والإفحام؛ أُرخي لهم العنان ليطلبوا من يشهد لهم، استدراجًا إلى غاية التبكيت، مع بلوغ إعجاز القرآن من الظهور ما لا يبقى معه سبيل إلى إنكاره.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص259، تحت عنوان «دلالة الأمر ﴿وادعوا شهداءكم﴾ على التعجيز والاستدراج إلى غاية التبكيت»","url":""}]},{"id":"s2-1482","number":1482,"surah":2,"verses":[23],"references":[{"surah":2,"verses":[23]}],"verseLabel":"البقرة: 23","question":"ماذا أضاف ﴿من دون الله﴾ إلى تحديهم بقوله ﴿وادعوا شهداءكم﴾؟","answer":"أُدمج توبيخهم على شركهم في أثناء تعجيزهم عن معارضة القرآن؛ فاجتمع غرض التحدي وغرض التوبيخ دون خروج عن سياق الكلام.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص259، تحت عنوان «بلاغة إدماج قوله تعالى: ﴿من دون الله﴾»","url":""}]},{"id":"s2-99","number":99,"surah":2,"verses":[23],"references":[{"surah":2,"verses":[23]},{"surah":10,"verses":[38]}],"verseLabel":"البقرة: 23، ويونس: 38","question":"ما سرّ اختلاف التعبير بين قوله تعالى في البقرة: ﴿بسورة من مثله﴾، وقوله تعالى في يونس: ﴿بسورة مثله﴾ من غير ﴿من﴾؟","answer":"وقع التحدي في يونس بسورة مماثلة للقرآن، أما آية البقرة ففيها تنزّل معهم من الإتيان بالمماثل إلى الإتيان بشيء مما يماثل؛ أي شيء من جنس المماثلة على وجه التقريب. وكانت آية البقرة آخر آيات التحدي الأربع نزولًا، فناسب زيادة ﴿من﴾ إظهارًا لعجزهم وتبكيتًا لهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص258، تحت «توجيه المتشابه اللفظي بين سورة البقرة وسورة يونس»","url":""}]},{"id":"s2-100","number":100,"surah":2,"verses":[24],"references":[{"surah":2,"verses":[24]}],"verseLabel":"البقرة: 24","question":"ما فائدة الاعتراض بقوله: ﴿ولن تفعلوا﴾ بين الشرط وجوابه؟","answer":"جيء به للمسارعة إلى بيان عجزهم وتسجيل عجزهم المطلق عن معارضة القرآن؛ فهو اعتراض يؤكد أنهم لن يتمكنوا مما طُلب منهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص261، تحت «الاعتراض في قوله: ﴿ولن تفعلوا﴾ لتعجيل بيان عجزهم، وأن عجزهم عن المعارضة مطلق»","url":""}]},{"id":"s2-101","number":101,"surah":2,"verses":[24],"references":[{"surah":2,"verses":[24]}],"verseLabel":"البقرة: 24","question":"ما دلالة قرن الناس بالحجارة في وقود النار؟","answer":"في وصف النار بأن وقودها الناس والحجارة زيادة تهويل وتفظيع. وقرن الكافرين بالحجارة لأنهم لازموها في الدنيا حين نحتوها أصنامًا وعبدوها من دون الله، فكان جزاؤهم أن يُقرنوا بها في الآخرة؛ جزاءً من جنس العمل وزيادةً في حسرتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص262، تحت «نكتة أسلوب الجمع»","url":""}]},{"id":"s2-102","number":102,"surah":2,"verses":[25],"references":[{"surah":2,"verses":[25]}],"verseLabel":"البقرة: 25","question":"ما مناسبة ذكر جزاء المؤمنين بعد وعيد الكافرين؟","answer":"لما ذكر جزاء أعدائه من الكافرين بسبب موقفهم من القرآن، ناسب أن يذكر جزاء أوليائه من المؤمنين به، على طريقة القرآن في الجمع بين الترغيب والترهيب؛ ليتبين حال الفريقين في الآخرة بعد بيان حالهما في الدنيا.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص266، تحت «مناسبة الآية لما قبلها»","url":""}]},{"id":"s2-103","number":103,"surah":2,"verses":[25],"references":[{"surah":2,"verses":[25]}],"verseLabel":"البقرة: 25","question":"ما سرّ التعبير عن أهل البشارة بالموصول: ﴿الذين آمنوا وعملوا الصالحات﴾؟","answer":"للتنبيه على أن سبب التبشير هو ما جاءت به الصلة: الإيمان والعمل الصالح. ففي التعبير بالموصول إشعار بالسببية، وثناء عليهم بأعمالهم القلبية والبدنية؛ إذ البشارة نتيجة لها.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص269، تحت «سر التعبير بالاسم الموصول دون الظاهر»","url":""}]},{"id":"s2-104","number":104,"surah":2,"verses":[25],"references":[{"surah":2,"verses":[25]}],"verseLabel":"البقرة: 25","question":"ما سرّ مجيء الأمر ﴿وبشّر﴾ مفردًا؟","answer":"يحتمل أن يكون الخطاب خاصًا بالنبي ﷺ، وهو الأصل في الخطاب، وفي اختصاصه بالبشارة تفخيم لأمرها وزيادة وثوق بها. ويحتمل أن يكون عامًا لكل من يتأتى خطابه؛ ليقوم كل قادر بهذه البشارة. والوجهان متكاملان: يبدأ النبي ﷺ وتقتدي به أمته.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص268–269، تحت «نكتة إفراد الخطاب في قوله: ﴿وبشر﴾»","url":""}]},{"id":"s2-105","number":105,"surah":2,"verses":[25],"references":[{"surah":2,"verses":[25]}],"verseLabel":"البقرة: 25","question":"ما سرّ التعبير في قوله تعالى: ﴿آمنوا وعملوا الصالحات﴾ بالماضي؟","answer":"لإفادة تحقق الإيمان والعمل الصالح لدى المؤمنين؛ فالعبارة إخبار عن إيمان وأعمال متحققة، لا عن تجدد ذلك منهم، وفيها تأكيد لسبب التبشير وغاية في الثناء الحسن.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص269، تحت «إيثار الماضي على المضارع لتأكيد سبب التبشير في تحقق الإيمان والعمل الصالح»","url":""}]},{"id":"s2-106","number":106,"surah":2,"verses":[25],"references":[{"surah":2,"verses":[25]}],"verseLabel":"البقرة: 25","question":"كيف يُفهم قول أهل الجنة عن الثمر: ﴿هَذَا الَّذِي رُزِقْنَا مِنْ قَبْلُ﴾، مع أنه ليس عينه؟","answer":"التقدير: «هذا مثل الذي رزقنا من قبل»، وحُذفت كلمة ﴿مثل﴾ لاستحكام الشبه حتى كأن هذه الثمرة هي تلك؛ فثمر الجنة يشبه بعضه بعضًا في اللون والشكل، ويختلف في الطعم.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص275–276، تحت «نكتة حذف كلمة (مثل)»","url":""}]},{"id":"s2-107","number":107,"surah":2,"verses":[25],"references":[{"surah":2,"verses":[25]}],"verseLabel":"البقرة: 25","question":"لماذا بُني الفعل للمفعول في قوله: ﴿وأُتوا به متشابهًا﴾؟","answer":"حُذف الفاعل للعلم به، وهم الولدان والخدم بأمر الله تعالى، ولتوجيه النظر إلى الحدث وهو الإتيان وإلى المأتي به وهو الثمر. وفي إظهار الفعل دون الفاعل مزيد تكريم لأهل الجنة.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص276، تحت «نكتة بناء الفعل ﴿وأتوا﴾»","url":""}]},{"id":"s2-108","number":108,"surah":2,"verses":[25],"references":[{"surah":2,"verses":[25]}],"verseLabel":"البقرة: 25","question":"ممّ طُهرت أزواج أهل الجنة في قوله: ﴿أزواج مطهرة﴾؟","answer":"طُهرت من كل ألوان الدنس الحسي، كالبول والحيض، والمعنوي، كالكذب وسوء الخلق.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص267–268، تحت عنوان «المعنى الإجمالي»، فقرة أزواج أهل الجنة","url":""}]},{"id":"s2-109","number":109,"surah":2,"verses":[25],"references":[{"surah":2,"verses":[25]},{"surah":9,"verses":[100]}],"verseLabel":"البقرة: 25، والتوبة: 100","question":"ما الفرق بين ﴿تجري من تحتها الأنهار﴾ و﴿تجري تحتها الأنهار﴾؟","answer":"قوله ﴿تجري تحتها الأنهار﴾ يخبر عن مرور الأنهار تحت الأشجار، أما ﴿تجري من تحتها الأنهار﴾ فيفيد أن الماء ينبع ابتداءً من تحتها ثم يجري تحت أشجارها؛ فموضع أثبت ابتداء الجري، والآخر أثبت المرور.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص272–273، تحت «توجيه المتشابه اللفظي»","url":""}]},{"id":"s2-110","number":110,"surah":2,"verses":[26],"references":[{"surah":2,"verses":[26]}],"verseLabel":"البقرة: 26","question":"ما مناسبة ذكر المثل بالبعوضة بعد تحدي المعاندين بالقرآن؟","answer":"لما عجز المعاندون عن التحدي أخذوا يطعنون في القرآن بسبب اشتماله على أمثال بما صغر كالذباب والبعوض؛ فجاءت الآية تنزه الوحي عن طعنهم، وتقرر أن حكمة المثل لا يمنعها صغر الشيء المضروب به.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص278، تحت «مناسبة الآية لما قبلها»","url":""}]},{"id":"s2-111","number":111,"surah":2,"verses":[26],"references":[{"surah":2,"verses":[26]}],"verseLabel":"البقرة: 26","question":"ما المراد بقوله: ﴿فما فوقها﴾: ما هو أكبر من البعوضة أم أصغر؟","answer":"يحتمل أن يراد ما فوقها في الحجم، أي ما هو أكبر منها، ويحتمل ما فوقها في الحقارة والصغر، أي ما هو أصغر منها. وعلى الوجهين يفيد القيد العموم: أن الله لا يستحيي أن يضرب مثلًا بما صغر أو كبر.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص282، تحت «أثر القيد في إفادة التعميم والوصف»","url":""}]},{"id":"s2-112","number":112,"surah":2,"verses":[26],"references":[{"surah":2,"verses":[26]}],"verseLabel":"البقرة: 26","question":"ما سرّ قول المؤمنين: ﴿أنه الحق من ربهم﴾ باسم الربوبية؟","answer":"للإشارة إلى أن هذا المثل رحمة من الله ونعمة للمؤمنين؛ فمن ربوبيته الخاصة بهم أنه يربيهم بالإيمان، ويوفقهم له ويكمله لهم، ويدفع عنهم الصوارف الحائلة بينهم وبينه.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص283–284، تحت «اختيار عنوان الربوبية للاعتراف بفضل الله ورعايته لعباده المؤمنين»","url":""}]},{"id":"s2-113","number":113,"surah":2,"verses":[26],"references":[{"surah":2,"verses":[26]}],"verseLabel":"البقرة: 26","question":"كيف يكون المثل الواحد سببًا لهداية قوم وإضلال آخرين؟","answer":"لأن المواقف منه تختلف: فمن يطلب الحق ويقصد اتباعه يهتدي به، ومن لا يطلب الهدى والحق يكون المثل سببًا لإضلاله؛ ولا يضل الله به إلا الخارجين عن طاعته.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص280–281، تحت عنوان «المعنى الإجمالي»","url":""}]},{"id":"s2-1483","number":1483,"surah":2,"verses":[26],"references":[{"surah":2,"verses":[26]}],"verseLabel":"البقرة: 26","question":"لماذا حُصر الإضلال بالمثل في الفاسقين بقوله ﴿وما يضل به إلا الفاسقين﴾؟","answer":"يبيّن القصر أن الفسق سبب كفرهم، وأن كفرهم حجبهم عن التفكر والتدبر في المثل حتى أنكروه وجحدوه؛ فنفى الإضلال به عن غيرهم ثم حصره فيهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص287، تحت عنوان «القصر بأسلوب النفي والإثبات لحصره في الفاسقين»","url":""}]},{"id":"s2-114","number":114,"surah":2,"verses":[27],"references":[{"surah":2,"verses":[27]}],"verseLabel":"البقرة: 27","question":"لماذا جاء نقض العهد بالمضارع في ﴿الذين ينقضون عهد الله﴾؟","answer":"ليصوّر تكرر نقضهم مرة بعد أخرى واستمرارهم عليه وعدم توانيهم عنه؛ وفي استحضار هذا التجدد تصوير لبشاعة نقضهم عهد الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص292، تحت عنوان «التعبير بصيغة المضارع لتصوير بشاعة نقض الفاسقين عهودهم»","url":""}]},{"id":"s2-1484","number":1484,"surah":2,"verses":[27],"references":[{"surah":2,"verses":[27]}],"verseLabel":"البقرة: 27","question":"ماذا يفيد المضارع في ﴿ويفسدون في الأرض﴾؟","answer":"يفيد تجدد الإفساد وتكرر وقوعه واستمرارهم عليه؛ فالوصف يصوّر سلوكًا متجددًا، لا حادثة انقضت.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص295، تحت عنوان «دلالة الفعل المضارع ﴿ويفسدون﴾ لبيان تكرر وقوعه»","url":""}]},{"id":"s2-115","number":115,"surah":2,"verses":[27],"references":[{"surah":2,"verses":[27]}],"verseLabel":"البقرة: 27","question":"ما سرّ التعبير في قوله تعالى: ﴿ما أمر الله به أن يوصل﴾ بـ﴿ما﴾؟","answer":"لأن ﴿ما﴾ أعم من «الذي»، فتفيد قطعهم كل ما أمر الله بوصله. وقيل: المراد أصلًا قطع الرحم، ويدخل غيره بطريق الأولى؛ غير أن العموم أنسب بالسياق، وهو يدل على عدم مراعاة أي حق يتصور أن يأمر الله بوصله.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص294، تحت «سر التعبير بـ(ما) دون الاسم الموصول»","url":""}]},{"id":"s2-116","number":116,"surah":2,"verses":[27],"references":[{"surah":2,"verses":[27]}],"verseLabel":"البقرة: 27","question":"كيف يصوّر القصر عظم الخسارة في ﴿أولئك هم الخاسرون﴾؟","answer":"قُصرت الخسارة عليهم مبالغةً في عظمها، حتى كأن خسارة غيرهم ليست شيئًا إلى جانبها. وهو قصر قلب يرد اعتقادهم أنهم رابحون، ويثبت لهم الخسران.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص297، تحت عنوان «فائدة القصر الادعائي»","url":""}]},{"id":"s2-1485","number":1485,"surah":2,"verses":[27],"references":[{"surah":2,"verses":[27]}],"verseLabel":"البقرة: 27","question":"ماذا يزيد ضمير ﴿هم﴾ في ﴿أولئك هم الخاسرون﴾؟","answer":"يؤكد القصر ويقوّيه؛ فالقصر مستفاد أصلًا من تعريف طرفي الجملة. واجتمع الضمير مع الجملة الاسمية لتقوية الحكم بثبوت الخسران لمن اتصف بهذه الصفات.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص297، تحت عنوان «فائدة التأكيد بضمير الفصل واسمية الجملة»","url":""}]},{"id":"s2-117","number":117,"surah":2,"verses":[27],"references":[{"surah":2,"verses":[27]},{"surah":13,"verses":[25]}],"verseLabel":"البقرة: 27، والرعد: 25","question":"ما سرّ مجيء ﴿الذين ينقضون عهد الله﴾ في البقرة بلا واو، وجاء في الرعد بالواو؟","answer":"في البقرة جاء الموصول بيانًا للفاسقين المذكورين قبله، فلم يحتج إلى الواو. أما في الرعد فانتقل السياق من صفات أولي الألباب الموفين بالعهد إلى أضدادهم الناقضين له، فعُطف الفريق المقابل بالواو.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص155، تحت «دلالة الواو في قوله: «والذين ينقضون»»","url":""}]},{"id":"s2-118","number":118,"surah":2,"verses":[27],"references":[{"surah":2,"verses":[27]},{"surah":13,"verses":[25]}],"verseLabel":"البقرة: 27، والرعد: 25","question":"ما سرّ ختم ناقضو العهد في البقرة بـ﴿الخاسرون﴾، وفي الرعد بـ﴿لهم اللعنة ولهم سوء الدار﴾؟","answer":"خُتمت آية البقرة بـ﴿الخاسرون﴾ لمقابلة ﴿المفلحون﴾ في السياق القريب، وخُتمت آية الرعد بـ﴿لهم اللعنة ولهم سوء الدار﴾ لمقابلة ما سبق للمؤمنين من ﴿عقبى الدار﴾؛ فناسبت كل خاتمة مقابلة سياقها.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص162–163، تحت «سر اختلاف الفاصلة بين آيتي البقرة والرعد»","url":""}]},{"id":"s2-119","number":119,"surah":2,"verses":[28],"references":[{"surah":2,"verses":[28]}],"verseLabel":"البقرة: 28","question":"ما سرّ التعبير في قوله تعالى: ﴿كيف تكفرون بالله﴾ ولم يقل: «أتكفرون بالله»؟","answer":"لأن ﴿كيف﴾ تتناول جميع أحوال الشيء، فدل الاستفهام بها على إنكار أن يكون لكفرهم أي حال يصح وقوعه عليها؛ ولذلك كانت أبلغ وأعم في الإنكار من الهمزة. ويحمل الاستفهام كذلك على التعجب والتعجيب والتوبيخ.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص302–303، تحت «اختيار الاستفهام بـ﴿كيف﴾ لاشتمالها جميع أحوال الشيء»","url":""}]},{"id":"s2-120","number":120,"surah":2,"verses":[28],"references":[{"surah":2,"verses":[28]}],"verseLabel":"البقرة: 28","question":"لماذا عُطف الإحياء الأول بالفاء، وما بعده بـ﴿ثم﴾؟","answer":"أفادت الفاء التعقيب؛ لأن المخاطبين لم يشعروا بحالهم قبل الإحياء الأول، بل وجدوا أنفسهم أحياء. أما الإماتة والإحياء الثاني والرجوع إلى الله فكل طور منها متراخٍ عما قبله، فناسبه حرف ﴿ثم﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص304، تحت «دقة البيان القرآني في استعمال الحروف»","url":""}]},{"id":"s2-121","number":121,"surah":2,"verses":[28],"references":[{"surah":2,"verses":[28]}],"verseLabel":"البقرة: 28","question":"ما دلالة تقديم ﴿إليه﴾ في قوله: ﴿ثم إليه ترجعون﴾؟","answer":"قُدّم الجار والمجرور لإفادة القصر؛ فالرجوع يوم القيامة إلى الله وحده للحساب والجزاء. وفيه إلزام لمن أنكر البعث، وقطع للطمع في الانتفاع بما عُبد من دون الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص305، تحت «فائدة القصر في قوله: ﴿إليه ترجعون﴾»","url":""}]},{"id":"s2-122","number":122,"surah":2,"verses":[28],"references":[{"surah":2,"verses":[28]},{"surah":29,"verses":[17]}],"verseLabel":"البقرة: 28، والعنكبوت: 17","question":"ما سرّ اختلاف التعبير بين قوله تعالى في البقرة: ﴿ثم إليه ترجعون﴾، وفي العنكبوت: ﴿إليه ترجعون﴾ بلا ﴿ثم﴾؟","answer":"في البقرة عُطفت أطوار الخلق والإماتة والإحياء والرجوع بـ﴿ثم﴾ الدالة على التراخي بين الأطوار؛ أما في العنكبوت فجاء ﴿إليه ترجعون﴾ عقب الأمر بالعبادة والشكر تقريرًا لمرجعهم إليه، من غير تعداد تلك الأطوار. وتقديم ﴿إليه﴾ في الموضعين للحصر.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص166–167، تحت «توجيه المتشابه اللفظي بين صيغتين»","url":""}]},{"id":"s2-123","number":123,"surah":2,"verses":[29],"references":[{"surah":2,"verses":[29]}],"verseLabel":"البقرة: 29","question":"ما دلالة الانتقال من خلق ما في الأرض إلى تسوية السماوات؟","answer":"هو انتقال من الاستدلال بخلق الأرض إلى ما هو أعظم منه، وفيه ترقٍّ من الأدنى إلى الأعلى؛ لينتبه المخاطب بالمعلوم المشاهد إلى عظيم قدرة الخالق فيما لا يبلغه علمه.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص309–310، تحت «فائدة الترقي الرتبي»","url":""}]},{"id":"s2-124","number":124,"surah":2,"verses":[29],"references":[{"surah":2,"verses":[29]}],"verseLabel":"البقرة: 29","question":"ما دلالة تعدية ﴿استوى﴾ بـ﴿إلى﴾ في قوله: ﴿ثم استوى إلى السماء﴾؟","answer":"ضُمّن ﴿استوى﴾ معنى «قصد» مع بقاء دلالة العلو؛ فالمعنى: علا إلى السماء وقصد إليها. وقد عبّر بعض أهل التفسير عن ذلك بأن الاستواء تضمن معنى القصد والإقبال لأنه عُدي بـ﴿إلى﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص310، تحت «تضمين الفعل ﴿استوى﴾ معنى (قصد) مع بقاء دلالة العلو فيه»","url":""}]},{"id":"s2-125","number":125,"surah":2,"verses":[29],"references":[{"surah":2,"verses":[29]}],"verseLabel":"البقرة: 29","question":"كيف عاد ضمير الجمع في ﴿فسواهن﴾ على ﴿السماء﴾ المفردة لفظًا؟","answer":"لأن المراد بلفظ ﴿السماء﴾ الجنس؛ فهو مفرد في اللفظ، جمع في المعنى، ولذلك أعيد عليه الضمير مجموعًا في ﴿فسواهن﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص310، تحت «معنى اللام في كلمة ﴿السماء﴾»","url":""}]},{"id":"s2-126","number":126,"surah":2,"verses":[30],"references":[{"surah":2,"verses":[30]}],"verseLabel":"البقرة: 30","question":"كيف بيّن تعليم آدم الأسماء معنى قوله للملائكة ﴿إني أعلم ما لا تعلمون﴾؟","answer":"جاء قوله ﴿إني أعلم ما لا تعلمون﴾ دليلًا مجملًا على استحقاق هذا المخلوق الخلافة، ثم أتبعه تعليم آدم الأسماء دليلًا مفصلًا على فضيلته؛ فظهر للملائكة وجه من الحكمة في استخلافه.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص326، تحت عنوان «بلاغة عطف المفصل على المجمل»","url":""}]},{"id":"s2-127","number":127,"surah":2,"verses":[30],"references":[{"surah":2,"verses":[30]}],"verseLabel":"البقرة: 30","question":"ما دلالة اسم الفاعل ﴿جاعل﴾ في قوله: ﴿إني جاعل في الأرض خليفة﴾؟","answer":"اسم الفاعل في ﴿جاعل﴾ يدل على تحقق فعل الجعل وأنه كائن بلا شك، وفيه معنى العظمة والتمكن في الخطاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص317–318، تحت «اختيار اسم الفاعل لتوكيد الوقوع حتمًا»","url":""}]},{"id":"s2-128","number":128,"surah":2,"verses":[30],"references":[{"surah":2,"verses":[30]}],"verseLabel":"البقرة: 30","question":"كيف عرفت الملائكة أن الخليفة يفسد في الأرض ويسفك الدماء؟","answer":"لا تعيّن الموسوعة في الموضع المحال إليه طريق معرفتهم بذلك، فلا يصح نسبة الاحتمالات المذكورة إليها. والمثبت أن قولهم كان سؤالًا أباحه الله لهم، صادرًا عن التعجب واستبعاد تعلق الحكمة، وغرضه الاحتياط من الإفساد وسفك الدماء.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص319–324، تحت «فائدة الإخبار عن تعجب الملائكة»","url":""}]},{"id":"s2-129","number":129,"surah":2,"verses":[30],"references":[{"surah":2,"verses":[30]}],"verseLabel":"البقرة: 30","question":"ماذا يصور التعبير بـ﴿يسفك الدماء﴾؟","answer":"السفك هو صب الدم وإراقته؛ فالتعبير يصور القتل في مشهد محسوس، ويكشف بشاعة الإفساد الواقع بإزهاق الأنفس.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص320–321، تحت «براعة الإيجاز فيما يشبه الإطناب»","url":""}]},{"id":"s2-130","number":130,"surah":2,"verses":[30],"references":[{"surah":2,"verses":[30]}],"verseLabel":"البقرة: 30","question":"هل كان قول الملائكة: ﴿أتجعل فيها من يفسد فيها... ونحن نسبح بحمدك ونقدس لك﴾ اعتراضًا؟","answer":"لم يكن اعتراضًا على حكم الله، وإنما سؤالًا عن الحكمة وطلبًا للعلم؛ وذكروا تسبيحهم وتقديسهم في سياق السؤال عمن يقع منه الإفساد وسفك الدماء.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص319–324، تحت «فائدة الإخبار عن تعجب الملائكة»","url":""}]},{"id":"s2-131","number":131,"surah":2,"verses":[31],"references":[{"surah":2,"verses":[31]}],"verseLabel":"البقرة: 31","question":"ما دلالة قوله: ﴿وعلم آدم الأسماء كلها﴾؟","answer":"يدل على اختصاص آدم بعلم أسماء المسميات التي عرضت على الملائكة، وهو العلم الذي ظهر به فضله عليهم في هذا المقام. وعموم ﴿كلها﴾ يؤكد شمول ما علّمه الله منها.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص327، تحت «دلالة اللام في ﴿الأسماء﴾»","url":""}]},{"id":"s2-132","number":132,"surah":2,"verses":[31],"references":[{"surah":2,"verses":[31]}],"verseLabel":"البقرة: 31","question":"ما دلالة قوله للملائكة: ﴿أنبئوني بأسماء هؤلاء﴾؟","answer":"الإنباء إخبار عن أمر ذي شأن، فجاء مناسبًا لمقام إظهار العلم الذي اختص الله به آدم، وإقامة الحجة على أن علم الملائكة مقصور على ما علمهم الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص328–329، تحت «دلالة الأمر في ﴿أنبئوني﴾»","url":""}]},{"id":"s2-133","number":133,"surah":2,"verses":[33],"references":[{"surah":2,"verses":[33]}],"verseLabel":"البقرة: 33","question":"ما أثر التصريح باسم آدم في قوله: ﴿يا آدم أنبئهم بأسمائهم﴾؟","answer":"فيه تشريف لآدم وتنويه به في مشهد الملائكة، وإظهار لفضله بالعلم حين أُمر أن ينبئهم بما عجزوا عن الإنباء به.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص331، تحت «دلالة النداء في ﴿يا آدم﴾»","url":""}]},{"id":"s2-134","number":134,"surah":2,"verses":[33],"references":[{"surah":2,"verses":[33]}],"verseLabel":"البقرة: 33","question":"ما دلالة ﴿كنتم﴾ في قوله: ﴿وما كنتم تكتمون﴾؟","answer":"تدل ﴿كنتم﴾ على أن الكتمان كان سابقًا مستمرًا قبل ظهور ما أظهره الله في هذا المقام، لا أمرًا نشأ في لحظة الخطاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص333–334، تحت «نكتة ذكر (كان) في قوله: ﴿وما كنتم تكتمون﴾»","url":""}]},{"id":"s2-135","number":135,"surah":2,"verses":[34],"references":[{"surah":2,"verses":[34]}],"verseLabel":"البقرة: 34","question":"كيف أُمر الملائكة بالسجود لآدم مع أن العبادة لا تكون إلا لله؟","answer":"كان سجود الملائكة لآدم تحيةً أو احترامًا له وطاعةً لله تعالى، ولم يكن عبادةً لآدم.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص336، تحت عنوان «شرح المفردات»، مدخل ﴿اسجدوا﴾","url":""}]},{"id":"s2-136","number":136,"surah":2,"verses":[34],"references":[{"surah":2,"verses":[34]},{"surah":7,"verses":[11]}],"verseLabel":"البقرة: 34؛ الأعراف: 11","question":"ما سرّ التعبير في قوله تعالى: ﴿فسجدوا إلا إبليس﴾ مع أن إبليس ليس من الملائكة؟","answer":"يُوجَّه الاستثناء على الاتصال باعتبار أن إبليس كان بين الملائكة مغمورًا في جماعتهم، فشمله الأمر بالسجود؛ ولا يلزم من ذلك أن يكون من جنسهم. ويُوجَّه على الانقطاع باعتبار اختلاف جنسه عن الملائكة، فيكون المعنى: لكن إبليس لم يكن من الساجدين.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص773، تحت عنوان «نوع الاستثناء في قوله: ﴿إلا إبليس﴾»","url":""}]},{"id":"s2-137","number":137,"surah":2,"verses":[34],"references":[{"surah":2,"verses":[34]},{"surah":15,"verses":[29,30]}],"verseLabel":"البقرة: 34، والحجر: 29–30","question":"لماذا أكّد سجود الملائكة في الحجر بقوله: ﴿كلهم أجمعون﴾، ولم يأت هذا التوكيد في البقرة؟","answer":"سبق الأمر في البقرة بيان فضل آدم وتعليمه الأسماء وظهور علمه، فكان امتثال الملائكة مفهومًا من السياق. أما الحجر فسبق السجود وصف مادة خلق آدم من صلصال وحمإ مسنون، فناسب توكيد امتثال الملائكة جميعًا، وألا يتخلف منهم أحد بسبب النظر إلى مادة الخلق.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص339–340، تحت «توجيه المتشابه اللفظي»","url":""}]},{"id":"s2-138","number":138,"surah":2,"verses":[34],"references":[{"surah":2,"verses":[34]},{"surah":38,"verses":[74]}],"verseLabel":"البقرة: 34، وص: 74","question":"ماذا تكشف التعبيرات المختلفة عن موقف إبليس من السجود، ولماذا اكتفت سورة ص بقوله: ﴿واستكبر﴾؟","answer":"تكشف عدم السجود بوصفه الفعل الظاهر، والإباء بوصفه امتناعًا مقصودًا، والاستكبار بوصفه الدافع الباطن. وجمعت البقرة الإباء وعلته، أما سورة ص فاكتفت بالاستكبار لأن سياقها في التحذير من عزة الكافرين وشقاقهم، فناسب ذكر أصل الداء.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص656، تحت «توجيه المتشابه اللفظي»","url":""}]},{"id":"s2-139","number":139,"surah":2,"verses":[35],"references":[{"surah":2,"verses":[35]}],"verseLabel":"البقرة: 35","question":"كيف دل قوله ﴿وكلا منها رغدًا حيث شئتما﴾ على سعة الإباحة في الجنة؟","answer":"أُبيح لهما الأكل من مطاعم الجنة على سبيل الاتساع؛ ويؤكد ذلك وصف الأكل بأنه رغد، أي واسع هنيء، وإطلاق المكان بقوله ﴿حيث شئتما﴾، فالإذن عام فيما أُبيح لهما من مطاعمها.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص350، تحت عنوان «فن الاستخدام»","url":""}]},{"id":"s2-1486","number":1486,"surah":2,"verses":[35],"references":[{"surah":2,"verses":[35]}],"verseLabel":"البقرة: 35","question":"ما الذي يفيده حمل اللام في ﴿هذه الشجرة﴾ على العهد الحضوري؟","answer":"يفيد أن المنهي عنه شجرة معينة واحدة، وهو الوجه الذي استظهره الطيبي؛ لأنه أظهر في إزالة العذر وأبلغ في الدلالة على اتساع الانتفاع بسائر ثمر الجنة. وذكر المصدر أيضًا احتمال إرادة جنس الشجرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص352، تحت عنوان «اللام في ﴿الشجرة﴾ للعهد الحضوري»","url":""}]},{"id":"s2-140","number":140,"surah":2,"verses":[35],"references":[{"surah":2,"verses":[35]}],"verseLabel":"البقرة: 35","question":"ما سرّ مجيء النهي بقوله: ﴿ولا تقربا هذه الشجرة﴾، لا بالنهي عن الأكل منها؟","answer":"لأن النهي عن القرب أبلغ؛ فهو يمنع الأكل ويمنع مقدماته والأسباب الموصلة إليه، وفيه مبالغة في التحذير من موضع الفتنة.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص351، تحت «بلاغة الكناية»","url":""}]},{"id":"s2-141","number":141,"surah":2,"verses":[35],"references":[{"surah":2,"verses":[35]},{"surah":7,"verses":[19]}],"verseLabel":"البقرة: 35؛ الأعراف: 19","question":"ما سرّ اختلاف التعبير بين قوله تعالى في البقرة: ﴿وكلا منها رغدًا﴾، وفي الأعراف: ﴿فكلا من حيث شئتما﴾؟","answer":"سياق البقرة سياق امتنان وتعداد للنعم، فناسب العطف بالواو ليظهر الإسكان نعمة مستقلة والأكل نعمة أخرى، وناسب ذكر ﴿رغدًا﴾ لبيان زيادة النعمة. أما سياق الأعراف فيعرض كرامة آدم ويحذر ذريته من اتباع إبليس، فناسبه ترتيب الأكل على الإسكان بالفاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج13، ص44، تحت عنوان «مقام تعداد النعم يناسبه استقلال كل منها بالواو»","url":""}]},{"id":"s2-142","number":142,"surah":2,"verses":[36],"references":[{"surah":2,"verses":[36]}],"verseLabel":"البقرة: 36","question":"لماذا نُسبت زلة آدم وزوجه إلى الشيطان في قوله: ﴿فأزلهما الشيطان عنها﴾؟","answer":"معنى ﴿فأزلهما﴾ أنه حملهما على الزلل، وهو هنا العصيان؛ فنسب الإزلال إليه باعتباره الحامل عليه. وأصل الزلل في القدم، فاستعير للوقوع في الخطيئة بما يصور ضررها وينفّر منها.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص353، تحت عنوان «نكتة الاستعارة»","url":""}]},{"id":"s2-143","number":143,"surah":2,"verses":[36],"references":[{"surah":2,"verses":[36]}],"verseLabel":"البقرة: 36","question":"ما سرّ مجيء الأمر بالهبوط للجمع: ﴿اهبطوا﴾ بعد خطاب آدم وزوجه؟","answer":"لأن الخطاب اتسع ليشمل آدم وزوجه وإبليس، وقيل: يشمل ذريتهما تبعًا لهما؛ ولذلك جاء بعده بيان العداوة والاستقرار في الأرض إلى حين.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص354–355، تحت «سر التعبير بالجمع في ﴿اهبطوا﴾»","url":""}]},{"id":"s2-144","number":144,"surah":2,"verses":[37],"references":[{"surah":2,"verses":[37]}],"verseLabel":"البقرة: 37","question":"ما دلالة ﴿تلقى﴾ في قوله: ﴿فتلقى آدم من ربه كلمات﴾؟","answer":"التلقي هو الاستقبال والأخذ بقبول؛ وفيه تصوير آدم متقبلًا كلمات ربه التي عُلّم بها طريق التوبة والرجوع.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص356، تحت «نكتة التعبير بالتلقي»","url":""}]},{"id":"s2-145","number":145,"surah":2,"verses":[37],"references":[{"surah":2,"verses":[37]}],"verseLabel":"البقرة: 37","question":"ما سرّ ذكر آدم وحده في قوله: ﴿فتاب عليه﴾ مع اشتراك زوجه في الزلة؟","answer":"خُص آدم بالذكر لأنه الأصل في القصة والخطاب، وتدخل زوجه معه تبعًا؛ وقد صرحت سورة الأعراف بدعائهما معًا: ﴿ربنا ظلمنا أنفسنا﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص357–358، تحت «سر التعبير بالإفراد دون التثنية»","url":""}]},{"id":"s2-146","number":146,"surah":2,"verses":[37],"references":[{"surah":2,"verses":[37]}],"verseLabel":"البقرة: 37","question":"ما مناسبة ختم قبول توبة آدم بقوله ﴿إنه هو التواب الرحيم﴾؟","answer":"الخاتمة تذييل يعمم قبول التوبة بعد ذكر توبة آدم خاصة؛ فهي تعلل قبول توبته بأن الله يقبل توبة من تاب إليه، فتصل الحكم الخاص بالمعنى العام.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص358، تحت عنوان «بلاغة الفاصلة القرآنية»","url":""}]},{"id":"s2-1487","number":1487,"surah":2,"verses":[37],"references":[{"surah":2,"verses":[37]}],"verseLabel":"البقرة: 37","question":"لماذا قُرن اسم التواب بالرحيم في ختام قصة توبة آدم؟","answer":"لأن اسم الرحيم يجري مجرى العلة لاسم التواب؛ فقبول الله توبة عباده من رحمته بهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص358، تحت عنوان «فائدة قرن اسم التواب بالرحيم»","url":""}]},{"id":"s2-1488","number":1488,"surah":2,"verses":[37],"references":[{"surah":2,"verses":[37]}],"verseLabel":"البقرة: 37","question":"ما أثر اجتماع المؤكدات في ﴿إنه هو التواب الرحيم﴾؟","answer":"تأكد الخبر بإن، وبتعريف طرفي الجملة المفيد للقصر، وبضمير الفصل الذي يقوي القصر، وباسمية الجملة الدالة على الثبات والدوام. وفي ذلك حث العباد جميعًا على التوبة مما بدر منهم، فقبول التوبة ليس خاصًا بآدم.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص358، تحت عنوان «سر تأكيد الجملة بأنواع من المؤكدات»","url":""}]},{"id":"s2-147","number":147,"surah":2,"verses":[38],"references":[{"surah":2,"verses":[38]}],"verseLabel":"البقرة: 38","question":"ما سرّ تكرار الأمر بالهبوط في الآيتين 36 و38؟","answer":"الهبوط الأول متصل بإخراج آدم وزوجه من الجنة عقب الزلة، أما الثاني فاستئناف لبيان ما يترتب على الحياة في الأرض من مجيء الهدى وانقسام الناس إلى متبع ومكذب؛ فليس تكرارًا خاليًا من الفائدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص362–363، تحت «نكتة تكرار الأمر بالهبوط»","url":""}]},{"id":"s2-148","number":148,"surah":2,"verses":[38],"references":[{"surah":2,"verses":[38]}],"verseLabel":"البقرة: 38","question":"ما سر تنكير ﴿هدى﴾ في قوله ﴿فإما يأتينكم مني هدى﴾؟","answer":"يفيد تعظيم الهدى وكثرة آثاره الحسنة؛ فهو هدى عظيم في نفسه، صادر من الله، ويترتب على اتباعه نفي الخوف والحزن.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص365، تحت عنوان «سر تنكير ﴿هدى﴾»","url":""}]},{"id":"s2-1489","number":1489,"surah":2,"verses":[38],"references":[{"surah":2,"verses":[38]}],"verseLabel":"البقرة: 38","question":"لماذا أعيد لفظ الهدى في ﴿فمن تبع هداي﴾ بدل أن يقال: فمن تبعه؟","answer":"في إظهار لفظ الهدى بدل ضميره إيماء إلى علة وجوب اتباعه، وهي كونه هدى، وفيه زيادة اهتمام به وترسيخ له في أذهان المخاطبين.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص365، تحت عنوان «وضع المظهر موضع المضمر في قوله ﴿فمن تبع هداي﴾»","url":""}]},{"id":"s2-149","number":149,"surah":2,"verses":[38],"references":[{"surah":2,"verses":[38]}],"verseLabel":"البقرة: 38","question":"ماذا تفيد الجملتان الاسميتان في ﴿فلا خوف عليهم ولا هم يحزنون﴾؟","answer":"تفيدان دوام نفي الخوف والحزن واستمرار هذه الحال في متبعي الهدى؛ فالمقصود دوام انتفاء الخوف والحزن، لا مجرد انتفاء استمرارهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص368، تحت عنوان «سر التعبير بالجمل الاسمية في قوله ﴿فلا خوف عليهم ولا هم يحزنون﴾»","url":""}]},{"id":"s2-1490","number":1490,"surah":2,"verses":[38],"references":[{"surah":2,"verses":[38]}],"verseLabel":"البقرة: 38","question":"كيف يقوّي الخبر الفعلي نفي الحزن في ﴿ولا هم يحزنون﴾؟","answer":"ورد الخبر جملة فعلية، فتكرر الإسناد إلى متبعي الهدى: إلى الضمير ﴿هم﴾ بإسناد الخبر إلى المبتدأ، وإلى واو الجماعة بإسناد الفعل إلى فاعله؛ فتأكد المعنى وقوي.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص369، تحت عنوان «فائدة مجيء الخبر جملة فعلية»","url":""}]},{"id":"s2-1491","number":1491,"surah":2,"verses":[38],"references":[{"surah":2,"verses":[38]}],"verseLabel":"البقرة: 38","question":"ما دلالة قراءة يعقوب ﴿فلا خوفَ عليهم﴾ بفتح الفاء من غير تنوين؟","answer":"بناء النكرة مع لا النافية للجنس يجعل النفي نصًّا في العموم؛ فهذه القراءة تؤكد نفي جنس الخوف بجميع أنواعه عن متبعي الهدى. وقرأ الباقون بالرفع والتنوين.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص367–368، تحت عنوان «توجيه قراءة فتح الفاء من ﴿فلا خوف عليهم﴾»","url":""}]},{"id":"s2-150","number":150,"surah":2,"verses":[38],"references":[{"surah":2,"verses":[38]}],"verseLabel":"البقرة: 38","question":"ما سرّ تقديم ﴿مني﴾ في قوله: ﴿فإما يأتينكم مني هدى﴾؟","answer":"الأصل: «يأتينكم هدى مني»، وقُدّم الجار والمجرور للعناية بمصدر الهدى، وللدلالة على أن الهدى الذي تنال به النجاة إنما يأتي من الله؛ فلا يُطلب من غيره.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص365، تحت «دلالة تقديم الجار والمجرور في ﴿مني﴾»","url":""}]},{"id":"s2-151","number":151,"surah":2,"verses":[38],"references":[{"surah":2,"verses":[38]},{"surah":20,"verses":[123]}],"verseLabel":"البقرة: 38، وطه: 123","question":"ما سرّ اختلاف التعبير بين قوله تعالى في البقرة: ﴿فمن تبع هداي﴾، وفي طه: ﴿فمن اتبع هداي﴾ بزيادة التاء؟","answer":"﴿تبع﴾ تفيد أصل الاتباع، أما زيادة المبنى في ﴿اتبع﴾ فتشعر بمزيد عناية وتعمل. ولما فصلت طه وسوسة الشيطان وحيلته في إغراء آدم، ناسبها ما يدل على مجاهدة التلبيس، بخلاف إجمال البقرة في قوله: ﴿فأزلهما الشيطان﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص366، تحت «توجيه المتشابه اللفظي بين ﴿فمن تبع هداي﴾ و﴿فمن اتبع هداي﴾»","url":""}]},{"id":"s2-152","number":152,"surah":2,"verses":[38],"references":[{"surah":2,"verses":[38]}],"verseLabel":"البقرة: 38","question":"ما سرّ تقديم نفي الخوف على نفي الحزن؟","answer":"لأن الخوف من مكروه مستقبل أشد تعلقًا بالنفس وأقوى أثرًا فيها من الحزن على ما فات، فقدم الأهم في مقام الوعد بالأمن، ثم نُفي الحزن ليكتمل الأمن من جهة الماضي.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص367، تحت «نكتة تقديم نفي الخوف على نفي الحزن»","url":""}]},{"id":"s2-153","number":153,"surah":2,"verses":[39],"references":[{"surah":2,"verses":[39]}],"verseLabel":"البقرة: 39","question":"ما دلالة تقديم ﴿فيها﴾ في قوله: ﴿أولئك أصحاب النار هم فيها خالدون﴾؟","answer":"تقديم الجار والمجرور يفيد اختصاص خلودهم بالنار، ويقوي تصوير ملازمتهم لها؛ ثم جاءت الجملة الاسمية مؤكدةً لثبات هذا المصير ودوامه.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص374، تحت «نكتة تقديم الجار والمجرور ﴿فيها﴾»","url":""}]},{"id":"s2-154","number":154,"surah":2,"verses":[40],"references":[{"surah":2,"verses":[40]}],"verseLabel":"البقرة: 40","question":"ما دلالة نداء اليهود باسم أبيهم في قوله: ﴿يا بني إسرائيل﴾؟","answer":"فيه تذكير لهم بنسبهم إلى نبي الله يعقوب، واستنهاض لأن يوافقوا سيرة أبيهم في الإيمان والوفاء، مع ما في النداء بهذا الاسم من تهيئة لقبول ما يذكّرون به من النعم والعهد.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص380، تحت «سر النداء بـ﴿يا بني إسرائيل﴾ دون (يا بني يعقوب)»","url":""}]},{"id":"s2-155","number":155,"surah":2,"verses":[40],"references":[{"surah":2,"verses":[40]}],"verseLabel":"البقرة: 40","question":"ما دلالة المقابلة في قوله: ﴿أوفوا بعهدي أوف بعهدكم﴾؟","answer":"رُتب وفاء الله بوعده لهم على وفائهم بما عهد إليهم من الإيمان والطاعة؛ فجاء الجزاء من جنس العمل، وجمعت المقابلة بين التكليف والوعد في عبارة موجزة.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص379، تحت عنوان «المعنى الإجمالي»","url":""}]},{"id":"s2-156","number":156,"surah":2,"verses":[40],"references":[{"surah":2,"verses":[40]}],"verseLabel":"البقرة: 40","question":"ما دلالة تقديم ﴿إياي﴾ في قوله: ﴿وإياي فارهبون﴾؟","answer":"قُدّم المفعول لإفادة الاختصاص؛ فالرهبة الحقة لا تكون إلا من الله، وأُكد هذا الاختصاص بتكرار فعل الرهبة وتكرار المفعول في الضمير المنفصل والياء المقدرة في ﴿فارهبون﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص382، تحت «سر تقديم المفعول ﴿إياي﴾»","url":""}]},{"id":"s2-157","number":157,"surah":2,"verses":[40,41],"references":[{"surah":2,"verses":[40,41]}],"verseLabel":"البقرة: 40–41","question":"ما سرّ ختم الآية 40 بـ﴿فارهبون﴾، والآية 41 بـ﴿فاتقون﴾؟","answer":"جاءت ﴿فارهبون﴾ بعد التذكير بالنعمة والأمر بالوفاء بالعهد؛ فناسب مقام الترغيب والترهيب. أما الآية التالية فجمعت أمرًا بالإيمان ونواهي عن الكفر وبيع الآيات، وحقيقة التقوى امتثال الأمر واجتناب النهي؛ فناسبها ﴿فاتقون﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص387، تحت «مناسبة الفواصل القرآنية لآياتها»","url":""}]},{"id":"s2-158","number":158,"surah":2,"verses":[41],"references":[{"surah":2,"verses":[41]}],"verseLabel":"البقرة: 41","question":"كيف نُهوا عن أن يكونوا ﴿أول كافر به﴾ وقد سبقهم مشركو مكة إلى الكفر؟","answer":"المراد: لا تكونوا أول كافر به من أهل الكتاب أو من قومكم؛ وكان سبقهم إلى الكفر أقبح لأنهم يعرفون صفات النبي ﷺ والكتاب الذي أنزل عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص384، تحت «غرض النهي في قوله: ﴿ولا تكونوا أول كافر به﴾»","url":""}]},{"id":"s2-159","number":159,"surah":2,"verses":[41],"references":[{"surah":2,"verses":[41]}],"verseLabel":"البقرة: 41","question":"ما سرّ وصف ثمن آيات الله بأنه ﴿قليلًا﴾؟","answer":"كل ما يؤخذ عوضًا عن آيات الله قليل، ولو كان الدنيا بحذافيرها؛ وقد اجتمع إفراد الثمن وتنكيره ووصفه بالقلة للدلالة على حقارته قدرًا ووصفًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص386، تحت «نكتة إفراد الثمن وتنكيره»","url":""}]},{"id":"s2-160","number":160,"surah":2,"verses":[42],"references":[{"surah":2,"verses":[42]}],"verseLabel":"البقرة: 42","question":"ما الصورة في قوله: ﴿ولا تلبسوا الحق بالباطل﴾؟","answer":"أصل اللبس الخلط حتى يشتبه أحد الشيئين بالآخر؛ فصور خلط الحق بالباطل على نحو يمنع الناس من تمييزهما، ويجعل الباطل ساترًا لوجه الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص389، تحت عنوان «شرح المفردات»، مدخل ﴿تلبسوا﴾","url":""}]},{"id":"s2-161","number":161,"surah":2,"verses":[42],"references":[{"surah":2,"verses":[42]}],"verseLabel":"البقرة: 42","question":"ما سرّ الجمع بين لبس الحق وكتمانه؟","answer":"لأنهما طريقتان في إخفاء الهدى عن الناس: يُخلط الحق بالباطل حتى يشتبه، أو يُكتم الحق فلا يظهر أصلًا؛ فجمع النهيان وجهي التحريف والإخفاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص390، تحت عنوان «المعنى الإجمالي»","url":""}]},{"id":"s2-162","number":162,"surah":2,"verses":[43],"references":[{"surah":2,"verses":[43]}],"verseLabel":"البقرة: 43","question":"ما سرّ التعبير عن الصلاة بقوله: ﴿أقيموا الصلاة﴾؟","answer":"إقامة الصلاة هي الإتيان بها مستقيمةً مستوفيةً شروطها وأركانها وحقوقها، مع المحافظة عليها؛ فهي أبلغ من مجرد وقوع فعل الصلاة.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص393، تحت عنوان «أثر تعدد دلالات (الإقامة)»","url":""}]},{"id":"s2-163","number":163,"surah":2,"verses":[43],"references":[{"surah":2,"verses":[43]}],"verseLabel":"البقرة: 43","question":"ما سرّ التعبير في قوله تعالى: ﴿واركعوا مع الراكعين﴾ بعد الأمر بإقامة الصلاة؟","answer":"خُص الركوع بالذكر لأنه ركن ظاهر تتميز به صلاة المسلمين، وقوله ﴿مع الراكعين﴾ يدعوهم إلى الصلاة مع جماعة المؤمنين والدخول في عبادتهم، لا البقاء منفردين على ما ألفوه.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص394–395، تحت عنوان «بلاغة المجاز في ﴿واركعوا﴾»","url":""}]},{"id":"s2-164","number":164,"surah":2,"verses":[44],"references":[{"surah":2,"verses":[44]}],"verseLabel":"البقرة: 44","question":"هل النسيان في قوله: ﴿وتنسون أنفسكم﴾ نسيان حقيقي؟","answer":"النسيان هنا بمعنى الترك؛ أي يأمرون الناس بالبر ويتركون أنفسهم عن أمرها به. فالمراد إهمال العمل بالبر، لا ذهاب المعلومة عن الذاكرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص398–399، تحت عنوان «شرح المفردات»، مدخل ﴿وتنسون﴾","url":""}]},{"id":"s2-165","number":165,"surah":2,"verses":[44],"references":[{"surah":2,"verses":[44]}],"verseLabel":"البقرة: 44","question":"ما سرّ ختم التوبيخ بقوله: ﴿أفلا تعقلون﴾؟","answer":"لأن العقل يقتضي أن ينتفع الإنسان بعلمه وأن يبدأ نفسه بما يأمر به غيره؛ أما تلاوة الكتاب مع مخالفة ما فيه فمناقضة لما يدل عليه العقل.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص403، تحت عنوان «نكتة حذف المفعول»","url":""}]},{"id":"s2-166","number":166,"surah":2,"verses":[45],"references":[{"surah":2,"verses":[45]}],"verseLabel":"البقرة: 45","question":"ما أنواع الصبر التي يشملها الأمر ﴿واستعينوا بالصبر﴾؟","answer":"اللام في الصبر للجنس، فتشمل الصبر على الطاعة حتى تؤدى، والصبر عن المعصية حتى تُجتنب، والصبر على القدر المؤلم دون تسخط؛ فهذه الأنواع داخلة في الاستعانة المأمور بها.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص407، تحت عنوان «دلالة اللام في ﴿بالصبر﴾»","url":""}]},{"id":"s2-1492","number":1492,"surah":2,"verses":[45],"references":[{"surah":2,"verses":[45]}],"verseLabel":"البقرة: 45","question":"ما وجه التناسب في الجمع بين الصبر والصلاة؟","answer":"في الجمع بينهما مراعاة للنظير؛ إذ بين الصبر والصلاة تناسب، لأن الصلاة نفسها تتضمن صبرًا من جهات مختلفة.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص407، تحت عنوان «فن مراعاة النظير في الجمع بين الصبر والصلاة»","url":""}]},{"id":"s2-1493","number":1493,"surah":2,"verses":[45],"references":[{"surah":2,"verses":[45]}],"verseLabel":"البقرة: 45","question":"لماذا لم يُذكر ما يُستعان عليه في ﴿واستعينوا بالصبر والصلاة﴾؟","answer":"حُذف متعلق الاستعانة لإفادة العموم والشمول؛ أي استعينوا بالصبر والصلاة على جميع أموركم، الدينية والدنيوية.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص408، تحت عنوان «سر حذف متعلق الاستعانة»","url":""}]},{"id":"s2-167","number":167,"surah":2,"verses":[45],"references":[{"surah":2,"verses":[45]}],"verseLabel":"البقرة: 45","question":"إلى ماذا يعود الضمير المفرد في قوله: ﴿وإنها لكبيرة﴾ بعد ذكر الصبر والصلاة؟","answer":"يعود الضمير في الأظهر إلى الصلاة؛ لأنها أقرب مذكور، وفي تخصيصها بعود الضمير إشارة إلى عظمة شأنها، وهي شاقة على غير الخاشعين سهلة عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص409، تحت «فائدة تخصيص الصلاة بعود الضمير عليها»","url":""}]},{"id":"s2-168","number":168,"surah":2,"verses":[46],"references":[{"surah":2,"verses":[46]}],"verseLabel":"البقرة: 46","question":"ما سرّ التعبير عن يقين الخاشعين بلقاء ربهم بقوله: ﴿يظنون﴾؟","answer":"الظن في العربية يأتي بمعنى اليقين إذا دل السياق عليه، وهو المراد هنا؛ لأن الخشوع والاستعداد للرجوع إلى الله مبنيان على يقينهم باللقاء لا على مجرد الشك.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص409، تحت «سر العدول عن التعبير باليقين إلى التعبير بالظن»","url":""}]},{"id":"s2-169","number":169,"surah":2,"verses":[47],"references":[{"surah":2,"verses":[47]}],"verseLabel":"البقرة: 47","question":"ما مناسبة إعادة نداء بني إسرائيل وتذكيرهم بالنعمة في الآية 47؟","answer":"استؤنف النداء بعد الأوامر والنواهي السابقة لتجديد تذكيرهم بأصل النعمة وما تقتضيه من امتثال، ثم وُصل ذلك بالتحذير من يوم لا تنفع فيه نفس نفسًا؛ فصار التذكير تمهيدًا للمحاسبة على شكر النعمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص413، تحت «نكتة الإطناب بتكرار النداء المتقدم ﴿يا بني إسرائيل﴾»","url":""}]},{"id":"s2-170","number":170,"surah":2,"verses":[47,122],"references":[{"surah":2,"verses":[47,122]}],"verseLabel":"البقرة: 47 و122","question":"ما سرّ تكرار آية: ﴿يا بني إسرائيل اذكروا نعمتي... وأني فضلتكم على العالمين﴾ في الآيتين 47 و122؟","answer":"جاءت الأولى قبل تفصيل نعم الله عليهم ومواقفهم منها، ثم أعيدت بعد ذلك التفصيل لتختم المقطع بما افتتح به، وتربط تعداد النعم بما تقتضيه من الشكر والاستجابة قبل الانتقال إلى الحديث عن إبراهيم عليه السلام.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص219، تحت «مناسبة الآية لما قبلها»","url":""}]},{"id":"s2-171","number":171,"surah":2,"verses":[48],"references":[{"surah":2,"verses":[48]}],"verseLabel":"البقرة: 48","question":"ما دلالة تنكير ﴿نفس﴾ و﴿شيئًا﴾ في قوله: ﴿لا تجزي نفس عن نفس شيئًا﴾؟","answer":"التنكير في سياق النفي يفيد العموم؛ فلا تجزي أي نفس عن أي نفس شيئًا، قليلًا كان أو كثيرًا. وبذلك يُقطع التعلق بالنسب أو الجاه أو أي وسيلة يظن أنها تغني يوم القيامة.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص417، تحت «سر تنكير ﴿نفس﴾ و﴿شيئًا﴾»","url":""}]},{"id":"s2-172","number":172,"surah":2,"verses":[48,123],"references":[{"surah":2,"verses":[48,123]}],"verseLabel":"البقرة: 48 و123","question":"ما سرّ تقديم الشفاعة على الفدية في الآية 48، وقدمت الفدية على الشفاعة في الآية 123؟","answer":"غيّر النظم ترتيب الشفاعة والفدية لاستيعاب وجوه النجاة التي يتوهمها الناس؛ فقدم في كل موضع ما يناسب ما قد يبتدئون بطلبه، ثم نفى الآخر، حتى لا يبقى توهم نجاة بشفاعة أو فداء.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص231، تحت «توجيه المتشابه اللفظي»","url":""}]},{"id":"s2-173","number":173,"surah":2,"verses":[48,123],"references":[{"surah":2,"verses":[48,123]}],"verseLabel":"البقرة: 48 و123","question":"لماذا قيل عن الشفاعة في البقرة ﴿لا يقبل منها شفاعة﴾ ثم ﴿لا تنفعها شفاعة﴾؟","answer":"لأن النظر في الآية الأولى إلى النفس الشافعة، فالشفاعة تُقبل من الشافع؛ وفي الثانية إلى النفس المشفوع لها، فالشفاعة تنفع المشفوع له. فناسب كل موضع الفعل الملائم للجهة المقصودة.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص231–232، تحت عنوان «توجيه المتشابه اللفظي»","url":""}]},{"id":"s2-1494","number":1494,"surah":2,"verses":[48,123],"references":[{"surah":2,"verses":[48,123]}],"verseLabel":"البقرة: 48 و123","question":"ما فائدة نفي نفع الشفاعة بعد نفي قبول الفدية في البقرة: 123؟","answer":"فيه احتراس؛ لأن نفي قبول الفدية وحده لا يقتضي نفي نفع الشفاعة، فجاء التصريح بنفي نفعها لئلا يُتوهم بقاء هذا الطريق للخلاص.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص232، تحت عنوان «بلاغة الاحتراس في نفي نفع الشفاعة»","url":""}]},{"id":"s2-174","number":174,"surah":2,"verses":[49],"references":[{"surah":2,"verses":[49]}],"verseLabel":"البقرة: 49","question":"ما دلالة ﴿يذبحون أبناءكم ويستحيون نساءكم﴾ في تصوير سوء العذاب؟","answer":"يبين التعبيران ما كانوا يسومون بني إسرائيل من العذاب: يكثرون من ذبح أبنائهم، ويستبقون نساءهم ليجعلوهن إماء وخدمًا. فجمعا إهلاك الأبناء وإبقاء النساء للخدمة والإذلال.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص422، تحت عنوان «المعنى الإجمالي»","url":""}]},{"id":"s2-175","number":175,"surah":2,"verses":[49],"references":[{"surah":2,"verses":[49]}],"verseLabel":"البقرة: 49","question":"إلى ماذا يشير قوله: ﴿وفي ذلكم بلاء من ربكم عظيم﴾؟","answer":"يحتمل أن يشير إلى سوء العذاب الذي سامهم إياه آل فرعون، فيكون البلاء محنة، ويحتمل أن يشير إلى إنجاء الله لهم، فيكون البلاء اختبارًا بالنعمة. فالبلاء يكون بالضراء وبالسراء.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص422، تحت عنوان «شرح المفردات»، مدخل ﴿بلاء﴾","url":""}]},{"id":"s2-176","number":176,"surah":2,"verses":[49],"references":[{"surah":2,"verses":[49]},{"surah":7,"verses":[141]}],"verseLabel":"البقرة: 49، والأعراف: 141","question":"ما سرّ اختلاف التعبير بين قوله تعالى في البقرة: ﴿نجيناكم﴾، وفي الأعراف: ﴿أنجيناكم﴾؟","answer":"استعمل ﴿نجّى﴾ لما فيه من دلالة على التلبث والتمهل، فناسب طول مدة البلاء مع آل فرعون، واستعمل ﴿أنجى﴾ لما فيه من دلالة على الإسراع، فناسب سرعة النجاة من البحر.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص439، تحت عنوان «استعمال كلمتي (نجّى) و(أنجى)»","url":""}]},{"id":"s2-177","number":177,"surah":2,"verses":[49],"references":[{"surah":2,"verses":[49]},{"surah":7,"verses":[141]},{"surah":14,"verses":[6]}],"verseLabel":"البقرة: 49، والأعراف: 141، وإبراهيم: 6","question":"ما سرّ التعبير في قوله تعالى: ﴿يذبحون أبناءكم﴾ في البقرة وإبراهيم، وقيل: ﴿يقتلون أبناءكم﴾ في الأعراف؟","answer":"التقتيل أعم من التذبيح؛ فكل ذبح قتل وليس كل قتل ذبحًا. و﴿يذبحون﴾ تستحضر الصورة الخاصة الأشد في معاملة الأبناء كالذبائح، أما ﴿يقتلون﴾ فتدل على جنس القتل الذي تدخل فيه صوره المختلفة؛ فتتكامل المواضع في تصوير المحنة.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص559، تحت «توجيه التشابه اللفظي باختيار المفردة»","url":""}]},{"id":"s2-178","number":178,"surah":2,"verses":[49],"references":[{"surah":2,"verses":[49]},{"surah":14,"verses":[6]}],"verseLabel":"البقرة: 49، وإبراهيم: 6","question":"ما سرّ التعبير بقوله تعالى: في البقرة: ﴿يسومونكم سوء العذاب يذبحون أبناءكم﴾ بلا واو، وفي إبراهيم: ﴿ويذبحون أبناءكم﴾ بالواو؟","answer":"في البقرة جاءت جملة ﴿يذبحون أبناءكم﴾ بيانًا وتفسيرًا لسوء العذاب، ففُصلت من غير واو. أما في إبراهيم فعُطفت بالواو لتجعل التذبيح محنة مضافة إلى سائر ألوان سوء العذاب في مقام تذكير موسى قومه بأيام الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص424، تحت «بلاغة الفصل والوصل في توجيه المتشابه اللفظي»","url":""}]},{"id":"s2-179","number":179,"surah":2,"verses":[50],"references":[{"surah":2,"verses":[50]}],"verseLabel":"البقرة: 50","question":"ما دلالة الباء في قوله: ﴿فرقنا بكم البحر﴾؟","answer":"تحتمل الباء الملابسة والمصاحبة؛ أي فرقنا البحر وأنتم داخلون فيه، وتحتمل السببية؛ أي بسببكم ولأجل إنجائكم. وعلى الوجهين تربط المعجزة بهم ربطًا مباشرًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص431، تحت «دلالة الباء في ﴿بكم﴾»","url":""}]},{"id":"s2-180","number":180,"surah":2,"verses":[50],"references":[{"surah":2,"verses":[50]}],"verseLabel":"البقرة: 50","question":"ما الذي أضافه قوله: ﴿وأنتم تنظرون﴾ إلى مشهد النجاة؟","answer":"أثبت أنهم عاينوا إغراق آل فرعون وإطباق البحر وانفلاقه عن طرق يابسة وسائر ما جرى؛ فاجتمعت لهم نعمة النجاة ومشاهدة هلاك عدوهم، وكل مشهد من ذلك نعمة امتن الله بها عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص433، تحت «حذف معمول النظر في قوله تعالى: ﴿وأنتم تنظرون﴾»","url":""}]},{"id":"s2-181","number":181,"surah":2,"verses":[50],"references":[{"surah":2,"verses":[50]}],"verseLabel":"البقرة: 50","question":"لماذا عبّرت البقرة عن موضع النجاة والإغراق بـ﴿البحر﴾، ويكثر في مشاهد إغراق فرعون لفظ ﴿اليم﴾؟","answer":"يغلب لفظ ﴿اليم﴾ في سياقات الخوف والعقاب والإغراق، أما ﴿البحر﴾ فيناسب سياق النعمة والنجاة. ولما كانت آية البقرة تعدد نعم الله على بني إسرائيل، وجه اللفظ النظر إلى جهة إنجائهم وإن كان المشهد نفسه قد تضمن إغراق عدوهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص379–380، تحت «البحر واليم»","url":""}]},{"id":"s2-182","number":182,"surah":2,"verses":[51],"references":[{"surah":2,"verses":[51]}],"verseLabel":"البقرة: 51","question":"ما المراد بقوله: ﴿ثم اتخذتم العجل من بعده﴾؟","answer":"المراد اتخاذ العجل إلهًا ومعبودًا من دون الله بعد غياب موسى؛ فدل السياق على متعلق الاتخاذ، ولم يحتج إلى التصريح بلفظ العبادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص442، تحت «نكتة حذف المفعول الثاني لـ﴿اتخذتم﴾»","url":""}]},{"id":"s2-183","number":183,"surah":2,"verses":[51],"references":[{"surah":2,"verses":[51]},{"surah":7,"verses":[142]}],"verseLabel":"البقرة: 51، والأعراف: 142","question":"لماذا أجملت البقرة ميقات موسى في ﴿أربعين ليلة﴾، وفصلته الأعراف: ﴿ثلاثين ليلة وأتممناها بعشر﴾؟","answer":"مقام البقرة تعداد النعم والمواقف في إيجاز، فذُكر مجموع الميقات بعد تمامه: أربعين ليلة. أما الأعراف فسياقها تفصيل قصة موسى، فذكرت أصل الموعد ثلاثين ثم إتمامه بعشر؛ فناسب الإجمال مقام البقرة والتفصيل مقام الأعراف.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص440، تحت «توجيه المتشابه اللفظي»","url":""}]},{"id":"s2-184","number":184,"surah":2,"verses":[51],"references":[{"surah":2,"verses":[51]}],"verseLabel":"البقرة: 51","question":"لماذا عُبر عن مدة الميقات بقوله: ﴿أربعين ليلة﴾ لا «أربعين يومًا»؟","answer":"لأن العرب تؤرخ الشهور بالليالي، إذ يظهر الهلال ليلًا، فتجعل الأيام تابعة لليالي في عد المدد. ويلائم ذكر الليل كذلك مقام مناجاة موسى وعبادته؛ فالليل زمن صفاء وخلوة من الشواغل.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص440–441، تحت «نكتة التعبير بالليلة دون اليوم»","url":""}]},{"id":"s2-185","number":185,"surah":2,"verses":[52],"references":[{"surah":2,"verses":[52]}],"verseLabel":"البقرة: 52","question":"ما مناسبة قوله بعد اتخاذ العجل: ﴿ثم عفونا عنكم من بعد ذلك﴾؟","answer":"عدّ العفو نعمة أخرى عليهم بعد عظم جرمهم؛ فمع استحقاقهم العقوبة تجاوز الله عنهم وقبل رجوعهم، ليظهر فضله وتقوم عليهم الحجة في وجوب الشكر.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص442–443، تحت «دلالة حرف العطف (ثم) في قوله تعالى: ﴿ثم عفونا عنكم﴾»","url":""}]},{"id":"s2-186","number":186,"surah":2,"verses":[52],"references":[{"surah":2,"verses":[52]}],"verseLabel":"البقرة: 52","question":"لماذا قيل بعد العفو ﴿لعلكم تشكرون﴾ بدل التعليل بلام كي؟","answer":"في التعبير بلعل إيماء إلى أن شكرهم، مع عظم منة الله عليهم، ليس متحققًا بل يحتمل تخلفه. وناسبت صيغة ﴿تشكرون﴾ فواصل الآيات كذلك.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص443، تحت عنوان «فائدة التعبير بـ﴿لعلكم﴾ دون لام التعليل»","url":""}]},{"id":"s2-1495","number":1495,"surah":2,"verses":[52],"references":[{"surah":2,"verses":[52]}],"verseLabel":"البقرة: 52","question":"ماذا يفيد المضارع في ﴿لعلكم تشكرون﴾؟","answer":"يفيد استمرار الشكر وتجدده؛ فكلما تجددت النعمة على العبد كان مطالبًا بإحداث شكر جديد عليها.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص444، تحت عنوان «نكتة التعبير بالفعل المضارع في قوله: ﴿لعلكم تشكرون﴾»","url":""}]},{"id":"s2-187","number":187,"surah":2,"verses":[53],"references":[{"surah":2,"verses":[53]}],"verseLabel":"البقرة: 53","question":"ما وجه عطف ﴿الفرقان﴾ على ﴿الكتاب﴾؟","answer":"الفرقان هو التوراة نفسها، وعُطف على الكتاب مع اتحاد المراد لتنزيل تغاير الصفتين منزلة تغاير الذاتين؛ فهي كتاب منزل، وهي فرقان يميز بين الحق والباطل.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص447، تحت «دلالة (الواو) في قوله: ﴿وإذ آتينا موسى الكتاب والفرقان﴾»","url":""}]},{"id":"s2-188","number":188,"surah":2,"verses":[54],"references":[{"surah":2,"verses":[54]}],"verseLabel":"البقرة: 54","question":"لماذا خاطب موسى عبدة العجل بقوله: ﴿يا قوم﴾ وهو يوبخهم على ظلم أنفسهم؟","answer":"في إضافة القوم إلى نفسه تذكير بالصلة والمودة التي تربطه بهم، وإشعار بتحننه عليهم؛ فيستميل قلوبهم لقبول النصح والتوبة مع شدة التوبيخ.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص452، تحت «دلالة النداء في قوله: «يا قوم»»","url":""}]},{"id":"s2-189","number":189,"surah":2,"verses":[54],"references":[{"surah":2,"verses":[54]}],"verseLabel":"البقرة: 54","question":"كيف كان امتثال حكم التوبة من عبادة العجل خيرًا لبني إسرائيل؟","answer":"أُمروا أن يتوبوا إلى خالقهم بأن يقتل بعضهم بعضًا؛ فامتثال ما أُمروا به كان خيرًا لهم من التمادي في الشرك وما يفضي إليه من عقوبة الآخرة. ولما استسلموا لهذا الأمر تفضل الله بقبول توبتهم، فكانت التوبة طهرة لهم من الشرك.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص451–452، تحت عنوان «المعنى الإجمالي»","url":""}]},{"id":"s2-190","number":190,"surah":2,"verses":[54],"references":[{"surah":2,"verses":[54]}],"verseLabel":"البقرة: 54","question":"ما مناسبة تكرار اسم الله ﴿بارئكم﴾ في آية التوبة من عبادة العجل؟","answer":"تكراره أوكد وأعلق بالذهن، ويستحضر معنى البارئ الذي أنشأهم. وفيه تنبيه إلى أن الذي قضى بإنشائهم هو الذي أمرهم بهذه التوبة، فواجبهم التسليم له في حكمه.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص454، تحت «نكتة تكرار اسم الله البارئ»","url":""}]},{"id":"s2-191","number":191,"surah":2,"verses":[54],"references":[{"surah":2,"verses":[54]}],"verseLabel":"البقرة: 54","question":"لماذا قال في قصة توبة قوم موسى: ﴿فتاب عليكم﴾، ولم يقل: «فتاب عليهم»؟","answer":"وُجّه الخطاب إلى بني إسرائيل تذكيرًا لهم بهذه النعمة العظيمة التي أنعم الله بها على قومهم؛ فاستُعمل ضمير الخطاب بدل مواصلة الحديث عن السابقين بضمير الغيبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص455، تحت «نكتة التعبير بضمير الخطاب دون ضمير الغيبة»","url":""}]},{"id":"s2-192","number":192,"surah":2,"verses":[55],"references":[{"surah":2,"verses":[55]}],"verseLabel":"البقرة: 55","question":"ما دلالة اللام في قولهم: ﴿لن نؤمن لك حتى نرى الله جهرة﴾؟","answer":"ضُمّن ﴿نؤمن﴾ معنى الإقرار أو الإذعان، فعدي باللام؛ أي لن نقر لك بما تقول، أو لن نذعن لك، حتى نرى الله عيانًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص461، تحت «تضمين فعل ﴿نؤمن﴾ معنى الإقرار أو الإذعان»","url":""}]},{"id":"s2-193","number":193,"surah":2,"verses":[55],"references":[{"surah":2,"verses":[55]}],"verseLabel":"البقرة: 55","question":"إلى ماذا يتعلق النظر في قوله: ﴿فأخذتكم الصاعقة وأنتم تنظرون﴾؟","answer":"حُذف المتعلق ليحتمل أنهم كانوا ينظرون إلى ما حل بهم من الصاعقة، أو ينظر بعضهم إلى بعض كيف يموت، أو إلى الإحياء بعد ذلك. واتساع الحذف يسمح بإرادة هذه المعاني غير المتعارضة، ويؤكد تحقق المشاهدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص463، تحت «حذف متعلق النظر في قوله تعالى: ﴿وأنتم تنظرون﴾»","url":""}]},{"id":"s2-194","number":194,"surah":2,"verses":[56],"references":[{"surah":2,"verses":[56]}],"verseLabel":"البقرة: 56","question":"ما مناسبة قوله بعد بعثهم: ﴿لعلكم تشكرون﴾؟","answer":"بعثهم الله بعد موتهم فكانت حياة جديدة ونعمة عظيمة بعد العقوبة، فناسب أن يُطلب منهم شكر هذه النعمة والاعتراف بفضل من أحياهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص464، تحت «حذف معمول الشكر في قوله سبحانه: ﴿لعلكم تشكرون﴾»","url":""}]},{"id":"s2-195","number":195,"surah":2,"verses":[57,172],"references":[{"surah":2,"verses":[57,172]}],"verseLabel":"البقرة: 57؛ البقرة: 172","question":"لماذا جُمعت ﴿طيبات﴾ في ﴿كلوا من طيبات ما رزقناكم﴾ في البقرة: 57؟","answer":"للإشارة إلى كثرة الطيبات التي أنعم الله بها عليهم. ويؤيد ذلك حرف ﴿من﴾ الدال على التبعيض، إذ لكثرتها يتعذر استيعابها بالأكل.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص470، تحت عنوان «نكتة إيثار جمع ﴿طيبات﴾ على إفرادها»","url":""}]},{"id":"s2-1496","number":1496,"surah":2,"verses":[57,172],"references":[{"surah":2,"verses":[57,172]}],"verseLabel":"البقرة: 57؛ البقرة: 172","question":"ما وجها دلالة ﴿من﴾ في ﴿كلوا من طيبات ما رزقناكم﴾ في البقرة: 172؟","answer":"تحتمل ابتداء الغاية متعلقة بالفعل ﴿كلوا﴾، وتحتمل التبعيض؛ أي كلوا رزقكم حال كونه بعض طيبات ما رزقناكم. وعلى وجه التبعيض يجمع الطيب هنا معنى الحلال والمستلذ.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص696، تحت عنوان «دلالة حرف (من) في قوله ﴿كلوا من طيبات ما رزقناكم﴾»","url":""}]},{"id":"s2-1497","number":1497,"surah":2,"verses":[57,172],"references":[{"surah":2,"verses":[57,172]}],"verseLabel":"البقرة: 57؛ البقرة: 172","question":"كيف يذكّر لفظ الطيبات بنعم الله في البقرة: 172؟","answer":"يذكّر بنعمتين: نعمة الرزق والعطاء، ونعمة إباحة الطيبات. وفي وصف المأكولات بأنها طيبة بيان لحلها وتعليل للأمر بالانتفاع بها، فيستدعي ذلك شكر المنعم.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص697، تحت عنوان «سر اختيار لفظ الطيبات في قوله ﴿من طيبات ما رزقناكم﴾»","url":""}]},{"id":"s2-196","number":196,"surah":2,"verses":[57],"references":[{"surah":2,"verses":[57]},{"surah":7,"verses":[160]}],"verseLabel":"البقرة: 57؛ الأعراف: 160","question":"ماذا يفيد تقديم ﴿أنفسهم﴾ في ﴿ولكن كانوا أنفسهم يظلمون﴾؟","answer":"يؤكد قصر ضرر ظلمهم عليهم، بعد الجمع بين النفي والإثبات؛ فوبال معصيتهم راجع إليهم لا يتخطاهم. وفي التقديم عناية بمن وقع عليه أثر الظلم.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص472، تحت عنوان «دلالة تقديم المفعول على عامله»","url":""}]},{"id":"s2-1498","number":1498,"surah":2,"verses":[57],"references":[{"surah":2,"verses":[57]},{"surah":7,"verses":[160]}],"verseLabel":"البقرة: 57؛ الأعراف: 160","question":"ما وظيفة الاستدراك بلكن في ﴿وما ظلمونا ولكن كانوا أنفسهم يظلمون﴾؟","answer":"بعد نفي وقوع ظلمهم على الله تتطلع النفس إلى معرفة من أصابه ضرره، فاستُدرك بإثباته على أنفسهم؛ إذ كان ظلمهم واقعًا بهم، لا بالله تعالى.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص746–747، تحت عنوان «معنى الحرف ﴿لكن﴾ في الآية»","url":""}]},{"id":"s2-197","number":197,"surah":2,"verses":[57],"references":[{"surah":2,"verses":[57]},{"surah":7,"verses":[160]}],"verseLabel":"البقرة: 57، والأعراف: 160","question":"ما سرّ مجيء في البقرة: ﴿ظللنا عليكم... وأنزلنا عليكم﴾، وفي الأعراف: ﴿ظللنا عليهم... وأنزلنا عليهم﴾؟","answer":"آية البقرة واقعة في خطاب متصل لبني إسرائيل بدأ بقوله: ﴿يا بني إسرائيل اذكروا نعمتي﴾، فاستمر ضمير الخطاب لمواجهتهم بالنعم. أما الأعراف فكانت الآيات تحكي أحوالهم بضمير الغائب، فجاء التظليل والإنزال على نسق الحكاية، ثم التفت إلى الخطاب في ﴿كلوا﴾ لأنه أمر موجه إليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص470، تحت عنوان «توجيه المتشابه اللفظي»","url":""}]},{"id":"s2-198","number":198,"surah":2,"verses":[58],"references":[{"surah":2,"verses":[58]},{"surah":7,"verses":[161]}],"verseLabel":"البقرة: 58، والأعراف: 161","question":"ما سرّ اختلاف التعبير بين قوله تعالى في البقرة: ﴿خطاياكم﴾، وفي الأعراف: ﴿خطيئاتكم﴾؟","answer":"بحسب التوجيه الوارد في هذا الموضع، ﴿خطايا﴾ جمع كثرة و﴿خطيئات﴾ جمع قلة؛ فجاءت صيغة الكثرة في البقرة ملائمة لإسناد القول إلى الله بضمير العظمة ولسياق تعداد النعم، إذ بيان مغفرة الذنوب الكثيرة أبلغ في الامتنان. أما الأعراف فلم يُصرح فيها بالفاعل في ﴿وإذ قيل لهم﴾، فلم يرد فيها لفظ الجمع الدال على الكثرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص487، تحت عنوان «توجيه المتشابه بين ألفاظ هذه القصة في سورتي البقرة والأعراف»، الوجه الخامس","url":""}]},{"id":"s2-199","number":199,"surah":2,"verses":[58],"references":[{"surah":2,"verses":[58]},{"surah":7,"verses":[161]}],"verseLabel":"البقرة: 58، والأعراف: 161","question":"ما سرّ اختلاف التعبير بين قوله تعالى في البقرة: ﴿فكلوا﴾، وفي الأعراف: ﴿وكلوا﴾؟","answer":"في البقرة عُلق الأكل على الدخول، فناسبت الفاء الدالة على التعقيب. وفي الأعراف جاء الأمر بالسكن، والأكل حاصل في أثناء السكن لا مترتبًا عليه ترتبًا مباشرًا، فناسب العطف بالواو.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص773–774، تحت «بلاغة التشابه اللفظي بين آيتي الأعراف161–162، وآيتي البقرة58–59»","url":""}]},{"id":"s2-200","number":200,"surah":2,"verses":[58],"references":[{"surah":2,"verses":[58]},{"surah":7,"verses":[161]}],"verseLabel":"البقرة: 58، والأعراف: 161","question":"ما سرّ اختلاف التعبير بين قوله تعالى في البقرة: ﴿وإذ قلنا ادخلوا﴾، وفي الأعراف: ﴿وإذ قيل لهم اسكنوا﴾؟","answer":"صرحت البقرة بالقائل بإسناد القول إلى ضمير العظمة إظهارًا للمنة، أما الأعراف فبنت الفعل للمفعول للعلم بالقائل، إذ لا يكون هذا الأمر إلا من الله. ويمنع اختلاف الأسلوب تكرار القصة على صورة واحدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص773–774، تحت «بلاغة التشابه اللفظي بين آيتي الأعراف161–162، وآيتي البقرة58–59»","url":""}]},{"id":"s2-201","number":201,"surah":2,"verses":[58],"references":[{"surah":2,"verses":[58]},{"surah":7,"verses":[161]}],"verseLabel":"البقرة: 58، والأعراف: 161","question":"ما سرّ اختلاف التعبير بين قوله تعالى في البقرة: ﴿ادخلوا هذه القرية﴾، وفي الأعراف: ﴿اسكنوا هذه القرية﴾؟","answer":"الدخول مبدأ الوصول إلى القرية، والسكن هو الإقامة فيها بعد الدخول؛ فذكر كل موضع مرحلة من الحدث، وتكامل التعبيران بدل أن تتكرر القصة بألفاظ واحدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص773–774، تحت «بلاغة التشابه اللفظي بين آيتي الأعراف161–162، وآيتي البقرة58–59»","url":""}]},{"id":"s2-202","number":202,"surah":2,"verses":[58],"references":[{"surah":2,"verses":[58]},{"surah":7,"verses":[161]}],"verseLabel":"البقرة: 58، والأعراف: 161","question":"ما سرّ تقديم البقرة: ﴿وادخلوا الباب سجدًا﴾ على ﴿وقولوا حطة﴾، وعكست الأعراف الترتيب؟","answer":"عُطف الأمران بالواو، وهي لا تقتضي ترتيبًا بينهما؛ فالمطلوب اجتماعهما عند الدخول: خضوع الجسد بالسجود وطلب المغفرة بالقول. وتغيير ترتيب الذكر لا يغير ترتيب الامتثال، بل ينوع عرض القصة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص773–775، تحت «بلاغة التشابه اللفظي بين آيتي الأعراف161–162، وآيتي البقرة58–59»","url":""}]},{"id":"s2-203","number":203,"surah":2,"verses":[58],"references":[{"surah":2,"verses":[58]},{"surah":7,"verses":[161]}],"verseLabel":"البقرة: 58، والأعراف: 161","question":"ما مناسبة الواو في ﴿وسنزيد المحسنين﴾ لسياق سورة البقرة؟","answer":"زيادة الواو دالة على الاهتمام والتنويع، وهي مناسبة لسياق الامتنان وتعداد النعم في البقرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص487، تحت عنوان «توجيه المتشابه بين ألفاظ هذه القصة في سورتي البقرة والأعراف»، الوجه السابع","url":""}]},{"id":"s2-1499","number":1499,"surah":2,"verses":[58],"references":[{"surah":2,"verses":[58]},{"surah":7,"verses":[161]}],"verseLabel":"البقرة: 58، والأعراف: 161","question":"كيف دل الاستئناف في ﴿سنزيد المحسنين﴾ بالأعراف على أن الزيادة تفضل من الله؟","answer":"خرجت الجملة بترك الواو مخرج الاستئناف؛ فدل استقلالها على أن الزيادة تفضل محض ومنة من الله، وليست مقابلة لما سبق من الأمر بالخضوع والسجود والاستغفار.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص775، تحت عنوان «بلاغة التشابه اللفظي بين آيتي الأعراف (161–162)، وآيتي البقرة (58–59)»، الوجه السابع","url":""}]},{"id":"s2-204","number":204,"surah":2,"verses":[59],"references":[{"surah":2,"verses":[59]}],"verseLabel":"البقرة: 59","question":"ما سرّ التعبير في قوله تعالى: ﴿فبدل الذين ظلموا﴾، ولم يقل: «فبدلوا»؟","answer":"أظهر الموصول وصلته لتسجيل وصف الظلم عليهم وبيان أن التبديل صدر من الفريق المتصف به، وفيه تعليل لما استحقوه بعد ذلك من إنزال الرجز.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص481–482، تحت «سر التعبير بالاسم الموصول»","url":""}]},{"id":"s2-205","number":205,"surah":2,"verses":[59],"references":[{"surah":2,"verses":[59]},{"surah":7,"verses":[162]}],"verseLabel":"البقرة: 59، والأعراف: 162","question":"ما سرّ اختلاف التعبير بين قوله تعالى في البقرة: ﴿فأنزلنا﴾، وفي الأعراف: ﴿فأرسلنا﴾؟","answer":"﴿أنزلنا﴾ يلحظ جهة مجيء الرجز من السماء، وهو مناسب لتصريح البقرة بعدها بقوله: ﴿من السماء﴾. أما ﴿أرسلنا﴾ فيصور توجيه العذاب وتسليطه عليهم؛ فذكر كل موضع جانبًا من وقوع الرجز.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص773–776، تحت «بلاغة التشابه اللفظي بين آيتي الأعراف161–162، وآيتي البقرة58–59»","url":""}]},{"id":"s2-206","number":206,"surah":2,"verses":[59],"references":[{"surah":2,"verses":[59]},{"surah":7,"verses":[162]}],"verseLabel":"البقرة: 59، والأعراف: 162","question":"لماذا أعيد الاسم الظاهر في البقرة بقوله ﴿فأنزلنا على الذين ظلموا﴾؟","answer":"لتسجيل موجب العذاب، وهو ظلمهم، وللمبالغة في تقبيح أمرهم وتعظيمه، ولئلا يتوهم أن الرجز عم جميع بني إسرائيل؛ فالإظهار يربط العذاب بمن صدر منهم الظلم.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص484، تحت عنوان «سر الإظهار في موضع الإضمار»","url":""}]},{"id":"s2-1500","number":1500,"surah":2,"verses":[59],"references":[{"surah":2,"verses":[59]},{"surah":7,"verses":[162]}],"verseLabel":"البقرة: 59، والأعراف: 162","question":"لماذا عاد التعبير بالضمير ﴿عليهم﴾ في الأعراف بدل إعادة ﴿على الذين ظلموا﴾؟","answer":"قصدت آية البقرة بيان سبب إنزال العذاب مرتين: بالموصول الدال على علة الحكم، ثم بحرف السببية في ختامها. أما آية الأعراف فاقتُصر فيها على بيان السبب في الخاتمة ﴿بما كانوا يظلمون﴾، فعاد قبلها الضمير في ﴿فأرسلنا عليهم﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص776، تحت عنوان «بلاغة التشابه اللفظي بين آيتي الأعراف (161–162)، وآيتي البقرة (58–59)»، الوجه العاشر","url":""}]},{"id":"s2-207","number":207,"surah":2,"verses":[59],"references":[{"surah":2,"verses":[59]},{"surah":7,"verses":[162,163,165]}],"verseLabel":"البقرة: 59؛ الأعراف: 162؛ الأعراف: 163؛ الأعراف: 165","question":"لماذا ختمت البقرة: 59 بـ﴿بما كانوا يفسقون﴾ والأعراف: 162 بـ﴿بما كانوا يظلمون﴾؟","answer":"اقتضى السياق تأكيد وصفهم بالظلم. وقد تكرر لفظه في آية البقرة مرتين، فعدل في الخاتمة إلى الفسق بدل تكراره ثالثة، وفيه تغليظ في ذمهم يناسب التوبيخ. أما الأعراف فأعيد وصفهم بالظلم في الخاتمة لتأكيده.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص776، تحت عنوان «بلاغة التشابه اللفظي بين آيتي الأعراف (161–162)، وآيتي البقرة (58–59)»، الوجه الحادي عشر","url":""}]},{"id":"s2-1501","number":1501,"surah":2,"verses":[59],"references":[{"surah":2,"verses":[59]},{"surah":7,"verses":[162,163,165]}],"verseLabel":"البقرة: 59؛ الأعراف: 162؛ الأعراف: 163؛ الأعراف: 165","question":"ماذا يفيد الجمع بين ﴿كانوا﴾ و﴿يفسقون﴾ في تعليل الابتلاء في الأعراف: 163؟","answer":"يدل على إصرارهم على الفسق واستمراره وتجدده؛ فالسبب ليس واقعة عابرة، بل اعتيادهم الخروج عن الطاعة في أفعالهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص794، تحت عنوان «نكتة التعبير بالفعل المضارع ﴿يفسقون﴾»","url":""}]},{"id":"s2-1502","number":1502,"surah":2,"verses":[59],"references":[{"surah":2,"verses":[59]},{"surah":7,"verses":[162,163,165]}],"verseLabel":"البقرة: 59؛ الأعراف: 162؛ الأعراف: 163؛ الأعراف: 165","question":"كيف يصور لفظ ﴿يفسقون﴾ معصيتهم في ختام الأعراف: 165؟","answer":"تدل مادة الفسق على الخروج عن الحد بسبب الفساد، وتستحضر صيغة المضارع صورة تعديهم حدود الله كأنها حاضرة أمام القارئ. وتفيد أيضًا تجدد الفعل واستمراره، وفي السياق يتجدد العذاب بتجدد موجباته.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص35، تحت عنوان «بلاغة التعبير بـ﴿يفسقون﴾ مادة وصيغة»","url":""}]},{"id":"s2-208","number":208,"surah":2,"verses":[60],"references":[{"surah":2,"verses":[60]},{"surah":7,"verses":[160]}],"verseLabel":"البقرة: 60، والأعراف: 160","question":"ما الفرق بين ﴿فانفجرت﴾ في البقرة و﴿فانبجست﴾ في الأعراف؟","answer":"الانبجاس أول خروج الماء أو خروجه قليلًا، والانفجار خروجه بكثرة وقوة؛ فعبّرت آية الأعراف عن بداية خروج العيون، وعبّرت البقرة عن تمام تدفقها ووفرة النعمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص498، تحت عنوان «توجيه المتشابه اللفظي»، الوجه الثالث: الانفجار والانبجاس","url":""}]},{"id":"s2-209","number":209,"surah":2,"verses":[60],"references":[{"surah":2,"verses":[60]}],"verseLabel":"البقرة: 60","question":"ما سرّ تحديد العيون في قوله: ﴿فانفجرت منه اثنتا عشرة عينًا﴾؟","answer":"كانت بعدد أسباط بني إسرائيل الاثني عشر، ليختص كل سبط بعين يعرف منها مشربه، كما دل عليه قوله: ﴿قد علم كل أناس مشربهم﴾؛ وبذلك اندفع التنازع بينهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص494–495، تحت «نكتة فصل جملة: ﴿قد علم كل أناس مشربهم﴾»","url":""}]},{"id":"s2-210","number":210,"surah":2,"verses":[60],"references":[{"surah":2,"verses":[60]},{"surah":7,"verses":[160]}],"verseLabel":"البقرة: 60، والأعراف: 160","question":"ما سرّ اختلاف التعبير بين ﴿استسقى موسى لقومه﴾ في البقرة و﴿استسقاه قومه﴾ في الأعراف؟","answer":"ذكرت الأعراف طلب القوم من موسى السقيا، وذكرت البقرة ما ترتب عليه من استسقاء موسى ربه لهم؛ ولا تعارض، لأنهم طلبوا منه فدعا ربه. وخصت البقرة استسقاء موسى بالذكر لأنه أكمل وأبلغ في النعمة والمنة.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص497، تحت «توجيه المتشابه اللفظي»","url":""}]},{"id":"s2-211","number":211,"surah":2,"verses":[60],"references":[{"surah":2,"verses":[60]},{"surah":7,"verses":[160]}],"verseLabel":"البقرة: 60، والأعراف: 160","question":"ما سرّ التعبير في البقرة بـ﴿فقلنا اضرب بعصاك الحجر﴾، وفي الأعراف بـ﴿وأوحينا إلى موسى... أن اضرب﴾؟","answer":"لما كان القول المباشر من الله أكمل وأشرف من الإيحاء، ناسب سياق البقرة الدال على الامتنان، فجاء ﴿فقلنا﴾؛ وفي الأعراف عبّر بالإيحاء إلى موسى.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص497–498، تحت «توجيه المتشابه اللفظي»","url":""}]},{"id":"s2-212","number":212,"surah":2,"verses":[61],"references":[{"surah":2,"verses":[61]}],"verseLabel":"البقرة: 61","question":"ما وجه وصف المن والسلوى بقوله: ﴿طعام واحد﴾ مع أنهما شيئان؟","answer":"المراد وحدة النوع المعتاد عندهم وتكرر الطعام على حال واحدة، لا أن المن والسلوى شيء واحد في العدد. وقيل: لأنهما كانا يؤكلان معًا فجعلا بمنزلة طعام واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص507، تحت «علة التعبير عن المن والسلوى ـ وهما اثنان ـ بـ﴿طعام واحد﴾»","url":""}]},{"id":"s2-213","number":213,"surah":2,"verses":[61],"references":[{"surah":2,"verses":[61]},{"surah":43,"verses":[49]}],"verseLabel":"البقرة: 61؛ الزخرف: 49","question":"ما دلالة قول بني إسرائيل ﴿فادع لنا ربك﴾ دون «ربنا» في البقرة: 61؟","answer":"في إضافة الرب إلى موسى دون أنفسهم إيماء إلى أنهم لم يرجعوا إلى الله بصفاء النية وخلوص العقيدة، مع تكرر الصيغة منهم. وفيها جفاء وجرأة على مقام الربوبية، كأنهم لا يقرون بربوبيته لهم كما يقرون بها لموسى.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص508–509، تحت عنوان «نكتة التعبير بـ﴿فادع لنا ربك﴾ دون (ادع لنا ربنا)»","url":""}]},{"id":"s2-1503","number":1503,"surah":2,"verses":[61],"references":[{"surah":2,"verses":[61]},{"surah":43,"verses":[49]}],"verseLabel":"البقرة: 61؛ الزخرف: 49","question":"لماذا أضاف قوم فرعون الرب إلى موسى في ﴿ادع لنا ربك﴾ بالزخرف: 49؟","answer":"لاحظوا ما رأوه من رعاية الله لموسى وإحسانه إليه، فعبّروا بعنوان الربوبية وأضافوه إلى ضميره. ويذكر المصدر أنهم كانوا يتصورون أن لكل أمة ربًّا ويجيزون تعدد الآلهة؛ فكشفت الإضافة عن تصورهم، ولم تكن إقرارًا منهم بالتوحيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص106–107، تحت عنوان «سر التعبير بـ﴿ربك﴾ وإضافتها إلى ضميره»","url":""}]},{"id":"s2-214","number":214,"surah":2,"verses":[61],"references":[{"surah":2,"verses":[61]}],"verseLabel":"البقرة: 61","question":"ما دلالة وصف ما طلبوه بـ﴿الذي هو أدنى﴾، والمن والسلوى بـ﴿الذي هو خير﴾؟","answer":"وصف مطلوبهم بالأدنى، أي الأخس والأقل منزلة بالنسبة إلى المن والسلوى اللذين رزقوهما بلا مشقة؛ فوبخوا على استبدال الأدنى بالخير.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص510، تحت «دلالة الاستفهام في قوله: ﴿أتستبدلون﴾»","url":""}]},{"id":"s2-215","number":215,"surah":2,"verses":[61],"references":[{"surah":2,"verses":[61]}],"verseLabel":"البقرة: 61","question":"ما دلالة تنكير ﴿مصرًا﴾ في قوله: ﴿اهبطوا مصرًا﴾؟ وهل المراد مصر المعروفة؟","answer":"ذكر المصدر قولين: أن المراد مصر المعروفة، أو أي بلد من البلدان لا على التعيين. ورجح الثاني لكون اللفظ مصروفًا، ولأن ما سألوه متيسر في الأمصار؛ فليس مما يستدعي هذا الطلب مع ما أنعم الله به عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص502–503، تحت عنوان «شرح المفردات»، مدخل ﴿مصرًا﴾","url":""}]},{"id":"s2-216","number":216,"surah":2,"verses":[61],"references":[{"surah":2,"verses":[61]},{"surah":3,"verses":[112]}],"verseLabel":"البقرة: 61، وآل عمران: 112","question":"ما سرّ اختلاف التعبير بين ﴿النبيين﴾ في البقرة و﴿الأنبياء﴾ في آل عمران؟","answer":"﴿الأنبياء﴾ جمع تكسير يُلحظ فيه معنى الكثرة، فناسب مقام آل عمران الأشد في تعداد قبائحهم والتشنيع عليهم. أما ﴿النبيين﴾ فجمع سالم جاء ملائمًا لسياق البقرة في هذا الموضع.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص517–518، تحت «توجيه المتشابه اللفظي»","url":""}]},{"id":"s2-217","number":217,"surah":2,"verses":[61],"references":[{"surah":2,"verses":[61]},{"surah":3,"verses":[112]}],"verseLabel":"البقرة: 61، وآل عمران: 112","question":"ما سرّ تعريف ﴿الحق﴾ في البقرة: ﴿بغير الحق﴾، وتنكيره في آل عمران: ﴿بغير حق﴾؟","answer":"التعريف في البقرة يشير إلى الحق المعروف الذي تشرع به العقوبة إذا ثبت، فنفى أن يكون قتلهم داخلًا فيه. أما التنكير في سياق النفي بآل عمران فيعم نفي أي حق لقتلهم من كل وجه، فكان أبلغ في التشنيع.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص517–518، تحت «توجيه المتشابه اللفظي»","url":""}]},{"id":"s2-218","number":218,"surah":2,"verses":[62],"references":[{"surah":2,"verses":[62]}],"verseLabel":"البقرة: 62","question":"ما وجه جمع المؤمنين واليهود والنصارى والصابئين في هذا الوعد؟","answer":"الآية تقرر أن الأسماء والانتسابات وحدها لا تنفع، وإنما العبرة بالإيمان بالله واليوم الآخر والعمل الصالح وفق الوحي الواجب الاتباع. فمن كان قبل بعثة محمد ﷺ لزمه اتباع رسول زمانه، ومن أدرك بعثته فلا يصح إيمانه إلا باتباعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص527، تحت «سر ذكر النصارى والصابئين في مقام الحديث عن اليهود»","url":""}]},{"id":"s2-219","number":219,"surah":2,"verses":[62],"references":[{"surah":2,"verses":[62]}],"verseLabel":"البقرة: 62","question":"لماذا خُص الإيمان بالله واليوم الآخر بالذكر في البقرة: 62؟","answer":"من التوجيهات أن الإيمان يدخل تحته أقسام كثيرة، فخُص هذان القسمان للتنبيه على شرفهما؛ والتقدير: من آمن منهم بالله واليوم الآخر.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص528–529، تحت عنوان «سر ذكر الإيمان في أول الآية: ﴿إن الذين آمنوا﴾ وآخرها: ﴿من آمن﴾»","url":""}]},{"id":"s2-1504","number":1504,"surah":2,"verses":[62],"references":[{"surah":2,"verses":[62]}],"verseLabel":"البقرة: 62","question":"ما مناسبة اختيار اسم ﴿اليوم الآخر﴾ في سياق البقرة: 62؟","answer":"سياق الآية يفتح باب الأمل والتوبة والإنابة، ويمنح المخاطبين فرصة للرجوع إلى الإيمان؛ فناسبه وصف اليوم بالآخر بما يلائم هذا المقام ويبعث على الإنابة.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص529–530، تحت عنوان «مناسبة اختيار ﴿اليوم الآخر﴾ دون بقية أسماء القيامة»","url":""}]},{"id":"s2-1505","number":1505,"surah":2,"verses":[62],"references":[{"surah":2,"verses":[62]}],"verseLabel":"البقرة: 62","question":"لماذا عُطف ﴿وعمل صالحًا﴾ على الإيمان في البقرة: 62؟","answer":"للدلالة على أن الإيمان والعمل لا يفترقان؛ فالعمل الصالح يصدق دعوى الإيمان، ولا يغني مجرد الادعاء دون الامتثال.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص530، تحت عنوان «فائدة عطف قوله: ﴿وعمل صالحًا﴾ على الإيمان»","url":""}]},{"id":"s2-220","number":220,"surah":2,"verses":[62],"references":[{"surah":2,"verses":[62]},{"surah":5,"verses":[69]}],"verseLabel":"البقرة: 62، والمائدة: 69","question":"ما سرّ نصب ﴿الصابئين﴾ في البقرة ورفع ﴿الصابئون﴾ في المائدة؟","answer":"نصبت ﴿الصابئين﴾ في البقرة عطفًا على اسم ﴿إن﴾، ورفعت ﴿الصابئون﴾ في المائدة على الابتداء، بتقدير: «والصابئون كذلك»؛ وفي إخراجها عن نسق المعطوفات لفت للانتباه إليهم ودلالة على مساواتهم بغيرهم في الحكم المشروط بالإيمان والعمل الصالح.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص538، تحت «السر البلاغي في رفع ﴿والصابئون﴾ في سورة المائدة»","url":""}]},{"id":"s2-221","number":221,"surah":2,"verses":[62],"references":[{"surah":2,"verses":[62]},{"surah":5,"verses":[69]},{"surah":22,"verses":[17]}],"verseLabel":"البقرة: 62، والمائدة: 69، والحج: 17","question":"ما سرّ تقديم النصارى على الصابئين في البقرة، وتقديم الصابئين في المائدة والحج؟","answer":"في البقرة قُدّم النصارى وأُخّر الصابئون مع دخولهم جميعًا تحت توكيد ﴿إن﴾. وفي المائدة قُدّم ﴿الصابئون﴾ لفظًا ورُفع على الابتداء، على غير إرادة توكيد ﴿إن﴾، تنبيهًا إلى بعدهم عن أهل الكتاب مع شمول الحكم المشروط بالإيمان والعمل الصالح. أما ترتيب الحج فلا يُعلل بالزمن من غير نص مباشر.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص390–391، تحت «توجيه المتشابه اللفظي في التقديم بين النصارى والصابئين»","url":""}]},{"id":"s2-222","number":222,"surah":2,"verses":[62],"references":[{"surah":2,"verses":[62]},{"surah":5,"verses":[69]}],"verseLabel":"البقرة: 62، والمائدة: 69","question":"ما سرّ ذكر ﴿فلهم أجرهم عند ربهم﴾ في البقرة وحذفه من نظير آية المائدة؟","answer":"أجملت البقرة الجزاء بهذه الجملة. أما المائدة فقد سبق نظيرها بقليل تفصيل الجزاء في قوله: ﴿لكفرنا عنهم سيئاتهم ولأدخلناهم جنات النعيم﴾، فاستغنى السياق عن إعادة الإجمال بعد أن فصله.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص538، تحت «تخصيص آية البقرة بقوله تعالى: ﴿فلهم أجرهم عند ربهم﴾»","url":""}]},{"id":"s2-223","number":223,"surah":2,"verses":[63],"references":[{"surah":2,"verses":[63]}],"verseLabel":"البقرة: 63","question":"ما دلالة قوله: ﴿ورفعنا فوقكم الطور﴾ عند أخذ الميثاق؟","answer":"رُفع الطور فوقهم تخويفًا وحملًا لهم على أخذ الميثاق بجد، فصار الجبل المرفوع آية محسوسة على قدرة الله، وتأكيدًا لشدة ما أُخذ عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص547، تحت «المعنى الإجمالي»","url":""}]},{"id":"s2-224","number":224,"surah":2,"verses":[63],"references":[{"surah":2,"verses":[63]}],"verseLabel":"البقرة: 63","question":"ما دلالة إفراد ﴿ميثاقكم﴾ مع تعدد ما أُمروا به؟","answer":"لأن الأوامر والنواهي اجتمعت في عهد واحد أُخذ عليهم، فالإفراد باعتبار وحدة الميثاق، وإن تعددت بنوده وما يقتضيه من طاعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص549–550، تحت «سر إفراد الميثاق دون جمعه»","url":""}]},{"id":"s2-225","number":225,"surah":2,"verses":[63],"references":[{"surah":2,"verses":[63]}],"verseLabel":"البقرة: 63","question":"ما معنى أخذ الكتاب بقوة في قوله: ﴿خذوا ما آتيناكم بقوة﴾؟","answer":"المراد تلقي ما أوتوا بعلم ودراية، وبطاعة لله وعمل بما فيه؛ فالعلم يقوي الإنسان ويبلغه المقصود من أمر الدين، والعمل الصالح يقويه على ما فوقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص546–547، تحت عنوان «شرح المفردات»، مدخل ﴿بقوة﴾","url":""}]},{"id":"s2-226","number":226,"surah":2,"verses":[63,93],"references":[{"surah":2,"verses":[63,93]}],"verseLabel":"البقرة: 63 و93","question":"ما سرّ اختلاف التعبير بين ﴿واذكروا ما فيه﴾ عند الميثاق الأول و﴿واسمعوا﴾ عند الميثاق الآخر؟","answer":"سبق الميثاق الأول ذكر إيتاء موسى الكتاب والفرقان، فناسب أمرهم بذكر ما في الكتاب. أما الموضع الآخر فجاء بعد مواجهة اليهود المعاصرين بالقرآن وإعراضهم عنه، فكان ﴿واسمعوا﴾ تعريضًا بالخلف الذين لم يسمعوا سماع قبول، في أثناء حكاية ما قيل لأسلافهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص553–554، تحت «توجيه المتشابه اللفظي»","url":""}]},{"id":"s2-227","number":227,"surah":2,"verses":[65],"references":[{"surah":2,"verses":[65]}],"verseLabel":"البقرة: 65","question":"ما دلالة الأمر في قوله: ﴿كونوا قردة خاسئين﴾؟","answer":"﴿كونوا﴾ أمر تكويني يحصل به مراد الله، فوجدوا قدرته قد تسلطت عليهم وحولتهم إلى قردة من غير اختيار لهم؛ و﴿خاسئين﴾ أي صاغرين مطرودين، فجمع العقاب بين المسخ والإذلال والطرد.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص560، تحت «دلالة الأمر في ﴿كونوا﴾»","url":""}]},{"id":"s2-228","number":228,"surah":2,"verses":[66],"references":[{"surah":2,"verses":[66]}],"verseLabel":"البقرة: 66","question":"ما المراد بقوله: ﴿فجعلناها نكالًا لما بين يديها وما خلفها﴾؟","answer":"جُعلت العقوبة زاجرًا لمن عاصرها وشاهدها ولمن جاء بعدها وبلغه خبرها. وقيل: لما بين يدي القرية وما خلفها من القرى، أو لما تقدم من ذنوبهم وما تأخر؛ وأقرب المعاني امتداد العبرة إلى الحاضرين واللاحقين.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص561–562، تحت «بلاغة النظم في قوله: ﴿لما بين يديها وما خلفها﴾»","url":""}]},{"id":"s2-229","number":229,"surah":2,"verses":[67],"references":[{"surah":2,"verses":[67]}],"verseLabel":"البقرة: 67","question":"ماذا يكشف قولهم لموسى: ﴿أتتخذنا هزوًا﴾؟","answer":"استبعدوا أن يكون ذبح البقرة طريقًا إلى كشف القاتل، فواجهوا الأمر بسوء ظن بدل التسليم. واستعاذ موسى أن يكون من الجاهلين؛ لأن الاستهزاء في مقام تبليغ حكم الله جهل لا يليق بنبي.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص566، تحت «غرض استعاذة موسى أن يكون من الجاهلين»","url":""}]},{"id":"s2-230","number":230,"surah":2,"verses":[67,68,69,70,71,72,73],"references":[{"surah":2,"verses":[67,68,69,70,71,72,73]}],"verseLabel":"البقرة: 67–73","question":"ما سرّ تقديم قصة ذبح البقرة على ذكر جريمة القتل التي كانت سببًا لها؟","answer":"هذا تقديم في الذكر لا في الوقوع؛ فالقتل والتنازع سبقا الأمر بالذبح. وقُدم الذبح لأن آيات البقرة سيقت لبيان النعم، فناسب تقديم النعمة على الذنب، وليتوجه إليهم العتاب مرتين: على ترك المسارعة إلى أمر نبيهم، وعلى قتل النفس.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص592، تحت «سر تقديم ذبح البقرة على قتل النفس»","url":""}]},{"id":"s2-231","number":231,"surah":2,"verses":[67,68,69,70,71],"references":[{"surah":2,"verses":[67,68,69,70,71]}],"verseLabel":"البقرة: 67–71","question":"ما سرّ اختيار ذبح بقرة دون سائر الحيوان في كشف القاتل؟","answer":"اختيرت البقرة لأنها من جنس العجل الذي عبدوه، ليهون عندهم ما بقي من تعظيم هذا الجنس، وليظهر بامتثالهم ما بقي في نفوسهم من أثر عبادته.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص583، تحت «سر اختيار ذبح البقر دون سائر الحيوان»","url":""}]},{"id":"s2-232","number":232,"surah":2,"verses":[68,69,70,71],"references":[{"surah":2,"verses":[68,69,70,71]}],"verseLabel":"البقرة: 68–71","question":"ما أثر أسئلتهم المتكررة عن صفات البقرة في التكليف؟","answer":"كان الأمر أولًا مطلقًا يصدق على أي بقرة، فلو بادروا لأجزأتهم، لكنهم شددوا بالسؤال فشُدد عليهم بتوالي الصفات حتى ضاقت دائرة الاختيار. وفي ذلك ذم للتعنت وكثرة السؤال بغير حاجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص578، تحت «مناسبة الآية لما قبلها»","url":""}]},{"id":"s2-233","number":233,"surah":2,"verses":[69],"references":[{"surah":2,"verses":[69]}],"verseLabel":"البقرة: 69","question":"ما دلالة قوله في وصف البقرة: ﴿صفراء فاقع لونها تسر الناظرين﴾؟","answer":"هي بقرة صفراء شديدة الصفرة، يسر منظرها من ينظر إليها لحسنها.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص565، تحت عنوان «المعنى الإجمالي»","url":""}]},{"id":"s2-234","number":234,"surah":2,"verses":[70],"references":[{"surah":2,"verses":[70]}],"verseLabel":"البقرة: 70","question":"ما أثر قولهم: ﴿وإنا إن شاء الله لمهتدون﴾ بعد تكرر أسئلتهم؟","answer":"دل قولهم على اهتمامهم بالاهتداء وصدق وعدهم بالانقياد بعد تكرر السؤال؛ فأكدوه بإن واللام والجملة الاسمية، وتوسطت مشيئة الله بين اسم إن وخبرها إشعارًا بندمهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص575، تحت «فائدة توسط فعل المشيئة بين اسم إن وخبرها»","url":""}]},{"id":"s2-235","number":235,"surah":2,"verses":[71],"references":[{"surah":2,"verses":[71]}],"verseLabel":"البقرة: 71","question":"ما سرّ تقديم الوصف ﴿لا ذلول﴾ على قوله: ﴿تثير الأرض ولا تسقي الحرث﴾؟","answer":"﴿لا ذلول﴾ هو الوصف العام؛ أي لم تذلل للعمل، ثم ذُكر من أفراد العمل إثارة الأرض وسقي الحرث. فقدم الأصل الجامع ثم فصل مظهرين منه، ليتبين أنها مصونة عن جنس الاستخدام كله.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص585، تحت «التعبير بإثارة الحرث وسقي الزرع بالفعلية وغيرهما بالاسمية»","url":""}]},{"id":"s2-236","number":236,"surah":2,"verses":[73],"references":[{"surah":2,"verses":[73]}],"verseLabel":"البقرة: 73","question":"ما دلالة إبهام الجزء في قوله: ﴿اضربوه ببعضها﴾؟","answer":"لم يتعلق الغرض بتعيين جزء من البقرة، وإنما بإظهار قدرة الله على إحياء القتيل؛ فالإبهام يصرف النظر عن خصوص المادة إلى الآية الواقعة بأمر الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص597، تحت «فائدة الأمر بضرب الميت ببعض البقرة»","url":""}]},{"id":"s2-237","number":237,"surah":2,"verses":[73],"references":[{"surah":2,"verses":[73]}],"verseLabel":"البقرة: 73","question":"ما دلالة الانتقال من إحياء القتيل إلى قوله: ﴿كذلك يحيي الله الموتى﴾؟","answer":"جعل إحياء القتيل دليلًا محسوسًا على إمكان البعث العام؛ فكما أحيا الله هذه النفس بعد موتها يحيي الموتى جميعًا، ثم يري عباده آياته ليعقلوا دلالتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص597–598، تحت «بلاغة التشبيه وتنوع دلالته في قوله: ﴿كذلك يحيي الله الموتى﴾»","url":""}]},{"id":"s2-238","number":238,"surah":2,"verses":[74],"references":[{"surah":2,"verses":[74]}],"verseLabel":"البقرة: 74","question":"ما مقصد تشبيه قلوبهم بالحجارة في ﴿فهي كالحجارة﴾؟","answer":"شُبهت القلوب بالحجارة في الصلابة والغلظة والقساوة؛ وفي ذلك تشنيع عليهم وتقريع، لأن القلوب مظنة اللين والرأفة والخشوع، وقد صارت على خلاف ذلك.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص607، تحت عنوان «مقصد التشبيه في قوله: ﴿كالحجارة﴾»","url":""}]},{"id":"s2-1506","number":1506,"surah":2,"verses":[74],"references":[{"surah":2,"verses":[74]}],"verseLabel":"البقرة: 74","question":"كيف يبيّن ذكر منافع الحجارة أنها خير من تلك القلوب القاسية؟","answer":"ذكر من الحجارة ما تتفجر منه الأنهار، وما يتشقق فيخرج منه الماء، وما يهبط من خشية الله؛ فاجتمعت لها منافع مادية ومعنوية. أما تلك القلوب فلا يوجد فيها مثل هذا النفع، فكان التعقيب تفضيلًا للحجارة عليها وتقريعًا لأصحابها.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص609، تحت عنوان «بلاغة تعدد التعقيب بعد ذكر التشبيه»","url":""}]},{"id":"s2-239","number":239,"surah":2,"verses":[74],"references":[{"surah":2,"verses":[74]}],"verseLabel":"البقرة: 74","question":"ما دلالة إسناد الخشية إلى الحجارة في قوله: ﴿وإن منها لما يهبط من خشية الله﴾؟","answer":"أُسند الهبوط إلى خشية الله مجازًا عن انقياد الحجارة لأمره وامتثالها لما يريد فيها، وفي مقابل ذلك تقريع للقلوب التي لا تنقاد ولا تفعل ما أُمرت به.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص612، تحت «إسناد الخشية إلى الحجارة مجازًا عقليًا»","url":""}]},{"id":"s2-240","number":240,"surah":2,"verses":[74],"references":[{"surah":2,"verses":[74]}],"verseLabel":"البقرة: 74","question":"ما دلالة ﴿أو﴾ في قوله: ﴿فهي كالحجارة أو أشد قسوة﴾؟","answer":"ليست ﴿أو﴾ للشك؛ بل تفيد أن قلوبهم كالحجارة، بل أشد، وأن من شبّهها بالحجارة أو بما هو أشد فقد أصاب؛ وفي هذا زيادة تبكيت وتقريع.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص607–608، تحت «فائدة الإتيان بحرف العطف (أو) في قوله: ﴿فهي كالحجارة أو أشد قسوة﴾»","url":""}]},{"id":"s2-241","number":241,"surah":2,"verses":[74],"references":[{"surah":2,"verses":[74]}],"verseLabel":"البقرة: 74","question":"ما سرّ التعبير بـ﴿أشد قسوة﴾ بدل «أقسى»؟","answer":"لأن ﴿أشد قسوة﴾ يبرز القسوة نفسها ويصف بلوغها مبلغًا شديدًا، وفي لفظ ﴿أشد﴾ معنى المبالغة من مادته وصيغته، بخلاف «أقسى» الذي يدل على التفضيل بصيغته وحدها؛ فكان التركيب أبلغ في التشنيع.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص608، تحت «بلاغة التعبير بأفعل التفضيل في قوله ﴿أو أشد قسوة﴾»","url":""}]},{"id":"s2-242","number":242,"surah":2,"verses":[75],"references":[{"surah":2,"verses":[75]}],"verseLabel":"البقرة: 75","question":"ما سرّ التعبير في قوله: ﴿ثم يحرفونه من بعد ما عقلوه﴾، لا بمجرد السماع؟","answer":"لأن العقل هنا فهم الكلام وإدراك معناه؛ فتحريفه بعد فهمه أبلغ في الذم من تغييره بعد سماع لا يصحبه علم، إذ يثبت أنهم فعلوه عن معرفة وعمد.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص621–622، تحت «سر دخول (من) في قوله ﴿من بعد ما عقلوه﴾»","url":""}]},{"id":"s2-243","number":243,"surah":2,"verses":[75],"references":[{"surah":2,"verses":[75]}],"verseLabel":"البقرة: 75","question":"ما سرّ تعدية ﴿يؤمنوا﴾ باللام في قوله: ﴿أفتطمعون أن يؤمنوا لكم﴾؟","answer":"ضُمّن الإيمان معنى الإقرار أو الإذعان، فعدي باللام؛ أي أتطمعون أن يقروا لكم ويذعنوا لما تدعونهم إليه؟ فالمقصود ليس مجرد المعرفة الباطنة، بل قبول الحق والانقياد له.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص621، تحت «تعدية الفعل ﴿يؤمنوا﴾ باللام»","url":""}]},{"id":"s2-244","number":244,"surah":2,"verses":[76],"references":[{"surah":2,"verses":[76]}],"verseLabel":"البقرة: 76","question":"ما دلالة ﴿خلا إلى﴾ في قوله: ﴿وإذا خلا بعضهم إلى بعض﴾؟","answer":"تدل على الانفراد والانصراف المقصود إلى بعضهم بعيدًا عن غيرهم؛ فصورت خلوهم في مجلس خاص يتراجعون فيه عما أظهروه للمؤمنين.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص624، تحت عنوان «شرح المفردات»، مدخل ﴿خلا﴾","url":""}]},{"id":"s2-245","number":245,"surah":2,"verses":[77],"references":[{"surah":2,"verses":[77]}],"verseLabel":"البقرة: 77","question":"ما دلالة المضارع في قوله: ﴿يعلم ما يسرون وما يعلنون﴾؟","answer":"يفيد تجدد علمه بكل ما يجددونه من إسرار وإعلان، واستحضار إحاطته الدائمة بباطن قولهم وظاهره؛ فلا يخفى عليه اختلاف أحوالهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص634، تحت «فائدة إيثار صيغة الأفعال المضارعة في الآية»","url":""}]},{"id":"s2-246","number":246,"surah":2,"verses":[77],"references":[{"surah":2,"verses":[77]}],"verseLabel":"البقرة: 77","question":"ما سرّ مقابلة الإسرار بالإعلان في قوله: ﴿ما يسرون وما يعلنون﴾؟","answer":"بين ﴿يسرون﴾ و﴿يعلنون﴾ طباق يقرر استواء السر والعلن في علم الله، ويؤكد إحاطة علمه بالأمرين.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص636، تحت عنوان «بديع الطباق في الآية»","url":""}]},{"id":"s2-247","number":247,"surah":2,"verses":[77,284],"references":[{"surah":2,"verses":[77,284]}],"verseLabel":"البقرة: 77 و284","question":"كيف يناسب تقديم ﴿ما يسرون﴾ سبقَ الإضمار في النفس للإعلان؟","answer":"لأن مرتبة السر متقدمة على مرتبة العلن؛ فما يعلن غالبًا يسبقه إضمار في القلب. فوافق ترتيب اللفظ هذا السبق، مع كون العلم بالأخفى أدل على الإحاطة.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص635، تحت عنوان «بلاغة تقديم الإسرار على الإعلان»","url":""}]},{"id":"s2-1507","number":1507,"surah":2,"verses":[77,284],"references":[{"surah":2,"verses":[77,284]}],"verseLabel":"البقرة: 77 و284","question":"لماذا قدم الإسرار في البقرة: 77، والإبداء في البقرة: 284؟","answer":"آية 77 في بيان العلم فناسبها تقديم الإسرار، أما آية 284 ففي مقام المحاسبة على الأعمال، والأصل في تصور المحاسبة أن تتعلق بالأمور الظاهرة؛ فقدم في كل سياق ما يناسبه.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص636، تحت عنوان «توجيه المتشابه اللفظي»","url":""}]},{"id":"s2-248","number":248,"surah":2,"verses":[78],"references":[{"surah":2,"verses":[78]}],"verseLabel":"البقرة: 78","question":"ما دلالة وصف الأميين بقوله تعالى: ﴿لا يعلمون الكتاب إلا أماني﴾، مع أن الأماني ليست علمًا؟","answer":"الاستثناء منقطع بمعنى الاستدراك؛ فنفى عنهم العلم الصحيح، ثم بيّن أن ما عندهم لا يعدو أماني باطلة يظنونها علمًا. وهذا أبلغ في ذمهم من مجرد نفي العلم؛ لأنه يكشف جهلهم المركب.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص644، تحت عنوان «سر استعمال الاستثناء المنقطع»","url":""}]},{"id":"s2-249","number":249,"surah":2,"verses":[79],"references":[{"surah":2,"verses":[79]}],"verseLabel":"البقرة: 79","question":"ما سرّ تكرار الوعيد في قوله: ﴿فويل لهم مما كتبت أيديهم وويل لهم مما يكسبون﴾؟","answer":"لأن الجريمة ذات جانبين: كتابة الباطل ونسبته إلى الله، ثم تحصيل الكسب المحرم به. فاستقل كل جانب بوعيد؛ الأول على الوسيلة المزورة، والثاني على ما اتخذوه منها من منفعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص651، تحت «بلاغة تكرار ﴿ويل﴾ في الآية»","url":""}]},{"id":"s2-250","number":250,"surah":2,"verses":[79],"references":[{"surah":2,"verses":[79]}],"verseLabel":"البقرة: 79","question":"ما سرّ الماضي في ﴿مما كتبت أيديهم﴾ والمضارع في ﴿مما يكسبون﴾؟","answer":"جاءت الكتابة بالماضي لأنها وقعت وثبت بها استحقاق الوعيد، وجاء الكسب بالمضارع لتصوير تجدده واستمراره؛ إذ تتجدد منافع التحريف وآثاره ما دام الناس يعملون به.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص651–652، تحت «سر مخالفة الصيغة الزمنية في الفعلين ﴿كتبت﴾ و﴿يكسبون﴾»","url":""}]},{"id":"s2-251","number":251,"surah":2,"verses":[80],"references":[{"surah":2,"verses":[80]}],"verseLabel":"البقرة: 80","question":"ما سرّ التعبير بالمس في قولهم: ﴿لن تمسنا النار إلا أيامًا معدودة﴾؟","answer":"اختاروا المس، وهو أول درجات الأذى وأقلها تمكنًا، تهوينًا للعذاب في زعمهم، ثم قصروا ذلك على أيام معدودة قليلة منقضية؛ فكشف التعبير بطلان دعواهم واغترارهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص658، تحت «المس والإصابة»","url":""}]},{"id":"s2-252","number":252,"surah":2,"verses":[80],"references":[{"surah":2,"verses":[80]}],"verseLabel":"البقرة: 80","question":"ما دلالة وصف الأيام بأنها ﴿معدودة﴾؟","answer":"وصف الأيام بالمعدودة يدل على قلتها؛ فقد شاع في الاستعمال أن ما يحصره العد قليل. وهذا يصور زعمهم أن مدة العذاب قصيرة محدودة.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص654، تحت عنوان «شرح المفردات»، مدخل ﴿معدودة﴾","url":""}]},{"id":"s2-253","number":253,"surah":2,"verses":[80],"references":[{"surah":2,"verses":[80]},{"surah":3,"verses":[24]}],"verseLabel":"البقرة: 80، وآل عمران: 24","question":"ما سرّ وصف ﴿أيامًا﴾ بالمفرد ﴿معدودة﴾ في البقرة، وبالجمع ﴿معدودات﴾ في آل عمران؟","answer":"جاء موضع البقرة أوجز في نقل دعواهم، فناسبه الوصف المفرد الذي يجوز مع جمع غير العاقل. أما آل عمران فبسطت قبائحهم وإعراضهم، فناسب البسط جمع الوصف في ﴿معدودات﴾، مع اتحاد أصل المعنى وهو ادعاء قلة الأيام.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص655، تحت «التعبير بالإفراد في الأيام»","url":""}]},{"id":"s2-254","number":254,"surah":2,"verses":[81,82],"references":[{"surah":2,"verses":[81,82]}],"verseLabel":"البقرة: 81–82","question":"ما وجه المقابلة بين أصحاب السيئة وأصحاب الإيمان والعمل الصالح في الآيتين 81 و82؟","answer":"قابلت الآيتان من كسب السيئة حتى أحاطت به خطيئته بمن آمن وعمل الصالحات؛ فهناك سيئة مستولية تقود إلى النار، وهنا إيمان تصدقه الأعمال يقود إلى الجنة. وبالمقابلة يظهر اختلاف السبب والعاقبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص665، تحت «بلاغة الوصل بين الجمل»","url":""}]},{"id":"s2-255","number":255,"surah":2,"verses":[81],"references":[{"surah":2,"verses":[81]}],"verseLabel":"البقرة: 81","question":"ما الصورة في قوله ﴿وأحاطت به خطيئته﴾؟","answer":"صُورت الخطيئة كحائط يطوق صاحبه من جميع الجوانب ولا يترك له منفذًا؛ ففي التعبير استعارة تمثيلية تصور تمكن الخطيئة منه وغلبتها عليه وعدم إقلاعه عنها.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص662، تحت عنوان «بلاغة الاستعارة التمثيلية في قوله تعالى: ﴿وأحاطت به خطيئته﴾»","url":""}]},{"id":"s2-1508","number":1508,"surah":2,"verses":[81],"references":[{"surah":2,"verses":[81]}],"verseLabel":"البقرة: 81","question":"كيف تؤدي المداومة على السيئة دون توبة إلى إحاطة الخطيئة بصاحبها؟","answer":"المداومة على السيئة تجر إلى معاودة الخطأ والانهماك فيه حتى يستولي على صاحبه ويصير ملازمًا له؛ فهذا أثر الاستمرار دون توبة، لا مجرد وقوع ذنب عارض ثم الإقلاع عنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص663، تحت عنوان «بلاغة ذكر السيئة قبل الخطيئة»","url":""}]},{"id":"s2-256","number":256,"surah":2,"verses":[83],"references":[{"surah":2,"verses":[83]}],"verseLabel":"البقرة: 83","question":"ما سرّ التعبير بالمصدر في قوله: ﴿وبالوالدين إحسانًا﴾؟","answer":"ناب المصدر ﴿إحسانًا﴾ عن فعل الأمر؛ أي: أحسنوا إلى الوالدين إحسانًا، وفي وضع المصدر موضع الأمر توكيد لطلب الإحسان وتقرير له.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص673–674، تحت «دلالة مجيء المصدر النائب عن فعل الأمر»","url":""}]},{"id":"s2-257","number":257,"surah":2,"verses":[83],"references":[{"surah":2,"verses":[83]}],"verseLabel":"البقرة: 83","question":"ما دلالة الإفراد في قوله: ﴿وذي القربى﴾؟","answer":"﴿ذو القربى﴾ اسم جنس يصدق على كل من له قرابة، فالمفرد هنا عام في أفراد الأقارب، ولم يُرد به قريب واحد بعينه.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص674، تحت «نكتة إفراد ﴿القربى﴾»","url":""}]},{"id":"s2-258","number":258,"surah":2,"verses":[83],"references":[{"surah":2,"verses":[83]},{"surah":4,"verses":[36]}],"verseLabel":"البقرة: 83، والنساء: 36","question":"ما سرّ عدم إعادة الباء في البقرة: ﴿وبالوالدين إحسانًا وذي القربى﴾، وإعادتها في النساء: ﴿وبذي القربى﴾؟","answer":"لم تُعد الباء في البقرة لأن الكلام حكاية عما مضى من ميثاق بني إسرائيل، وأعيدت في النساء لأن سياق السورة قبلها في الأقارب وأحكامهم من المواريث والوصايا والصلات، فناسب توكيد العناية بذي القربى بإعادة الباء.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص140، تحت «دلالة إعادة حرف الجر في قوله: ﴿وبذي القربى﴾»","url":""}]},{"id":"s2-259","number":259,"surah":2,"verses":[83],"references":[{"surah":2,"verses":[83]}],"verseLabel":"البقرة: 83","question":"ما سرّ مجيء النهي في صورة الخبر: ﴿لا تعبدون إلا الله﴾؟","answer":"أُخرج التكليف في صورة خبر مبالغةً في توكيده، حتى كأن امتثالهم له أمر محقق يُخبر عنه. وفي ذلك حث على الوفاء بالميثاق، وإشعار بأن توحيد الله لا ينبغي أن يقع منهم خلافه.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص672، تحت «بلاغة مجيء الإنشاء بصورة الخبر»","url":""}]},{"id":"s2-260","number":260,"surah":2,"verses":[84],"references":[{"surah":2,"verses":[84]}],"verseLabel":"البقرة: 84","question":"ما سرّ التعبير عن دماء غيرهم وديارهم بقوله: ﴿دماءكم﴾ و﴿أنفسكم من دياركم﴾؟","answer":"جعل أهل النسب أو الدين بمنزلة النفس لشدة الاتصال بينهم؛ فمن سفك دم أخيه فكأنما قتل نفسه، كما أن قتل غيره قد يفضي إلى قتله قصاصًا، وإخراجه غيره قد يفضي إلى إخراجه.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص682، تحت «فائدة إضافة الدماء إلى الضمير»","url":""}]},{"id":"s2-261","number":261,"surah":2,"verses":[84,85],"references":[{"surah":2,"verses":[84,85]}],"verseLabel":"البقرة: 84–85","question":"ما سرّ التعبير أولًا بـ﴿لا تسفكون دماءكم﴾، ثم وصف فعلهم بقوله: ﴿تقتلون أنفسكم﴾؟","answer":"سفك الدم أعم، فيشمل القتل والجراح وكل إراقة للدم، فناسب الميثاق الذي يمنع جنس الاعتداء. ثم خُص القتل عند وصف فعلهم لأنه أقبح صور السفك التي انتهكوا بها العهد؛ فانتقل من العام إلى أشد أفراده.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص691، تحت «بلاغة التعبير القرآني بقتل النفس»","url":""}]},{"id":"s2-262","number":262,"surah":2,"verses":[84,85],"references":[{"surah":2,"verses":[84,85]}],"verseLabel":"البقرة: 84–85","question":"ما سرّ التعبير في الميثاق بـ﴿ولا تخرجون أنفسكم من دياركم﴾، وعند وصف الفعل بـ﴿وتخرجون فريقًا منكم من ديارهم﴾؟","answer":"صاغ الميثاق إخراج بعضهم كأنه إخراج للنفس لما بينهم من وحدة الدين والجماعة، ثم فصّل الواقع فبيّن أنهم أخرجوا فريقًا معينًا منهم من دياره. فانتقل من تصوير حرمة الفعل إلى تسجيل من وقع عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص691–692، تحت «براعة الاختلاف في التعبير بين الإجمال والتفصيل»","url":""}]},{"id":"s2-263","number":263,"surah":2,"verses":[85],"references":[{"surah":2,"verses":[85]}],"verseLabel":"البقرة: 85","question":"ما دلالة وصف أخذ بعض أحكام الكتاب وترك بعضها بالإيمان والكفر؟","answer":"شُبّه امتثالهم حكم الفداء بالإيمان، وشُبّه تعمدهم القتل والإخراج بالكفر، مبالغةً في تقبيح المخالفة والردع عنها، مع الإنذار بأن تعمد مخالفة الكتاب قد يفضي إلى الكفر به.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص694–695، تحت «دلالة همزة الاستفهام»","url":""}]},{"id":"s2-264","number":264,"surah":2,"verses":[85],"references":[{"surah":2,"verses":[85]},{"surah":8,"verses":[70]}],"verseLabel":"البقرة: 85، والأنفال: 70","question":"ما الفرق بين ﴿أُسارى﴾ في البقرة و﴿أسرى﴾ في الأنفال؟","answer":"كلاهما جمع أسير، وقيل: ﴿أسرى﴾ لمن كان في الأسر، و﴿أُسارى﴾ لمن اشتد عليه الأسر والوثاق. فناسب ﴿أسرى﴾ أسرى بدر الذين صاروا في يد المسلمين، وناسب ﴿أُسارى﴾ من جيء بهم في حال الضعف ليفادوا.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص465–467، تحت «سر التعبير بالأسرى في القراءات القرآنية»","url":""}]},{"id":"s2-265","number":265,"surah":2,"verses":[85],"references":[{"surah":2,"verses":[85]}],"verseLabel":"البقرة: 85","question":"ما دلالة توالي الأفعال المضارعة في وصف اعتدائهم في الآية 85؟","answer":"تستحضر صيغة المضارع أفعالهم كأنها تقع أمام السامع، وتدل على تجدد هذا المسلك واستمرارهم عليه: يقتلون ويخرجون ويتظاهرون ثم يفادون، ويؤمنون ببعض الكتاب ويكفرون ببعض.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص691، تحت «بديع استعمال صيغة المضارع»","url":""}]},{"id":"s2-266","number":266,"surah":2,"verses":[85],"references":[{"surah":2,"verses":[85]}],"verseLabel":"البقرة: 85","question":"ما سرّ التعبير بنفي الغفلة في قوله: ﴿وما الله بغافل عما تعملون﴾؟","answer":"لأن تماديهم في المخالفة يشبه فعل من يظن أن عمله يفوت علم الله وجزاءه، فجاء نفي الغفلة تهديدًا بأن أعمالهم كلها محفوظة وسيحاسبون عليها. وهو أوقع في مقام الوعيد من مجرد الإخبار بالعلم.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص698، تحت «سر نفي الغفلة لا إثبات العلم»","url":""}]},{"id":"s2-267","number":267,"surah":2,"verses":[86],"references":[{"surah":2,"verses":[86]}],"verseLabel":"البقرة: 86","question":"ما الصورة في قوله: ﴿اشتروا الحياة الدنيا بالآخرة﴾؟","answer":"صُور إيثارهم الدنيا على الآخرة بصفقة جعلوا فيها الآخرة ثمنًا للدنيا؛ فدل الشراء على قصدهم واختيارهم، وكشف فداحة الخسارة في مبادلة الباقي بالفاني.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص702، تحت «بلاغة الاستعارة التصريحية التبعية»","url":""}]},{"id":"s2-268","number":268,"surah":2,"verses":[87],"references":[{"surah":2,"verses":[87]}],"verseLabel":"البقرة: 87","question":"ما الصورة في قوله: ﴿وقفينا من بعده بالرسل﴾؟","answer":"التقفية جعل الشيء في قفا الشيء؛ فصُور تتابع الرسل بعد موسى كأن كل رسول يتبع أثر من قبله. وفي ذلك بيان استمرار الحجة وعدم انقطاع إرسال الرسل.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص706، تحت عنوان «شرح المفردات»، مدخل ﴿وقفينا﴾","url":""}]},{"id":"s2-269","number":269,"surah":2,"verses":[87],"references":[{"surah":2,"verses":[87]},{"surah":5,"verses":[70]}],"verseLabel":"البقرة: 87، والمائدة: 70","question":"ما سرّ خطاب بني إسرائيل في البقرة: ﴿ففريقًا كذبتم وفريقًا تقتلون﴾، والإخبار عنهم بالغائب في المائدة؟","answer":"واجهت البقرة اليهود الحاضرين بأفعال أسلافهم لأنهم رضوا طريقتهم واستمروا عليها، فناسب الخطاب في مقام التوبيخ. أما المائدة فحكت تاريخ بني إسرائيل في سياق الإخبار عنهم، فناسب ضمير الغائب.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص426، تحت «من المتشابه اللفظي: الفرق بين «فريقًا كذبتم وفريقًا تقتلون» وبين «فريقًا كذبوا وفريقًا يقتلون»»","url":""}]},{"id":"s2-270","number":270,"surah":2,"verses":[87],"references":[{"surah":2,"verses":[87]}],"verseLabel":"البقرة: 87","question":"ما سرّ الماضي في ﴿ففريقًا كذبتم﴾ والمضارع في ﴿وفريقًا تقتلون﴾؟","answer":"جاء التكذيب بالماضي لإثبات ما وقع، وجاء القتل بالمضارع لاستحضار بشاعته كأنه يقع الآن، وللدلالة على استمرار طريقتهم واستعدادهم لقتل من خالف أهواءهم من الرسل.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص712، تحت «علة الاختلاف بين المتقابلين»","url":""}]},{"id":"s2-271","number":271,"surah":2,"verses":[87],"references":[{"surah":2,"verses":[87]}],"verseLabel":"البقرة: 87","question":"ما سرّ تقديم تكذيب الرسل على قتلهم؟","answer":"لأن التكذيب مبدأ الجريمة ومشترك بين الفريقين؛ فالذين قُتلوا قد كُذبوا أولًا. ثم ترقى التعبير من التكذيب إلى القتل، فانتقل من القبيح إلى ما هو أشد قبحًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص714، تحت «سر تقديم التكذيب على القتل»","url":""}]},{"id":"s2-272","number":272,"surah":2,"verses":[87],"references":[{"surah":2,"verses":[87]}],"verseLabel":"البقرة: 87","question":"ما سرّ التعبير بـ﴿بما لا تهوى أنفسكم﴾ بدل «بما تكره أنفسكم»؟","answer":"عدم الهوى أعم من الكراهة؛ فقد لا تكره النفس الشيء ولكنها لا تميل إليه ولا يوافق غرضها. فدل التعبير على أنهم يردون كل ما لا يوافق أهواءهم، لا ما يكرهونه كراهة صريحة فقط.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص714، تحت «(لا تهوى) و(تكره)»","url":""}]},{"id":"s2-273","number":273,"surah":2,"verses":[88],"references":[{"surah":2,"verses":[88]}],"verseLabel":"البقرة: 88","question":"ما دلالة قوله: ﴿فقليلًا ما يؤمنون﴾؟","answer":"جاءت الفاء لتفريع قلة إيمانهم على لعنهم وطردهم من رحمة الله بسبب كفرهم؛ فبسبب اللعن استحقوا ألا يؤمنوا إلا قليلًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص717، تحت «شرح المفردات: «قليلًا»، والمعنى الإجمالي»","url":""}]},{"id":"s2-274","number":274,"surah":2,"verses":[89],"references":[{"surah":2,"verses":[89]}],"verseLabel":"البقرة: 89","question":"ما فائدة قوله: ﴿مصدق لما معهم﴾ في إقامة الحجة على أهل الكتاب؟","answer":"جاء وصف القرآن بأنه ﴿مصدق لما معهم﴾ بعد وصفه بأنه من عند الله، فأثبت أنه يوافق ما معهم من التوراة ولا يعارضها أو يكذبها. وهذا دليل آخر على صدقه لديهم، وتأكيد لكونه من عند الله يلزمهم الحجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص726–727، تحت عنوان «نكتة توالي الصفات»","url":""}]},{"id":"s2-275","number":275,"surah":2,"verses":[89],"references":[{"surah":2,"verses":[89]}],"verseLabel":"البقرة: 89","question":"ما دلالة قوله عن أهل الكتاب: ﴿وكانوا من قبل يستفتحون على الذين كفروا﴾؟","answer":"كانوا قبل بعثة النبي ﷺ يترقبون مجيئه وينتظرون النصر به على مشركي العرب، وكانت صفاته ونعوته مكتوبة عندهم؛ فلما جاءهم ما عرفوا كفروا به، فناقض فعلهم معرفتهم وانتظارهم السابق.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص729، تحت «نكتة تعدية فعل الاستفتاح بحرف الاستعلاء»","url":""}]},{"id":"s2-276","number":276,"surah":2,"verses":[90],"references":[{"surah":2,"verses":[90]}],"verseLabel":"البقرة: 90","question":"ما الصورة في قوله: ﴿بئسما اشتروا به أنفسهم﴾؟","answer":"شُبّه استبدالهم الإيمان بالكفر بصفقة بيع وشراء: أنفسهم هي المثمن، والكفر هو الثمن؛ فباعوا أنفسهم بالكفر وزهدوا فيها. وجاء ﴿بئسما﴾ لاستيفاء ذم هذا الصنيع وبيان قبحه وخسارته.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص736، تحت «بلاغة الاستعارة في قوله تعالى: ﴿اشتروا به أنفسهم﴾»","url":""}]},{"id":"s2-277","number":277,"surah":2,"verses":[90],"references":[{"surah":2,"verses":[90]}],"verseLabel":"البقرة: 90","question":"ما سرّ التعبير بـ﴿بغيًا﴾ في قوله: ﴿بغيًا أن ينزل الله من فضله﴾ بدل الاقتصار على الحسد؟","answer":"البغي أعم من الحسد؛ فهو تجاوز الحد في الأمر كله، ويدل على الحسد تضمّنًا، وقد جمع السياق معنى الحسد لخروج النبوة من بني إسرائيل؛ فجمع التعبير معنى التجاوز ودلالة الحسد، ووصفهم بالأعم زيادةً في ذمهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص738، تحت «سر التعبير بالبغي دون الحسد»","url":""}]},{"id":"s2-278","number":278,"surah":2,"verses":[90],"references":[{"surah":2,"verses":[90]}],"verseLabel":"البقرة: 90","question":"ما دلالة حرف الاستعلاء في قوله تعالى: ﴿فباءوا بغضب على غضب﴾؟","answer":"يدل حرف ﴿على﴾ على اجتماع الغضبين وتضاعفهما من غير فتور بينهما، جزاءً لأعمالهم القبيحة المتوالية.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص740، تحت «دلالة حرف الاستعلاء في قوله ﴿غضب على غضب﴾»","url":""}]},{"id":"s2-279","number":279,"surah":2,"verses":[91],"references":[{"surah":2,"verses":[91]}],"verseLabel":"البقرة: 91","question":"ما دلالة بناء فعل القول للمفعول في قوله تعالى: ﴿وإذا قيل لهم آمنوا بما أنزل الله﴾؟","answer":"بُني فعل القول للمفعول لأن القائل معلوم، ولإظهار أن موقف اليهود ثابت من كل من يدعوهم إلى الإيمان، بصرف النظر عن مكانته؛ سواء أكان نبيًا أم صحابيًا أم أعرابيًا: الرفض والإعراض.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص745، تحت «فائدة بناء الفعل للمفعول»","url":""}]},{"id":"s2-280","number":280,"surah":2,"verses":[91],"references":[{"surah":2,"verses":[91]}],"verseLabel":"البقرة: 91","question":"ماذا يفيد المضارع في قولهم ﴿نؤمن بما أنزل علينا﴾؟","answer":"يصور ادعاءهم استمرار الإيمان بما أنزل عليهم من التوراة. وقد اتخذوا هذا الادعاء اعتذارًا لرفض الإيمان بالقرآن، محتجين بفضل اختصاصهم بما أنزل عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص746، تحت عنوان «نكتة مجيء الفعل ﴿نؤمن﴾ بصيغة المضارع»","url":""}]},{"id":"s2-1509","number":1509,"surah":2,"verses":[91],"references":[{"surah":2,"verses":[91]}],"verseLabel":"البقرة: 91","question":"لماذا جاء قولهم ﴿بما أنزل علينا﴾ مبنيًا للمفعول دون التصريح باسم الله؟","answer":"لأن غرضهم تعظيم أنفسهم والتوراة من جهة اختصاصهم بإنزالها عليهم؛ فعدلوا عن التصريح بالفاعل، مع ما فيه من التشريف، لقلة عنايتهم إلا بأنفسهم. وليس سبب الحذف جهلهم بالمنزّل، فهم يعلمون أنه الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص746–747، تحت عنوان «العدول عن الفعل المبني للفاعل إلى المبني للمفعول»","url":""}]},{"id":"s2-281","number":281,"surah":2,"verses":[91,97],"references":[{"surah":2,"verses":[91,97]}],"verseLabel":"البقرة: 91 و97","question":"ما سرّ اختلاف التعبير بين قوله تعالى في الآية 91: ﴿مصدقًا لما معهم﴾، وقوله في الآية 97: ﴿مصدقًا لما بين يديه﴾؟","answer":"خُصَّ التصديق في الآية 91 بما مع اليهود من التوراة لأن المقام مقام مخاطبتهم وإلزامهم الحجة. أما الآية 97 فمقامها تفخيم القرآن وبيان موقف جبريل منه، فجيء بالوصف عامًا في تصديقه الكتب السابقة كلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص794، تحت «توجيه المتشابه اللفظي»","url":""}]},{"id":"s2-282","number":282,"surah":2,"verses":[91],"references":[{"surah":2,"verses":[91]}],"verseLabel":"البقرة: 91","question":"ما دلالة قوله تعالى عن القرآن: ﴿ويكفرون بما وراءه﴾؟","answer":"إن كانت ﴿وراء﴾ بمعنى الخلف، ففيها كناية أو استعارة عن طرح القرآن وراء ظهورهم وترك الإيمان به. وإن كانت بمعنى أمام، ففيها مدح للقرآن المهيمن على الكتب السابقة وذم لهم إذ كفروا به. وكلا الوجهين يذم عدم إيمانهم بالقرآن.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص747–748، تحت «أثر معنى المفردة ﴿وراءه﴾ في استجلاء الدلالات»","url":""}]},{"id":"s2-283","number":283,"surah":2,"verses":[91],"references":[{"surah":2,"verses":[91]}],"verseLabel":"البقرة: 91","question":"ما سرّ مجيء ﴿تقتلون﴾ بالمضارع مع تقييده بقوله: ﴿من قبل﴾؟","answer":"جيء بالمضارع لاستحضار بشاعة قتل الأنبياء، وللدلالة على رضا المعاصرين بفعل أسلافهم واتباعهم منهجهم والعزم عليه. وجاء ﴿من قبل﴾ احتراسًا لئلا يُتوهم أنهم باشروا القتل، مع إبقاء نسبته إليهم بسبب رضاهم به.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص751، تحت «سر اقتران الحال والاستقبال بقيد الماضي»","url":""}]},{"id":"s2-284","number":284,"surah":2,"verses":[92],"references":[{"surah":2,"verses":[92]}],"verseLabel":"البقرة: 92","question":"ما سرّ استعمال ﴿ثم﴾ في قوله تعالى: ﴿ثم اتخذتم العجل﴾ بدل الواو؟","answer":"أفادت ﴿ثم﴾ أنهم اتخذوا العجل بعد مهلة من مجيء البينات كان ينبغي أن تزيدهم تدبرًا وثباتًا على التوحيد؛ فزاد ذلك فعلهم استبعادًا وتعجيبًا وتقريعًا، وهي معان لا تؤديها الواو المجردة.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص756، تحت «نكتة استعمال (ثم) دون (الواو) في قوله تعالى ﴿ثم اتخذتم﴾»","url":""}]},{"id":"s2-285","number":285,"surah":2,"verses":[92],"references":[{"surah":2,"verses":[92]}],"verseLabel":"البقرة: 92","question":"ما سرّ التعبير بقوله تعالى: ﴿اتخذتم العجل﴾ بدل «عبدتم العجل»؟","answer":"الاتخاذ يتضمن حيازة الشيء وطلبه والرغبة فيه والاستمرار عليه، وهو أنسب بحالهم؛ لأنهم لم ينقادوا للعجل في جميع أمورهم، بل فيما وافق أهواءهم. وفي صيغة الاتخاذ كذلك تكلفٌ يشعر بمخالفة الفطرة، وحُذف مفعوله الثاني المقدر بـ«إلهًا» لظهوره ولصون العبارة عن التصريح بالوصف القبيح.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص756، تحت «سر التعبير بالاتخاذ»","url":""}]},{"id":"s2-286","number":286,"surah":2,"verses":[93],"references":[{"surah":2,"verses":[93]}],"verseLabel":"البقرة: 93","question":"ما الصورة البيانية في قوله تعالى: ﴿وأشربوا في قلوبهم العجل﴾؟","answer":"حُذف «حب عبادة العجل»، وشُبّه تمكنه من قلوبهم بالشراب الذي يسري في البدن ويخالطه؛ فدل التعبير على رسوخ الحب وإغراقهم في الضلالة. وبناء ﴿أشربوا﴾ للمفعول يصور استيلاء الخرافة عليهم حتى كأنهم مقهورون عليها.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص765–766، تحت «براعة الاستعارة القرآنية»","url":""}]},{"id":"s2-287","number":287,"surah":2,"verses":[94,95],"references":[{"surah":2,"verses":[94,95]}],"verseLabel":"البقرة: 94–95","question":"كيف كان الأمر ﴿فتمنوا الموت﴾ حجة تكشف بطلان دعواهم؟","answer":"من أيقن أنه من أهل الجنة يكون الموت خلاصًا له من الدار الفانية. فجاء الأمر على وجه التحدي والتعجيز؛ ليظهر عجزهم عن تمني الموت ويكشف حقيقة دعواهم أن الآخرة خالصة لهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص777–778، تحت عنوان «حمل المجاز على الصيغة»","url":""}]},{"id":"s2-1510","number":1510,"surah":2,"verses":[94,95],"references":[{"surah":2,"verses":[94,95]}],"verseLabel":"البقرة: 94–95","question":"ما المراد بـ﴿ما قدمت أيديهم﴾ في بيان سبب امتناعهم عن تمني الموت؟","answer":"المراد ما اكتسبوه من الجنايات والسيئات، من قول وفعل واعتقاد. ونُسب الكسب إلى الأيدي مجازًا لأنها أكثر الجوارح مباشرة للأعمال؛ فالعبارة تشمل ما قدموه من أعمال، ولا تختص بما فعلته اليد وحدها.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص780، تحت عنوان «بلاغة المجاز مع الإيجاز في قوله: ﴿بما قدمت أيديهم﴾»","url":""}]},{"id":"s2-288","number":288,"surah":2,"verses":[94,95],"references":[{"surah":2,"verses":[94,95]},{"surah":62,"verses":[6,7]}],"verseLabel":"البقرة: 94–95، والجمعة: 6–7","question":"ما سرّ اختلاف التعبير بين قوله تعالى في البقرة: ﴿ولن يتمنوه أبدًا﴾، وقوله في الجمعة: ﴿ولا يتمنونه أبدًا﴾؟","answer":"دعواهم في البقرة أن الدار الآخرة خالصة لهم من دون الناس هي غاية ما يدعيه المدعي، فناسبها النفي المؤكد بـ﴿لن﴾. أما دعواهم في الجمعة أنهم أولياء لله، فليست في قوة الدعوى الأولى؛ إذ يبقى بعدها إثبات استحقاق الآخرة، فجاء النفي بـ﴿لا﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص681–682، تحت «توجيه المتشابه اللفظي في جملة «ولا يتمنونه» وجملة «ولن يتمنوه»»","url":""}]},{"id":"s2-289","number":289,"surah":2,"verses":[96],"references":[{"surah":2,"verses":[96]}],"verseLabel":"البقرة: 96","question":"ما دلالة تنكير ﴿حياة﴾ في قوله تعالى: ﴿أحرص الناس على حياة﴾؟","answer":"نُكرت ﴿حياة﴾ للتنويع؛ فهم يحرصون على أية حياة، عزيزة كانت أو ذليلة. وجمع التنكير التقليل والتحقير لقبولهم الحياة الحقيرة خوفًا من الموت، والتعظيم لحرصهم على حياة متطاولة.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص782–783، تحت «نكتة التنكير في مفردة ﴿حياة﴾»","url":""}]},{"id":"s2-290","number":290,"surah":2,"verses":[96],"references":[{"surah":2,"verses":[96]}],"verseLabel":"البقرة: 96","question":"ما سرّ عطف قوله تعالى: ﴿ومن الذين أشركوا﴾ على ﴿الناس﴾ مع دخول المشركين فيهم؟","answer":"خُص المشركون بالذكر بعد عموم الناس للمبالغة والترقي في ذم اليهود؛ فالمشركون أشد الناس حرصًا على الحياة، ومع ذلك كان اليهود أحرص منهم، فكان حرصًا من ورائه حرص.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص782، تحت «فائدة عطف المشركين على الناس»","url":""}]},{"id":"s2-291","number":291,"surah":2,"verses":[96],"references":[{"surah":2,"verses":[96]}],"verseLabel":"البقرة: 96","question":"ما مناسبة التعبير بـ﴿ألف سنة﴾ بدل «ألف عام»؟","answer":"تستعمل «السنة» غالبًا للحول الذي فيه جدب وضيق وتعب، بخلاف «العام» الذي يغلب استعماله في الخصب والخير. فناسبت ﴿سنة﴾ ذم حرصهم على البقاء ولو في حياة بالغة الذل والشقاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص784، تحت «مناسبة كلمة ﴿سنة﴾ للسياق»","url":""}]},{"id":"s2-292","number":292,"surah":2,"verses":[96],"references":[{"surah":2,"verses":[96]}],"verseLabel":"البقرة: 96","question":"ما دلالة قوله تعالى: ﴿وما هو بمزحزحه من العذاب﴾؟","answer":"الزحزحة هي الإبعاد والتنحية، ونفت الباء في ﴿بمزحزحه﴾ نفيًا مؤكدًا مستغرقًا لأي نوع من الإبعاد عن العذاب؛ فلا ينفعه طول العمر مهما بلغ.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص785، تحت «مناسبة تكرار الصوت لدلالة المعنى المعجمي»","url":""}]},{"id":"s2-293","number":293,"surah":2,"verses":[97],"references":[{"surah":2,"verses":[97]}],"verseLabel":"البقرة: 97","question":"ما سرّ مجيء قوله تعالى: ﴿من كان عدوًّا لجبريل﴾ بصيغة عامة بدل خطاب اليهود مباشرة؟","answer":"صيغ الشرط عامًا ليشمل كل من يعادي جبريل في أي زمن، مع دخول اليهود فيه أولًا بسياق الكلام؛ لأن عداوة جبريل كفر لا يختص بشريعة معينة، بل هي من أصول الدين التي لا تختلف بين الأنبياء والرسل.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص790، تحت «نكتة اختلاف النظم»","url":""}]},{"id":"s2-294","number":294,"surah":2,"verses":[97],"references":[{"surah":2,"verses":[97]}],"verseLabel":"البقرة: 97","question":"ما سرّ حذف جواب الشرط في قوله تعالى: ﴿من كان عدوًّا لجبريل فإنه نزله على قلبك﴾؟","answer":"حُذف الجواب ليذهب ذهن السامع في الوعيد كل مذهب، فيعظم التخويف. ثم ذُكرت علة بطلان العداوة: أن جبريل نزّل القرآن بأمر الله، مصدقًا لكتابهم وهدًى وبشرى؛ فجمع السياق بين الوعيد وإقامة الحجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص790، تحت «بلاغة حذف جواب الشرط»","url":""}]},{"id":"s2-295","number":295,"surah":2,"verses":[97],"references":[{"surah":2,"verses":[97]},{"surah":26,"verses":[193,194]}],"verseLabel":"البقرة: 97، والشعراء: 193–194","question":"ما سرّ اختلاف التعبير بين قوله تعالى هنا: ﴿فإنه نزله على قلبك﴾ بالتشديد، وقوله في الشعراء: ﴿نزل به الروح الأمين﴾ من غير تشديد؟","answer":"أفادت صيغة ﴿نزّل﴾ التفريق والتكثير، وناسبت مقام تثبيت قلب النبي ﷺ أمام أكاذيب اليهود وذكر أوصاف القرآن. أما آية الشعراء فمقامها الإنذار بجميع القرآن، فناسبها الفعل المجرد ﴿نزل﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص791–792، تحت «توجيه المتشابه اللفظي»","url":""}]},{"id":"s2-296","number":296,"surah":2,"verses":[97],"references":[{"surah":2,"verses":[97]}],"verseLabel":"البقرة: 97","question":"ما دلالة عود الضمير في قوله تعالى: ﴿فإنه نزله﴾ إلى القرآن مع عدم ذكره قبله صراحة؟","answer":"أضمر القرآن لفخامة شأنه وكمال شهرته حتى استغنى عن ذكره بالاسم الظاهر، وفعل ﴿نزّله﴾ قرينة تعيّنه؛ إذ من صفات القرآن أنه منزل من عند الله وأن النازل به جبريل.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص792، تحت «نكتة إبهام الضمير»","url":""}]},{"id":"s2-297","number":297,"surah":2,"verses":[97],"references":[{"surah":2,"verses":[97]}],"verseLabel":"البقرة: 97","question":"ما سرّ تعدية فعل التنزيل بـ﴿على﴾ في قوله تعالى: ﴿نزله على قلبك﴾ بدل «إلى»؟","answer":"تفيد ﴿على﴾ استعلاء القرآن على القلب واستيعابه وتمكنه منه، وفي ذلك تشريف للنبي ﷺ. أما «إلى» فتفيد انتهاء الغاية من غير دلالة الاستيعاب والإحاطة.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص793، تحت «دلالة التعبير بحرف الاستعلاء»","url":""}]},{"id":"s2-298","number":298,"surah":2,"verses":[97],"references":[{"surah":2,"verses":[97]}],"verseLabel":"البقرة: 97","question":"ما سرّ وصف القرآن بالمصدرين ﴿هدًى وبشرى﴾ بدل «هاديًا ومبشرًا»؟","answer":"عُدل عن اسمي الفاعل إلى المصدرين للمبالغة في وصف القرآن بالهداية والبشرى وتعظيم شأنه، حتى جُعل نفس الهدى والبشرى للمؤمنين.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص795، تحت «سر العدول في الصيغ»","url":""}]},{"id":"s2-299","number":299,"surah":2,"verses":[97],"references":[{"surah":2,"verses":[97]}],"verseLabel":"البقرة: 97","question":"ما مناسبة تقديم ﴿هدًى﴾ على ﴿بشرى للمؤمنين﴾؟","answer":"الهدى يبين الطريق الموصل، والبشرى تبين ثواب من سلكه؛ فالهدى مقدم على البشرى في الوجود، ولذلك قُدّم في الذكر.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص795، تحت «نكتة تقديم الهدى على البشرى»","url":""}]},{"id":"s2-300","number":300,"surah":2,"verses":[97,99],"references":[{"surah":2,"verses":[97,99]}],"verseLabel":"البقرة: 97 و99","question":"لماذا عُدي الإنزال بإلى في ﴿ولقد أنزلنا إليك آيات بينات﴾؟","answer":"لبيان أن غاية نزول القرآن بلوغه النبي ﷺ، فهو المقصود بالرسالة وتبليغ القرآن إلى الناس؛ فناسبت إلى معنى انتهاء الإنزال إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص17، تحت عنوان «اختيار حرف تعدية الأفعال قائم على التناسب بين المعاني»","url":""}]},{"id":"s2-1511","number":1511,"surah":2,"verses":[97,99],"references":[{"surah":2,"verses":[97,99]}],"verseLabel":"البقرة: 97 و99","question":"ما فائدة تقديم ﴿إليك﴾ على ﴿آيات بينات﴾؟","answer":"يفيد الاهتمام بالنبي ﷺ والعناية به ليكون موضع نظر المخاطبين، ويبين اختصاصه بإنزال هذه الآيات إليه. وفي السياق رد على عداوة اليهود له؛ فمن اختصه الله بالوحي حقيق بالإكرام.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص17، تحت عنوان «نكتة التقديم والتأخير»","url":""}]},{"id":"s2-301","number":301,"surah":2,"verses":[98],"references":[{"surah":2,"verses":[98]}],"verseLabel":"البقرة: 98","question":"ما سرّ تخصيص جبريل وميكال بالذكر بعد قوله تعالى: ﴿وملائكته﴾؟","answer":"خُص جبريل وميكال بالذكر بعد دخولهما في عموم الملائكة تشريفًا وتفضيلًا لهما، وعنايةً بمن عاداه اليهود، ولأن الآية نزلت فيما يتعلق بهما؛ فحسن التصريح باسميهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص12–13، تحت «توجيه المخصوص بالذكر»","url":""}]},{"id":"s2-302","number":302,"surah":2,"verses":[98],"references":[{"surah":2,"verses":[98]}],"verseLabel":"البقرة: 98","question":"ما سرّ إظهار اسم الله ووصفهم بالكفر في قوله تعالى: ﴿فإن الله عدو للكافرين﴾ بدل «فإنه عدو لهم»؟","answer":"أُظهر اسم الله لدفع التباس مرجع الضمير بعد تعدد المذكورين، ولتفخيم الأمر وتعظيم الجزاء. ووُضع ﴿للكافرين﴾ موضع الضمير لبيان أن كفرهم سبب العداوة، ولجعل الجملة حكمًا عامًا ثابتًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص12، تحت «بلاغة وضع الاسم الظاهر موضع المضمر»","url":""}]},{"id":"s2-303","number":303,"surah":2,"verses":[98],"references":[{"surah":2,"verses":[98]}],"verseLabel":"البقرة: 98","question":"ما مناسبة تقديم الملائكة على الرسل في قوله تعالى: ﴿وملائكته ورسله﴾؟","answer":"جاء الترتيب اللفظي موافقًا للترتيب الوجودي؛ فالملائكة أسبق وجودًا عند ظهور الإرسال، وعداوة الرسل فرع عن عداوة من يبلغهم الوحي، والجميع تابعون لأمر الله تعالى.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص12، تحت «نكتة تقديم الملائكة على الرسل»","url":""}]},{"id":"s2-304","number":304,"surah":2,"verses":[99],"references":[{"surah":2,"verses":[99]}],"verseLabel":"البقرة: 99","question":"ما فائدة وصف الآيات بأنها ﴿بينات﴾؟","answer":"الوصف يدل على وضوح طريق معرفتها، وأنها تزيل الالتباس وتفصل بين الحق والباطل؛ فالقرآن بما اشتمل عليه من الآيات واضح الدلالة على معانيه وعلى صدق نزوله وصحة نبوة الرسول ﷺ.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص17–18، تحت «فائدة وصف الآيات بالبينات»","url":""}]},{"id":"s2-305","number":305,"surah":2,"verses":[99],"references":[{"surah":2,"verses":[99]}],"verseLabel":"البقرة: 99","question":"ما دلالة وصف من يكفر بالآيات البينات بـ﴿الفاسقين﴾؟","answer":"الفسق تجاوز للحد، وإذا استعمل في نوع من المعصية دل على بلوغ الغاية فيه؛ فوصف الكافرين بالفاسقين ليبين أنهم تجاوزوا الحد المعقول في كفرهم وبلغوا فيه أقصى المبالغة، ففسقوا بكفرهم، وهذا غاية في الذم.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص18، تحت «توجيه تخصيص الفسق بالذكر»","url":""}]},{"id":"s2-306","number":306,"surah":2,"verses":[100],"references":[{"surah":2,"verses":[100]}],"verseLabel":"البقرة: 100","question":"ما الصورة في قوله تعالى عن العهد: ﴿نبذه فريق منهم﴾؟","answer":"صُوِّر العهد بشيء يُطرح ويُرمى احتقارًا له وعدم اعتداد به. وإسناد النبذ إلى ﴿فريق منهم﴾ يمنع تعميم مباشرة الفعل على جميعهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص24، تحت «بلاغة الاستعارة في إسناد النبذ إلى العهد»","url":""}]},{"id":"s2-307","number":307,"surah":2,"verses":[100,101],"references":[{"surah":2,"verses":[100,101]}],"verseLabel":"البقرة: 100–101","question":"ما سرّ اختلاف التعبير بين قوله تعالى: ﴿نبذه فريق منهم﴾، وقوله بعدها: ﴿نبذ فريق من الذين أوتوا الكتاب كتاب الله﴾؟","answer":"الآية الأولى في نبذ عهد من العهود، فاقتصر على الضمير العائد إليه. أما الثانية ففي نبذ كتاب الله عند مجيء الرسول المصدق لما معهم، فصرّحت بوصفهم ﴿الذين أوتوا الكتاب﴾ وبالمنبوذ ﴿كتاب الله﴾؛ زيادةً في تقبيح فعل من أوتي الكتاب ثم طرحه.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص30، تحت «توجيه المتشابه اللفظي»","url":""}]},{"id":"s2-308","number":308,"surah":2,"verses":[100,101],"references":[{"surah":2,"verses":[100,101]}],"verseLabel":"البقرة: 100–101","question":"ما سرّ زيادة قوله تعالى: ﴿وراء ظهورهم﴾ في الآية 101 بعد الاكتفاء بالنبذ في الآية 100؟","answer":"في الآية الأولى دل النبذ على رفض العهد وعدم الاعتداد به. وفي الثانية زيد ﴿وراء ظهورهم﴾ لتصوير شدة استخفافهم بكتاب الله وإعراضهم عنه، فكأنهم طرحوه في موضع لا يرونه ولا يلتفتون إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص30–31، تحت «توجيه المتشابه اللفظي»","url":""}]},{"id":"s2-309","number":309,"surah":2,"verses":[100],"references":[{"surah":2,"verses":[100]}],"verseLabel":"البقرة: 100","question":"ما الغرض من الاستفهام في قوله تعالى: ﴿أوكلما عاهدوا عهدًا نبذه فريق منهم﴾؟","answer":"الاستفهام ليس لطلب جواب، بل للإنكار والتوبيخ والتعجيب والتقريع؛ فهو يواجههم بعادتهم في نبذ العهد كلما عاهدوا، ويحملهم على الإقرار بها بقصد ردعهم عن الغواية والكفر.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص22، تحت «غرض الاستفهام في صدر الآية»","url":""}]},{"id":"s2-310","number":310,"surah":2,"verses":[100],"references":[{"surah":2,"verses":[100]}],"verseLabel":"البقرة: 100","question":"ما دلالة تنكير ﴿عهدًا﴾ في قوله تعالى: ﴿كلما عاهدوا عهدًا﴾؟","answer":"نُكرت ﴿عهدًا﴾ لتشمل أي عهد، ولتفيد التقليل أيضًا: فكلما عاهدوا عهدًا، وإن كان صغيرًا قليلًا لا يكلفهم ولا يجهدهم، نبذوه غير مبالين به؛ مما يدل على أن نقض العهود متصل بأخلاقهم في التعامل لا بمشقة عهد بعينه.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص24، تحت «دلالة التنوين في قوله «عهدًا»»","url":""}]},{"id":"s2-311","number":311,"surah":2,"verses":[100],"references":[{"surah":2,"verses":[100]}],"verseLabel":"البقرة: 100","question":"ما دلالة الانتقال من قوله تعالى: ﴿نبذه فريق منهم﴾ إلى قوله: ﴿بل أكثرهم لا يؤمنون﴾؟","answer":"نسب النبذ إلى فريق احتراسًا من تعميم مباشرة الفعل، ثم أضرب بـ﴿بل﴾ لبيان أن عدم الإيمان أوسع؛ فأكثرهم لا يؤمنون، وإن لم يباشر كل واحد منهم نبذ كل عهد.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص25، تحت «بلاغة حرف الإضراب»","url":""}]},{"id":"s2-312","number":312,"surah":2,"verses":[101],"references":[{"surah":2,"verses":[101]}],"verseLabel":"البقرة: 101","question":"ما سرّ التعبير بـ﴿يتلو﴾ بدل «يقرأ»؟","answer":"التلاوة أخص من القراءة؛ ففيها اتباع الكلمات بعضها بعضًا، وتغلب في قراءة الكتب المنزلة وما يُظن أنه منها، كما تتضمن اتباع المتلو بالعلم والعمل. ولذلك ناسبت مجيء الرسول بالكتاب، وناسبت أيضًا ما كانت الشياطين تزعم أنه من كتب الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص48، تحت «التلاوة والقراءة»","url":""}]},{"id":"s2-313","number":313,"surah":2,"verses":[101],"references":[{"surah":2,"verses":[101]}],"verseLabel":"البقرة: 101","question":"ما دلالة تنكير ﴿رسول﴾ في قوله تعالى: ﴿ولما جاءهم رسول من عند الله﴾؟","answer":"التنكير للتعظيم والتفخيم؛ فهو رسول عظيم القدر عند مرسله، وفي ذلك زيادة تقبيح لإعراضهم عنه ونبذهم كتاب الله عند مجيئه.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص28، تحت «دلالة التنوين في «رسول»»","url":""}]},{"id":"s2-314","number":314,"surah":2,"verses":[101],"references":[{"surah":2,"verses":[101]}],"verseLabel":"البقرة: 101","question":"ما دلالة تشبيه أهل الكتاب بقوله تعالى: ﴿كأنهم لا يعلمون﴾؟","answer":"كانوا يعلمون صدق الرسول وموافقة القرآن لما معهم، لكنهم لم يعملوا بعلمهم؛ فنُزّل العالم الذي لا ينتفع بعلمه منزلة الجاهل، وفي التشبيه تعريض بمكابرتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص29، تحت «بلاغة التشبيه في قوله ﴿كأنهم لا يعلمون﴾»","url":""}]},{"id":"s2-315","number":315,"surah":2,"verses":[101],"references":[{"surah":2,"verses":[101]}],"verseLabel":"البقرة: 101","question":"ما دلالة مجيء ﴿يعلمون﴾ بالمضارع في قوله تعالى: ﴿كأنهم لا يعلمون﴾؟","answer":"يدل المضارع على تجدد حالهم واستمرارها؛ فهم يتظاهرون بعدم العلم ويعطلون أثره كلما جاءهم الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص30، تحت «التعبير بصيغة المضارع «يعلمون»»","url":""}]},{"id":"s2-316","number":316,"surah":2,"verses":[102],"references":[{"surah":2,"verses":[102]}],"verseLabel":"البقرة: 102","question":"ما دلالة اختيار لفظ ﴿المرء﴾ في قوله تعالى: ﴿يفرقون به بين المرء وزوجه﴾؟","answer":"اختير ﴿المرء﴾ لما يفيده من كمال القوة وحسن الأدب والمروءة؛ فإذا بلغ السحر أن يفرق بينه وبين زوجه مع قوة رابطة الزوجية، كان أثره فيما دونها أولى، وفي ذلك بيان لشناعته.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص42، تحت «سر اختيار مفردة ﴿المرء﴾ في الآية»","url":""}]},{"id":"s2-317","number":317,"surah":2,"verses":[102],"references":[{"surah":2,"verses":[102]}],"verseLabel":"البقرة: 102","question":"ما سرّ مجيء ﴿تتلو الشياطين﴾ بالمضارع مع أن الحديث عن زمن سليمان؟","answer":"جاء المضارع لاستحضار الصورة، وللدلالة على تجدد تلاوة الشياطين وكثرة ما تتلوه وفشوه، وأن أحبار اليهود في زمن النزول واصلوا تلاوة ما ورثوه عن أسلافهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص37، تحت «نكتة مجيء الفعل «تتلو» بصيغة المضارع»","url":""}]},{"id":"s2-318","number":318,"surah":2,"verses":[102],"references":[{"surah":2,"verses":[102]}],"verseLabel":"البقرة: 102","question":"ما سرّ التعبير بـ﴿تتلو الشياطين﴾ بدل «تقرأ الشياطين»؟","answer":"اختيرت التلاوة دون القراءة أو التقول لأن التلاوة ذات صبغة دينية؛ فاستعمال ﴿تتلو﴾ يصور باطلهم في صورة قراءة لكتب الله، بإلقاء منغم وكلمات متوالية واضحة، ليكون أوقع في السامعين وأقدر على خداعهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص48، تحت «التلاوة والقراءة»","url":""}]},{"id":"s2-319","number":319,"surah":2,"verses":[102],"references":[{"surah":2,"verses":[102]}],"verseLabel":"البقرة: 102","question":"ما سرّ نفي الكفر عن سليمان في قوله تعالى: ﴿وما كفر سليمان﴾ بدل الاقتصار على نفي السحر؟","answer":"نفى القرآن عن سليمان الكفر لأن السحر الذي نسبوه إليه من الكفر، فنفي اللازم الأشد أبلغ في تبرئته وفي تقبيح ما نسبوه إليه. ثم قابل ذلك بقوله: ﴿ولكن الشياطين كفروا﴾ فنقل التهمة إلى أصحابها.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص37، تحت «بلاغة نفي الكفر دون السحر»","url":""}]},{"id":"s2-320","number":320,"surah":2,"verses":[102],"references":[{"surah":2,"verses":[102]}],"verseLabel":"البقرة: 102","question":"ما دلالة مجيء قوله تعالى: ﴿يعلمون الناس السحر﴾ بعد قوله: ﴿ولكن الشياطين كفروا﴾؟","answer":"جاءت جملة ﴿يعلمون الناس السحر﴾ حالًا تكشف هيئة كفرهم: لم يكتفوا بالكفر في أنفسهم، بل زادوا عليه تعليم السحر للناس ونشره بينهم؛ فاقتران التعليم بالكفر يبرز شناعة فعلهم وتعدي فساده إلى غيرهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص38، تحت «دلالة الجملة الحالية ﴿يعلمون الناس السحر﴾»","url":""}]},{"id":"s2-321","number":321,"surah":2,"verses":[102],"references":[{"surah":2,"verses":[102]}],"verseLabel":"البقرة: 102","question":"كيف كان تعليم الملكين فتنةً مع تحذيرهما: ﴿إنما نحن فتنة فلا تكفر﴾؟","answer":"كان أمرهما اختبارًا ظاهرًا للناس، فلا يعلمان أحدًا حتى يبينَا له أنهما فتنة ويحذراه من الكفر. فالتعليم في هذا السياق ابتلاء مع إقامة التحذير، لا دعوة إلى العمل بالسحر.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص40، تحت «بلاغة أسلوب القصر: «إنما»»","url":""}]},{"id":"s2-322","number":322,"surah":2,"verses":[102],"references":[{"surah":2,"verses":[102]}],"verseLabel":"البقرة: 102","question":"ما سرّ التعبير بالمصدر في قول الملكين: ﴿إنما نحن فتنة﴾ بدل «فاتنان»؟","answer":"جاء الخبر بالمصدر للمبالغة، فكأنهما نفس الفتنة والاختبار، وزاد القصر بـ﴿إنما﴾ وضوح أن مهمتهما في هذا المقام امتحان المكلفين.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص40، تحت «نكتة الإخبار بالمصدر ﴿فتنة﴾»","url":""}]},{"id":"s2-323","number":323,"surah":2,"verses":[102],"references":[{"surah":2,"verses":[102]}],"verseLabel":"البقرة: 102","question":"ما دلالة الفاء في قوله تعالى بعد تحذير الملكين: ﴿فيتعلمون منهما﴾؟","answer":"تفيد الفاء التعقيب، فتصور مسارعتهم إلى التعلم عقب التحذير من الكفر، وفي ذلك تقريع لهم؛ إذ لم يردعهم الإنذار.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص41، تحت «دلالة الفاء في قوله «فيتعلمون منهما»»","url":""}]},{"id":"s2-324","number":324,"surah":2,"verses":[102],"references":[{"surah":2,"verses":[102]}],"verseLabel":"البقرة: 102","question":"ما دلالة مجيء ﴿فيتعلمون﴾ و﴿يفرقون﴾ بالمضارع في سياق قصة ماضية؟","answer":"يستحضر المضارع صورة تعلمهم السحر والتفريق به، ويفيد تجدد الفعل واستمراره، لا كونه واقعة انقطعت.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص41، تحت «براعة التعبير بصيغة المضارع في ﴿فيتعلمون﴾ و﴿يفرقون﴾»","url":""}]},{"id":"s2-325","number":325,"surah":2,"verses":[102],"references":[{"surah":2,"verses":[102]}],"verseLabel":"البقرة: 102","question":"ما دلالة تخصيص التفريق بين المرء وزوجه بالذكر من آثار السحر؟","answer":"رابطة الزوجية من أشد أواصر الاتصال لما فيها من مودة ورحمة وتدبير وتربية؛ فإذا بلغ السحر أن يفسخ هذه الرابطة الوثيقة، كان تأثيره فيما دونها أولى. فذُكر هذا الأثر تنبيهًا على بقية آثاره وتحذيرًا من خطره في المجتمع.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص41–42، تحت «سر ذكر التفريق بين المرء وزوجه»","url":""}]},{"id":"s2-326","number":326,"surah":2,"verses":[102],"references":[{"surah":2,"verses":[102]}],"verseLabel":"البقرة: 102","question":"ما دلالة أسلوب النفي والاستثناء في قوله تعالى: ﴿وما هم بضارين به من أحد إلا بإذن الله﴾؟","answer":"جاء الأسلوب بالقصر والنفي المؤكد؛ فالباء تؤكد النفي، و﴿من أحد﴾ تستغرق كل أحد، ثم حُصر وقوع الضرر في إذن الله. وبذلك يُدفع توهم أن للسحر تأثيرًا مستقلًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص42–43، تحت «بلاغة أسلوب القصر بالنفي وإلا المفيد للتخصيص، ولتوكيد الاستغراق»","url":""}]},{"id":"s2-327","number":327,"surah":2,"verses":[102],"references":[{"surah":2,"verses":[102]}],"verseLabel":"البقرة: 102","question":"ما دلالة تكرار ﴿فيتعلمون﴾ في الآية؟","answer":"أفاد التكرار اختلاف مآلَي التعلم: فالأول يبين التفريق بين المرء وزوجه، وهو ضرر يقع في المجتمع، والثاني يبين أن السحر يضر متعلمه ولا ينفعه. فلكل جملة غرض جديد.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص43، تحت «دلالة تكرار الفعل ﴿فيتعلمون﴾»","url":""}]},{"id":"s2-328","number":328,"surah":2,"verses":[102],"references":[{"surah":2,"verses":[102]}],"verseLabel":"البقرة: 102","question":"ما فائدة التصريح بنفي النفع بعد إثبات الضرر في قوله تعالى: ﴿ما يضرهم ولا ينفعهم﴾؟","answer":"قد يجتمع في الشيء ضرر ونفع، فلا يلزم من ثبوت الضرر انتفاء النفع؛ لذلك صرّح بنفي النفع ليدل على أن السحر شر محض وضرر محض. وإطلاق الإسناد يفيد عموم ضرره في كل زمان ومكان، وتجدد نفي نفعه في الدنيا والآخرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص44، تحت «سبب العدول عن صيغة القصر إلى الجمع بين إثبات الضر ونفي النفع»","url":""}]},{"id":"s2-329","number":329,"surah":2,"verses":[102],"references":[{"surah":2,"verses":[102]}],"verseLabel":"البقرة: 102","question":"كيف أثبت لهم العلم في قوله تعالى: ﴿ولقد علموا﴾ ثم نفاه بقوله: ﴿لو كانوا يعلمون﴾؟","answer":"أثبت لهم العلم المؤكد بعاقبة السحر، لكنهم لم يعملوا به ولم ينتفعوا منه؛ فنُزّل العالم الذي لا ينتفع بعلمه منزلة الجاهل، ونُفي عنه العلم النافع.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص47، تحت «بلاغة قوله تعالى ﴿لو كانوا يعلمون﴾»","url":""}]},{"id":"s2-330","number":330,"surah":2,"verses":[102,103],"references":[{"surah":2,"verses":[102,103]}],"verseLabel":"البقرة: 102–103","question":"ما دلالة تكرار قوله تعالى: ﴿لو كانوا يعلمون﴾ في ختام الآيتين 102 و103؟","answer":"في ختام الآية 102 نُفي عنهم العلم النافع بعد إثبات علمهم بعاقبة السحر، وفي الآية 103 عاد النفي لأنهم لم يعلموا علمًا يحملهم على الإيمان والتقوى وإيثار مثوبة الله. فتكرر اللفظ لاتصال المعنى مع اختلاف متعلقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص54، تحت «نكتة تكرير الجملة في الآيتين»","url":""}]},{"id":"s2-331","number":331,"surah":2,"verses":[103],"references":[{"surah":2,"verses":[103]}],"verseLabel":"البقرة: 103","question":"ما دلالة الشرط بـ﴿لو﴾ في قوله تعالى: ﴿ولو أنهم آمنوا واتقوا﴾؟","answer":"اختيرت ﴿لو﴾ لأنها تفيد امتناع حصول الشرط؛ فتؤكد أنهم لم يؤمنوا ولم يتقوا، ولذلك امتنع عنهم جزاء الشرط، وهو المثوبة من عند الله. وزادت ﴿أن﴾ الشرط توكيدًا وتقريرًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص52، تحت «بلاغة أسلوب الشرط بلو الداخلة عليها أن»","url":""}]},{"id":"s2-332","number":332,"surah":2,"verses":[103],"references":[{"surah":2,"verses":[103]},{"surah":5,"verses":[65]}],"verseLabel":"البقرة: 103؛ المائدة: 65","question":"ما نكتة الجمع بين الإيمان والتقوى في ﴿ولو أنهم آمنوا واتقوا﴾ في البقرة؟","answer":"لأنهم تركوا المأمورات وفعلوا المنهيات؛ فالإيمان يدل على طلب فعل المأمورات، ومنها الإيمان بالرسول ﷺ وما أنزل عليه، والتقوى تقتضي ترك المنهيات، ومنها نبذ كتاب الله واتباع السحر.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص52، تحت عنوان «نكتة الجمع بين ﴿آمنوا﴾ و﴿اتقوا﴾»","url":""}]},{"id":"s2-1512","number":1512,"surah":2,"verses":[103],"references":[{"surah":2,"verses":[103]},{"surah":5,"verses":[65]}],"verseLabel":"البقرة: 103؛ المائدة: 65","question":"لماذا قُرن الإيمان بالتقوى في ﴿ولو أن أهل الكتاب آمنوا واتقوا﴾ في المائدة؟","answer":"قُرن اشتراط الإيمان باشتراط التقوى لتكفير السيئات ودخول الجنة؛ فالإيمان الذي يترتب عليه هذا الجزاء هو ما قصد به تحقيق تقوى الله والعمل الصالح، لا تحقيق الأغراض الدنيوية كإيمان المنافقين.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص391، تحت عنوان «دلالة قرن الإيمان بالتقوى في: ﴿آمنوا واتقوا﴾»","url":""}]},{"id":"s2-333","number":333,"surah":2,"verses":[103],"references":[{"surah":2,"verses":[103]}],"verseLabel":"البقرة: 103","question":"ما دلالة تنكير ﴿مثوبة﴾ في قوله تعالى: ﴿لمثوبة من عند الله خير﴾؟","answer":"أفاد التنكير التقليل؛ أي إن مثوبة قليلة من عند الله خير لهم، فإذا كان القليل خيرًا فكيف بالمثوبة الكثيرة؟ ففي ذكر القليل تنبيه على الكثير.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص53، تحت «سبب تنكير ﴿لمثوبة﴾»","url":""}]},{"id":"s2-334","number":334,"surah":2,"verses":[103],"references":[{"surah":2,"verses":[103]}],"verseLabel":"البقرة: 103","question":"ما فائدة وصف المثوبة بقوله تعالى: ﴿من عند الله﴾؟","answer":"لما أفاد تنكير ﴿مثوبة﴾ التقليل، وُصفت بأنها ﴿من عند الله﴾ لتعظيمها وتفخيم شأنها؛ فما كان من عند الله عظيم وإن قل، و﴿من﴾ تفيد ابتداءها منه سبحانه.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص54، تحت «نكتة مجيء الصفة «من عند الله»»","url":""}]},{"id":"s2-335","number":335,"surah":2,"verses":[103],"references":[{"surah":2,"verses":[103]}],"verseLabel":"البقرة: 103","question":"ما دلالة استعمال ﴿خير﴾ في قوله تعالى: ﴿لمثوبة من عند الله خير﴾ مع أنه لا خير في نبذ الكتاب وتعلم السحر؟","answer":"لم تستعمل ﴿خير﴾ هنا للمفاضلة بين شيئين فيهما خير، بل بمعنى الصفة الثابتة المقابلة للشر؛ فأثبتت الخير للمثوبة ونفته عن العمل المقابل، وفي صيغة التفضيل مبالغة في بيان شأن الخير المستحق للعمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص54، تحت «نكتة التعبير باسم التفضيل على معنى الصفة»","url":""}]},{"id":"s2-336","number":336,"surah":2,"verses":[104],"references":[{"surah":2,"verses":[104]}],"verseLabel":"البقرة: 104","question":"ما وجه الجفاء في معنى ﴿راعنا﴾ عند خطاب النبي ﷺ؟","answer":"تحتمل المفاعلة، كأن المتكلم يقول: راع سمعنا نرع سمعك. وفي هذا إيحاء بالندية والاشتراط والتعليق، وهو جفاء لا يليق بمقام النبي ﷺ.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص56، تحت عنوان «شرح المفردات»، مدخل ﴿راعنا﴾","url":""}]},{"id":"s2-1513","number":1513,"surah":2,"verses":[104],"references":[{"surah":2,"verses":[104]}],"verseLabel":"البقرة: 104","question":"كيف اتخذ اليهود لفظ ﴿راعنا﴾ وسيلة لأذى النبي ﷺ؟","answer":"كانوا يقولونه للنبي ﷺ ويلوون ألسنتهم به يقصدون سبه؛ فنُهي المؤمنون عن هذا اللفظ، وأُمروا باختيار أحسن الألفاظ وأرفق المعاني في خطابه.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص57، تحت عنوان «المعنى الإجمالي»","url":""}]},{"id":"s2-337","number":337,"surah":2,"verses":[104],"references":[{"surah":2,"verses":[104]}],"verseLabel":"البقرة: 104","question":"ما سرّ اختيار ﴿انظرنا﴾ بدل ﴿راعنا﴾؟","answer":"تؤدي ﴿انظرنا﴾ معنى الانتظار والإمهال والرفق، ولا تتضمن معنى المفاعلة والندية الذي في ﴿راعنا﴾، ولا توهم سوء الأدب الذي يتذرع به الكفار إلى أذى النبي ﷺ. وهي كذلك أخف صوتًا وأنسب معنى.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص59، تحت «﴿راعنا﴾ و﴿انظرنا﴾»","url":""}]},{"id":"s2-338","number":338,"surah":2,"verses":[104],"references":[{"surah":2,"verses":[104]}],"verseLabel":"البقرة: 104","question":"ما مناسبة تقديم النهي ﴿لا تقولوا راعنا﴾ على الأمر ﴿وقولوا انظرنا﴾؟","answer":"قُدّم النهي لأن اللفظ المنهي عنه كان موجودًا شائعًا في الاستعمال، فأُمروا بتركه أولًا، ثم أُقيم اللفظ البديل مكانه؛ فكانت التخلية قبل التحلية.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص57، تحت «سبب تقديم النهي وتأخير الأمر»","url":""}]},{"id":"s2-339","number":339,"surah":2,"verses":[104],"references":[{"surah":2,"verses":[104]}],"verseLabel":"البقرة: 104","question":"ما دلالة حذف مفعول ﴿واسمعوا﴾؟","answer":"أفاد الحذف العموم: اسمعوا كلام النبي ﷺ سماع إصغاء وفهم وحفظ وطاعة وامتثال، ولا يختص الأمر بمسموع واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص58، تحت «بلاغة حذف المفعول»","url":""}]},{"id":"s2-340","number":340,"surah":2,"verses":[104],"references":[{"surah":2,"verses":[104]}],"verseLabel":"البقرة: 104","question":"ما سرّ وضع الوصف الظاهر في قوله تعالى: ﴿وللكافرين عذاب أليم﴾ موضع الضمير؟","answer":"وُضع الوصف الظاهر ﴿الكافرين﴾ موضع الضمير لتعميم الوعيد، ولبيان أن تهاون اليهود بالرسول ﷺ واستهزاءهم به مضاهأة في الكفر، بل يكون غالبًا كفرًا كاملًا يستحق العذاب الأليم؛ فالحكم لا يختص بأولئك اليهود، بل يعم كل من اتصف بالكفر.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص58، تحت «بلاغة وضع الظاهر موضع المضمر»","url":""}]},{"id":"s2-341","number":341,"surah":2,"verses":[105],"references":[{"surah":2,"verses":[105]}],"verseLabel":"البقرة: 105","question":"ما سرّ التعبير بـ﴿يختص برحمته﴾ بدل «يخص برحمته»؟","answer":"﴿يختص﴾ تدل على الانفراد بالشيء لنفسه، فهي أوكد في الخصوصية من «يخص». وفيها أن الله يصطفي من يشاء برحمته وفضله، خلافًا لما يتمناه الحاسدون لأنفسهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص65، تحت «نكتة التعبير بـ«يختص» دون (يخص)»","url":""}]},{"id":"s2-342","number":342,"surah":2,"verses":[105],"references":[{"surah":2,"verses":[105]}],"verseLabel":"البقرة: 105","question":"ما سرّ التعبير بقوله تعالى: ﴿ما يود الذين كفروا﴾ بدل «ما يحب»؟","answer":"الود يجمع محبة الشيء وتمني حصوله، فجاء هنا ليصور موافقة تمنيهم لطباعهم السيئة وحسدهم، وليفيد أن ما يتمنونه من انقطاع الخير عن المؤمنين لا مطمع في وقوعه. كما أفاد المضارع تجدد نفي ودهم واستمراره.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص62، تحت «بلاغة التعبير بـ﴿ما يود﴾»","url":""}]},{"id":"s2-343","number":343,"surah":2,"verses":[105],"references":[{"surah":2,"verses":[105]}],"verseLabel":"البقرة: 105","question":"ما دلالة قوله تعالى: ﴿الذين كفروا من أهل الكتاب﴾؟","answer":"جاء الموصول وصلته ليشمل الحكم الكافرين من اليهود والنصارى، وليومئ إلى أن كفرهم هو سبب كراهتهم الخير للمؤمنين. و﴿من﴾ بيانية تبين صنف هؤلاء الكافرين، وقيل: تبعيضية؛ أي بعض أهل الكتاب ممن كفر.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص64، تحت «دلالة حرف الجر «من» في قوله: «من أهل الكتاب»»","url":""}]},{"id":"s2-344","number":344,"surah":2,"verses":[105],"references":[{"surah":2,"verses":[105]}],"verseLabel":"البقرة: 105","question":"ما مناسبة تقديم أهل الكتاب على المشركين في قوله تعالى: ﴿من أهل الكتاب ولا المشركين﴾؟","answer":"قُدّم أهل الكتاب لأن السياق فيهم، ولأن الجحود ممن أوتي علمًا أشد من جحود الجاهل؛ فقد عرفوا ثم لم ينتفعوا بعلمهم، وكان حسدهم أن تكون الرسالة في ولد إسماعيل أشد.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص64، تحت «سبب تقديم أهل الكتاب على المشركين»","url":""}]},{"id":"s2-345","number":345,"surah":2,"verses":[105],"references":[{"surah":2,"verses":[105]}],"verseLabel":"البقرة: 105","question":"ما سرّ بناء ﴿ينزل﴾ للمفعول في قوله تعالى: ﴿أن ينزل عليكم من خير من ربكم﴾؟","answer":"عُبر بصيغة ما لم يسم فاعله في ﴿أن يُنزَّل عليكم﴾ للإشعار بأن ابتداء الخير من الله تعالى، وفي ذلك تكريم للمؤمنين الذين نزل عليهم هذا الخير.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص65، تحت «إيثار صيغة المبني لما لم يسم فاعله «ينزل»»","url":""}]},{"id":"s2-346","number":346,"surah":2,"verses":[105],"references":[{"surah":2,"verses":[105]}],"verseLabel":"البقرة: 105","question":"ما دلالة حرف الاستعلاء في قوله تعالى: ﴿أن ينزل عليكم﴾؟","answer":"أفادت ﴿على﴾ عظمة الخير المنزل وعلوه، كما أفادت استيعابه للمؤمنين وتمكنه فيهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص65، تحت «دلالة حرف الاستعلاء في ﴿عليكم﴾»","url":""}]},{"id":"s2-347","number":347,"surah":2,"verses":[105],"references":[{"surah":2,"verses":[105]}],"verseLabel":"البقرة: 105","question":"ما دلالة حذف مفعول ﴿يشاء﴾ في قوله تعالى: ﴿والله يختص برحمته من يشاء﴾؟","answer":"دل السياق على المحذوف، والتقدير: يختص برحمته من يشاء اختصاصه بها. وحُذف مفعول المشيئة لإفادة العموم؛ لأن مشيئة الله لا يحصرها شيء، مع ما في الحذف من الاختصار.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص66، تحت «بلاغة حذف مفعول ﴿يشاء﴾»","url":""}]},{"id":"s2-348","number":348,"surah":2,"verses":[105],"references":[{"surah":2,"verses":[105]}],"verseLabel":"البقرة: 105","question":"ما دلالة ﴿من﴾ في قوله تعالى: ﴿من خير من ربكم﴾؟","answer":"الأولى في ﴿من خير﴾ لاستغراق جنس الخير؛ فهم لا يودون أن ينزل على المؤمنين أي نوع منه ولو قليلًا. والثانية في ﴿من ربكم﴾ لابتداء الغاية؛ أي إن ابتداء تنزيل الخير من الله تعالى، وفي ذلك تكريم للمؤمنين.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص66، تحت «دلالة حرف الجر ﴿من ربكم﴾»","url":""}]},{"id":"s2-349","number":349,"surah":2,"verses":[105],"references":[{"surah":2,"verses":[105]}],"verseLabel":"البقرة: 105","question":"ما سرّ التعبير بقوله تعالى: ﴿والله ذو الفضل العظيم﴾ بدل «صاحب الفضل»؟","answer":"التعبير بـ﴿ذو﴾ أشرف في الاستعمال من «صاحب»، ويفيد أن الفضل العظيم وصف ملازم لله غير مفارق له. وتذييل الآية بهذه الجملة يدل على عموم فضله ودوامه، وأن اختصاص بعض عباده بالرحمة ليس لضيق فضله.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص67، تحت «سبب التعبير بـ«ذو الفضل»»","url":""}]},{"id":"s2-350","number":350,"surah":2,"verses":[106],"references":[{"surah":2,"verses":[106]}],"verseLabel":"البقرة: 106","question":"ما المقصود بالنسخ في قوله تعالى ﴿ما ننسخ من آية﴾؟","answer":"النسخ هنا إزالة حكم بحكم يتعقبه؛ فليس المراد مجرد نقل الألفاظ، بل رفع الحكم وإحلال حكم آخر محله.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص69، تحت عنوان «شرح المفردات»، مدخل ﴿ننسخ﴾","url":""}]},{"id":"s2-1514","number":1514,"surah":2,"verses":[106],"references":[{"surah":2,"verses":[106]}],"verseLabel":"البقرة: 106","question":"ما الفرق بين قراءتي ﴿ننسها﴾ و﴿ننسأها﴾؟","answer":"قراءة الجمهور ﴿نُنسِها﴾ بضم النون وكسر السين من غير همز يوجهها المصدر بمعنى الترك وإهمال العمل. أما قراءة ابن كثير وأبي عمرو ﴿نَنْسَأْها﴾ بفتح النون والسين وهمزة ساكنة فبمعنى التأخير. فمعنى التأخير متعلق بالقراءة المهموزة، ولا يصح إطلاقه على القراءتين دون تمييز.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص75، تحت عنوان «توجيه القراءات في ﴿ننسها﴾»","url":""}]},{"id":"s2-351","number":351,"surah":2,"verses":[106],"references":[{"surah":2,"verses":[106]}],"verseLabel":"البقرة: 106","question":"ما مناسبة ختم آية النسخ بقوله تعالى: ﴿ألم تعلم أن الله على كل شيء قدير﴾؟","answer":"لأن المقام مقام تقرير القدرة على نسخ الآيات والإتيان بخير منها أو مثلها؛ فمن كان قديرًا على كل شيء كان قادرًا على تبديل الحكم وفق مقتضى الحكمة، وفي الخاتمة رد على الطاعنين في النسخ.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص79، تحت «التناسب التقابلي في العموم»","url":""}]},{"id":"s2-352","number":352,"surah":2,"verses":[106],"references":[{"surah":2,"verses":[106]}],"verseLabel":"البقرة: 106","question":"ما سرّ استعمال ﴿ما﴾ الشرطية في قوله تعالى: ﴿ما ننسخ من آية﴾ بدل «إن»؟","answer":"أفادت ﴿ما﴾ العموم؛ فالنسخ متصور الوقوع في كل آية، ثم جاءت ﴿من﴾ لتبين هذا العموم. كما حسنت الوقع الصوتي؛ لأن «إن ننسخ» تجمع نونات متوالية فيها ثقل، مع بقاء المعنى هو الأصل والصوت تابعًا له.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص73، تحت «سر استعمال ما الشرطية»","url":""}]},{"id":"s2-353","number":353,"surah":2,"verses":[106],"references":[{"surah":2,"verses":[106]}],"verseLabel":"البقرة: 106","question":"ما دلالة قوله تعالى: ﴿من آية﴾ مع إفراد ﴿آية﴾؟","answer":"جاءت ﴿من﴾ بيانًا للاسم الشرطي المبهم ﴿ما﴾، ووقعت ﴿آية﴾ نكرة في سياق الشرط فعمّت كل آية. وأفادت ﴿من﴾ أيضًا أن وقوع النسخ إنما يكون في بعض الآيات، مع إمكان تعلق الحكم بأي فرد منها.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص74، تحت «أثر حروف المعاني في البيان»","url":""}]},{"id":"s2-354","number":354,"surah":2,"verses":[106],"references":[{"surah":2,"verses":[106]}],"verseLabel":"البقرة: 106","question":"ما معنى الخيرية في قوله تعالى عن الآية البديلة: ﴿نأت بخير منها﴾؟","answer":"تكون الآية البديلة خيرًا إما بخفة تكليفها مع ثبات الثواب، وإما بكثرة ثوابها وإن كان تكليفها أثقل. فالخيرية في حكمها للمكلفين، ولا تعني القدح في الآية المنسوخة.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص76، تحت «فوائد الحذف والذكر»","url":""}]},{"id":"s2-355","number":355,"surah":2,"verses":[106],"references":[{"surah":2,"verses":[106]}],"verseLabel":"البقرة: 106","question":"ما فائدة قوله تعالى: ﴿أو مثلها﴾ بعد قوله: ﴿بخير منها﴾؟","answer":"بيّن العطف أن البديل قد يكون خيرًا من المنسوخ بما فيه من خفة أو زيادة ثواب، وقد يكون مماثلًا له في القدر والحكم؛ فشملت الآية القسمين.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص76، تحت «فائدة العطف بقوله ﴿أو مثلها﴾»","url":""}]},{"id":"s2-356","number":356,"surah":2,"verses":[106],"references":[{"surah":2,"verses":[106]}],"verseLabel":"البقرة: 106","question":"ما سرّ التعبير بصفة ﴿قدير﴾ بدل «قادر» في ختام الآية؟","answer":"﴿قدير﴾ على وزن «فعيل»، وهي صيغة تدل على المبالغة وكثرة آثار القدرة وتكررها، بخلاف «قادر» الدال على مجرد صدور الفعل. وهذا أنسب بإحاطة قدرة الله بكل شيء.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص77، تحت «سر التعبير بـ﴿قدير﴾ دون (قادر)»","url":""}]},{"id":"s2-357","number":357,"surah":2,"verses":[107],"references":[{"surah":2,"verses":[107]}],"verseLabel":"البقرة: 107","question":"ما دلالة الجمع بين ﴿ولي﴾ و﴿نصير﴾ في قوله تعالى: ﴿وما لكم من دون الله من ولي ولا نصير﴾؟","answer":"الولي هو القريب الذي يتولى أمر صاحبه ويرعاه، والنصير من يعينه ويدفع عنه ولو لم يكن وليًا. فنفى النص جهتي الحماية: الولاية القريبة والنصرة عند الحاجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص87، تحت «بلاغة الاحتراس»","url":""}]},{"id":"s2-358","number":358,"surah":2,"verses":[107],"references":[{"surah":2,"verses":[107]},{"surah":5,"verses":[40]},{"surah":7,"verses":[158]}],"verseLabel":"البقرة: 107؛ المائدة: 40؛ الأعراف: 158","question":"ما دلالة تقديم ﴿له﴾ في قوله تعالى: ﴿أن الله له ملك السماوات والأرض﴾؟","answer":"يفيد تقديم الجار والمجرور اختصاص الله بملك السماوات والأرض دون سواه. وفيه أيضًا تشويق؛ إذ يترقب السامع بعد ﴿أن الله له﴾ معرفة ما له. فالاختصاص هو المعنى المشترك في المواضع المشار إليها، وتفصيل التقديم في البقرة موثق تحت هذا العنوان.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص85، تحت عنوان «قوة التئام النظم بالسياق»","url":""}]},{"id":"s2-359","number":359,"surah":2,"verses":[107],"references":[{"surah":2,"verses":[107]}],"verseLabel":"البقرة: 107","question":"ما مناسبة تقديم ﴿ولي﴾ على ﴿نصير﴾؟","answer":"الولي أقرب وأشمل؛ فهو يتولى أمر صاحبه ملازمةً، أما النصير فقد يكون من غير دائرة الولاية ولا يظهر إلا عند الحاجة. فنُفي الأقرب أولًا ثم ما قد يُتوهم من نصرة غيره.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص86، تحت «سر تقديم الولي على النصير»","url":""}]},{"id":"s2-360","number":360,"surah":2,"verses":[108],"references":[{"surah":2,"verses":[108]}],"verseLabel":"البقرة: 108","question":"ما الغرض من الاستفهام في قوله تعالى: ﴿أم تريدون أن تسألوا رسولكم كما سئل موسى من قبل﴾؟","answer":"﴿أم﴾ للإضراب والانتقال إلى استفهام إنكاري عن إرادة السؤال المتعنت. وتوجيه الإنكار إلى الإرادة أبلغ في التحذير؛ لأن الإرادة تسبق الفعل، فنُهوا عن مبدئه قبل وقوعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص93، تحت «تضمين «أم» معنى الإضراب والاستفهام»","url":""}]},{"id":"s2-361","number":361,"surah":2,"verses":[108],"references":[{"surah":2,"verses":[108]}],"verseLabel":"البقرة: 108","question":"ما سرّ التعبير بـ﴿رسولكم﴾ بدل «نبيكم»؟","answer":"وُصف بالرسالة لأن السؤال المقترح متعلق برسالته، ولا سيما القرآن، لا بذاته ولا بثبوت نبوته؛ فناسب وصف الرسالة موضع التحذير.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص94، تحت «إيثار نعت الرسالة على النبوة»","url":""}]},{"id":"s2-362","number":362,"surah":2,"verses":[108],"references":[{"surah":2,"verses":[108]}],"verseLabel":"البقرة: 108","question":"ما دلالة إضافة الرسول إلى المخاطبين في قوله تعالى: ﴿رسولكم﴾؟","answer":"تزيد الإضافة تبشيع سؤال التعنت؛ فهو رسولهم الذي يعرفون حرصه عليهم وحبه لهم ورحمته بهم، وفيها تحذير من مشابهة منهج بني إسرائيل في سؤال رسلهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص95، تحت «نكتة إضافة رسول إلى ضمير المخاطبين»","url":""}]},{"id":"s2-363","number":363,"surah":2,"verses":[108],"references":[{"surah":2,"verses":[108]}],"verseLabel":"البقرة: 108","question":"ما سرّ بناء ﴿سئل موسى﴾ للمفعول؟","answer":"عُبر بصيغة المبني للمفعول ﴿سُئل﴾ للتشنيع على السائلين من كبرهم، ولزيادة التحذير من صنيعهم؛ إذ مُثّل سؤال المخاطبين المقترح بسؤال أولئك لموسى، وفي التشبيه تقبيح للفعل وتصريح بالنهي عنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص96، تحت «أثر الصيغة في بيان المعاني»","url":""}]},{"id":"s2-364","number":364,"surah":2,"verses":[108],"references":[{"surah":2,"verses":[108]}],"verseLabel":"البقرة: 108","question":"ما فائدة زيادة قوله تعالى: ﴿من قبل﴾ بعد قوله: ﴿كما سئل موسى﴾؟","answer":"زيد الظرف للتشنيع على سؤال التعنت، وهو يطلق ذهن السامع في تقدير السابقية: من قبل رسولكم، أو قبل نزول كتابكم، أو قبل ضلال السائلين وكفرهم؛ فالإطناب به أبلغ في التحذير.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص96، تحت «فائدة ذكر الظرف»","url":""}]},{"id":"s2-365","number":365,"surah":2,"verses":[108],"references":[{"surah":2,"verses":[108]}],"verseLabel":"البقرة: 108","question":"ما معنى الباء في قوله تعالى: ﴿ومن يتبدل الكفر بالإيمان﴾؟","answer":"تحتمل الباء البدل والمقابلة، والمعنيان متقاربان: من يأخذ الكفر بدل الإيمان أو عوضًا عنه. وفي جمع الكفر والإيمان طباق يبرز قبح الكفر وجمال الإيمان وشدة خسارة من آثر الأول.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص98، تحت «معنى الباء في قوله ﴿بالإيمان﴾»","url":""}]},{"id":"s2-366","number":366,"surah":2,"verses":[108],"references":[{"surah":2,"verses":[108]},{"surah":5,"verses":[12]}],"verseLabel":"البقرة: 108؛ المائدة: 12","question":"ما الصورة في قوله تعالى: ﴿فقد ضل سواء السبيل﴾، وما دلالة ﴿سواء﴾؟","answer":"سواء السبيل وسط الطريق وأعدله، وهو أسهل وأوضح للسير من أطرافه. فالتعبير يصور من يستبدل الكفر بالإيمان كمن يخطئ وسط طريق ظاهر ميسّر؛ وفيه شدة توبيخ وتشنيع على ضلاله مع وضوح الطريق.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص98، تحت عنوان «سر التعبير بـ﴿سواء﴾»","url":""}]},{"id":"s2-367","number":367,"surah":2,"verses":[109],"references":[{"surah":2,"verses":[109]}],"verseLabel":"البقرة: 109","question":"ما دلالة قوله تعالى: ﴿يردونكم من بعد إيمانكم كفارًا﴾؟","answer":"أُسند الرد إلى ضمير المؤمنين لأن أهل الكتاب أرادوا إرجاعهم هم بعد تقدمهم واستقامتهم، وجاءت ﴿كفارًا﴾ حالًا تبين الهيئة التي يودون أن يصيروا إليها: أن يعودوا كفارًا كما كانوا قبل الإسلام، من غير أن يبقى معهم شيء مما اكتسبوه من الإيمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص105، تحت «سر التعبير بكلمة ﴿يردونكم﴾»","url":""}]},{"id":"s2-368","number":368,"surah":2,"verses":[109],"references":[{"surah":2,"verses":[109]}],"verseLabel":"البقرة: 109","question":"ما سرّ الجمع بين العفو والصفح في قوله تعالى: ﴿فاعفوا واصفحوا﴾؟","answer":"أُمر المؤمنون بالعفو والصفح علاجًا لما يثيره الحسد من الفتن والشقاق، وتربيةً لهم على قوة النفس والعقل والثبات. وقُيّد الأمر بقوله ﴿حتى يأتي الله بأمره﴾؛ إيذانًا بأنهم سيُقوَّون ويُهيأون لمواجهة خصومهم حين يأتي أمر الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص111، تحت «سر التعبير بالعفو والصفح»","url":""}]},{"id":"s2-369","number":369,"surah":2,"verses":[109],"references":[{"surah":2,"verses":[109]}],"verseLabel":"البقرة: 109","question":"ما دلالة التعبير بـ﴿كثير﴾ في قوله تعالى: ﴿ود كثير من أهل الكتاب﴾؟","answer":"يدل ﴿كثير﴾ على أن هذا الود صدر عن عدد كثير من أهل الكتاب، لا عن جميعهم ولا عن أكثرهم، مع أنهم ليسوا عددًا قليلًا. وفي ذلك دقة وعدل في نسبة الموقف إلى أصحابه، وإشارة إلى وجود من يُرجى إيمانه منهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص105، تحت «فائدة التعبير بـ«كثير»»","url":""}]},{"id":"s2-370","number":370,"surah":2,"verses":[109],"references":[{"surah":2,"verses":[109]}],"verseLabel":"البقرة: 109","question":"ما سرّ التعبير في قوله تعالى: ﴿كُفَّارًا﴾ بصيغة الجمع المكثّر، دون أن يقال: «كافرين»؟","answer":"﴿كفار﴾ من صيغ جمع التكسير الدالة على الكثرة، فناسبت تمنيهم رد المؤمنين جميعًا إلى الكفر.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص106، تحت «بلاغة اختيار الصيغ»","url":""}]},{"id":"s2-371","number":371,"surah":2,"verses":[109],"references":[{"surah":2,"verses":[109]}],"verseLabel":"البقرة: 109","question":"ما سرّ التعبير في قوله تعالى: ﴿مِنْ بَعْدِ إِيمَانِكُمْ﴾، ولم يكتفِ بقوله: «بعد إيمانكم»؟","answer":"دخلت ﴿من﴾ على الظرف لتفيد ابتداء الزمن وسرعة وقوع إرادتهم؛ فبمجرد ظهور إيمان المؤمنين أراد أهل الكتاب ردهم عنه، وفي ذلك كشف عن تعجل حسدهم وسرعة تمكنه منهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص106، تحت «بلاغة مجيء حرف ابتداء الغاية»","url":""}]},{"id":"s2-372","number":372,"surah":2,"verses":[109],"references":[{"surah":2,"verses":[109]}],"verseLabel":"البقرة: 109","question":"ما سرّ التعبير في قوله تعالى: ﴿حَسَدًا مِنْ عِنْدِ أَنْفُسِهِمْ﴾، أليس الحسد بطبيعته صادرًا من النفس؟","answer":"أضيفت ﴿عند﴾ إلى ﴿أنفسهم﴾ لتبين أن الحسد متأصل في نفوسهم، مستمر متمكن منها، ومنبعث من قبلها لا من كتابهم ولا من شرائع الرسل؛ فالتعبير يؤكد منبع الحسد ويقطع عنه كل مستند خارجي.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص108، تحت «التعبير بـ﴿من﴾ لابتداء الغاية»","url":""}]},{"id":"s2-373","number":373,"surah":2,"verses":[109],"references":[{"surah":2,"verses":[109]}],"verseLabel":"البقرة: 109","question":"ما سرّ التعبير في قوله تعالى: ﴿مِنْ بَعْدِ مَا تَبَيَّنَ لَهُمُ الْحَقُّ﴾، ولم يكتفِ بذكر حسدهم؟","answer":"بيّن القيد أنهم تمنوا رد المؤمنين بعد أن ظهر لهم الحق، فكان فعلهم عنادًا وحسدًا لا التباسًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص109، تحت «فائدة دخول حرف الابتداء على الظرف»","url":""}]},{"id":"s2-374","number":374,"surah":2,"verses":[110],"references":[{"surah":2,"verses":[110]}],"verseLabel":"البقرة: 110","question":"ما مناسبة تقديم الصلاة على الزكاة في قوله: ﴿وَأَقِيمُوا الصَّلَاةَ وَآتُوا الزَّكَاةَ﴾؟","answer":"قُدمت الصلاة لأنها الأهم وقاعدة الدين وفرض عين على كل مسلم، بخلاف الزكاة التي لا تجب إلا على من تحققت فيه شروطها. ولأن الصلاة عبادة يومية متكررة تستغرق زمن حياة المسلم، أما الزكاة فتؤدى في وقت يسير؛ كما تتصل الصلاة بحياة المسلم والزكاة بحياة المجتمع.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص119، تحت «نكات تقديم الجملة على الجملة»","url":""}]},{"id":"s2-375","number":375,"surah":2,"verses":[110],"references":[{"surah":2,"verses":[110]}],"verseLabel":"البقرة: 110","question":"ما سرّ التعبير في قوله تعالى: ﴿وَآتُوا الزَّكَاةَ﴾ ولم يذكر من تُعطى لهم؟","answer":"حُذف المفعول الثاني، وتقديره «مستحقيها»، للإيجاز لأن مستحقي الزكاة معلومون بالدليل الشرعي، ولتوجيه العناية إلى الزكاة المعطاة والحث على المبادرة بإيتائها والتخلص منها على وجه السرعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص119، تحت «نكتة حذف المفعول الثاني»","url":""}]},{"id":"s2-376","number":376,"surah":2,"verses":[110],"references":[{"surah":2,"verses":[110]}],"verseLabel":"البقرة: 110","question":"ما سرّ تعميم قوله تعالى: ﴿وما تقدموا لأنفسكم من خير﴾ بعد الأمر بالصلاة والزكاة؟","answer":"ذكر الصلاة والزكاة بوصفهما أصلين عظيمين، ثم عمم بعد الخاص ليشمل كل بر: فرضًا أو نافلة، بدنيًا أو ماليًا، كثيرًا أو قليلًا. فالجملة لا تكرر ما قبلها، بل تفتح الباب من المثالين الأبرز إلى بنك العمل الصالح كله.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص120، تحت «بلاغة عطف العام على الخاص»","url":""}]},{"id":"s2-377","number":377,"surah":2,"verses":[110],"references":[{"surah":2,"verses":[110]}],"verseLabel":"البقرة: 110","question":"ما مناسبة تقديم ﴿لِأَنْفُسِكُمْ﴾ على ﴿مِنْ خَيْرٍ﴾؟","answer":"قدم الغاية على الوسيلة لتحريك أقوى باعث في النفس: كل خير تبذله يعود نفعه إليك أنت. فقبل أن يذكر نوع الخير نبّه إلى صاحبه الحقيقي، وبذلك يحض الإنسان على العمل من باب حرصه الفطري على ما ينجيه وينفعه في آخرته.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص122، تحت «بلاغة التقديم والتأخير»","url":""}]},{"id":"s2-378","number":378,"surah":2,"verses":[110],"references":[{"surah":2,"verses":[110]}],"verseLabel":"البقرة: 110","question":"ما سرّ التعبير في قوله تعالى: ﴿تَجِدُوهُ عِنْدَ اللَّهِ﴾، دون أن يقال: «تجدوا ثوابه»؟","answer":"في قوله ﴿عند الله﴾ ترغيب في تقديم الخير وتشريف لجزائه بالقرب، ومبالغة في تعظيم الثواب؛ لأن لفظ ﴿عند﴾ من ظروف القرب وقد أضيف هنا إلى الله تعالى مجازًا. أما تخصيص الفرق بين ﴿تجدوه﴾ و«تجدوا ثوابه» فيحتاج إلى دليل آخر مباشر.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص122، تحت «فائدة التعبير بالظرف»","url":""}]},{"id":"s2-379","number":379,"surah":2,"verses":[110],"references":[{"surah":2,"verses":[110]}],"verseLabel":"البقرة: 110","question":"ما سرّ التعبير في قوله تعالى: ﴿إِنَّ اللَّهَ بِمَا تَعْمَلُونَ بَصِيرٌ﴾ فقدم ﴿بما تعملون﴾، دون أن يقال: «إن الله بصير بما تعملون»؟","answer":"قدم العمل لأنه محور الآية من الصلاة والزكاة وكل خير يُقدَّم، فناسب أن يبقى في واجهة الخاتمة. وفي التقديم تقوية للعناية والمراقبة: أعمالكم كلها هي محل البصر الإلهي، فيستوي ظاهرها وخفيها ولا يضيع منها شيء، ثم جاءت ﴿بصير﴾ فاصلةً ثابتة تناسب هذا المعنى.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص123، تحت «نكتة تقديم ﴿بما تعملون﴾ على الصفة ﴿بصير﴾»","url":""}]},{"id":"s2-380","number":380,"surah":2,"verses":[111],"references":[{"surah":2,"verses":[111]}],"verseLabel":"البقرة: 111","question":"ما مضمون دعوى اليهود والنصارى في قوله تعالى: ﴿لَنْ يَدْخُلَ الْجَنَّةَ إِلَّا مَنْ كَانَ هُودًا أَوْ نَصَارَى﴾، وكيف رد القرآن عليها؟","answer":"قصرت كل طائفة دخول الجنة على أتباع ملتها؛ فاليهود زعمت أنه لا يدخلها إلا اليهود، والنصارى زعمت ذلك للنصارى. ورد القرآن بأن هذه مجرد أماني لا تقوم على علم، وطالبهم بالبرهان إن كانوا صادقين.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص128، تحت «بلاغة اللف والنشر»","url":""}]},{"id":"s2-382","number":382,"surah":2,"verses":[111],"references":[{"surah":2,"verses":[111]}],"verseLabel":"البقرة: 111","question":"ما سرّ التعبير في قوله تعالى: ﴿تِلْكَ أَمَانِيُّهُمْ﴾ باسم الإشارة للبعيد، دون أن يقال: «هذه أمانيهم»؟","answer":"أشير إلى أمانيهم باسم البعيد لتحقيرها وإبعادها عن الحق والواقع، وللتنبيه إلى بطلانها.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص129، تحت «استعمال الإشارة للبعيد دون القريب»","url":""}]},{"id":"s2-383","number":383,"surah":2,"verses":[111],"references":[{"surah":2,"verses":[111]}],"verseLabel":"البقرة: 111","question":"ما سرّ التعبير في قوله تعالى: ﴿أَمَانِيُّهُمْ﴾ بالجمع، مع أن المذكور أمنية واحدة هي دخول الجنة؟","answer":"جُمعت ﴿أماني﴾ لأن الدعوى صدرت من فريقين، ولكل فريق أمنيته، ولأنها جنس يضم أمانيهم الباطلة المتعددة.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص129، تحت «العدول عن الإفراد إلى الجمع»","url":""}]},{"id":"s2-384","number":384,"surah":2,"verses":[111],"references":[{"surah":2,"verses":[111]}],"verseLabel":"البقرة: 111","question":"ما سرّ التعبير في قوله تعالى: ﴿هَاتُوا بُرْهَانَكُمْ﴾، دون أن يقال: «هاتوا دليلكم»؟","answer":"البرهان أخص من مطلق الدليل وأقوى ظهورًا في إثبات صدق الدعوى؛ فالدليل قد يكون علامة أو قولًا يُستدل به، أما البرهان فلا يسمى كذلك إلا إذا أظهر صحة المدعى. ولأنهم حكموا في أعظم الغيوب حكمًا قاطعًا، طولبوا بأقوى درجات الحجة لا بمجرد شبهة يحتجون بها.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص131، تحت «البرهان والدليل»","url":""}]},{"id":"s2-385","number":385,"surah":2,"verses":[111],"references":[{"surah":2,"verses":[111]}],"verseLabel":"البقرة: 111","question":"ما سرّ التعبير في قوله تعالى: ﴿إِنْ كُنْتُمْ صَادِقِينَ﴾، دون أن يقال مباشرة: «وأنتم كاذبون»؟","answer":"الشرط يضع دعواهم أمام اختبار عملي: إن كان الصدق قائمًا فموضعه البرهان. وفيه تعريض بالكذب أبلغ من التصريح؛ لأن عجزهم عن إحضار الحجة هو الذي يكشفهم، كما أن تقديم جواب الشرط ﴿هاتوا برهانكم﴾ يجعل مدار المحاجة كله على الدليل لا على مجرد تبادل الاتهام.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص130، تحت «بلاغة الجملة الشرطية في التعريض بكذبهم»","url":""}]},{"id":"s2-386","number":386,"surah":2,"verses":[112],"references":[{"surah":2,"verses":[112]}],"verseLabel":"البقرة: 112","question":"ما سرّ ابتداء الرد بقوله: ﴿بَلَى﴾، ولم يقل: «نعم»؟","answer":"لأن كلامهم تضمن نفي دخول الجنة عن غير اليهود أو النصارى، و﴿بلى﴾ هي التي تنقض النفي وتثبت ضده؛ أما «نعم» فتصدق الكلام السابق على وجهه وقد توهم إقرار النفي. فجاء حرف واحد يهدم الاحتكار كله، ثم يقرر المعيار الصحيح لدخول الجنة.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص136، تحت «بلاغة الرد بالأداة بلى»","url":""}]},{"id":"s2-387","number":387,"surah":2,"verses":[112],"references":[{"surah":2,"verses":[112]}],"verseLabel":"البقرة: 112","question":"ما سرّ التعبير في قوله تعالى: ﴿أَسْلَمَ وَجْهَهُ لِلَّهِ﴾، دون أن يقال: «أسلم نفسه لله»؟","answer":"عُبّر بالوجه عن الذات كلها لأنه أشرف ما يظهر من الإنسان وأول ما يتجه به إلى مقصده؛ فإذا سلّم وجهه لله دل ذلك على إخلاص توجهه وانقياد ذاته بلا التفات إلى غيره. فذكر الجزء الأظهر يصور استسلام الكل تصويرًا محسوسًا، ويضيف معنى القصد والتوجه الذي لا تؤديه «نفسه» بالقوة نفسها.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص137، تحت «توجيه المخصوص بالذكر»","url":""}]},{"id":"s2-388","number":388,"surah":2,"verses":[112],"references":[{"surah":2,"verses":[112]}],"verseLabel":"البقرة: 112","question":"ما سرّ التعبير في قوله تعالى: ﴿مَنْ أَسْلَمَ﴾ بالماضي، دون أن يقال: «من يُسلم وجهه»؟","answer":"جاء ﴿أسلم﴾ بالماضي للدلالة على تحقق الإسلام وثبوته، لا على مجرد دعوى أو نية مؤجلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص136، تحت «نكتة التعبير بصيغة الفعل الماضي»","url":""}]},{"id":"s2-389","number":389,"surah":2,"verses":[112],"references":[{"surah":2,"verses":[112]}],"verseLabel":"البقرة: 112","question":"إذا أسلم الإنسان وجهه لله، فلماذا زاد: ﴿وَهُوَ مُحْسِنٌ﴾؟","answer":"لأن مجرد الانقياد الظاهر لا يكفي حتى يكون العمل حسنًا موافقًا للحق؛ فقد يتواضع المرء أو يتعبد على صورة فاسدة. فجمعت الآية إخلاص الوجه لله مع إحسان العمل، أي صحة القصد وصحة الفعل، وبذلك أبطلت النجاة بالانتساب المجرد من جهتين.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص137، تحت «ارتباط الإحسان بالتسليم»","url":""}]},{"id":"s2-390","number":390,"surah":2,"verses":[112],"references":[{"surah":2,"verses":[112]}],"verseLabel":"البقرة: 112","question":"ما فائدة تقديم ﴿له﴾ على ﴿أجره﴾ في قوله ﴿فله أجره عند ربه﴾؟","answer":"يفيد التشويق؛ فنفس من أسلم وجهه لله تترقب معرفة ما أعد لها، وتزيد إضافة الأجر إلى ضميره هذا التشويق: فهو أجره المكتوب له والمحفوظ عند ربه.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص138، تحت عنوان «نكتة التقديم والتأخير»","url":""}]},{"id":"s2-1515","number":1515,"surah":2,"verses":[112],"references":[{"surah":2,"verses":[112]}],"verseLabel":"البقرة: 112","question":"لماذا أوثر لفظ ﴿ربه﴾ في قوله ﴿فله أجره عند ربه﴾؟","answer":"لأن الرب هو الناظر في مصالح عبده ومربيه ومدبر أحواله؛ فذكر الربوبية يجعل العبد أطمع في الجزاء ويشعر المحسن بالطمأنينة إلى ما أعده له ربه في الآخرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص138، تحت عنوان «إيثار عنوان الربوبية على الألوهية»","url":""}]},{"id":"s2-391","number":391,"surah":2,"verses":[112],"references":[{"surah":2,"verses":[112]}],"verseLabel":"البقرة: 112","question":"ما دلالة الانتقال من الإفراد في قوله تعالى: ﴿من أسلم وجهه... فله أجره﴾ إلى الجمع في قوله: ﴿عليهم... هم يحزنون﴾؟","answer":"روعي أولًا لفظ ﴿من﴾ المفرد لتصوير مسؤولية كل إنسان وحده: إسلامه وإحسانه وأجره، ثم روعي معناها العام فانتقل إلى الجمع عند الحديث عن المآل الذي تشترك فيه الجماعة كلها. فالتحول ليس اضطرابًا، بل انتقال من عمل الفرد وحسابه إلى أمان المؤمنين جميعًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص140، تحت «سر التغاير بين الإفراد والجمع»","url":""}]},{"id":"s2-392","number":392,"surah":2,"verses":[113],"references":[{"surah":2,"verses":[113]}],"verseLabel":"البقرة: 113","question":"ما سرّ التعبير في قوله تعالى: ﴿قَالَتِ الْيَهُودُ﴾ و﴿قَالَتِ النَّصَارَى﴾ بتأنيث الفعل؟","answer":"لأن اسمي اليهود والنصارى أُخذا هنا باعتبار الجماعة أو الطائفة، فأنّث الفعل مراعاة لهذا المعنى. وهذا التصوير ينسب القول إلى الطائفة بوصفه موقفًا جماعيًا متداولًا فيها، لا زلة فرد منفرد.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص143، تحت «فائدة تأنيث الفعل المسند إلى الفاعل»","url":""}]},{"id":"s2-393","number":393,"surah":2,"verses":[113],"references":[{"surah":2,"verses":[113]}],"verseLabel":"البقرة: 113","question":"ما سرّ صياغة قول اليهود والنصارى في عبارتين متطابقتين تقريبًا: ﴿لَيْسَتِ النَّصَارَى عَلَى شَيْءٍ﴾ و﴿لَيْسَتِ الْيَهُودُ عَلَى شَيْءٍ﴾؟","answer":"صيغ القولان على نسق واحد لإظهار تناقض الفريقين: كل فريق ينفي عن الآخر كل حظ من الحق، ثم يرد الآخر بالحكم نفسه. فتكشف المقابلة فساد الدعويين، وتثير التعجب من صدورهما عمن يتلون الكتاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص143، تحت «بلاغة عطف القول على القول»","url":""}]},{"id":"s2-394","number":394,"surah":2,"verses":[113],"references":[{"surah":2,"verses":[113]}],"verseLabel":"البقرة: 113","question":"ما سرّ التعبير في قوله تعالى: ﴿وَهُمْ يَتْلُونَ الْكِتَابَ﴾ بعد حكاية إنكار كل فريق للآخر؟","answer":"جاءت الجملة حالًا لتصور هيئتهم العجيبة وتزيد التشنيع: ينفي كل فريق عن الآخر كل حظ من الحق مع أنهم يتلون الكتاب، لكنهم لا ينتفعون بتلاوته ولا يعملون بمقتضى العلم؛ فكأن تلاوتهم بلا فائدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص147، تحت «سر إيثار أن تكون الحال جملة لا مفردًا»","url":""}]},{"id":"s2-395","number":395,"surah":2,"verses":[113],"references":[{"surah":2,"verses":[113]}],"verseLabel":"البقرة: 113","question":"ما سرّ التعبير في قوله تعالى: ﴿الَّذِينَ لَا يَعْلَمُونَ﴾، ولم يسمِّ المشركين صراحة؟","answer":"عُبر عن المشركين بقوله ﴿الذين لا يعلمون﴾ لتحقيق غرضين: التعريض بأهل الكتاب، فكأنهم قيل لهم إنكم مع ادعاء العلم تشابهون من لا يعلم؛ ومخاطبة المشركين بلطف بنفي العلم عنهم بدل إثبات الجهل لهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص149، تحت «سر إيثار النفي على الإثبات»","url":""}]},{"id":"s2-396","number":396,"surah":2,"verses":[113],"references":[{"surah":2,"verses":[113]}],"verseLabel":"البقرة: 113","question":"ما سرّ الجمع بين ﴿كَذَلِكَ﴾ و﴿مِثْلَ قَوْلِهِمْ﴾؛ أليس أحد التعبيرين كافيًا للدلالة على التشابه؟","answer":"كاف التشبيه في ﴿كذلك﴾ تفيد المشابهة، ثم جاء ﴿مثل قولهم﴾ تأكيدًا لها وبيانًا لتمامها بين قول الذين لا يعلمون وقول اليهود والنصارى. وتقديم ﴿كذلك﴾ يمهد لما بعده ويشوق إليه، ويربط القول اللاحق بالسابق بإيجاز.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص148، تحت «فائدة التشبيه بين أهل الكتاب والمشركين»","url":""}]},{"id":"s2-397","number":397,"surah":2,"verses":[113],"references":[{"surah":2,"verses":[113]}],"verseLabel":"البقرة: 113","question":"ما الذي يفيده ختام الآية: ﴿فَاللَّهُ يَحْكُمُ بَيْنَهُمْ يَوْمَ الْقِيَامَةِ فِيمَا كَانُوا فِيهِ يَخْتَلِفُونَ﴾؟","answer":"يفيد أن الفصل النهائي في اختلاف اليهود والنصارى موكول إلى حكم الله يوم القيامة؛ فيميز الحق من الباطل ويجازي كل فريق. وجيء بالمضارع في خبر المستقبل لتحقيق وقوع الحكم واستحضاره.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص150، تحت «لفتة في الإعجاز الغيبي»","url":""}]},{"id":"s2-398","number":398,"surah":2,"verses":[113],"references":[{"surah":2,"verses":[113]}],"verseLabel":"البقرة: 113","question":"لماذا قُدِّم ﴿بينهم﴾ على ﴿يوم القيامة﴾ في قوله: ﴿فالله يحكم بينهم يوم القيامة﴾؟","answer":"لأن سياق الآية يعرض اختلاف أهل الملل، فكان الحكم بين المختلفين هو الأبرز في المقام؛ لذلك قُدِّم ما يدل عليهم على زمن الحكم.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص150–151، تحت «علة تقديم الظروف بعضها على بعض»","url":""}]},{"id":"s2-399","number":399,"surah":2,"verses":[114],"references":[{"surah":2,"verses":[114]}],"verseLabel":"البقرة: 114","question":"ما وجه وصف أكثر من جريمة في القرآن بأنها الأظلم في قوله ﴿وَمَنْ أَظْلَمُ﴾؛ مع أن «الأظلم» واحد؟","answer":"الاستفهام ينفي أن يوجد من هو أشد ظلمًا من صاحب الجريمة في بابها وسياقها، ولا يلزم أن تكون كل الآيات ترتيبًا حسابيًا لجميع الجرائم في قائمة واحدة. وقد تتساوى صور متعددة في بلوغ الغاية من الظلم، أو يكون كل وصف أظلم من جهة مخصوصة؛ وهنا بلغ الظلم ذروته لأنه صدّ الناس عن بيوت الله وعمل في خرابها.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص156، تحت «تعدد متعلق «ومن أظلم» في القرآن الكريم»","url":""}]},{"id":"s2-400","number":400,"surah":2,"verses":[114],"references":[{"surah":2,"verses":[114]}],"verseLabel":"البقرة: 114","question":"ما سرّ التعبير في قوله تعالى: ﴿أَنْ يُذْكَرَ فِيهَا اسْمُهُ﴾، دون أن يقال: «أن يُعبد الله فيها»؟","answer":"ذُكر منع اسم الله لأنه من أيسر صور العبادة، فإذا منعوه في مساجد الله كان ذلك أبلغ في تصوير شناعته وعمق عداوته. وحُذف فاعل ﴿يذكر﴾ للإيجاز والتعميم، وقُدمت ﴿فيها﴾ للمبالغة في تقبيح منع الذكر في المساجد.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص159، تحت «دلالة التعبير بمنع ذكر اسمه»","url":""}]},{"id":"s2-401","number":401,"surah":2,"verses":[114],"references":[{"surah":2,"verses":[114]}],"verseLabel":"البقرة: 114","question":"ما سرّ التعبير في قوله تعالى: ﴿أَنْ يُذْكَرَ﴾ بالبناء للمجهول، دون أن يقال: «أن يذكر المؤمنون»؟","answer":"حُذف الذاكر ليعم الحكم كل ذاكر وكل لون مشروع من الذكر؛ فالجريمة ليست منع فئة مسماة، بل منع أن يقع ذكر الله أصلًا في مساجده. كما تتجه العناية إلى الفعل الممنوع وإلى قدسية المكان، لا إلى هوية من يؤديه.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص159، تحت «نكتة التعبير بالفعل المبني للمجهول»","url":""}]},{"id":"s2-402","number":402,"surah":2,"verses":[114],"references":[{"surah":2,"verses":[114]}],"verseLabel":"البقرة: 114","question":"ما مناسبة تقديم ﴿فِيهَا﴾ فقال: ﴿أَنْ يُذْكَرَ فِيهَا اسْمُهُ﴾، ولم يقل: «أن يذكر اسمه فيها»؟","answer":"قُدمت ﴿فيها﴾ للاهتمام بالمساجد والإشارة إلى منزلتها، ولإفادة القصر على سبيل المبالغة في تقبيح منع ذكر الله في الموضع المعد له، مع أن ذكر الله مشروع فيها وفي غيرها.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص160، تحت «نكتة تقديم «فيها» على «اسمه»»","url":""}]},{"id":"s2-403","number":403,"surah":2,"verses":[114],"references":[{"surah":2,"verses":[114]}],"verseLabel":"البقرة: 114","question":"ما سرّ التعبير في قوله تعالى: ﴿وَسَعَى فِي خَرَابِهَا﴾، دون أن يقال: «وخرّبها»؟","answer":"السعي يصور قصدًا وحركةً وبذل جهد في الوصول إلى الخراب، فيشمل الهدم الحسي وتعطيل العبادة وصد الناس وكل مقدمة توصل إلى ذلك. أما «خربها» فتحصر النظر غالبًا في النتيجة الواقعة؛ فجاء اللفظ ليجرّم المشروع والمسار ولو لم يكتمل أثره.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص160، تحت «سر استعمال مفردة السعي»","url":""}]},{"id":"s2-404","number":404,"surah":2,"verses":[114],"references":[{"surah":2,"verses":[114]}],"verseLabel":"البقرة: 114","question":"ما سرّ التعبير في قوله تعالى: ﴿مَا كَانَ لَهُمْ أَنْ يَدْخُلُوهَا إِلَّا خَائِفِينَ﴾، دون أن يقال: «لا يدخلونها إلا خائفين»؟","answer":"﴿ما كان لهم﴾ تنفي الاستحقاق واللياقة، لا مجرد وقوع الدخول؛ أي ما صح ولا استقام لهؤلاء أن يدخلوها آمنين بعد أن منعوا أهلها وسعوا في خرابها. والاستثناء يقلب صورة قوتهم: المكان الذي استباحوه ينبغي أن لا يدخلوه إلا في ذلة وخوف من المؤمنين أو من عقاب الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص161، تحت «بلاغة الاستئناف البياني»","url":""}]},{"id":"s2-405","number":405,"surah":2,"verses":[114],"references":[{"surah":2,"verses":[114]}],"verseLabel":"البقرة: 114","question":"ما دلالة تكرار ﴿لَهُمْ﴾ فقال: ﴿لَهُمْ فِي الدُّنْيَا خِزْيٌ وَلَهُمْ فِي الْآخِرَةِ عَذَابٌ عَظِيمٌ﴾؟","answer":"أعيد ﴿لهم﴾ للإشعار بقوة الجزاءين واستقلال كل واحد منهما، ولتأكيد استحقاقهم خزي الدنيا وعذاب الآخرة معًا؛ فلا يحجب وقوع الأول نزول الثاني.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص164، تحت «نكتة إعادة ذكر الجار والمجرور»","url":""}]},{"id":"s2-406","number":406,"surah":2,"verses":[114],"references":[{"surah":2,"verses":[114]}],"verseLabel":"البقرة: 114","question":"ما سرّ التعبير في قوله تعالى: ﴿خِزْيٌ﴾ بالتنكير، دون أن يقال: «الخزي»؟","answer":"التنكير يفخم خزيًا لا يحيط السامع بمقداره، ويترك صوره مفتوحة: ذلة وفضيحة وقهر بعد استعلاء. فهو لا يشير إلى خزي معروف محدود، بل يوحي بنوع عظيم من الهوان يناسب شناعة منع بيوت الله من وظيفتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص163، تحت «نكتة تنكير لفظ «خزي»»","url":""}]},{"id":"s2-407","number":407,"surah":2,"verses":[115],"references":[{"surah":2,"verses":[115]}],"verseLabel":"البقرة: 115","question":"كيف يُفهم قوله تعالى: ﴿فَأَيْنَمَا تُوَلُّوا فَثَمَّ وَجْهُ اللَّهِ﴾ مع وجود قبلة مأمور بها؟","answer":"الجهات كلها لله؛ فمن أدركته الصلاة وتعذرت عليه معرفة القبلة تحرى وصلى إلى الجهة التي غلب على ظنه صحتها، وكذلك وردت الرخصة في أحوال السفر. فالمقصود امتثال أمر الله وطلب رضاه، لا أن ملكه أو علمه محصور في جهة.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص169، تحت «سر التعبير بالوجه»","url":""}]},{"id":"s2-408","number":408,"surah":2,"verses":[115,142],"references":[{"surah":2,"verses":[115,142]},{"surah":55,"verses":[17]}],"verseLabel":"البقرة: 115 و142؛ الرحمن: 17","question":"لماذا جاء ﴿لله المشرق والمغرب﴾ في البقرة، و﴿رب المشرقين ورب المغربين﴾ في الرحمن؟","answer":"في سياق تحويل القبلة جاء التعبير باسم الله للحث على إخلاص العبودية له. وفي الرحمن أضيف المشرقان والمغربان إلى الربوبية لإظهار الامتنان بالإنعام والتربية ومراعاة ما به قوام حياة الإنس والجن؛ فلكل تعبير ما يناسب مقامه.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص744–745، تحت عنوان «الغرض من الإضافة إلى الربوبية»","url":""}]},{"id":"s2-1516","number":1516,"surah":2,"verses":[115,142],"references":[{"surah":2,"verses":[115,142]},{"surah":55,"verses":[17]}],"verseLabel":"البقرة: 115 و142؛ الرحمن: 17","question":"ما دلالة تكرار لفظ ﴿رب﴾ في ﴿رب المشرقين ورب المغربين﴾؟","answer":"كرر لفظ رب للتأكيد؛ لأن الموضع مقام امتنان وتعديد للنعم، والخطاب فيه موجّه إلى جنسين هما الإنس والجن، فناسبه هذا التأكيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص745، تحت عنوان «دلالة تكرار لفظ ﴿رب﴾»","url":""}]},{"id":"s2-410","number":410,"surah":2,"verses":[115],"references":[{"surah":2,"verses":[115]}],"verseLabel":"البقرة: 115","question":"ما مناسبة تقديم ﴿الْمَشْرِقُ﴾ على ﴿الْمَغْرِبُ﴾؟","answer":"لأن الشروق بداية الحركة والضياء، والغروب نهايتها وبداية الظلمة؛ فوافق الترتيب مسار اليوم من المبدأ إلى المنتهى. كما أن مواقيت الصلاة تتبع هذه الدورة، فجرى اللفظ على النظام الكوني والشرعي الذي يبدأ بالظهور ثم ينتهي بالأفول.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص168، تحت «دلالة تقديم المشرق على المغرب»","url":""}]},{"id":"s2-411","number":411,"surah":2,"verses":[115],"references":[{"surah":2,"verses":[115]}],"verseLabel":"البقرة: 115","question":"ما سرّ التعبير في قوله تعالى: ﴿فَأَيْنَمَا تُوَلُّوا﴾ ولم يذكر ما الذي يولّون إليه وجوههم؟","answer":"حذف جهة التولية ليعم كل اتجاه تصح إليه الصلاة في الأحوال التي تبينها الشريعة؛ فلا يحبس المعنى في جهة واحدة مذكورة. والسياق نفسه يملأ المحذوف: أي جهة تستقبلونها أو تنصرفون إليها، فهي داخل ملك الله وعلمه، لا تخرجون بالتوجه عن سلطانه.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص169، تحت «سر استعمال «فأينما» الظرفية اسم شرط»","url":""}]},{"id":"s2-412","number":412,"surah":2,"verses":[115],"references":[{"surah":2,"verses":[115]}],"verseLabel":"البقرة: 115","question":"ما معنى قوله تعالى: ﴿فثم وجه الله﴾، وما سرّ هذا التعبير؟","answer":"المعنى: فهناك الجهة التي وجهكم الله إليها. وعُبر بـ﴿وجه الله﴾ دون «القبلة» لبيان أن المصلي يقصد وجه الله ورضاه؛ فالتوجه إلى المشرق أو المغرب عند تحقق العذر امتثال لأمره وتحقيق للغاية من الصلاة.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص169، تحت «سر التعبير بالوجه»","url":""}]},{"id":"s2-413","number":413,"surah":2,"verses":[115],"references":[{"surah":2,"verses":[115]}],"verseLabel":"البقرة: 115","question":"ما مناسبة ختم الآية بقوله تعالى: ﴿إن الله واسع عليم﴾ وترتيب الاسمين على هذا الوجه؟","answer":"﴿واسع﴾ تناسب أولًا اتساع الجهات والمشرق والمغرب وسعة الرحمة والرخصة، ثم تأتي ﴿عليم﴾ لتقرر أنه يعلم وجهة كل مصلٍّ ونيته وعذره فلا يلتبس عليه اختلاف الأماكن. فبدأ بالصفة التي تجيب عن ضيق الجهة، ثم ختم بالعلم الذي يحيط بمن يتوجه فيها.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص170، تحت «بلاغة ترتيب الصفات في الفاصلة»","url":""}]},{"id":"s2-414","number":414,"surah":2,"verses":[115],"references":[{"surah":2,"verses":[115]}],"verseLabel":"البقرة: 115","question":"ما سرّ التعبير في قوله تعالى: ﴿وَلِلَّهِ الْمَشْرِقُ وَالْمَغْرِبُ﴾ فقدم ﴿لله﴾، دون أن يقال: «والمشرق والمغرب لله»؟","answer":"التقديم يفيد الاختصاص والقصر: الجهات كلها ملك لله وتحت تدبيره، فلا تستقل جهة بقداسة من ذاتها ولا يملك معترض أن يحجر أمر القبلة عليها. وفيه تشويق أيضًا؛ فبعد ذكر خزي الظالمين يتطلع السامع إلى ما اختص الله به، فإذا الجواب محيط بطرفي الأرض.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص167–168، تحت «نكتة تقديم الخبر»","url":""}]},{"id":"s2-415","number":415,"surah":2,"verses":[115],"references":[{"surah":2,"verses":[115]}],"verseLabel":"البقرة: 115","question":"ما سرّ الاقتصار على ﴿المشرق والمغرب﴾ مع أن بينهما جهات كثيرة؟","answer":"عطف الطرف المقابل على مقابله يفيد الإحاطة بما بينهما؛ فذكر المشرق والمغرب يغني عن تعداد الشمال والجنوب وسائر الجهات، وكأن التقدير: لله المشرق والمغرب وما بينهما. وهذا الإيجاز يخدم المقصود مباشرة: أينما يقع التوجه فهو داخل هذا الملك الشامل.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص168، تحت «بلاغة الإيجاز بالحذف»","url":""}]},{"id":"s2-417","number":417,"surah":2,"verses":[116],"references":[{"surah":2,"verses":[116]},{"surah":10,"verses":[68]}],"verseLabel":"البقرة: 116، يونس: 68","question":"ما سرّ اختلاف التعبير بين قوله تعالى في البقرة: ﴿وَقَالُوا اتَّخَذَ اللَّهُ وَلَدًا﴾ بالواو، وقوله تعالى في يونس: ﴿قَالُوا اتَّخَذَ اللَّهُ وَلَدًا﴾ دون واو؟","answer":"عطفت البقرة هذه المقالة على سلسلة أقوال سبقتها، وهي تشمل افتراءات فرق متعددة: اليهود والنصارى والمشركين؛ فناسب وصلها بالواو بما قبلها. أما آية يونس ففي كفار قريش خاصة، وجاءت بيانًا مستقلًا لما سبق من حالهم، ففُصلت الجملة.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص173، تحت «توجيه المتشابه اللفظي»","url":""}]},{"id":"s2-418","number":418,"surah":2,"verses":[116],"references":[{"surah":2,"verses":[116]}],"verseLabel":"البقرة: 116","question":"ما سرّ مجيء التنزيه فور دعواهم فقال: ﴿وَقَالُوا اتَّخَذَ اللَّهُ وَلَدًا سُبْحَانَهُ﴾، ولم يبدأ بإقامة الدليل على بطلانها؟","answer":"لأن الدعوى من الشناعة بحيث لا تنتظر تفصيل الرد؛ فبادر القرآن بتنزيه الله عنها قبل مناقشتها، وفي ﴿سبحانه﴾ تعجب من جرأتهم مع إعلان براءة الله من النقص. ثم جاءت الحجة بعدها: من يملك السماوات والأرض ويقنت له الجميع لا يحتاج إلى ولد.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص174، تحت ««سبحانه» مصدر منصوب للتوكيد»","url":""}]},{"id":"s2-419","number":419,"surah":2,"verses":[116],"references":[{"surah":2,"verses":[116]}],"verseLabel":"البقرة: 116","question":"كيف رد قوله تعالى: ﴿بَلْ لَهُ مَا فِي السَّمَاوَاتِ وَالْأَرْضِ كُلٌّ لَهُ قَانِتُونَ﴾ على دعوى ﴿اتَّخَذَ اللَّهُ وَلَدًا﴾؟","answer":"أثبتت ﴿له ما في السماوات والأرض﴾ أن ما في الكون ملك لله، ثم جاءت ﴿كل له قانتون﴾ حجة مستقلة تؤكد أن الجميع عابدون طائعون له؛ فالملك العام والخضوع له ينفيان دعوى اتخاذ الولد.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص176، تحت عنوان «بلاغة الفصل بين الجمل»","url":""}]},{"id":"s2-420","number":420,"surah":2,"verses":[116],"references":[{"surah":2,"verses":[116]}],"verseLabel":"البقرة: 116","question":"ما مناسبة تقديم ﴿لَهُ﴾ فقال: ﴿لَهُ مَا فِي السَّمَاوَاتِ وَالْأَرْضِ﴾، ولم يقل: «ما في السماوات والأرض له»؟","answer":"التقديم يفيد اختصاص الملك بالله: كل ما في الكون له وحده خلقًا وتدبيرًا وعبودية. وهذه الخصوصية هي قلب الحجة؛ إذ تنفي أن يكون في ملكه شريك أو ولد يخرج عن سلطان العبودية.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص175، تحت «فائدة تقديم المتعلق «له» على المبتدأ»","url":""}]},{"id":"s2-421","number":421,"surah":2,"verses":[116],"references":[{"surah":2,"verses":[116]}],"verseLabel":"البقرة: 116","question":"ما مناسبة تقديم السماوات على الأرض في قوله: ﴿مَا فِي السَّمَاوَاتِ وَالْأَرْضِ﴾؟","answer":"لأنها أعلى وأعظم وأوسع، وتحوي من المخلوقات ما لا تحويه الأرض، فبدأ بالأعظم الحاوي ثم عطف عليه ما دونه. كما جرى أكثر القرآن على هذا الترتيب الموافق لما يشاهده الإنسان من علو السماء وإحاطتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص176، تحت «نكتة تقديم «السماوات» على «الأرض»»","url":""}]},{"id":"s2-422","number":422,"surah":2,"verses":[116],"references":[{"surah":2,"verses":[116]}],"verseLabel":"البقرة: 116","question":"ما سرّ التعبير في قوله تعالى: ﴿كُلٌّ لَهُ قَانِتُونَ﴾ بالجمع، مع أن لفظ ﴿كل﴾ مفرد؟","answer":"روعي معنى ﴿كل﴾ لا لفظها؛ فهي تستغرق مخلوقات كثيرة، فجاء الخبر جمعًا ليظهر هذا العموم. والتعبير بـ﴿قانتون﴾ يصورهم عقلاء خاضعين طائعين، وفي ذلك تشريف لمن أطاع وتغليب لذوي الإدراك، مع تقرير أن الجميع تحت أمر الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص176، تحت «نكتة الجمع في «قانتون»»","url":""}]},{"id":"s2-423","number":423,"surah":2,"verses":[117],"references":[{"surah":2,"verses":[117]}],"verseLabel":"البقرة: 117","question":"ما سرّ التعبير في قوله تعالى: ﴿بَدِيعُ السَّمَاوَاتِ وَالْأَرْضِ﴾، دون أن يقال: «خالق السماوات والأرض»؟","answer":"﴿بديع﴾ يبرز إنشاء السماوات والأرض على غير مثال سابق، لا مجرد أصل الخلق؛ ولذلك يلائم الرد على دعوى الولد: فمن أبدع هذا الكون لا يحتاج إلى ولد.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص178، تحت «شرح المفردات: «بديع»»","url":""}]},{"id":"s2-424","number":424,"surah":2,"verses":[117],"references":[{"surah":2,"verses":[117]}],"verseLabel":"البقرة: 117","question":"ما سرّ التعبير في قوله تعالى: ﴿بَدِيعُ السَّمَاوَاتِ وَالْأَرْضِ﴾ من غير أن يقول: «هو بديع السماوات والأرض»؟","answer":"حُذف المبتدأ لأن المرجع إلى الله معلوم من الآية السابقة، فجاء الوصف مستقلًا كحجة مباغتة لا تحتاج إلى تمهيد: بديع السماوات والأرض! وهذا القطع يشبه إبراز النعت وحده لتعظيمه، ويجعل الدليل أسرع وقوعًا في السمع.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص179، تحت «براعة حذف المسند إليه»","url":""}]},{"id":"s2-425","number":425,"surah":2,"verses":[117],"references":[{"surah":2,"verses":[117]}],"verseLabel":"البقرة: 117","question":"ما سرّ التعبير في قوله تعالى: ﴿وَإِذَا قَضَى أَمْرًا﴾ بـ﴿إذا﴾، مع أن قضاء الله سابق لوجود الزمان؟","answer":"تفيد ﴿إذا﴾ تحقق وقوع المقضي كلما تعلق به قضاؤه سبحانه، ولا يراد بها تقييد قدرته بزمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص180، تحت «معنى «وإذا» في سياقها»","url":""}]},{"id":"s2-426","number":426,"surah":2,"verses":[117],"references":[{"surah":2,"verses":[117]}],"verseLabel":"البقرة: 117","question":"ما سرّ التعبير في قوله تعالى: ﴿قَضَى أَمْرًا﴾، دون أن يقال: «حكم أمرًا»؟","answer":"اختير ﴿قضى﴾ لأن القضاء في هذا السياق إحكام الأمر وإمضاؤه وإتمامه على وفق المراد؛ فإذا تعلق قضاؤه بإيجاد شيء نفذ أمره وتحقق بلا إبطاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص180، تحت «سر التعبير بـ«قضى» دون «حكم»»","url":""}]},{"id":"s2-427","number":427,"surah":2,"verses":[117],"references":[{"surah":2,"verses":[117]}],"verseLabel":"البقرة: 117","question":"هل يقول الله للأشياء حقيقةً: ﴿كُنْ﴾ قبل وجودها؟ وكيف تسمع وهي معدومة؟","answer":"الكلام تمثيل لسرعة نفاذ إرادة الله وتكوينه من غير مهلة ولا عائق، لا لاحتياج الإيجاد إلى صوت تسمعه الموجودات قبل وجودها.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص181، تحت «معنى القضاء وتحققه»","url":""}]},{"id":"s2-428","number":428,"surah":2,"verses":[118],"references":[{"surah":2,"verses":[118]}],"verseLabel":"البقرة: 118","question":"ما سرّ التعبير في قوله تعالى: ﴿الَّذِينَ لَا يَعْلَمُونَ﴾، دون أن يقال: «المشركون»؟","answer":"وصفهم بأنهم ﴿الذين لا يعلمون﴾ للتشنيع عليهم وتقبيح مقالتهم؛ فالقول الذي شأنه أن يصدر عن علم صدر ممن لا يعلمون ما يقولون، وفيه كشف لجرأتهم على الله بغير علم.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص187، تحت «بلاغة إسناد القول إلى قائله»","url":""}]},{"id":"s2-429","number":429,"surah":2,"verses":[118],"references":[{"surah":2,"verses":[118]}],"verseLabel":"البقرة: 118","question":"ما سرّ مجيء نفي العلم بالمضارع: ﴿لَا يَعْلَمُونَ﴾، ولم يقل: «لم يعلموا»؟","answer":"المضارع يصور جهلهم متجددًا يصاحب كل اعتراض، لا واقعةً مضت وانتهت. وحتى لو عرفوا بعض الحقائق، فإن عدم الانتفاع بعلمهم أنزلهم منزلة من يتجدد منه الجهل قولًا وعملًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص187، تحت «نكتة التعبير بصيغة المضارع»","url":""}]},{"id":"s2-430","number":430,"surah":2,"verses":[118],"references":[{"surah":2,"verses":[118]}],"verseLabel":"البقرة: 118","question":"ما دلالة قولهم: ﴿لَوْلَا يُكَلِّمُنَا اللَّهُ﴾ دون «هل يكلمنا الله؟»؟","answer":"﴿لولا﴾ هنا للتحضيض الممزوج بالاعتراض؛ فهم لا يسألون طالبين الهداية، بل يطالبون أن يقع الأمر وفق اقتراحهم كأنه كان ينبغي أن يحدث. لذلك تكشف الأداة استكبار النية قبل أن تكشف مضمون الطلب.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص188، تحت «دلالة «لولا» على التحضيض»","url":""}]},{"id":"s2-431","number":431,"surah":2,"verses":[118],"references":[{"surah":2,"verses":[118]}],"verseLabel":"البقرة: 118","question":"ما الفرق بين مطلبيهم في قوله: ﴿لَوْلَا يُكَلِّمُنَا اللَّهُ أَوْ تَأْتِينَا آيَةٌ﴾؟","answer":"الأول طلب معنوي متعنت، وهو أن يكلمهم الله مباشرة فيساووا الرسل في التلقي؛ والثاني طلب آية حسية خارقة. وكلاهما صدر عن استكبار وعناد مع قيام الآيات الدالة على صدق الرسول.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص188، تحت «دلالة المقابلة»","url":""}]},{"id":"s2-432","number":432,"surah":2,"verses":[118],"references":[{"surah":2,"verses":[118]}],"verseLabel":"البقرة: 118","question":"لماذا نكّروا الآية فقالوا: ﴿أَوْ تَأْتِينَا آيَةٌ﴾، مع أن بين أيديهم آيات كثيرة؟","answer":"نُكرت ﴿آية﴾ للنوعية؛ فهم لا يطلبون آية مخصوصة، بل مطلق آية مادية خارقة للعادة، مع أن الآيات القرآنية والعقلية والكونية قد قامت بينهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص188، تحت «دلالة المقابلة»","url":""}]},{"id":"s2-433","number":433,"surah":2,"verses":[118],"references":[{"surah":2,"verses":[118]}],"verseLabel":"البقرة: 118","question":"ما سرّ التعبير في قوله تعالى: ﴿كَذَلِكَ قَالَ الَّذِينَ مِنْ قَبْلِهِمْ مِثْلَ قَوْلِهِمْ﴾، فجمع بين ﴿كذلك﴾ و﴿مثل قولهم﴾؟","answer":"كاف التشبيه في ﴿كذلك﴾ تفيد المشابهة، ثم جاء ﴿مثل قولهم﴾ لتأكيد تمام المشابهة بين قول هؤلاء وقول السابقين؛ وتقديم ﴿كذلك﴾ يمهد لما بعده ويشوق إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص189، تحت «الجمع بين تشبيه الأقوال وتشابه القلوب»","url":""}]},{"id":"s2-434","number":434,"surah":2,"verses":[118],"references":[{"surah":2,"verses":[118]}],"verseLabel":"البقرة: 118","question":"ما سرّ التعبير في قوله تعالى: ﴿الَّذِينَ مِنْ قَبْلِهِمْ﴾ بـ﴿من﴾، دون أن يقال: «الذين قبلهم»؟","answer":"﴿من﴾ تفتح ابتداء الغاية إلى الأمم السابقة كلها، فلا تقصر التشابه على الجيل الأقرب زمنًا. فكأن هذا الاعتراض سلسلة قديمة تبدأ قبلهم وتمتد عبر أقوام متباعدين، كلما تشابهت دوافعهم أعادوا العبارة نفسها.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص188، تحت «دلالة حرف ابتداء الغاية»","url":""}]},{"id":"s2-435","number":435,"surah":2,"verses":[118],"references":[{"surah":2,"verses":[118]}],"verseLabel":"البقرة: 118","question":"ما سرّ التعبير في قوله تعالى: ﴿تَشَابَهَتْ قُلُوبُهُمْ﴾، دون أن يقال: «تشابهت أقوالهم» وقد ذكر تشابه القول قبلها؟","answer":"ذكر تشابه القلوب لأن تشابه الأقوال فرع عن تشابه ما في القلوب من الكفر والطغيان وسوء النظر؛ فانتقل من القول الظاهر إلى أصله الباطن. ووصف القلوب بالتشابه لا بالتماثل، لأنها تشترك في هذه الصفات ولا تتطابق من جميع الوجوه.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص189، تحت «الجمع بين تشبيه الأقوال وتشابه القلوب»","url":""}]},{"id":"s2-436","number":436,"surah":2,"verses":[118],"references":[{"surah":2,"verses":[118]}],"verseLabel":"البقرة: 118","question":"ما سرّ مجيء الرد بالجمع في قوله تعالى: ﴿قد بينا الآيات﴾ مع طلبهم ﴿آية﴾ واحدة؟","answer":"زادهم القرآن فوق مقترحهم: لم تأتهم علامة واحدة بل دلائل كثيرة متنوعة عقلية ووحيية وكونية. فالعدول إلى الجمع يرد التعنت بسعة البيان، ويكشف أن العائق ليس قلة الآيات وإنما غياب اليقين الذي ينتفع بها.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص190، تحت «سر العدول عن طلب السائلين»","url":""}]},{"id":"s2-437","number":437,"surah":2,"verses":[118],"references":[{"surah":2,"verses":[118]}],"verseLabel":"البقرة: 118","question":"ما سرّ تخصيص الانتفاع بالآيات بقوله: ﴿لِقَوْمٍ يُوقِنُونَ﴾، ولم يقل: «لقوم يعلمون»؟","answer":"خُصَّ الموقنون لأن اليقين منتهى الوثوق وزوال الشك؛ فالآيات البينة ينتفع بها من يطلب الحق ويوقن عند ظهور الدليل، لا من يكون ديدنه التردد والمكابرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص190، تحت «توجيه المخصوص بالذكر»","url":""}]},{"id":"s2-438","number":438,"surah":2,"verses":[119],"references":[{"surah":2,"verses":[119]}],"verseLabel":"البقرة: 119","question":"ما سرّ التعبير في قوله تعالى: ﴿إنا أرسلناك بالحق﴾ لا بالصدق؟","answer":"الحق أعم من الصدق؛ فالصدق يكون في الخبر، أما الحق فيشمل صدق الرسالة وثباتها وموافقتها لما يجب أن يكون.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص195، تحت «نكتة التعبير بالحق دون الصدق»","url":""}]},{"id":"s2-440","number":440,"surah":2,"verses":[119],"references":[{"surah":2,"verses":[119]}],"verseLabel":"البقرة: 119","question":"ما سرّ التعبير في قوله تعالى: ﴿إِنَّا أَرْسَلْنَاكَ﴾ بهذه المؤكدات، مع أن النبي ﷺ لا يشك في رسالته؟","answer":"جاء التأكيد تنويهًا بعظم الخبر وتثبيتًا للنبي أمام تشكيك المعاندين، لا إزالةً لشك عنده. فاجتمعت ﴿إن﴾ وضمير العظمة وإعادة الضمير في الفعل لتعلن أن الرسالة صادرة من الله يقينًا، وأن اقتراحات المكذبين لا تنقص منها شيئًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص196، تحت «فائدة تعدد المؤكدات»","url":""}]},{"id":"s2-441","number":441,"surah":2,"verses":[119],"references":[{"surah":2,"verses":[119]}],"verseLabel":"البقرة: 119","question":"ما مناسبة تقديم ﴿بِالْحَقِّ﴾ فقال: ﴿أَرْسَلْنَاكَ بِالْحَقِّ بَشِيرًا وَنَذِيرًا﴾؟","answer":"قُدم ﴿بالحق﴾ لتقوية الجملة والعناية بأن ما أُرسل به النبي ﷺ هو الحق دون سواه، تعريضًا بأهل الكتاب والمشركين المخالفين له.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص195، تحت «نكتة انتقاء لفظ الحق»","url":""}]},{"id":"s2-442","number":442,"surah":2,"verses":[119],"references":[{"surah":2,"verses":[119]}],"verseLabel":"البقرة: 119","question":"ما مناسبة تقديم ﴿بَشِيرًا﴾ على ﴿نَذِيرًا﴾؟","answer":"قُدمت البشارة لأنها أقرب إلى قبول النفوس وأليق بفتح باب الرجاء، ثم ذُكرت النذارة ليجتمع الترغيب والترهيب.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص195، تحت «علة تقديم البشير على النذير»","url":""}]},{"id":"s2-443","number":443,"surah":2,"verses":[119],"references":[{"surah":2,"verses":[119]}],"verseLabel":"البقرة: 119","question":"ما سرّ التعبير في قوله تعالى: ﴿أَصْحَابِ الْجَحِيمِ﴾، دون أن يقال: «أهل الجحيم» أو «الداخلين فيها»؟","answer":"الصحبة تفيد الملازمة والاستقرار؛ فليسوا عابرين في النار ثم يفارقونها، بل صاروا أصحابها المختصين بها. واللفظ يصور مآلهم في صورة حال ملازمة، فيزيد الإنذار رهبة ويكشف قبح الإصرار الذي أوصلهم إليها.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص197، تحت «فائدة التعبير بـ«أصحاب الجحيم»»","url":""}]},{"id":"s2-444","number":444,"surah":2,"verses":[119],"references":[{"surah":2,"verses":[119]}],"verseLabel":"البقرة: 119","question":"ما سرّ التعبير في قوله تعالى: ﴿وَلَا تُسْأَلُ عَنْ أَصْحَابِ الْجَحِيمِ﴾؛ أهو نفي للسؤال أم نهي عنه؟","answer":"تحتمل القراءات المعنيين: خبرًا بأن الرسول لا يُسأل عن مصير من رفض الحق، ونهيًا له عن السؤال عنهم لهول ما أُعد لهم. ويلتقي الوجهان في تسليته ﷺ: وظيفته البلاغ بالبشارة والنذارة، وليس عليه إيمان من اختار الجحيم ولا تبعة مصيره.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص196، تحت «توجيه القراءات»","url":""}]},{"id":"s2-445","number":445,"surah":2,"verses":[120,145],"references":[{"surah":2,"verses":[120,145]}],"verseLabel":"البقرة: 120 و145","question":"ما سرّ اختلاف التعبير والوعيد بين الآيتين 120 و145 من سورة البقرة؟","answer":"في الآية 120 جاء ﴿بعد الذي جاءك من العلم﴾ لأن المقام في أصل الهدى والملة، فناسب العلم المعهود الشامل، وجاء الوعيد بنفي الولي والنصير. وفي الآية 145 تعلق السياق بحكم القبلة، فجاء ﴿من بعد ما جاءك﴾، وناسب العدول عنه وصف الظلم.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص455، تحت «توجيه المتشابه اللفظي»","url":""}]},{"id":"s2-446","number":446,"surah":2,"verses":[120],"references":[{"surah":2,"verses":[120]},{"surah":3,"verses":[73]}],"verseLabel":"البقرة: 120، آل عمران: 73","question":"ما سرّ اختلاف التعبير بين قوله تعالى في البقرة: ﴿قُلْ إِنَّ هُدَى اللَّهِ هُوَ الْهُدَى﴾، وقوله تعالى في آل عمران: ﴿قُلْ إِنَّ الْهُدَى هُدَى اللَّهِ﴾ فعكس ترتيب كلمتي الهدى؟","answer":"في البقرة المقام رد على من زعم أن الهدى في ملته، فقُدّم ﴿هدى الله﴾ وقُصر عليه جنس الهدى. وفي آل عمران كان المقصود تقرير أن الهدى المعروف إنما هو هدى الله، فناسب تقديم ﴿الهدى﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص207، تحت «توجيه المتشابه اللفظي»","url":""}]},{"id":"s2-447","number":447,"surah":2,"verses":[120],"references":[{"surah":2,"verses":[120]}],"verseLabel":"البقرة: 120","question":"ما سرّ التعبير في قوله تعالى: ﴿وَلَنْ تَرْضَى عَنْكَ الْيَهُودُ وَلَا النَّصَارَى﴾ بـ﴿لن﴾، دون أن يقال: «لا ترضى»؟","answer":"اختيرت ﴿لن﴾ لأنها تخلص النفي للاستقبال، فتقرر أنهم لا يرضون في الحاضر ولا في المستقبل حتى تُتبع ملتهم، وفي ذلك قطع لأمل المنافقين والمداهنين في استرضائهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص202، تحت «سر التعبير عن نفي رضا اليهود والنصارى بأداة «ولن»»","url":""}]},{"id":"s2-448","number":448,"surah":2,"verses":[120],"references":[{"surah":2,"verses":[120]}],"verseLabel":"البقرة: 120","question":"ما سرّ التعبير في قوله تعالى: ﴿تَرْضَى عَنْكَ﴾ بحرف ﴿عن﴾، دون أن يقال: «ترضى بك»؟","answer":"الرضا بـ﴿عن﴾ يتجه إلى موقفهم من الشخص وسلوكه، وفيه معنى انصراف السخط عنه؛ أما الرضا بالشيء فيغلب أن يكون قبولًا له واختيارًا. والسياق يصور أسبابًا في نظرهم تمنع رضاهم عن الرسول حتى يترك استقلاله ويتبع ملتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص203، تحت «سر تعدية الفعل «ترضى» بحرف «عن»»","url":""}]},{"id":"s2-449","number":449,"surah":2,"verses":[120],"references":[{"surah":2,"verses":[120]}],"verseLabel":"البقرة: 120","question":"ما مناسبة تقديم اليهود على النصارى؟","answer":"لأن اليهود أسبق زمنًا وأشد عداوةً للمؤمنين كما يبين القرآن، فقدم الفريق الأقدم والأغلظ في هذا المقام. ثم عطف النصارى لتكتمل صورة أهل الكتاب الذين لا يجمعهم رضا واحد إلا مطالبة الرسول باتباع ما هم عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص204، تحت «نكتة تقديم اليهود على النصارى»","url":""}]},{"id":"s2-450","number":450,"surah":2,"verses":[120],"references":[{"surah":2,"verses":[120]}],"verseLabel":"البقرة: 120","question":"ما دلالة تكرار النفي في قوله تعالى: ﴿اليهود ولا النصارى﴾ بدل عطف الاسمين من غير تكراره؟","answer":"تكرار ﴿لا﴾ يجعل نفي الرضا مستقلًا عن كل فريق؛ فلا يتوهم أن اجتماعهما وحده هو المنفي أو أن أحدهما قد يرضى منفردًا. كما يفصل الصوت بين الخصمين اللذين تختلف ملتاهما، مع اتحادهما في الضغط على الرسول.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص204، تحت «نكتة إيراد «ولا» النافية قبل «النصارى»»","url":""}]},{"id":"s2-451","number":451,"surah":2,"verses":[120],"references":[{"surah":2,"verses":[120]}],"verseLabel":"البقرة: 120","question":"ما سرّ التعبير في قوله تعالى: ﴿حَتَّى تَتَّبِعَ مِلَّتَهُمْ﴾، دون أن يقال: «إلى أن تتبع ملتهم»؟","answer":"اختيرت ﴿حتى﴾ لأن ما بعدها داخل في الغاية بخلاف «إلى»؛ فعلق رضاهم على حصول اتباع ملتهم نفسه، وفي ذلك تيئيس من رضاهم لأن هذا الاتباع مستحيل.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص205، تحت «فائدة اختيار الفعل «تتبع» دون غيره من الأفعال»","url":""}]},{"id":"s2-452","number":452,"surah":2,"verses":[120],"references":[{"surah":2,"verses":[120]}],"verseLabel":"البقرة: 120","question":"ما سرّ التعبير في قوله تعالى: ﴿تَتَّبِعَ مِلَّتَهُمْ﴾، دون أن يقال: «تدخل في ملتهم»؟","answer":"اختير ﴿تتبع﴾ لما فيه من كمال الانقياد والاستسلام والمداومة؛ فهم يريدون موافقتهم في الأقوال والأفعال والشرائع خطوةً خطوة، لا مجرد انتساب اسمي.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص205، تحت «فائدة اختيار الفعل «تتبع» دون غيره من الأفعال»","url":""}]},{"id":"s2-453","number":453,"surah":2,"verses":[120],"references":[{"surah":2,"verses":[120]}],"verseLabel":"البقرة: 120","question":"ما سرّ إفراد ﴿ملتهم﴾ مع أن اليهود والنصارى ملتان متعارضتان؟","answer":"أُفردت ﴿ملتهم﴾ لأن اليهود والنصارى اجتمعوا في هذا المقام على مخالفة الإسلام وطلب اتباع غيره، وإن اختلفت ملتاهما في التفاصيل.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص206، تحت «نكتة إفراد الملة وإضافتها لليهود والنصارى»","url":""}]},{"id":"s2-454","number":454,"surah":2,"verses":[120],"references":[{"surah":2,"verses":[120]}],"verseLabel":"البقرة: 120","question":"ما سرّ التعبير في قوله تعالى: ﴿قُلْ إِنَّ هُدَى اللَّهِ هُوَ الْهُدَى﴾، مع أن معنى الجملة يبدو معلومًا؟","answer":"أسلوب القصر يقلب دعوى من زعم أن الهدى حكر على ملته: الهدى الكامل حقًا هو ما جاء من الله، لا ما بدلته الجماعات بحسب أهوائها. وضمير الفصل والتعريف يجعلان سائر ما خالف الوحي ساقطًا عن رتبة الهداية مهما رفع أصحابه شعاراتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص207، تحت «فائدة تعدد المؤكدات في قوله تعالى: «قل إن هدى الله هو الهدى»»","url":""}]},{"id":"s2-455","number":455,"surah":2,"verses":[120],"references":[{"surah":2,"verses":[120]}],"verseLabel":"البقرة: 120","question":"ما دلالة إضافة الهدى إلى الله فقال: ﴿هُدَى اللَّهِ﴾؟","answer":"الإضافة تشرف الهدى بمصدره وتضع معيارًا لا يتغير بتغير الجماعات: ما كان وحيًا من الله فهو الهدى، وما خالفه لا يكتسب قيمته من كثرة أتباعه. وفيها تحقير ضمني للبدائل البشرية التي نسبها أصحابها إلى الدين بعد التحريف.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص206، تحت «دلالة إضافة لفظ «هدى» إلى لفظ الجلالة «الله»»","url":""}]},{"id":"s2-456","number":456,"surah":2,"verses":[120],"references":[{"surah":2,"verses":[120]}],"verseLabel":"البقرة: 120","question":"ما سرّ تسمية ملتهم ﴿أَهْوَاءَهُمْ﴾، ولم يقل: «ولئن اتبعت ملتهم»؟","answer":"لأن ما خالف الوحي فيها لم يعد شريعةً من الله، بل صار اختيارات تميل إليها النفوس طلبًا للرئاسة أو موافقة للرغبة. فالعدول إلى ﴿الأهواء﴾ ينزع عن الباطل قناع الدين، ويكشف أن مطالبتهم الرسول ليست طلبًا للحقيقة بل طلبًا لأن يخضع لرغباتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص208، تحت «نكتة التعبير بالأهواء وجمعها»","url":""}]},{"id":"s2-457","number":457,"surah":2,"verses":[120],"references":[{"surah":2,"verses":[120]}],"verseLabel":"البقرة: 120","question":"ما سرّ التعبير في قوله تعالى: ﴿أَهْوَاءَهُمْ﴾ بالجمع، مع أنه قال قبلها: ﴿مِلَّتَهُمْ﴾ بالإفراد؟","answer":"أُفردت ﴿ملتهم﴾ لاجتماعهم في مخالفة الحق، وجُمعت ﴿أهواءهم﴾ لأن أهواءهم متعددة متفرقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص208، تحت «نكتة التعبير بالأهواء وجمعها»","url":""}]},{"id":"s2-458","number":458,"surah":2,"verses":[120,145],"references":[{"surah":2,"verses":[120,145]}],"verseLabel":"البقرة: 120 و145","question":"ما سرّ التعبير هنا في قوله تعالى: ﴿بَعْدَ الَّذِي جَاءَكَ مِنَ الْعِلْمِ﴾، ثم قال في الآية 145: ﴿مِنْ بَعْدِ مَا جَاءَكَ مِنَ الْعِلْمِ﴾؟","answer":"جاء ﴿الذي﴾ في آية 120 لأنه أعرق في التعريف، ولأن العلم فيها علم عام كامل يتعلق بأصول الملة وبطلان ما خالف الإسلام. أما آية 145 ففي فرع القبلة، فجاءت ﴿ما﴾ للعلم الجزئي، ودخلت ﴿من﴾ لتشير إلى أن علم القبلة جزء من عموم العلم السابق.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص209، تحت «توجيه المتشابه اللفظي»","url":""}]},{"id":"s2-459","number":459,"surah":2,"verses":[121],"references":[{"surah":2,"verses":[121]}],"verseLabel":"البقرة: 121","question":"ما سرّ التعبير في قوله تعالى: ﴿يتلونه حق تلاوته﴾؟ وكيف تكون للكتاب تلاوة حق؟","answer":"حق التلاوة يجمع ضبط اللفظ، وفهم المعنى، ولزوم العمل؛ فليس المراد مجرد القراءة باللسان، بل قراءة يتبعها التصديق والاتباع.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص217، تحت «بلاغة التعبير «يتلونه» دلالة وصيغة»","url":""}]},{"id":"s2-460","number":460,"surah":2,"verses":[121],"references":[{"surah":2,"verses":[121]}],"verseLabel":"البقرة: 121","question":"ما سرّ التعبير في قوله تعالى: ﴿الَّذِينَ آتَيْنَاهُمُ الْكِتَابَ﴾، دون أن يقال: «أهل الكتاب»؟","answer":"لأن الوصف لا يشمل كل منتسب إلى الكتاب؛ بل يخص الذين تلقوه حقًا وحفظوا عهد الله فيه، ومنهم من آمن بالنبي ﷺ. فصلة الموصول تجعل استحقاق المدح متعلقًا بالإيتاء والتلاوة الصحيحة، لا بلقب موروث قد يحمله من كتم وحرّف.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص216، تحت «فائدة التعبير بالاسم الموصول: «الذين آتيناهم الكتاب»»","url":""}]},{"id":"s2-461","number":461,"surah":2,"verses":[121],"references":[{"surah":2,"verses":[121]}],"verseLabel":"البقرة: 121","question":"ما سرّ تعريف ﴿الكتاب﴾ في قوله تعالى: ﴿الَّذِينَ آتَيْنَاهُمُ الْكِتَابَ﴾، دون أن يقال: «كتابًا»؟","answer":"يجوز أن يراد بالكتاب العهد، ويجوز أن يراد جنس الكتاب المنزل الذي يجمع التوراة والإنجيل والقرآن في أصل الوحي؛ فالتعريف يعيّن الكتاب الإلهي المعروف الذي يجب الوفاء به والإيمان بما يصدقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص216، تحت «معنى التعريف في الكتاب وسر اختياره»","url":""}]},{"id":"s2-462","number":462,"surah":2,"verses":[121],"references":[{"surah":2,"verses":[121]}],"verseLabel":"البقرة: 121","question":"ما سرّ التعبير في قوله تعالى: ﴿يَتْلُونَهُ﴾، دون أن يقال: «يقرؤونه»؟","answer":"التلاوة تجمع القراءة والاتباع؛ أصلها أن يتلو الشيءُ الشيءَ، فكأن عملهم يأتي خلف ألفاظ الكتاب ولا ينفصل عنها. أما القراءة وحدها فقد تقع باللسان مع ترك الحكم، وهو الخلل الذي ذمته الآيات السابقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص217، تحت «بلاغة التعبير «يتلونه» دلالة وصيغة»","url":""}]},{"id":"s2-463","number":463,"surah":2,"verses":[121],"references":[{"surah":2,"verses":[121]}],"verseLabel":"البقرة: 121","question":"ما سرّ التعبير في قوله تعالى: ﴿يَتْلُونَهُ﴾ بالمضارع؟","answer":"ليصور التلاوة والاتباع عادة متجددة لا موقفًا وقع مرة ثم انقطع؛ فهم يرجعون إلى الكتاب في أحوالهم ويلازمون هديه. وهذا الاستمرار هو الذي يميز من يعيش بالوحي عمن عرف دلالته لحظة ثم كتمها.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص217، تحت «بلاغة التعبير «يتلونه» دلالة وصيغة»","url":""}]},{"id":"s2-464","number":464,"surah":2,"verses":[121],"references":[{"surah":2,"verses":[121]}],"verseLabel":"البقرة: 121","question":"ما دلالة اسم الإشارة للبعيد في قوله تعالى: ﴿أُولَئِكَ يُؤْمِنُونَ بِهِ﴾؟","answer":"البعد هنا لعلو المنزلة، لا لبعد المكان؛ رفع الذين جمعوا التلاوة والعمل حتى كأنهم في مقام يشار إليه من بعيد. كما يربط اسم الإشارة الحكم بالصفات السابقة: بسبب إيتائهم الكتاب وتلاوته حقًا استحقوا وصف الإيمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص217، تحت «فائدة استعمال اسم الإشارة للبعيد»","url":""}]},{"id":"s2-465","number":465,"surah":2,"verses":[121],"references":[{"surah":2,"verses":[121]}],"verseLabel":"البقرة: 121","question":"ما سرّ التعبير في قوله تعالى: ﴿وَمَنْ يَكْفُرْ بِهِ فَأُولَئِكَ هُمُ الْخَاسِرُونَ﴾، فبدأ بالمفرد ثم انتقل إلى الجمع؟","answer":"روعي لفظ ﴿من﴾ أولًا في فعل الفرد واختياره، ثم روعي معناها العام في الحكم الذي يشمل كل من اتصف بالكفر. فيضع التركيب المسؤولية على كل شخص، ثم يجمع أصحاب النتيجة الواحدة في مصير الخسران.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص218، تحت «اختلاف الصيغة بين الشرط وجوابه»","url":""}]},{"id":"s2-466","number":466,"surah":2,"verses":[121],"references":[{"surah":2,"verses":[121]}],"verseLabel":"البقرة: 121","question":"ماذا أضاف التعبير: ﴿فَأُولَئِكَ هُمُ الْخَاسِرُونَ﴾ إلى جواب الشرط؟","answer":"جعل الكفر بالكتاب مقابِلًا لتلاوته حق تلاوته والإيمان به، ثم أكد أن هؤلاء هم المتحققون بالخسران؛ فاسم الإشارة يميزهم، وضمير الفصل مع تعريف الخبر يفيدان قصر الخسران الحقيقي عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص218، تحت «فائدة ضمير الفصل»","url":""}]},{"id":"s2-467","number":467,"surah":2,"verses":[122],"references":[{"surah":2,"verses":[122]}],"verseLabel":"البقرة: 122","question":"ما سرّ التعبير في قوله تعالى: ﴿أَنْعَمْتُ عَلَيْكُمْ﴾ بحرف ﴿على﴾، دون أن يقال: «أنعمت إليكم»؟","answer":"﴿على﴾ تستحضر علو مصدر النعمة وانصبابها عليهم وكثرتها ودوام آثارها؛ فهي ليست عطيةً وصلت ثم انقطعت، بل إحسان نزل من عند الله وأحاط بالمخاطبين. وهذا أدعى إلى الطمأنينة والشكر لمن عرف مصدر النعمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص223، تحت «فائدة تعدي الفعل (أنعم) بحرف الاستعلاء»","url":""}]},{"id":"s2-468","number":468,"surah":2,"verses":[123],"references":[{"surah":2,"verses":[123]}],"verseLabel":"البقرة: 123","question":"ما سرّ التعبير في قوله تعالى: ﴿لَا تَجْزِي نَفْسٌ عَنْ نَفْسٍ شَيْئًا﴾، دون أن يقال: «لا تجزي روح عن روح»؟","answer":"النفس هي صاحبة الكسب التي تنسب إليها الطاعة والمعصية ويقع عليها الحساب والجزاء، أما الروح فهي سر الحياة ولا تنسب إليها الأعمال بهذا الاعتبار. لذلك يختار القرآن لفظ النفس في مواطن المسؤولية الأخروية؛ فهي التي صنعت الاختيار وتواجه نتيجته.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص230، تحت «سر التعبير بالنفس»","url":""}]},{"id":"s2-469","number":469,"surah":2,"verses":[123],"references":[{"surah":2,"verses":[123]}],"verseLabel":"البقرة: 123","question":"ما سرّ ترتيب وسائل النجاة المنفية في قوله تعالى: ﴿لَا تَجْزِي نَفْسٌ... وَلَا يُقْبَلُ مِنْهَا عَدْلٌ وَلَا تَنْفَعُهَا شَفَاعَةٌ وَلَا هُمْ يُنْصَرُونَ﴾؟","answer":"نفت الآية وسائل الخلاص المعهودة مرتبة: أن يؤدي غيره الحق عنه، ثم أن يقدم فدية، ثم أن تنفعه شفاعة، ثم أن تنقذه قوة ناصرة؛ فاستوعبت وجوه النجاة المتوهمة وقطعتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص232، تحت «بلاغة ترتيب المنفيات الأربعة»","url":""}]},{"id":"s2-470","number":470,"surah":2,"verses":[123],"references":[{"surah":2,"verses":[123]}],"verseLabel":"البقرة: 123","question":"ما دلالة قوله تعالى: ﴿وَلَا هُمْ يُنْصَرُونَ﴾ بذكر الضمير، دون أن يقال: «ولا يُنصرون»؟","answer":"تقديم ﴿هم﴾ يزيد نفي النصرة توكيدًا، والبناء للمجهول يغيّب أي ناصر محتمل، وتكرار ﴿لا﴾ يجعل هذا الباب منفيًا مستقلًا بعد الفدية والشفاعة. هكذا تنتهي الآية بقطع آخر وهم يمكن أن يتعلق به المكذب.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص233، تحت «بلاغة الفاصلة»","url":""}]},{"id":"s2-471","number":471,"surah":2,"verses":[124],"references":[{"surah":2,"verses":[124]}],"verseLabel":"البقرة: 124","question":"ما سرّ التعبير في قوله تعالى: ﴿وإذ ابتلى إبراهيم ربه﴾ باسم الربوبية؟","answer":"الابتلاء هنا تربية وارتقاء من الرب لعبده حتى يبلغ الإمامة، لا امتحان من يجهل النتيجة؛ فاسم الرب يبرز الرعاية داخل التكليف.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص244، تحت «دلالة إضافة الهاء إلى الرب»","url":""}]},{"id":"s2-472","number":472,"surah":2,"verses":[124],"references":[{"surah":2,"verses":[124]}],"verseLabel":"البقرة: 124","question":"ما سرّ التعبير في قوله تعالى: ﴿بكلمات﴾ جمع قلة، مع كثرة ما ابتُلي به إبراهيم؟","answer":"جاءت ﴿كلمات﴾ جمع قلة للإيحاء بيسر ما كُلّف به إبراهيم ولطف الله بعباده في التكاليف؛ فالتكليف في طاقتهم وليس فيه مشقة خارجة عن الوسع.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص246، تحت «سر التعبير بالتمام دون الكمال»","url":""}]},{"id":"s2-473","number":473,"surah":2,"verses":[124],"references":[{"surah":2,"verses":[124]}],"verseLabel":"البقرة: 124","question":"ما سرّ التعبير في قوله تعالى: ﴿فأتمهن﴾ بالتمام لا بالكمال؟","answer":"اختير ﴿فأتمهن﴾ لأن التمام يدل في هذا السياق على اتصال الأداء من غير فتور أو انقطاع؛ فمدح إبراهيم بأنه استمر نشطًا متواصلًا في أداء الكلمات.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص246، تحت «سر التعبير بالتمام دون الكمال»","url":""}]},{"id":"s2-474","number":474,"surah":2,"verses":[124],"references":[{"surah":2,"verses":[124]}],"verseLabel":"البقرة: 124","question":"ما سرّ التعبير في قوله تعالى: ﴿إني جاعلك للناس إمامًا﴾، دون أن يقال: رسولًا؟","answer":"الإمامة أعم أثرًا من مجرد تبليغ الرسالة؛ إذ ينتفع به قومه بالمباشرة، وتقتدي به الأمم بعده، فناسب مقام القدوة العامة قوله: ﴿لِلنَّاسِ إِمَامًا﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص248، تحت «نكتة اختيار لفظ «إمامًا» دون «رسول»»","url":""}]},{"id":"s2-475","number":475,"surah":2,"verses":[124],"references":[{"surah":2,"verses":[124]}],"verseLabel":"البقرة: 124","question":"لماذا سُمِّيت الإمامة في جواب إبراهيم عهدًا: ﴿لا ينال عهدي الظالمين﴾؟","answer":"سُمِّيت عهدًا لأن ما يعد الله به لا يتخلّف، وفي اختيار اللفظ أيضًا تعريض بناقضي العهود؛ فمن نقض عهد الله لا يليق أن يتطلع إلى الإمامة التي وعد بها إبراهيم.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص250، تحت «اختيار لفظة «عهدي» في نفي الإمامة»","url":""}]},{"id":"s2-476","number":476,"surah":2,"verses":[124],"references":[{"surah":2,"verses":[124]}],"verseLabel":"البقرة: 124","question":"ما سرّ التعبير في قوله تعالى: ﴿وَإِذِ ابْتَلَى إِبْرَاهِيمَ رَبُّهُ﴾ فقدم إبراهيم على الفاعل ﴿ربه﴾؟","answer":"قُدم إبراهيم للاهتمام بشأنه بوصفه المبتلى، ولئلا يعود ضمير ﴿ربه﴾ على متأخر لفظًا ورتبة؛ وأضيف اسم الرب إلى ضميره تشريفًا وتكريمًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص244، تحت «توجيه قراءة ابن عامر «إبراهيم»»","url":""}]},{"id":"s2-477","number":477,"surah":2,"verses":[124],"references":[{"surah":2,"verses":[124]}],"verseLabel":"البقرة: 124","question":"ما سرّ التعبير في قوله تعالى: ﴿فَأَتَمَّهُنَّ﴾ بالفاء؟","answer":"الفاء تصور سرعة إبراهيم في الامتثال؛ فما إن جاء التكليف حتى أعقبه الإتمام بلا تراخٍ أو تسويف. فاختصرت حرفٌ واحد مسافةً كاملة بين الأمر والعمل، وصار مدح إبراهيم في المبادرة ظاهرًا قبل أن يذكر جزاؤه بالإمامة.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص245، تحت «سر دخول حرف الفاء على «فأتمهن»»","url":""}]},{"id":"s2-478","number":478,"surah":2,"verses":[124],"references":[{"surah":2,"verses":[124]}],"verseLabel":"البقرة: 124","question":"ما سرّ التعبير في قوله تعالى بعد الابتلاء: ﴿قَالَ إِنِّي جَاعِلُكَ لِلنَّاسِ إِمَامًا﴾، دون أن يقال: «فقال»؟","answer":"الفصل يشعر بأن الإمامة منحة إلهية مستقلة بمحض الاصطفاء، لا نتيجة آلية يملكها الإنسان بمجرد العمل. نعم جاءت بعد نجاح الابتلاء جزاءً وتشريفًا، لكنها تظل فضلًا من الله ورسالة لا تنال بالكسب وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص247، تحت «فائدة الفصل بين الجمل»","url":""}]},{"id":"s2-479","number":479,"surah":2,"verses":[124],"references":[{"surah":2,"verses":[124]}],"verseLabel":"البقرة: 124","question":"ما سرّ التعبير في قوله تعالى: ﴿إِنِّي جَاعِلُكَ﴾ باسم الفاعل، دون أن يقال: «سأجعلك»؟","answer":"اسم الفاعل يصور الجعل مستقبلًا محققًا كأنه قائم حاصل لا يشوبه شك، وهو أوكد من مجرد وعد بالفعل. فالإمامة ليست احتمالًا ينتظر الظروف، بل أمر قضاه الله بعد نجاح إبراهيم في الابتلاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص247، تحت «سر العدول عن الإخبار بالفعل الدال على المستقبل إلى الاسم»","url":""}]},{"id":"s2-480","number":480,"surah":2,"verses":[124],"references":[{"surah":2,"verses":[124]}],"verseLabel":"البقرة: 124","question":"ما دلالة تقديم ﴿للناس﴾ في قوله تعالى: ﴿إِنِّي جَاعِلُكَ لِلنَّاسِ إِمَامًا﴾؟","answer":"التقديم يبرز سعة الإمامة واختصاص أثرها بالناس جميعًا، لا بجماعة محلية واحدة. ومن ذريته جاءت النبوات بعده، وصار قدوة تتجاوز زمنه ومكانه؛ فقدم نطاق الرسالة قبل لقبها.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص248، تحت «فائدة تقديم الجار والمجرور»","url":""}]},{"id":"s2-481","number":481,"surah":2,"verses":[124],"references":[{"surah":2,"verses":[124]}],"verseLabel":"البقرة: 124","question":"لماذا لم يقل إبراهيم مباشرة: «واجعل ذريتي أئمة»، بل قال: ﴿وَمِنْ ذُرِّيَّتِي﴾؟","answer":"عدل إلى عبارة خبرية قصيرة تحمل الطلب بأدب، فلم يأمر ربه ولم يصرح باستحقاق ذريته، بل عرض رجاءه بلطف: واجعل من ذريتي. وفيها حرص الأب على صلاح نسله مع بقاء مقام العبودية والتسليم.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص248، تحت «لطف العدول عن الطلب بالأمر إلى الاستفهام»","url":""}]},{"id":"s2-482","number":482,"surah":2,"verses":[124],"references":[{"surah":2,"verses":[124]}],"verseLabel":"البقرة: 124","question":"ما سرّ التعبير في قوله تعالى: ﴿مِنْ ذُرِّيَّتِي﴾، دون أن يقال: «وذريتي»؟","answer":"﴿من﴾ للتبعيض؛ فإبراهيم لم يسأل الإمامة لجميع نسله على اختلاف أحوالهم، وإنما لمن يصلح منهم للاقتداء. فجاء الدعاء موافقًا للحكمة والواقع، ومهّد للجواب الذي يستبعد الظالمين.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص249، تحت «سر استعمال حرف الجر «من» في «قال ومن ذريتي»»","url":""}]},{"id":"s2-483","number":483,"surah":2,"verses":[124],"references":[{"surah":2,"verses":[124]}],"verseLabel":"البقرة: 124","question":"ما الذي تقرره جملة ﴿لَا يَنَالُ عَهْدِي الظَّالِمِينَ﴾ في جواب دعاء إبراهيم لذريته؟","answer":"تقرر أن عهد الإمامة لا يصيب الظالمين ولا يشملهم؛ فليس مجرد الانتساب إلى إبراهيم سببًا كافيًا لنيلها، بل الظلم مانع من هذا العهد الإلهي.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص250، تحت «نكتة إيثار لفظ الظلم على غيره من الألفاظ والعدول في أسلوب الجواب»","url":""}]},{"id":"s2-484","number":484,"surah":2,"verses":[125],"references":[{"surah":2,"verses":[125]}],"verseLabel":"البقرة: 125","question":"ما سرّ التعبير عن البيت بأنه ﴿مَثَابَةً لِلنَّاسِ﴾، دون «مرجعًا»؟","answer":"المثابة تتضمن الرجوع والثواب، وتفيد تكرر عودة الناس إلى البيت مع الشوق إليه؛ فهي أبلغ من لفظ يدل على مطلق الرجوع.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص260–261، تحت «سر اختيار مفردة «مثابة» دون الرجوع؛ ودلالة الهاء في كلمة «مثابة»»","url":""}]},{"id":"s2-485","number":485,"surah":2,"verses":[125],"references":[{"surah":2,"verses":[125]}],"verseLabel":"البقرة: 125","question":"ما سرّ التعبير في قوله تعالى: ﴿للناس﴾ لا: للمسلمين؟","answer":"لأن حرمة البيت وأصله الإبراهيمي وآية الأمن موجهة للبشر، ودعوته سابقة على التقسيمات اللاحقة؛ ثم ينتفع بها المؤمنون أتم انتفاع.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص261، تحت «سر اختيار لفظ «الناس» دون المسلمين»","url":""}]},{"id":"s2-486","number":486,"surah":2,"verses":[125],"references":[{"surah":2,"verses":[125]}],"verseLabel":"البقرة: 125","question":"ما سرّ التعبير في قوله تعالى: ﴿البيت﴾ مجردًا من الوصف، مع أنه البيت الحرام؟","answer":"أُطلق ﴿البيت﴾ من غير تقييده بوصف ليدل تعدد أوصافه المحذوفة على شرفه وكماله؛ فهو أول بيت للعبادة وموضع الأمن، وصار الاسم علمًا على البناء الذي ارتضاه الله لعبادته.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص260، تحت «سر استعمال لفظ «البيت» دون وصف»","url":""}]},{"id":"s2-487","number":487,"surah":2,"verses":[125],"references":[{"surah":2,"verses":[125]},{"surah":22,"verses":[26]}],"verseLabel":"البقرة: 125، الحج: 26","question":"ما سرّ اختلاف التعبير بين قوله تعالى في البقرة عند تطهير البيت: ﴿لِلطَّائِفِينَ وَالْعَاكِفِينَ﴾، وقوله تعالى في الحج: ﴿لِلطَّائِفِينَ وَالْقَائِمِينَ﴾؟","answer":"ذُكر ﴿العاكفين﴾ في البقرة لأن السياق في أهل البيت والإقامة عنده، وذُكر ﴿القائمين﴾ في الحج لأن السياق في العمل لله وإقامة العبادة، ومنه القيام بالصلاة والحج؛ فناسب كل لفظ سياقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص502، تحت «بلاغة توجيه التشابه اللفظي بين هذه الآية وآية البقرة»","url":""}]},{"id":"s2-488","number":488,"surah":2,"verses":[125],"references":[{"surah":2,"verses":[125]}],"verseLabel":"البقرة: 125","question":"لماذا قُدِّم وصف البيت بأنه ﴿مثابة للناس﴾ على وصفه بأنه ﴿أمنًا﴾؟","answer":"لأن رجوع الناس إلى البيت للعبادة هو الغاية، والأمن وسيلة تعينهم على الوصول والعبادة والاستقرار؛ فقُدِّمت الغاية على الوسيلة والأصل على ما يخدمه.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص262، تحت «بلاغة تقديم المثابة على الأمن»","url":""}]},{"id":"s2-489","number":489,"surah":2,"verses":[125],"references":[{"surah":2,"verses":[125]}],"verseLabel":"البقرة: 125","question":"ما سرّ التعبير في قوله تعالى: ﴿وَأَمْنًا﴾ بالمصدر، دون أن يقال: «وآمنًا»؟","answer":"الإخبار بالمصدر للمبالغة؛ فكأن البيت نفس الأمن لا مجرد مكان متصف به. وهذا يصور رسوخ الحرمة وامتداد الطمأنينة إلى من دخله وما حوله، ويجعل الأمن وظيفةً أصيلة في بنائه لا صفة عارضة.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص261، تحت «نكتة التعبير بالمصدر «وأمنًا»»","url":""}]},{"id":"s2-490","number":490,"surah":2,"verses":[125],"references":[{"surah":2,"verses":[125]}],"verseLabel":"البقرة: 125","question":"ما المراد بـ﴿مَقَامِ إِبْرَاهِيمَ﴾، وما معنى اتخاذه مصلى؟","answer":"مقام إبراهيم هو الحجر المعروف الذي قام عليه إبراهيم عند بناء الكعبة، ومعنى ﴿وَاتَّخِذُوا مِنْ مَقَامِ إِبْرَاهِيمَ مُصَلًّى﴾ أن يجعلوا موضعًا عنده للصلاة.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص264، تحت «نكتة التعبير بمقام دون مكان»","url":""}]},{"id":"s2-491","number":491,"surah":2,"verses":[125],"references":[{"surah":2,"verses":[125]}],"verseLabel":"البقرة: 125","question":"ما سرّ التعبير في قوله تعالى: ﴿وَعَهِدْنَا إِلَى إِبْرَاهِيمَ وَإِسْمَاعِيلَ﴾ بحرف ﴿إلى﴾؟","answer":"عُدّي فعل العهد بـ﴿إلى﴾ لأن العهد هنا بمعنى الوصية المؤكدة على العمل بها؛ أي أوصينا إبراهيم وإسماعيل، وفي ذلك دلالة على شدة حرصهما على تنفيذ ما عُهد إليهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص264، تحت «دلالة تعدية الفعل «عهد» بحرف «إلى»»","url":""}]},{"id":"s2-492","number":492,"surah":2,"verses":[125],"references":[{"surah":2,"verses":[125]}],"verseLabel":"البقرة: 125","question":"ما سرّ التعبير في قوله تعالى: ﴿طَهِّرَا بَيْتِيَ﴾ فأضاف البيت إلى نفسه؟","answer":"الإضافة للتشريف والتكريم؛ فهو البيت المخصوص بعبادة الله، وفيها دعوة إلى شدة العناية بتطهيره، وهي سبب جاذب للقلوب إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص265، تحت «دلالة إضافة البيت إلى ياء المتكلم في قوله: «بيتي»»","url":""}]},{"id":"s2-493","number":493,"surah":2,"verses":[125],"references":[{"surah":2,"verses":[125]}],"verseLabel":"البقرة: 125","question":"ما سرّ ترتيب أصناف العابدين في قوله تعالى: ﴿لِلطَّائِفِينَ وَالْعَاكِفِينَ وَالرُّكَّعِ السُّجُودِ﴾؟","answer":"رُتبت الأصناف من الأقل عددًا إلى الأكثر، ومن الأخص بعبادة البيت إلى الأعم: فالطواف لا يكون إلا حول الكعبة، والاعتكاف يكون في المساجد، والمصلون الراكعون الساجدون أكثر؛ كما قُدم الركوع لأن السجود أكثر عددًا ونوعًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص265، تحت «نكتة ترتيب أصناف العابدين»","url":""}]},{"id":"s2-494","number":494,"surah":2,"verses":[125],"references":[{"surah":2,"verses":[125]}],"verseLabel":"البقرة: 125","question":"ما سرّ التعبير في قوله تعالى: ﴿الطَّائِفِينَ وَالْعَاكِفِينَ﴾ بجمع السلامة، ثم ﴿الرُّكَّعِ السُّجُودِ﴾ بجمع التكسير؟","answer":"جيء بجمع السلامة في الطائفين والعاكفين لقربه من لفظ الفعل وإشعاره بتجدد العمل وقرب صاحبيه من البيت، وجيء بجمع الكثرة والمصدر في ﴿الركع السجود﴾ للدلالة على كثرة المصلين وكثرة أنواع السجود.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص265، تحت «سر اختيار جمع السلامة وجمع التكسير في كل صنف»","url":""}]},{"id":"s2-496","number":496,"surah":2,"verses":[126],"references":[{"surah":2,"verses":[126]},{"surah":14,"verses":[35]}],"verseLabel":"البقرة: 126؛ إبراهيم: 35","question":"ما سرّ اختلاف التعبير بين قوله تعالى في البقرة: ﴿اجْعَلْ هَذَا بَلَدًا آمِنًا﴾، وقوله في إبراهيم: ﴿اجْعَلْ هَذَا الْبَلَدَ آمِنًا﴾؟","answer":"تعريف البلد في سورة إبراهيم للعهد؛ فهو البلد المعلوم الحاضر المقصود بالدعاء. أما تنكير ﴿بلدًا﴾ في البقرة فللنوعية، أي اجعله من نوع البلاد الآمنة التي يأمن أهلها ولا يخافون. ويبين المصدر أن المآل واحد في طلب الأمن.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص92، تحت عنوان «نكتة تعريف ﴿البلد﴾ هنا، وتنكيرها في ﴿بلدًا آمنًا﴾»","url":""}]},{"id":"s2-497","number":497,"surah":2,"verses":[126],"references":[{"surah":2,"verses":[126]},{"surah":106,"verses":[4]}],"verseLabel":"البقرة: 126، قريش: 4","question":"ما سرّ اختلاف الترتيب بين تقديم الأمن على الرزق في دعاء إبراهيم، وتقديم الإطعام على الأمن في سورة قريش؟","answer":"في دعاء البقرة قُدّم الأمن لأن الدعاء كان قبل قيام البلد واستقرار أهله، ووجود البلدة الآمنة سابق لانتفاع أهلها بالرزق. وفي سورة قريش جاء الكلام خبرًا عن نعم واقعة، فبدأ بالإطعام الذي يقع على الناس مباشرة، ثم الأمن.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص276، تحت «سر تقديم الأمن وتأخيره»","url":""}]},{"id":"s2-498","number":498,"surah":2,"verses":[126],"references":[{"surah":2,"verses":[126]}],"verseLabel":"البقرة: 126","question":"ما مناسبة دعاء إبراهيم باسم الربوبية في قوله: ﴿رَبِّ اجْعَلْ هَذَا بَلَدًا آمِنًا﴾؟","answer":"دعا بوصف الربوبية اعترافًا بأن المطلوب لا يقوم به إلا الرب، ولما في إضافته إلى السائل من التلطف والضراعة ورجاء قبول السؤال وإجابته.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص274، تحت «نكتة الدعاء بعنوان الربوبية»","url":""}]},{"id":"s2-499","number":499,"surah":2,"verses":[126],"references":[{"surah":2,"verses":[126]}],"verseLabel":"البقرة: 126","question":"ما دلالة التعريف في ﴿الثمرات﴾، ودخول ﴿من﴾ عليها في قوله تعالى: ﴿وَارْزُقْ أَهْلَهُ مِنَ الثَّمَرَاتِ﴾؟","answer":"التعريف في ﴿الثمرات﴾ للاستغراق العرفي، أي الثمرات المعروفة للناس، و﴿من﴾ للتبعيض والرفق؛ حتى تتوافر لهم أنواع من الثمار من غير أن تتحول مكة إلى موطن زراعة يشغل النفوس بالارتحال إليها.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص277، تحت «دلالة الألف واللام في الثمرات»","url":""}]},{"id":"s2-500","number":500,"surah":2,"verses":[126],"references":[{"surah":2,"verses":[126]}],"verseLabel":"البقرة: 126","question":"كيف شمل الوعد بالرزق من كفر، مع أن إبراهيم خصّ المؤمنين بدعائه؟","answer":"رزق الله في الدنيا شامل للمؤمن والكافر؛ لكنه لا يدل على رضا الله عن الكفر. ولذلك أعقب ذكر المتاع ببيان العذاب، حتى لا يغتر المنعَم عليه بما أُعطي في الدنيا.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص277، تحت «فن الاحتراس»","url":""}]},{"id":"s2-501","number":501,"surah":2,"verses":[126],"references":[{"surah":2,"verses":[126]}],"verseLabel":"البقرة: 126","question":"ما سرّ التعبير في قوله تعالى: ﴿ثُمَّ أَضْطَرُّهُ إِلَى عَذَابِ النَّارِ﴾، دون أن يقال: «ثم أعذبه»؟","answer":"الاضطرار أبلغ من مطلق التعذيب؛ إذ يصور إلجاء الكافر وحمله قسرًا إلى ما يكره من عذاب النار.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص272، تحت «شرح المفردات: «أضطره»»","url":""}]},{"id":"s2-502","number":502,"surah":2,"verses":[127],"references":[{"surah":2,"verses":[127]}],"verseLabel":"البقرة: 127","question":"ما سرّ التعبير في قوله تعالى: ﴿يرفع إبراهيم القواعد من البيت﴾ مع أن القواعد هي التي تحمل البناء؟","answer":"رفع القواعد إعلاؤها حتى تصير جدارًا ويكتمل البناء مرتفعًا. وفي اختيار الرفع بدل البناء إيماء إلى وجود أصل البيت قبل رفعه، وإثبات القواعد له وتشريفه.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص282، تحت عنوان «علة اختيار مادة الرفع دون غيرها»","url":""}]},{"id":"s2-503","number":503,"surah":2,"verses":[127],"references":[{"surah":2,"verses":[127]}],"verseLabel":"البقرة: 127","question":"ما سرّ التعبير في قولهما: ﴿رَبَّنَا تَقَبَّلْ مِنَّا﴾، دون «اقبل منا»؟","answer":"في ﴿تقبل﴾ معنى التكلف في القبول؛ كأن العمل، مع إخلاص صاحبه، لا يستحق القبول بذاته لما فيه من نقص، فيسأل العبد ربه أن يتفضّل بقبوله.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص284، تحت «دلالة التعبير بصيغة الفعل «تقبل» دون «اقبل»»","url":""}]},{"id":"s2-504","number":504,"surah":2,"verses":[127],"references":[{"surah":2,"verses":[127]}],"verseLabel":"البقرة: 127","question":"ما دلالة حكاية بناء البيت بالمضارع في قوله تعالى: ﴿وَإِذْ يَرْفَعُ إِبْرَاهِيمُ الْقَوَاعِدَ﴾ مع وقوعه في الماضي؟","answer":"عُبر بالمضارع لحكاية الحال الماضية واستحضارها كأن إبراهيم حاضر بين المخاطبين وأحواله مشاهدة أمامهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص282، تحت «سر إيثار صيغة المضارع بدلًا من الماضي»","url":""}]},{"id":"s2-506","number":506,"surah":2,"verses":[127],"references":[{"surah":2,"verses":[127]}],"verseLabel":"البقرة: 127","question":"ما سرّ التعبير في قوله تعالى: ﴿الْقَوَاعِدَ مِنَ الْبَيْتِ﴾، دون أن يقال: «قواعد البيت»؟","answer":"عُرّفت ﴿القواعد﴾ ثم بُيّنت بقوله ﴿من البيت﴾ بعد إبهام، فحصل التشويق والتفخيم؛ ولو قيل «قواعد البيت» لزال هذا الأثر.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص283، تحت «التعبير بأل دون التركيب الإضافي»","url":""}]},{"id":"s2-507","number":507,"surah":2,"verses":[127],"references":[{"surah":2,"verses":[127]}],"verseLabel":"البقرة: 127","question":"ما سرّ تقديم إبراهيم على إسماعيل، والفصل بين الاسمين بقوله: ﴿الْقَوَاعِدَ مِنَ الْبَيْتِ﴾؟","answer":"قُدّم إبراهيم لأنه صاحب العمل الأصلي، وكان إسماعيل معينًا له. والفصل بين الاسمين بمتعلقات الفعل يلمح إلى تفاوت نصيبهما في العمل مع اشتراكهما فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص283، تحت «نكتة تقديم «إبراهيم» على «إسماعيل» والفصل بينهما»","url":""}]},{"id":"s2-508","number":508,"surah":2,"verses":[127],"references":[{"surah":2,"verses":[127]}],"verseLabel":"البقرة: 127","question":"ما دلالة حذف مفعول ﴿تقبل﴾ في قولهما: ﴿رَبَّنَا تَقَبَّلْ مِنَّا﴾؟","answer":"حُذف مفعول ﴿تقبل﴾ ليدل على عموم القبول، فيدخل تحته القول والعمل وكل خير، ولا ينحصر الطلب في بناء البيت وحده؛ فالعبرة بقبول العمل لا بمقداره ولا بمكانه.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص284، تحت «دلالة حذف مفعول «تقبل»»","url":""}]},{"id":"s2-509","number":509,"surah":2,"verses":[127],"references":[{"surah":2,"verses":[127]}],"verseLabel":"البقرة: 127","question":"ما مناسبة ختم الدعاء بقولهما: ﴿إِنَّكَ أَنْتَ السَّمِيعُ الْعَلِيمُ﴾؟","answer":"الخاتمة تعلل الدعاء: فالله يسمع قولهما ويعلم نيتهما وعملهما. وضمير الفصل وتعريف الخبر يفيدان اختصاصه بكمال السمع والعلم.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص285، تحت «فصل جملة «إنك أنت السميع العليم»، ودلالة ضمير الفصل فيها»","url":""}]},{"id":"s2-510","number":510,"surah":2,"verses":[128],"references":[{"surah":2,"verses":[128]}],"verseLabel":"البقرة: 128","question":"ما سرّ دعاء إبراهيم وإسماعيل: ﴿وَاجْعَلْنَا مُسْلِمَيْنِ لَكَ﴾ مع أنهما نبيان مسلمان؟","answer":"الدعاء لزيادة الإسلام والثبات عليه وبلوغ كماله في المستقبل، لا لطلب أصل الإسلام الذي كان حاصلًا لهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص291–292، تحت «تخصيص الاستسلام والخضوع لله»","url":""}]},{"id":"s2-511","number":511,"surah":2,"verses":[128],"references":[{"surah":2,"verses":[128]}],"verseLabel":"البقرة: 128","question":"لماذا كررا النداء: ﴿رَبَّنَا﴾ بعد قولهما في الآية السابقة: ﴿رَبَّنَا تَقَبَّلْ مِنَّا﴾؟","answer":"لأن كل دعوة حاجة مستقلة تستحق ضراعة جديدة، وتكرار الربوبية يظهر لذة المناجاة وشدة الافتقار. فبعد طلب قبول العمل انتقلا إلى طلب الثبات لهما ولذريتهما وتعليم العبادة وقبول التوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص291، تحت «بلاغة تكرار النداء»","url":""}]},{"id":"s2-512","number":512,"surah":2,"verses":[128],"references":[{"surah":2,"verses":[128]}],"verseLabel":"البقرة: 128","question":"ما سرّ قول إبراهيم وإسماعيل: ﴿وَمِنْ ذُرِّيَّتِنَا أُمَّةً مُسْلِمَةً لَكَ﴾ دون «واجعل ذريتنا مسلمة»؟","answer":"﴿من﴾ للتبعيض؛ فسألا إسلام بعض الذرية جمعًا بين الحرص على حصول الفضيلة لها والأدب في الدعاء، لعلمهما أن الذرية لا تكون كلها على قلب واحد ومستوى واحد في الاستسلام لله.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص292، تحت «دلالة حرف «من» في قوله: «ومن ذريتنا»»","url":""}]},{"id":"s2-513","number":513,"surah":2,"verses":[128],"references":[{"surah":2,"verses":[128]}],"verseLabel":"البقرة: 128","question":"ما سرّ قول إبراهيم وإسماعيل: ﴿وَأَرِنَا مَنَاسِكَنَا﴾ دون «وعلّمنا مناسكنا»؟","answer":"الرؤية تحتمل الإبصار المباشر والعلم اليقيني، فتجمع أن يريهما الله مواقع النسك وكيفيته وأن يفقههما معناه. أما التعليم وحده فقد لا يستحضر المشاهدة العملية التي تحتاجها أعمال الحج وبناء الشعائر.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص292، تحت «سر التعبير بالرؤية دون غيرها من الألفاظ»","url":""}]},{"id":"s2-514","number":514,"surah":2,"verses":[128],"references":[{"surah":2,"verses":[128]}],"verseLabel":"البقرة: 128","question":"ما مناسبة ختم الدعاء بقوله: ﴿إِنَّكَ أَنْتَ التَّوَّابُ الرَّحِيمُ﴾، وتقديم ﴿التواب﴾ على ﴿الرحيم﴾؟","answer":"قُدّم ﴿التواب﴾ لمجاورته طلبهما ﴿وتب علينا﴾، ثم ذُكر ﴿الرحيم﴾ لأنه أعم، ولأن قبول التوبة أثر من آثار رحمته.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص293، تحت عنوان «بلاغة الفاصلة في اختيار صفتي ﴿التواب﴾ و﴿الرحيم﴾ وترتيبهما»","url":""}]},{"id":"s2-515","number":515,"surah":2,"verses":[129],"references":[{"surah":2,"verses":[129]},{"surah":3,"verses":[164]},{"surah":62,"verses":[2]}],"verseLabel":"البقرة: 129، آل عمران: 164، الجمعة: 2","question":"ما سرّ اختلاف ترتيب التعليم والتزكية بين دعاء إبراهيم في البقرة: 129، وآيتي الاستجابة في آل عمران والجمعة؟","answer":"دعا إبراهيم قبل وجود الأمة، فكانت حاجتها أولًا إلى التلاوة والتعليم اللذين تنشأ عنهما التزكية؛ أما آيتا الاستجابة ففي مقام الامتنان على قوم وجد منهم الضلال فعلًا، فناسب تقديم تزكيتهم وإنقاذهم منه ثم ذكر التعليم.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص300، تحت «الترتيب بين التلاوة والتعليم والتزكية»","url":""}]},{"id":"s2-516","number":516,"surah":2,"verses":[129],"references":[{"surah":2,"verses":[129]}],"verseLabel":"البقرة: 129","question":"ما سرّ التعبير بـ﴿فيهم﴾ في قوله: ﴿وَابْعَثْ فِيهِمْ رَسُولًا﴾، دون «إليهم»؟","answer":"﴿فيهم﴾ تكشف الرغبة في أن يكون الرسول من جماعتهم وذريتهم، بخلاف «إليهم» التي تحتمل أن يأتي من خارجهم وقد توهم قصر رسالته عليهم؛ وكونه منهم يجعلهم أعرف بمولده وصدقه وأمانته، مع بقاء رسالته عامة للعالمين.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص298، تحت «إيثار التعبير «فيهم» لا «إليهم»»","url":""}]},{"id":"s2-517","number":517,"surah":2,"verses":[129],"references":[{"surah":2,"verses":[129]}],"verseLabel":"البقرة: 129","question":"ما دلالة ﴿منهم﴾ في قوله: ﴿وَابْعَثْ فِيهِمْ رَسُولًا مِنْهُمْ﴾؟","answer":"كونه منهم يرفع محلهم ورتبتهم، ويجعلهم يعرفون مولده ومنشأه وصدقه وأمانته فيقرب عليهم تصديقه، كما يكون أحرص الناس على خيرهم وأشفق عليهم، فيكونون أجدر باتباعه ونصره.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص299، تحت «أغراض التعبير بالمتعلق «منهم»»","url":""}]},{"id":"s2-518","number":518,"surah":2,"verses":[129],"references":[{"surah":2,"verses":[129]}],"verseLabel":"البقرة: 129","question":"ما سرّ تقديم تلاوة الآيات على تعليم الكتاب والحكمة في دعاء إبراهيم؟","answer":"قُدمت تلاوة الآيات لأنها برهان الرسالة وأصل تلقي الوحي، ومنها يبدأ تعليم الكتاب والحكمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص300، تحت «توجيه المتشابه اللفظي»","url":""}]},{"id":"s2-519","number":519,"surah":2,"verses":[129],"references":[{"surah":2,"verses":[129]}],"verseLabel":"البقرة: 129","question":"ما سرّ تقديم ﴿العزيز﴾ على ﴿الحكيم﴾ في ختام الدعاء؟","answer":"خُتم الدعاء بالعزيز ذي القوة والغلبة، القادر على إنجاز المطلوب، وبالحكيم الذي يضع كل أمر في موضعه الصحيح؛ وقُدم العزيز لأن العزة سبب نفاذ الحكم: عز فحكم.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص301، تحت «تقديم صفة «العزيز» على «الحكيم»»","url":""}]},{"id":"s2-520","number":520,"surah":2,"verses":[130],"references":[{"surah":2,"verses":[130]}],"verseLabel":"البقرة: 130","question":"ما سرّ التعبير في قوله تعالى: ﴿إلا من سفه نفسه﴾ لا: إلا سفيه؟","answer":"الأصل كأن يقال: «سفهت نفسه»، ثم حُول الإسناد إلى صاحب النفس ونُصبت ﴿نفسه﴾ تمييزًا؛ للمبالغة في تمكن السفاهة منه حتى كأنها امتزجت بنفسه وغرق فيها.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص307–308، تحت «أثر الإعراب في الكشف عن جمال المجاز»","url":""}]},{"id":"s2-521","number":521,"surah":2,"verses":[130],"references":[{"surah":2,"verses":[130]}],"verseLabel":"البقرة: 130","question":"ما سرّ التعبير في قوله تعالى: ﴿وَمَنْ يَرْغَبُ عَنْ مِلَّةِ إِبْرَاهِيمَ﴾ في صورة سؤال، دون أن يقال: «لا يرغب عنها عاقل»؟","answer":"جاء الاستفهام إنكاريًا بمعنى النفي؛ ليقرر أنه لا يعرض عن ملة إبراهيم إلا من خسر نفسه، وليفيد التوبيخ والتقريع والتشنيع واستبعاد هذا الإعراض مع وضوح فضل الملة.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص307، تحت «بلاغة النفي بأداة الاستفهام»","url":""}]},{"id":"s2-522","number":522,"surah":2,"verses":[130],"references":[{"surah":2,"verses":[130]}],"verseLabel":"البقرة: 130","question":"ما دلالة لفظ ﴿اصطفيناه﴾ في قوله تعالى: ﴿وَلَقَدِ اصْطَفَيْنَاهُ فِي الدُّنْيَا﴾؟","answer":"الاصطفاء تناول صفو الشيء وخلاصته؛ والمعنى أن الله اختار إبراهيم من بين الخلق للنبوة والحكمة في الدنيا.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص308، تحت «اصطفى واختار»","url":""}]},{"id":"s2-523","number":523,"surah":2,"verses":[130],"references":[{"surah":2,"verses":[130]}],"verseLabel":"البقرة: 130","question":"ما سرّ التعبير في قوله تعالى: ﴿وَإِنَّهُ فِي الْآخِرَةِ لَمِنَ الصَّالِحِينَ﴾، دون أن يقال: «وإنه في الآخرة صالح»؟","answer":"التعبير بـ﴿لَمِنَ الصَّالِحِينَ﴾ أدخل إبراهيم في جماعة الصالحين وثبت له الوصف توكيدًا. وتعدد المؤكدات يناسب الرد على من عرف اصطفاءه ثم رغب عن ملته.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص308، تحت «سر توالي المؤكدات في شأن إبراهيم»","url":""}]},{"id":"s2-524","number":524,"surah":2,"verses":[131],"references":[{"surah":2,"verses":[131]}],"verseLabel":"البقرة: 131","question":"ما دلالة حذف المفعول في الأمر والجواب: ﴿أَسْلِمْ قَالَ أَسْلَمْتُ﴾؟","answer":"حذف مفعول ﴿أسلم﴾ و﴿أسلمت﴾ للإيجاز ولإطلاق معنى الإسلام من غير تقييد، والتقدير: أسلم نفسك لي. وجاء الجواب دالًا على المبادرة إلى الامتثال.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص310، تحت «دلالة حذف مفعول «أسلمت»»","url":""}]},{"id":"s2-525","number":525,"surah":2,"verses":[131],"references":[{"surah":2,"verses":[131]}],"verseLabel":"البقرة: 131","question":"ما سرّ اختيار إبراهيم وصف ﴿رَبِّ الْعَالَمِينَ﴾ في جوابه: ﴿أَسْلَمْتُ لِرَبِّ الْعَالَمِينَ﴾؟","answer":"وصف ﴿رب العالمين﴾ يناسب قوله ﴿إذ قال له ربه﴾، ويعلن أن إسلام إبراهيم ليس لرب خاص بقوم، بل لرب جميع العالمين.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص311، تحت «فائدة التعبير برب العالمين»","url":""}]},{"id":"s2-526","number":526,"surah":2,"verses":[132],"references":[{"surah":2,"verses":[132]}],"verseLabel":"البقرة: 132","question":"ما سرّ التعبير في قوله تعالى: ﴿وَوَصَّى بِهَا إِبْرَاهِيمُ بَنِيهِ﴾، وإلى ماذا يعود ضمير ﴿بها﴾؟","answer":"الضمير في ﴿بها﴾ يعود ـ على قول ـ إلى كلمة ﴿أسلمت لرب العالمين﴾، وعلى قول آخر إلى ملة إبراهيم، أي الإسلام؛ وفي الإحالة ربط للوصية بما سبق ذكره.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص317، تحت «تقديم المتعلق «بها» العائد على الملة»","url":""}]},{"id":"s2-527","number":527,"surah":2,"verses":[132],"references":[{"surah":2,"verses":[132]}],"verseLabel":"البقرة: 132","question":"ما سرّ إفراد يعقوب بالذكر في قوله تعالى: ﴿وَوَصَّى بِهَا إِبْرَاهِيمُ بَنِيهِ وَيَعْقُوبُ﴾؟","answer":"أُفرد يعقوب بالذكر لأنه وصّى بنيه الوصية نفسها، ولإقامة الحجة على بني إسرائيل خاصة؛ فهو الجامع لنسبهم الذي ينتسبون إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص317، تحت «توجيه المخصوص بالذكر»","url":""}]},{"id":"s2-528","number":528,"surah":2,"verses":[132],"references":[{"surah":2,"verses":[132]}],"verseLabel":"البقرة: 132","question":"ما سرّ التعبير في قوله تعالى: ﴿إِنَّ اللَّهَ اصْطَفَى لَكُمُ الدِّينَ﴾، دون أن يقال: «اصطفاكم للدين»؟","answer":"﴿اصطفى لكم الدين﴾ تفيد أن الله اختار لهم الدين الصفو الكامل وادخره لهم تفضّلًا، فالعناية هنا بالدين المختار لهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص318، تحت «الألف واللام في الدين للكمال»","url":""}]},{"id":"s2-529","number":529,"surah":2,"verses":[132],"references":[{"surah":2,"verses":[132]}],"verseLabel":"البقرة: 132","question":"كيف يُفهم النهي في قوله تعالى: ﴿فَلَا تَمُوتُنَّ إِلَّا وَأَنْتُمْ مُسْلِمُونَ﴾ مع أن الإنسان لا يملك وقت موته؟","answer":"ليس النهي عن وقوع الموت نفسه، بل عن مفارقة الإسلام في أي وقت؛ أي داوموا على الإسلام حتى إذا جاءكم الموت وجدكم عليه. والجملة الاسمية ﴿وأنتم مسلمون﴾ تثبت هذه الحال.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص318، تحت «غرض النهي في قوله تعالى: «فلا تموتن»»","url":""}]},{"id":"s2-530","number":530,"surah":2,"verses":[133],"references":[{"surah":2,"verses":[133]}],"verseLabel":"البقرة: 133","question":"ما دلالة الاستفهام بـ﴿ما﴾ دون ﴿من﴾ في قول يعقوب: ﴿مَا تَعْبُدُونَ مِنْ بَعْدِي﴾؟","answer":"﴿ما﴾ أعم من ﴿من﴾؛ فهي تسأل عن المعبود وحقيقته وصفته، أما ﴿من﴾ فتختص غالبًا بالعاقل. فالمقام امتحان لحقيقة ما يعبدون لا لمجرد تعيين أشخاص.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص325، تحت «قوله «ما تعبدون» التعبير بـ«ما» دون «من»»","url":""}]},{"id":"s2-531","number":531,"surah":2,"verses":[133],"references":[{"surah":2,"verses":[133]}],"verseLabel":"البقرة: 133","question":"ما دلالة دخول ﴿من﴾ على ﴿بعدي﴾ في قوله تعالى: ﴿مَا تَعْبُدُونَ مِنْ بَعْدِي﴾؟","answer":"جيء بـ﴿من﴾ الابتدائية في ﴿من بعدي﴾ لتدل على ابتداء الزمن من أول ما بعد موته مباشرة، تأكيدًا لحرصه على ثباتهم دون مهلة للتغيير.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص325، تحت «فائدة إدخال «من» على «بعد» في قوله: «من بعدي»»","url":""}]},{"id":"s2-532","number":532,"surah":2,"verses":[133],"references":[{"surah":2,"verses":[133]}],"verseLabel":"البقرة: 133","question":"ما سرّ التعبير في قوله تعالى: ﴿أَمْ كُنْتُمْ شُهَدَاءَ﴾، ولم يسألهم مباشرة: «ماذا أوصى يعقوب أبناءه؟»؟","answer":"﴿أم﴾ منقطعة بمعنى «بل أكنتم شهداء؟»، والاستفهام للإنكار والتوبيخ؛ ينفي حضورهم وصية يعقوب ويبطل دعواهم أن الأنبياء كانوا يهودًا أو نصارى.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص323، تحت «التعبير بـ«أم» المنقطعة الدالة على الإضراب»","url":""}]},{"id":"s2-533","number":533,"surah":2,"verses":[133],"references":[{"surah":2,"verses":[133]}],"verseLabel":"البقرة: 133","question":"ما سرّ التعبير في قوله تعالى: ﴿إِذْ حَضَرَ يَعْقُوبَ الْمَوْتُ﴾، مع أن الموت لا يحضر قبل وقوعه؟","answer":"صُوّر الموت كأنه شخص حاضر ليقرب المشهد ويستحضر شدته، ويجوز أن يراد حضور مقدماته وأسبابه التي دلت على قربه.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص324، تحت «تنوع المجاز والاستعارة المكنية في «إذ حضر يعقوب الموت»»","url":""}]},{"id":"s2-534","number":534,"surah":2,"verses":[133],"references":[{"surah":2,"verses":[133]}],"verseLabel":"البقرة: 133","question":"ما دلالة قولهم: ﴿نَعْبُدُ إِلَهَكَ وَإِلَهَ آبَائِكَ﴾، دون الاكتفاء بقولهم: «نعبد الله»؟","answer":"ربطوا توحيدهم بتربية أبيهم وسلسلة النبوة قبله، فأعلنوا أن معبودهم ليس اختيارًا جديدًا بعد موته بل إله البيت النبوي كله. وإضافة الإله إلى يعقوب وآبائه تشعر باتصال العهد من جيل إلى جيل.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص326، تحت «دلالة التعريف بالإضافة في «إلهك»»","url":""}]}]);
